module barrel_shifter8 (
    input [7:0] din,
    input [2:0] shamt,
    input [1:0] mode,
    output [7:0] dout
);
    reg [7:0] dout;

    always @(*) begin
        case (mode)
            2'b00: begin // Logic left shift
                if (shamt == 3'b000)
                    dout = din;
                else if (shamt >= 3'b100) // shamt >= 8
                    dout = 8'b00000000;
                else
                    dout = din << shamt;
            end
            2'b01: begin // Logic right shift
                if (shamt == 3'b000)
                    dout = din;
                else if (shamt >= 3'b100) // shamt >= 8
                    dout = 8'b00000000;
                else
                    dout = din >> shamt;
            end
            2'b10: begin // Arithmetic right shift
                if (shamt == 3'b000)
                    dout = din;
                else if (shamt >= 3'b100) // shamt >= 8
                    dout = {8{din[7]}}; // Fill with sign bit
                else
                    dout = $signed(din) >>> shamt;
            end
            2'b11: begin // Rotate left
                if (shamt == 3'b000)
                    dout = din;
                else
                    dout = (din << shamt) | (din >> (8 - shamt));
            end
            default: begin
                dout = din;
            end
        endcase
    end
endmodule
