module barrel_shifter8 (
    input [7:0] din,
    input [2:0] shamt,
    input [1:0] mode,
    output [7:0] dout
);

    wire [7:0] logic_left_shift;
    wire [7:0] logic_right_shift;
    wire [7:0] arithmetic_right_shift;
    wire [7:0] rotate_left;

    // Logic left shift
    assign logic_left_shift = (shamt == 3'b000) ? din : {din[7-shamt:0], {shamt{1'b0}}};

    // Logic right shift
    assign logic_right_shift = (shamt == 3'b000) ? din : {{shamt{1'b0}}, din[7:shamt]};

    // Arithmetic right shift
    assign arithmetic_right_shift = (shamt == 3'b000) ? din : 
                                   {{shamt{din[7]}}, din[7:shamt]};

    // Rotate left
    assign rotate_left = (shamt == 3'b000) ? din : {din[7-shamt:0], din[7:8-shamt]};

    // Output multiplexer based on mode
    always @(*) begin
        case (mode)
            2'b00: dout = logic_left_shift;
            2'b01: dout = logic_right_shift;
            2'b10: dout = arithmetic_right_shift;
            2'b11: dout = rotate_left;
            default: dout = logic_left_shift;
        endcase
    end

endmodule
