    input [7:0] din,
    input [2:0] shamt,
    input [1:0] mode,
    output [7:0] dout
);
    reg [7:0] dout;

    always @(*) begin
        case (mode)
            2'b00: // 逻辑左移
                dout = din << shamt;
            2'b01: // 逻辑右移
                dout = din >> shamt;
            2'b10: // 算术右移
                dout = $signed(din) >>> shamt;
            2'b11: // 循环左移
                case (shamt)
                    3'd0: dout = din;
                    3'd1: dout = {din[6:0], din[7]};
