                    3'd3: dout = {din[4:0], din[7:5]};
                    3'd4: dout = {din[3:0], din[7:4]};
                    3'd5: dout = {din[2:0], din[7:3]};
                    3'd6: dout = {din[1:0], din[7:2]};
                    3'd7: dout = {din[0], din[7:1]};
                    default: dout = din;
