    assign arithmetic_right = (shamt == 3'd0) ? din :
                             (shamt == 3'd1) ? {din[7], din[7:1]} :
                             (shamt == 3'd2) ? {din[7], din[7], din[7:2]} :
                             (shamt == 3'd3) ? {din[7], din[7], din[7], din[7:3]} :
                             (shamt == 3'd4) ? {din[7], din[7], din[7], din[7], din[7:4]} :
