    assign bin_to_gray[2] = din[3] ^ din[2];
    assign bin_to_gray[1] = din[2] ^ din[1];
    assign bin_to_gray[0] = din[1] ^ din[0];

    // Gray to Binary conversion
    assign gray_to_bin[3] = din[3];
    assign gray_to_bin[2] = din[3] ^ din[2];
    assign gray_to_bin[1] = din[3] ^ din[2] ^ din[1];
    assign gray_to_bin[0] = din[3] ^ din[2] ^ din[1] ^ din[0];

    // Select output based on mode
    assign dout = (mode == 0) ? bin_to_gray : gray_to_bin;
