module seq_detector_1011 (
    input clk,
    input rst_n,
    input din,
    output det
);
    reg [3:0] state;
    parameter S0 = 4'b0000, S1 = 4'b0001, S2 = 4'b0010, S3 = 4'b0100, S4 = 4'b1000;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= S0;
        else begin
            case (state)
                S0: begin
                    if (din)
                        state <= S1;
                    else
                        state <= S0;
                end
                S1: begin
                    if (!din)
                        state <= S2;
                    else
                        state <= S1;
                end
                S2: begin
                    if (din)
                        state <= S3;
                    else
                        state <= S0;
                end
                S3: begin
                    if (din)
                        state <= S4;
                    else
                        state <= S2;
                end
                S4: begin
                    if (din)
                        state <= S1;
                    else
                        state <= S2;
                end
                default: state <= S0;
            endcase
        end
    end

    assign det = (state == S4);
endmodule
