module seq_detector_1011 (
    input clk,
    input rst_n,
    input din,
    output det
);

    reg [1:0] state;
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    wire det_next;
    assign det = (state == S3 && din == 1'b1) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= S0;
        else begin
            case (state)
                S0: begin
                    if (din == 1'b1)
                        state <= S1;
                    else
                        state <= S0;
                end
                S1: begin
                    if (din == 1'b0)
                        state <= S2;
                    else
                        state <= S1;
                end
                S2: begin
                    if (din == 1'b1)
                        state <= S3;
                    else
                        state <= S0;
                end
                S3: begin
                    if (din == 1'b1)
                        state <= S1;  // 允许重叠，检测到1011后，最后的1作为新序列的开始
                    else
                        state <= S2;
                end
                default: state <= S0;
            endcase
        end
    end

