module seq_detector_1011 (
    input clk,
    input rst_n,
    input din,
    output det
);

    reg [3:0] shift_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            shift_reg <= 4'b0000;
        else
            shift_reg <= {shift_reg[2:0], din};
    end

    assign det = (shift_reg == 4'b1011) ? 1'b1 : 1'b0;

endmodule

