2. **状态机设计**：使用Moore状态机，4个状态表示已匹配的位数：S0(0位), S1(1位), S2(2位), S3(3位)
   - S0: 等待'1' -> S1, 其他->S0
   - S1: '0'->S2, '1'->S1  
   - S2: '1'->S3, '0'->S0
   - S3: '1'->输出1并转S1, '0'->S2
3. **复位行为**：同步复位，将状态清零，输出清零
4. **时序要求**：使用Moore状态机自然提供1周期延迟，检测到1011后下一周期输出1

```verilog
module seq_detector_1011 (
    input clk,
    input rst_n,
    input din,
    output det
);
    reg [1:0] state;
    reg det_reg;

    parameter S0 = 2'b00; // 已匹配0位
    parameter S1 = 2'b01; // 已匹配1位 (1)
    parameter S2 = 2'b10; // 已匹配2位 (10) 
    parameter S3 = 2'b11; // 已匹配3位 (101)

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S0;
            det_reg <= 0;
        end else begin
            case (state)
                S0: begin
                    if (din == 1) state <= S1;
                    else state <= S0;
                    det_reg <= 0;
                end
                S1: begin
                    if (din == 0) state <= S2;
                    else state <= S1;
                    det_reg <= 0;
                end
                S2: begin
                    if (din == 1) state <= S3;
                    else state <= S0;
                    det_reg <= 0;
                end
                S3: begin
                    if (din == 1) begin
                        state <= S1;  // 接收最后的1后，下一位如果是1则从S1开始
                        det_reg <= 1;
                    end else begin
                        state <= S2;  // 下一位是0，则从10开始匹配
                        det_reg <= 0;
                    end
                end
                default: begin
                    state <= S0;
                    det_reg <= 0;
                end
            endcase
        end
    end

    assign det = det_reg;
endmodule
