              S3 = 3'b011,  // 已匹配 "101"
              S4 = 3'b100;  // 已匹配 "1011"

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S0;
            det <= 0;
        end else begin
            case (state)
                S0: begin
                    if (din == 1'b1)
