## 设计思路

1. **信号分析**：输入包括clk,rst_n,wr_en(1位),wr_data(8位),rd_en(1位)；输出包括rd_data(8位)组合逻辑，full,empty(1位)组合逻辑，count(5位)寄存器

2. **计数器设计**：使用5位计数器记录当前存储数量[0:31]，满条件为count==16，空条件为count==0

3. **复位与时序**：异步低有效复位清零所有寄存器；FIFO内部存储16个数据，读使能后下一周期数据有效需用读指针寄存器；写满不写，读空不读

4. **地址管理**：使用4位读写指针(0-15)，写使能且不满时写入并更新写指针，读使能且非空时更新读指针并输出对应数据

```verilog
module sync_fifo #(parameter DW = 8, parameter DEPTH = 16) (
    input clk,
    input rst_n,
    input wr_en,
    input [7:0] wr_data,
    input rd_en,
    output [7:0] rd_data,
    output full,
    output empty,
    output [4:0] count
);

    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;
    reg [4:0] count_reg;
    reg [7:0] mem [0:15];

    wire [4:0] next_count;
    wire can_write;
    wire can_read;

    assign next_count = count_reg + (can_write ? 1 : 0) - (can_read ? 1 : 0);
    assign can_write = wr_en & ~full;
    assign can_read = rd_en & ~empty;
    assign full = (count_reg == 5'd16);
    assign empty = (count_reg == 5'd0);
    assign count = count_reg;
    assign rd_data = mem[rd_ptr];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count_reg <= 5'd0;
        end else begin
            count_reg <= next_count;

            if (can_write) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr <= wr_ptr + 1'b1;
            end

            if (can_read)
                rd_ptr <= rd_ptr + 1'b1;
        end
    end

