module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // Transmitter signals
    reg [3:0] tx_state;
    reg [3:0] tx_bit_cnt;
    reg [7:0] tx_shift_reg;
    reg tx_busy_r;
    reg tx_out;

    // Receiver signals
    reg [4:0] rx_state;
    reg [4:0] rx_bit_cnt;
    reg [7:0] rx_shift_reg;
    reg [4:0] rx_sample_cnt;
    reg rx_prev;
    reg rx_sync;
    reg rx_valid_r;
    reg rx_err_r;

    // Transmitter FSM states
    parameter TX_IDLE = 4'd0,
              TX_START = 4'd1,
              TX_DATA = 4'd2,
              TX_STOP = 4'd3;

    // Receiver FSM states
    parameter RX_IDLE = 5'd0,
              RX_WAIT_START = 5'd1,
              RX_SAMPLE_START = 5'd2,
              RX_SAMPLE_DATA = 5'd3,
              RX_SAMPLE_STOP = 5'd4;

    // Transmitter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx_bit_cnt <= 0;
            tx_shift_reg <= 0;
            tx_busy_r <= 0;
            tx_out <= 1;  // Idle state is high
        end else begin
            case (tx_state)
                TX_IDLE: begin
                    if (tx_start) begin
                        tx_shift_reg <= tx_data;
                        tx_bit_cnt <= 0;
                        tx_busy_r <= 1;
                        tx_out <= 0;  // Start bit
                        tx_state <= TX_START;
                    end
                end

                TX_START: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        tx_bit_cnt <= 0;
                        tx_out <= tx_shift_reg[0];  // First data bit
                        tx_state <= TX_DATA;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1;
                    end
                end

                TX_DATA: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        tx_bit_cnt <= 0;
                        if (tx_shift_reg[7:1] == 0 && tx_shift_reg[0] == 0) begin  // All bits sent
                            tx_out <= 1;  // Stop bit
                            tx_state <= TX_STOP;
                        end else begin
                            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            tx_out <= tx_shift_reg[0];
                        end
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1;
                    end
                end

                TX_STOP: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        tx_out <= 1;  // Back to idle
                        tx_busy_r <= 0;
                        tx_state <= TX_IDLE;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1;
                    end
                end

                default: tx_state <= TX_IDLE;
            endcase
        end
    end

    // Receiver logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_prev <= 1;
            rx_sync <= 1;
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 0;
            rx_sample_cnt <= 0;
            rx_shift_reg <= 0;
            rx_valid_r <= 0;
            rx_err_r <= 0;
        end else begin
            rx_prev <= rx;
            rx_sync <= rx_prev;

            rx_valid_r <= 0;

            case (rx_state)
                RX_IDLE: begin
                    if (rx_sync == 0) begin  // Found start bit
                        rx_sample_cnt <= CLKS_PER_BIT / 2;  // Wait half a bit period
                        rx_state <= RX_WAIT_START;
                    end
                end

                RX_WAIT_START: begin
                    if (rx_sample_cnt == CLKS_PER_BIT / 2 - 1) begin
                        rx_sample_cnt <= 0;
                        if (rx_sync == 0) begin  // Verify start bit still low
                            rx_bit_cnt <= 0;
                            rx_shift_reg <= 0;
                            rx_state <= RX_SAMPLE_DATA;
                        end else begin
                            rx_state <= RX_IDLE;  // False start
                        end
                    end else begin
                        rx_sample_cnt <= rx_sample_cnt + 1;
                    end
                end

                RX_SAMPLE_DATA: begin
                    if (rx_sample_cnt == CLKS_PER_BIT - 1) begin
                        rx_sample_cnt <= 0;
                        rx_shift_reg <= {rx_sync, rx_shift_reg[7:1]};

                        if (rx_bit_cnt == 7) begin  // Last data bit
                            rx_bit_cnt <= 0;
                            rx_state <= RX_SAMPLE_STOP;
                        end else begin
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end
                    end else begin
                        rx_sample_cnt <= rx_sample_cnt + 1;
                    end
                end

                RX_SAMPLE_STOP: begin
                    if (rx_sample_cnt == CLKS_PER_BIT - 1) begin
                        // Check stop bit (should be high)
                        if (rx_sync == 1) begin
                            rx_data <= rx_shift_reg;
                            rx_valid_r <= 1;
                            rx_err_r <= 0;
                        end else begin
                            rx_err_r <= 1;  // Stop bit error
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_sample_cnt <= rx_sample_cnt + 1;
                    end
                end

                default: rx_state <= RX_IDLE;
            endcase
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_out;
    assign rx_data = rx_shift_reg;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

