                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                TX_STOP: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        tx_state <= TX_IDLE;
                        tx_busy_reg <= 1'b0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                default: begin
                    tx_state <= TX_IDLE;
                    tx_busy_reg <= 1'b0;
                end
            endcase
        end
    end

    // Receiver FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 0;
            rx_clk_cnt <= 0;
            rx_shift_reg <= 0;
            rx_data_reg <= 0;
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;
            rx_prev <= 1'b1;
            rx_sample <= 1'b0;
        end else begin
            rx_prev <= rx;

            case (rx_state)
                RX_IDLE: begin
                    rx_sample <= 1'b0;
                    if (rx_prev & ~rx) begin // Falling edge detected (start bit)
                        rx_state <= RX_WAIT_START;
                        rx_clk_cnt <= 0;
                    end
                end
                RX_WAIT_START: begin
                    if (rx_clk_cnt == (CLKS_PER_BIT >> 1) - 1) begin // Half bit period to center sample
                        rx_clk_cnt <= 0;
                        rx_sample <= 1'b1;
                        rx_state <= RX_SAMPLE_START;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_SAMPLE_START: begin
                    if (rx_sample) begin
                        if (~rx) begin // Valid start bit
                            rx_shift_reg <= 0; // Clear shift register
                            rx_bit_cnt <= 0;
                            rx_state <= RX_SAMPLE_DATA;
                        end else begin // Invalid start bit
                            rx_state <= RX_IDLE;
                        end
                        rx_sample <= 1'b0;
                    end
                end
                RX_SAMPLE_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};
                        if (rx_bit_cnt < 7) begin
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end else begin
                            rx_bit_cnt <= 0;
                            rx_state <= RX_SAMPLE_STOP;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_SAMPLE_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};
                        rx_data_reg <= rx_shift_reg[8:1]; // Data bits
                        rx_err_reg <= ~rx_shift_reg[0]; // Check stop bit (should be high)
                        rx_valid_reg <= 1'b1;
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                default: begin
                    rx_state <= RX_IDLE;
                end
            endcase

            if (rx_valid_reg)
                rx_valid_reg <= 1'b0;
        end
    end

    assign tx_busy = tx_busy_reg;
    assign tx = tx_out;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;
    assign rx_err = rx_err_reg;

