```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

reg tx_busy_r;
reg tx_r;
reg [9:0] tx_shift_reg;
reg [2:0] tx_bit_cnt;
reg [3:0] tx_clk_cnt;
reg [2:0] tx_state;

reg [9:0] rx_shift_reg;
reg [2:0] rx_bit_cnt;
reg [3:0] rx_clk_cnt;
reg [2:0] rx_state;
reg rx_valid_r;
reg rx_err_r;
reg [7:0] rx_data_r;

// 发送状态定义
localparam TX_IDLE = 3'd0,
           TX_START = 3'd1,
           TX_DATA = 3'd2,
           TX_STOP = 3'd3;

// 接收状态定义
localparam RX_IDLE = 3'd0,
           RX_START = 3'd1,
           RX_DATA = 3'd2,
           RX_STOP = 3'd3;

assign tx_busy = tx_busy_r;
assign tx = tx_r;
assign rx_data = rx_data_r;
assign rx_valid = rx_valid_r;
assign rx_err = rx_err_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        tx_r <= 1'b1;
        tx_busy_r <= 1'b0;
        tx_shift_reg <= 10'b0;
        tx_bit_cnt <= 3'd0;
        tx_clk_cnt <= 4'd0;
        tx_state <= TX_IDLE;
    end else begin
        case (tx_state)
            TX_IDLE: begin
                tx_r <= 1'b1;
                if (tx_start) begin
                    tx_busy_r <= 1'b1;
                    tx_shift_reg <= {1'b1, tx_data, 1'b0}; // 停止位+数据位+起始位
                    tx_bit_cnt <= 3'd0;
                    tx_clk_cnt <= 4'd0;
                    tx_state <= TX_START;
                    tx_r <= 1'b0; // 起始位
                end
            end
            TX_START: begin
                if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= 4'd0;
                    tx_r <= tx_shift_reg[1]; // 第一个数据位
                    tx_state <= TX_DATA;
                end else begin
                    tx_clk_cnt <= tx_clk_cnt + 1'b1;
                end
            end
            TX_DATA: begin
                if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= 4'd0;
                    if (tx_bit_cnt == 3'd7) begin
                        tx_bit_cnt <= 3'd0;
                        tx_r <= tx_shift_reg[9]; // 停止位
                        tx_state <= TX_STOP;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                        tx_r <= tx_shift_reg[tx_bit_cnt + 2];
                        tx_shift_reg <= {1'b0, tx_shift_reg[9:1]};
                    end
                end else begin
                    tx_clk_cnt <= tx_clk_cnt + 1'b1;
                end
            end
            TX_STOP: begin
                if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                    tx_busy_r <= 1'b0;
                    tx_state <= TX_IDLE;
                end else begin
                    tx_clk_cnt <= tx_clk_cnt + 1'b1;
                end
            end
            default: tx_state <= TX_IDLE;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rx_shift_reg <= 10'b0;
        rx_bit_cnt <= 3'd0;
        rx_clk_cnt <= 4'd0;
        rx_state <= RX_IDLE;
        rx_valid_r <= 1'b0;
        rx_err_r <= 1'b0;
        rx_data_r <= 8'b0;
    end else begin
        rx_valid_r <= 1'b0;

        case (rx_state)
            RX_IDLE: begin
                if (!rx) begin // 检测到起始位
                    rx_clk_cnt <= 4'd0;
                    rx_bit_cnt <= 3'd0;
                    rx_shift_reg <= 10'b0;
                    rx_state <= RX_START;
                end
            end
            RX_START: begin
                if (rx_clk_cnt == (CLKS_PER_BIT >> 1) - 1) begin // 中点采样
                    if (!rx) begin // 确认起始位
                        rx_clk_cnt <= 4'd0;
                        rx_state <= RX_DATA;
                    end else begin
                        rx_state <= RX_IDLE; // 不是有效起始位
                    end
                end else begin
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                end
            end
            RX_DATA: begin
                if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                    rx_clk_cnt <= 4'd0;
                    rx_shift_reg <= {rx, rx_shift_reg[9:1]};

                    if (rx_bit_cnt == 3'd7) begin
                        rx_bit_cnt <= 3'd0;
                        rx_state <= RX_STOP;
                    end else begin
                        rx_bit_cnt <= rx_bit_cnt + 1'b1;
                    end
                end else begin
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                end
            end
            RX_STOP: begin
                if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                    rx_data_r <= rx_shift_reg[8:1]; // 数据位
                    rx_valid_r <= 1'b1;
                    rx_err_r <= !rx; // 停止位应为高电平
                    rx_state <= RX_IDLE;
                end else begin
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                end
            end
            default: rx_state <= RX_IDLE;
        endcase
    end
end

endmodule
