                TX_DATA: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        if (tx_bit_cnt < 8) begin
                            tx_reg <= tx_data[tx_bit_cnt];
                            tx_bit_cnt <= tx_bit_cnt + 1;
