    // RX state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 0;
            rx_clk_cnt <= 0;
            rx_data_reg <= 8'h00;
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;
        end else begin
            rx_valid_reg <= 1'b0;  // Clear valid pulse

