                            rx_bit_cnt <= 0;
                            rx_state <= RX_DATA;
                        end else begin
                            rx_state <= RX_IDLE;  // False start
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        if (rx_bit_cnt < 8) begin
                            rx_data_reg[rx_bit_cnt] <= rx_sync2;
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end else begin
                            rx_state <= RX_STOP;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        if (rx_sync2 == 1'b1) begin  // Valid stop bit
