                            rx_err_reg <= 1'b0;
                        end else begin  // Invalid stop bit
                            rx_err_reg <= 1'b1;
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

    assign tx_busy = tx_busy_reg;
    assign tx = tx_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;
    assign rx_err = rx_err_reg;

