module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // 发送相关信号
    reg [2:0] tx_state;
    reg [3:0] tx_bit_cnt;
    reg [3:0] tx_clk_cnt;
    reg [7:0] tx_shift_reg;
    reg tx_busy_r;
    reg tx_out;

    // 接收相关信号
    reg [2:0] rx_state;
    reg [3:0] rx_bit_cnt;
    reg [3:0] rx_clk_cnt;
    reg [7:0] rx_shift_reg;
    reg rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg rx_sample;

    parameter TX_IDLE = 3'b000;
    parameter TX_START = 3'b001;
    parameter TX_DATA = 3'b010;
    parameter TX_STOP = 3'b011;

    parameter RX_IDLE = 3'b000;
    parameter RX_START = 3'b001;
    parameter RX_DATA = 3'b010;
    parameter RX_STOP = 3'b011;

    // 发送状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx_bit_cnt <= 0;
            tx_clk_cnt <= 0;
            tx_shift_reg <= 0;
            tx_busy_r <= 0;
            tx_out <= 1;  // 空闲时为高电平
        end else begin
            case (tx_state)
                TX_IDLE: begin
                    tx_out <= 1;
                    if (tx_start) begin
                        tx_shift_reg <= tx_data;
                        tx_bit_cnt <= 0;
                        tx_clk_cnt <= 0;
                        tx_busy_r <= 1;
                        tx_state <= TX_START;
                        tx_out <= 0;  // 开始位
                    end
                end
                TX_START: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        tx_out <= tx_shift_reg[0];  // 发送最低位
                        tx_state <= TX_DATA;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                TX_DATA: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        if (tx_bit_cnt == 7) begin
                            tx_bit_cnt <= 0;
                            tx_out <= 1;  // 停止位
                            tx_state <= TX_STOP;
                        end else begin
                            tx_bit_cnt <= tx_bit_cnt + 1;
                            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            tx_out <= tx_shift_reg[0];
                        end
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                TX_STOP: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_busy_r <= 0;
                        tx_state <= TX_IDLE;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                default: tx_state <= TX_IDLE;
            endcase
        end
    end

