    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 0;
            rx_clk_cnt <= 0;
            rx_shift_reg <= 0;
            rx_data_r <= 0;
            rx_valid_r <= 0;
            rx_err_r <= 0;
            rx_sample <= 1;
        end else begin
            rx_valid_r <= 0;
            case (rx_state)
                RX_IDLE: begin
                    if (rx == 0) begin  // 检测到起始位
                        rx_clk_cnt <= 0;
                        rx_bit_cnt <= 0;
                        rx_sample <= 0;
                        rx_state <= RX_START;
                    end
                end
                RX_START: begin
                    if (rx_clk_cnt == (CLKS_PER_BIT >> 1) - 1) begin  // 中点采样
                        rx_clk_cnt <= 0;
                        if (rx == 0) begin  // 确认起始位
                            rx_sample <= 1;
                            rx_state <= RX_DATA;
                        end else begin
                            rx_state <= RX_IDLE;  // 不是有效起始位
                        end
                    end else if (rx_sample) begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                        if (rx_bit_cnt == 7) begin
                            rx_bit_cnt <= 0;
                            rx_state <= RX_STOP;
                        end else begin
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end
                    end else if (rx_sample) begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_data_r <= rx_shift_reg;
                        rx_valid_r <= 1;
                        if (rx != 1) begin  // 停止位应为高电平
                            rx_err_r <= 1;
                        end else begin
                            rx_err_r <= 0;
                        end
                        rx_state <= RX_IDLE;
                    end else if (rx_sample) begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_out;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

endmodule
