                    if (tx_start) begin
                        tx_shift_reg <= tx_data;
                        tx_bit_cnt <= 4'b0;
                        tx_clk_cnt <= 4'b0;
                        tx_busy_r <= 1'b1;
                        tx_r <= 1'b0; // 发送起始位
                        tx_state <= TX_START;
                    end
                end
                TX_START: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 4'b0;
                        tx_r <= tx_shift_reg[0]; // 发送数据位
                        tx_state <= TX_DATA;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1'b1;
                    end
