                            rx_data_r <= rx_shift_reg;
                            rx_valid_r <= 1'b1;
                            rx_err_r <= 1'b0;
                        end else begin
                            rx_err_r <= 1'b1; // 停止位错误
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

