                TX_START: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 4'b0;
                        tx_r <= tx_shift_reg[0]; // 发送数据位
                        tx_state <= TX_DATA;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1'b1;
                    end
                end
                TX_DATA: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 4'b0;
                        if (tx_bit_cnt < 7) begin
                            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            tx_r <= tx_shift_reg[0];
                            tx_bit_cnt <= tx_bit_cnt + 1'b1;
                        end else begin
                            tx_r <= 1'b1; // 发送停止位
                            tx_state <= TX_STOP;
                        end
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1'b1;
                    end
                end
                TX_STOP: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_state <= TX_IDLE;
                        tx_busy_r <= 1'b0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1'b1;
                    end
                end
                default: tx_state <= TX_IDLE;
            endcase
        end
    end

    // 接收状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_prev <= 1'b1;
            rx_sample <= 1'b1;
            rx_shift_reg <= 8'b0;
            rx_bit_cnt <= 4'b0;
            rx_clk_cnt <= 4'b0;
            rx_data_r <= 8'b0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
        end else begin
            rx_prev <= rx;
            rx_sample <= rx_prev;

            rx_valid_r <= 1'b0; // 默认无效

            case (rx_state)
                RX_IDLE: begin
                    if (rx_prev & ~rx_sample) begin // 检测下降沿
                        rx_state <= RX_START;
                        rx_clk_cnt <= CLKS_PER_BIT >> 1; // 延迟半个位时间
                    end
                end
                RX_START: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        if (~rx_sample) begin // 验证起始位
                            rx_clk_cnt <= 4'b0;
                            rx_bit_cnt <= 4'b0;
                            rx_shift_reg <= 8'b0;
                            rx_state <= RX_DATA;
                        end else begin
                            rx_state <= RX_IDLE; // 起始位错误
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    end
                end
                RX_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 4'b0;
                        rx_shift_reg <= {rx_sample, rx_shift_reg[7:1]};
                        if (rx_bit_cnt < 7) begin
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                        end else begin
                            rx_state <= RX_STOP;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    end
                end
                RX_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        if (rx_sample) begin // 检查停止位是否为高电平
                            rx_data_r <= rx_shift_reg;
                            rx_valid_r <= 1'b1;
                            rx_err_r <= 1'b0;
                        end else begin
                            rx_err_r <= 1'b1; // 停止位错误
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

