## 设计思路

**1. 信号分析：**
- 输入：clk(1), rst_n(1), tx_start(1), tx_data(8), rx(1)
- 输出：tx_busy(1, 寄存器), tx(1, 寄存器), rx_data(8, 寄存器), rx_valid(1, 寄存器), rx_err(1, 寄存器)
- 内部：发送/接收状态机、位计数器、数据移位寄存器

**2. 状态机设计：**
- 发送：IDLE -> START -> DATA[0-7] -> STOP
- 接收：IDLE -> START -> DATA[0-7] -> STOP
- 计数器：0到CLKS_PER_BIT-1（需要log2(CLKS_PER_BIT)位）

**3. 复位行为：**
- 异步复位，所有寄存器清零
- tx输出高电平（空闲态）

**4. 时序要求：**
- 8N1格式：1位起始位(0)，8位数据，1位停止位(1)
- 每位持续CLKS_PER_BIT个时钟周期

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg [3:0] tx_state;
    reg [3:0] rx_state;
    reg [3:0] tx_bit_cnt;
    reg [3:0] rx_bit_cnt;
    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg tx_busy_r;
    reg tx_r;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;

    // 发送状态定义
    parameter TX_IDLE = 4'b0000,
              TX_START = 4'b0001,
              TX_DATA = 4'b0010,
              TX_STOP = 4'b0011;

    // 接收状态定义
    parameter RX_IDLE = 4'b0000,
              RX_START = 4'b0001,
              RX_DATA = 4'b0010,
              RX_STOP = 4'b0011;

    // 发送逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx_shift_reg <= 8'h00;
            tx_bit_cnt <= 4'h0;
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1; // 空闲时为高电平
        end else begin
            case (tx_state)
                TX_IDLE: begin
                    tx_busy_r <= 1'b0;
                    tx_r <= 1'b1;
                    if (tx_start) begin
                        tx_shift_reg <= tx_data;
                        tx_bit_cnt <= 4'h0;
                        tx_r <= 1'b0; // 起始位
                        tx_busy_r <= 1'b1;
                        tx_state <= TX_START;
                    end
                end
                TX_START: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        tx_bit_cnt <= 4'h0;
                        tx_r <= tx_shift_reg[0]; // 第一位数据
                        tx_state <= TX_DATA;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    end
                end
                TX_DATA: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        if (tx_bit_cnt < 7) begin // 传输8位数据
                            tx_bit_cnt <= 4'h0;
                            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            tx_r <= tx_shift_reg[0];
                        end else begin
                            tx_bit_cnt <= 4'h0;
                            tx_r <= 1'b1; // 停止位
                            tx_state <= TX_STOP;
                        end
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    end
                end
                TX_STOP: begin
                    if (tx_bit_cnt == CLKS_PER_BIT - 1) begin
                        tx_state <= TX_IDLE;
                    end else begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    end
                end
                default: tx_state <= TX_IDLE;
            endcase
        end
    end

    // 接收逻辑
    reg [3:0] rx_sample_point;
    reg rx_sync1, rx_sync2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_sync1 <= 1'b1;
            rx_sync2 <= 1'b1;
            rx_state <= RX_IDLE;
            rx_shift_reg <= 8'h00;
            rx_bit_cnt <= 4'h0;
            rx_sample_point <= 4'h0;
            rx_data_r <= 8'h00;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
        end else begin
            rx_sync1 <= rx;
            rx_sync2 <= rx_sync1;

            rx_valid_r <= 1'b0;

            case (rx_state)
                RX_IDLE: begin
                    if (rx_sync2 == 1'b0) begin // 检测到起始位
                        rx_state <= RX_START;
                        rx_bit_cnt <= 5'd0;
                        rx_sample_point <= CLKS_PER_BIT / 2; // 在中间采样
                    end
                end
                RX_START: begin
                    if (rx_sample_point == 0) begin
                        if (rx_sync2 == 1'b0) begin // 确认是起始位
                            rx_state <= RX_DATA;
                            rx_bit_cnt <= 5'd0;
                            rx_sample_point <= CLKS_PER_BIT - 1;
                        end else begin
                            rx_state <= RX_IDLE; // 不是真正的起始位
                        end
                    end else begin
                        rx_sample_point <= rx_sample_point - 1'b1;
                    end
                end
                RX_DATA: begin
                    if (rx_sample_point == 0) begin
                        rx_shift_reg <= {rx_sync2, rx_shift_reg[7:1]};
                        if (rx_bit_cnt < 7) begin
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                            rx_sample_point <= CLKS_PER_BIT - 1;
                        end else begin
                            rx_bit_cnt <= 4'h0;
                            rx_sample_point <= CLKS_PER_BIT - 1;
                            rx_state <= RX_STOP;
                        end
                    end else begin
                        rx_sample_point <= rx_sample_point - 1'b1;
                    end
                end
                RX_STOP: begin
                    if (rx_sample_point == 0) begin
                        rx_err_r <= (rx_sync2 != 1'b1); // 检查停止位是否为1
                        rx_data_r <= rx_shift_reg;
                        rx_valid_r <= 1'b1;
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_sample_point <= rx_sample_point - 1'b1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

endmodule
