```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // Transmitter signals
    reg [9:0] tx_shift_reg;
    reg tx_busy_r;
    reg [3:0] tx_bit_cnt;
    reg [CLKS_PER_BIT-1:0] tx_clk_cnt;
    reg tx_out;

    // Receiver signals
    reg [9:0] rx_shift_reg;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg [3:0] rx_bit_cnt;
    reg [CLKS_PER_BIT-1:0] rx_clk_cnt;
    reg rx_sample_point;
    reg rx_prev, rx_curr;
    reg rx_start_detected;
    reg [3:0] rx_state;  // 0: idle, 1: wait_mid_start, 2: sample_bits

    // Transmitter logic
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_shift_reg <= 10'b1111111111;  // Initialize to idle state (all 1s)
            tx_busy_r <= 1'b0;
            tx_bit_cnt <= 4'd0;
            tx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
            tx_out <= 1'b1;
        end else begin
            if (!tx_busy_r && tx_start) begin
                tx_shift_reg <= {1'b1, tx_data, 1'b0};  // Stop bit(1), data(8), start bit(0)
                tx_busy_r <= 1'b1;
                tx_bit_cnt <= 4'd0;
                tx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
                tx_out <= 1'b0;  // Start bit
            end else if (tx_busy_r) begin
                tx_clk_cnt <= tx_clk_cnt + 1'b1;
                if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
                    if (tx_bit_cnt < 9) begin  // 10 bits total: start(0) + 8 data + stop(1)
                        tx_out <= tx_shift_reg[0];
                        tx_shift_reg <= {1'b1, tx_shift_reg[9:1]};  // Shift right and pad with 1
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    end else begin  // Last bit is stop bit
                        tx_out <= 1'b1;  // Stop bit
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    end

                    if (tx_bit_cnt == 9 && tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_busy_r <= 1'b0;
                    end
                end
            end
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_out;

    // Receiver logic
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_prev <= 1'b1;
            rx_curr <= 1'b1;
            rx_shift_reg <= 10'b0;
            rx_data_r <= 8'b0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
            rx_sample_point <= 1'b0;
            rx_start_detected <= 1'b0;
            rx_state <= 4'd0;  // Idle
        end else begin
            rx_prev <= rx;
            rx_curr <= rx_prev;

            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            case (rx_state)
                4'd0: begin  // Idle - waiting for start bit
                    if (rx_prev == 1'b1 && rx_curr == 1'b0) begin  // Start bit detected
                        rx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
                        rx_state <= 4'd1;  // Wait for middle of start bit
                        rx_start_detected <= 1'b1;
                    end
                end

                4'd1: begin  // Wait for middle of start bit
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    if (rx_clk_cnt == (CLKS_PER_BIT >> 1) - 1) begin  // Half bit time
                        rx_clk_cnt <= {CLKS_PER_BIT{1'b0}};
                        // Sample the middle of start bit
                        if (rx == 1'b0) begin  // Valid start bit
                            rx_bit_cnt <= 4'd0;
                            rx_state <= 4'd2;  // Sample data and stop bits
                        end else begin  // False start - return to idle
                            rx_state <= 4'd0;
                            rx_start_detected <= 1'b0;
                        end
                    end
                end

                4'd2: begin  // Sampling bits (data + stop)
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin  // End of bit period
                        rx_clk_cnt <= {CLKS_PER_BIT{1'b0}};

                        // Sample at the middle of the bit
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};

                        if (rx_bit_cnt < 9) begin  // Data bits (0-7) + stop bit (8)
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                        end else begin  // Process stop bit
                            if (rx_shift_reg[1] == 1'b1) begin  // Stop bit is 1 - valid frame
                                rx_data_r <= rx_shift_reg[9:2];  // Data bits
                                rx_valid_r <= 1'b1;
                            end else begin  // Stop bit is 0 - error
                                rx_err_r <= 1'b1;
                            end

                            // Go back to idle
                            rx_state <= 4'd0;
                            rx_start_detected <= 1'b0;
                        end
                    end
                end

                default: rx_state <= 4'd0;
            endcase
        end
    end

    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

endmodule
