    // Synchronize asynchronous inputs
    always @(posedge clk) begin
        if (!rst_n) begin
            sclk_sync <= 2'b00;
            cs_n_sync <= 2'b11;  // Default high
            mosi_sync <= 2'b00;
        end else begin
            sclk_sync <= {sclk_sync[0], sclk};
            cs_n_sync <= {cs_n_sync[0], cs_n};
            mosi_sync <= {mosi_sync[0], mosi};
        end
    end

    // Edge detection
    always @(posedge clk) begin
        if (!rst_n) begin
            sclk_pos_edge <= 1'b0;
            sclk_neg_edge <= 1'b0;
            cs_n_neg_edge <= 1'b0;
        end else begin
            sclk_pos_edge <= (~sclk_sync[1]) & sclk_sync[0];  // Rising edge of sclk
            sclk_neg_edge <= sclk_sync[1] & (~sclk_sync[0]);  // Falling edge of sclk
            cs_n_neg_edge <= cs_n_sync[1] & (~cs_n_sync[0]);  // Falling edge of cs_n
        end
    end

    // Bit counter and state control
    always @(posedge clk) begin
        if (!rst_n) begin
            bit_count <= 3'b000;
            cs_active <= 1'b0;
        end else if (cs_n_neg_edge) begin
            bit_count <= 3'b000;
            cs_active <= 1'b1;
        end else if (cs_active && sclk_pos_edge) begin
            if (bit_count == 3'd7)
                bit_count <= 3'b000;
            else
                bit_count <= bit_count + 1'b1;
        end else if (!cs_n_sync[0]) begin  // cs_n is low
            // Keep cs_active high while cs_n is low
            cs_active <= 1'b1;
        end else begin  // cs_n is high
            cs_active <= 1'b0;
            bit_count <= 3'b000;
        end
    end

