    always @(posedge clk) begin
        if (!rst_n) begin
            tx_shift_reg <= 8'b0;
        end else if (cs_n_neg_edge) begin
            tx_shift_reg <= tx_data;
        end else if (cs_active && sclk_neg_edge) begin
            tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
