                miso_reg <= tx_data[7];
            end
            // 如果cs_n为高，停止传输
            else if (cs_n_sync[0]) begin
                transfer_active <= 1'b0;
                miso_reg <= 1'b0;
                rx_valid_reg <= 1'b0;
            end
            // 在传输过程中处理SPI时序
            else if (transfer_active) begin
