    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg [2:0] bit_count;
    reg miso_out;
    reg rx_valid_out;
    reg [2:0] miso_delay_counter;
    reg [2:0] rx_update_counter;
    reg [3:0] sample_delay_counter;

    // Synchronize inputs
    always @(posedge clk) begin
        if (!rst_n) begin
            sclk_sync <= 2'b00;
            cs_n_sync <= 2'b11;  // Assuming cs_n is high during reset
            mosi_sync <= 2'b00;
        end else begin
            sclk_sync <= {sclk_sync[0], sclk};
            cs_n_sync <= {cs_n_sync[0], cs_n};
            mosi_sync <= {mosi_sync[0], mosi};
        end
    end

    // Edge detection
    assign sclk_edge_detect = {sclk_edge_detect[1:0], sclk_sync[1] ^ sclk_sync[0]};
    assign cs_n_edge_detect = {cs_n_edge_detect[1:0], cs_n_sync[1] ^ cs_n_sync[0]};

    // Rising edge of sclk (sample on rising edge)
    wire sclk_posedge = sclk_edge_detect[1] & sclk_sync[1];
    // Falling edge of sclk (update miso on falling edge)
    wire sclk_negedge = sclk_edge_detect[1] & ~sclk_sync[1];
    // Falling edge of cs_n (start transaction)
    wire cs_n_falling = cs_n_edge_detect[1] & ~cs_n_sync[1];

    // Main state machine and counters
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_shift_reg <= 8'h00;
            rx_shift_reg <= 8'h00;
            bit_count <= 3'h0;
            miso_out <= 1'b0;
            rx_valid_out <= 1'b0;
            miso_delay_counter <= 3'h0;
            rx_update_counter <= 3'h0;
            sample_delay_counter <= 4'h0;
        end else begin
            // Detect falling edge of cs_n to start new transaction
            if (cs_n_falling) begin
                tx_shift_reg <= tx_data;
                rx_shift_reg <= 8'h00;
                bit_count <= 3'h0;
                miso_out <= tx_data[7];  // Output MSB after 4 cycles
                rx_valid_out <= 1'b0;
                miso_delay_counter <= 3'h4;  // Schedule miso update in 4 cycles
                rx_update_counter <= 3'h0;
                sample_delay_counter <= 4'h0;
            end 
