                    rx_update_counter <= 3'h4;  // Schedule rx_valid pulse in 4 cycles
                    bit_count <= 3'h0;  // Reset for next byte
                end

                // Schedule miso update after sclk falling edge (handled below)
                if (bit_count < 3'd7) begin
                    miso_delay_counter <= 3'h4;  // Schedule miso update in 4 cycles
