            end
            // Handle cs_n going high - reset everything
            else if (cs_n_sync[1]) begin
                miso_out <= 1'b0;
                rx_valid_out <= 1'b0;
            end

            // Decrement delay counters
            if (miso_delay_counter > 0) begin
                miso_delay_counter <= miso_delay_counter - 1;
                if (miso_delay_counter == 1) begin
                    if (bit_count < 3'd7) begin
                        miso_out <= tx_shift_reg[6-bit_count];  // Next bit to send
                    end else begin
                        miso_out <= 1'b0;  // After sending 8 bits, output 0
                    end
                end
            end

            if (rx_update_counter > 0) begin
                rx_update_counter <= rx_update_counter - 1;
                if (rx_update_counter == 1) begin
                    rx_valid_out <= 1'b1;
                end else begin
                    rx_valid_out <= 1'b0;
                end
            end else begin
                rx_valid_out <= 1'b0;
            end
        end
    end

    // Assign outputs
    assign miso = cs_n_sync[1] ? 1'b0 : miso_out;
    assign rx_data = rx_shift_reg;
    assign rx_valid = rx_valid_out;

