                    rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[1]};
                    bit_count <= bit_count + 1'b1;

                    if (bit_count == 3'd7) begin  // Last bit received
                        rx_update_counter <= 3'd4;  // Schedule rx_valid for 4 cycles later
                    end
