                // On sclk falling edge - prepare next MISO bit
                else if (sclk_edge_detect == 3'b101) begin  // Falling edge of sclk
                    if (bit_count < 3'd7) begin
                        miso_delay_counter <= 3'd4;  // Schedule miso change for 4 cycles later
                    end
                    else if (bit_count == 3'd7) begin  // After sending last bit, go to 0
                        miso_delay_counter <= 3'd4;  // Schedule miso to 0 after 4 cycles
                    end
                end
            end

            // Update miso output after delay
            if (miso_delay_counter > 0) begin
                miso_delay_counter <= miso_delay_counter - 1'b1;
                if (miso_delay_counter == 1) begin
                    if (bit_count < 3'd7) begin
                        miso_out <= tx_shift_reg[6-bit_count];  // Next bit to send
                    end else begin
                        miso_out <= 1'b0;  // After 8 bits, output 0
