                end else begin
                    rx_valid_out <= 1'b0;
                end
            end else if (cs_n_edge_detect == 3'b101) begin  // Clear rx_valid on new transaction
                rx_valid_out <= 1'b0;
            end

            // Reset miso when cs_n is high
            if (cs_n_sync[1]) begin
                miso_out <= 1'b0;
            end
        end
    end

    // Output assignments
    assign miso = miso_out;
    assign rx_data = rx_shift_reg;
    assign rx_valid = rx_valid_out;

