                        // 如果收到了8位数据
                        if (bit_count == 3'd7) begin
                            // 更新rx_data
                            rx_data <= {rx_shift_reg[6:0], mosi_sync[0]};
                            // 产生rx_valid脉冲
                            rx_valid <= 1'b1;

                            // 重置位计数
                            bit_count <= 3'b0;
                            // 重新装载发送寄存器（准备下一字节）
                            tx_shift_reg <= tx_data;
                            // miso输出下一字节的最高位
                            miso <= tx_data[7];
                        end else begin
                            // 不是第8位，继续传输
