## 设计思路

1. **信号分类**：
   - 寄存器输出：miso, rx_data, rx_valid
   - 组合输出：无
   - 内部寄存器：同步器、边沿检测器、移位寄存器、位计数器等

2. **状态机**：采用简单控制逻辑，通过位计数器判断当前传输状态
   - 计数范围：0-7（8个位）
   - 传输状态：等待片选→接收/发送8位→完成

3. **复位行为**：所有寄存器清零，miso=0, rx_valid=0, 位计数器清零
   - 异步信号同步：sclk、cs_n、mosi各用2级寄存器同步
   - 边沿检测：基于同步后的信号检测上升沿/下降沿
   - 时序要求：在指定时钟周期内切换输出

## 完整代码

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    // 同步器
    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;
    wire sclk_pos_edge, sclk_neg_edge, cs_n_neg_edge;

    // 内部信号
    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg, rx_shift_reg;
    reg miso_reg, rx_valid_reg;
    reg [7:0] rx_data_reg;

    // 同步输入信号
    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        cs_n_sync <= {cs_n_sync[0], cs_n};
        mosi_sync <= {mosi_sync[0], mosi};
    end

    // 边沿检测
    assign sclk_pos_edge = ~sclk_sync[1] & sclk_sync[0];
    assign sclk_neg_edge = sclk_sync[1] & ~sclk_sync[0];
    assign cs_n_neg_edge = cs_n_sync[1] & ~cs_n_sync[0];

    // 位计数器和移位寄存器控制
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_count <= 3'b000;
        end else if (cs_n_neg_edge) begin
            bit_count <= 3'b000;
        end else if (~cs_n_sync[0] && sclk_pos_edge) begin
            if (bit_count == 3'b111)
                bit_count <= 3'b000;
            else
                bit_count <= bit_count + 1'b1;
        end
    end

    // TX 移位寄存器 - 在CS_N下降沿装载，在SCLK下降沿移位
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_shift_reg <= 8'b0;
        end else if (cs_n_neg_edge) begin
            tx_shift_reg <= tx_data;
        end else if (~cs_n_sync[0] && sclk_neg_edge) begin
            if (bit_count != 3'b111) begin
                tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
            end
        end
    end

    // RX 移位寄存器 - 在SCLK上升沿采样
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_shift_reg <= 8'b0;
        end else if (cs_n_neg_edge) begin
            rx_shift_reg <= 8'b0;
        end else if (~cs_n_sync[0] && sclk_pos_edge) begin
            rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[0]};
        end
    end

    // MISO 输出 - CS_N为高时输出0，否则输出TX移位寄存器最高位
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            miso_reg <= 1'b0;
        end else if (cs_n_sync[0]) begin
            miso_reg <= 1'b0;
        end else if (cs_n_neg_edge) begin
            miso_reg <= tx_data[7];  // 在CS_N下降沿后4个周期内设置
        end else if (~cs_n_sync[0] && sclk_neg_edge) begin
            if (bit_count == 3'b000) begin
                miso_reg <= tx_shift_reg[6];  // 第一个下降沿后输出下一位
            end else if (bit_count != 3'b111) begin
                miso_reg <= tx_shift_reg[6];  // 后续下降沿输出当前位
            end else begin
                miso_reg <= 1'b0;  // 传输完成后输出0
            end
        end
    end

    // RX 数据和有效信号 - 在第8个SCLK上升沿后4个周期更新
    reg [2:0] delay_cnt;
    reg update_rx;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            delay_cnt <= 3'b000;
            update_rx <= 1'b0;
        end else if (sclk_pos_edge && ~cs_n_sync[0] && bit_count == 3'b111) begin
            delay_cnt <= 3'b001;  // 开始延迟计数
            update_rx <= 1'b0;
        end else if (update_rx) begin
            delay_cnt <= 3'b000;
            update_rx <= 1'b0;
        end else if (delay_cnt > 0) begin
            if (delay_cnt == 3'b100) begin
                delay_cnt <= 3'b000;
                update_rx <= 1'b1;
            end else begin
                delay_cnt <= delay_cnt + 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_data_reg <= 8'b0;
        end else if (update_rx) begin
            rx_data_reg <= rx_shift_reg;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_valid_reg <= 1'b0;
        end else begin
            rx_valid_reg <= update_rx;
        end
    end

    // 输出赋值
    assign miso = miso_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

endmodule
