## 设计思路

1. **信号分类**：输入信号包括clk, rst_n, sclk, cs_n, mosi, tx_data；输出信号包括miso(寄存器), rx_data(寄存器), rx_valid(寄存器)。

2. **状态机**：采用状态机控制，包含IDLE(空闲), TRANSMIT(发送), RECEIVE(接收)等状态。使用3位位计数器(count[2:0])记录当前传输位(0-7)。

3. **同步处理**：对sclk, cs_n, mosi进行2级寄存器同步，然后检测边沿。设置同步后的信号为sclk_sync, cs_n_sync, mosi_sync及对应的边沿信号。

4. **时序控制**：使用计数器delay_cnt控制4个clk周期的延迟要求，确保在指定时机切换miso输出和更新rx_data。

## 完整代码

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    reg [1:0] cs_n_sync_reg;
    reg [1:0] sclk_sync_reg;
    reg [1:0] mosi_sync_reg;

    wire cs_n_pos_edge;
    wire sclk_pos_edge;
    wire sclk_neg_edge;

    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg miso_reg;
    reg [7:0] rx_data_reg;
    reg rx_valid_reg;

    reg [2:0] delay_cnt;
    reg state_load; // 检测到cs_n下降沿时置1，持续一个clk周期

    assign cs_n_pos_edge = ~cs_n_sync_reg[1] & cs_n_sync_reg[0];
    assign sclk_pos_edge = ~sclk_sync_reg[1] & sclk_sync_reg[0];
    assign sclk_neg_edge = sclk_sync_reg[1] & ~sclk_sync_reg[0];

    assign miso = miso_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

    // 同步输入信号
    always @(posedge clk) begin
        cs_n_sync_reg <= {cs_n_sync_reg[0], cs_n};
        sclk_sync_reg <= {sclk_sync_reg[0], sclk};
        mosi_sync_reg <= {mosi_sync_reg[0], mosi};
    end

    // 检测cs_n下降沿并生成单周期pulse
    reg cs_n_prev;
    always @(posedge clk) begin
        cs_n_prev <= cs_n_sync_reg[0];
        state_load <= (~cs_n_sync_reg[0] & cs_n_prev); // cs_n下降沿
    end

    // 主要逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            bit_count <= 3'b000;
            tx_shift_reg <= 8'b0;
            rx_shift_reg <= 8'b0;
            miso_reg <= 1'b0;
            rx_data_reg <= 8'b0;
            rx_valid_reg <= 1'b0;
            delay_cnt <= 3'b000;
        end else begin
            // 默认值
            rx_valid_reg <= 1'b0;

            // 检测cs_n下降沿，装载数据
            if (state_load) begin
                tx_shift_reg <= tx_data;
                bit_count <= 3'b000;
                delay_cnt <= 3'b000;
                miso_reg <= tx_data[7]; // 4个clk内输出最高位
            end

            // 如果cs_n为低，处理SPI通信
            if (!cs_n_sync_reg[0]) begin
                // sclk上升沿 - 采样MOSI
                if (sclk_pos_edge) begin
                    rx_shift_reg[7-bit_count] <= mosi_sync_reg[0];

                    if (bit_count == 3'd7) begin
                        // 第8位采样完成后，准备更新rx_data
                        delay_cnt <= 3'd1; // 开始4周期延迟
                    end else begin
                        bit_count <= bit_count + 1'b1;
                    end
                end

                // sclk下降沿 - 准备输出下一位
                if (sclk_neg_edge) begin
                    if (bit_count < 3'd7) begin
                        delay_cnt <= 3'd1; // 开始4周期延迟
                    end
                end

                // 延迟计数器处理
                if (delay_cnt > 0 && delay_cnt < 4) begin
                    delay_cnt <= delay_cnt + 1'b1;
                end else if (delay_cnt == 4) begin
                    // 4个周期延迟完成
                    if (sclk_neg_edge && bit_count < 3'd7) begin
                        miso_reg <= tx_shift_reg[6-bit_count]; // 输出下一位
                    end

                    if (bit_count == 3'd7 && sclk_pos_edge) begin
                        // 第8位接收完成，更新rx_data并产生valid脉冲
                        rx_data_reg <= rx_shift_reg;
                        rx_valid_reg <= 1'b1;
                        bit_count <= 3'b000; // 准备下一字节
                        tx_shift_reg <= tx_data; // 装载新数据
                        miso_reg <= tx_data[7]; // 输出新字节的最高位
                    end

                    if (sclk_neg_edge && bit_count < 3'd7) begin
                        bit_count <= bit_count + 1'b1;
                    end

                    delay_cnt <= 3'd0;
                end
            end else begin
                // cs_n为高，重置状态
                miso_reg <= 1'b0;
                bit_count <= 3'b000;
                delay_cnt <= 3'd0;
            end

            // 如果cs_n变高且未完成8位传输，则丢弃当前数据
            if (!cs_n_sync_reg[0] && cs_n_sync_reg[1] && bit_count != 0 && bit_count != 7) begin
                bit_count <= 3'b000;
                delay_cnt <= 3'd0;
            end
        end
    end

endmodule
