                    miso <= tx_shift_reg[6];  // 输出下一位
                    tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};  // 左移
                end else begin
                    miso <= 1'b0;  // 最后一位发送完成后输出0
                end
            end

            // 保持rx_valid为一个周期
            if (rx_valid)
                rx_valid <= 1'b0;
        end
    end

