## 设计思路

1. **信号分类**：
   - 寄存器输出：miso, rx_data, rx_valid
   - 组合输出：无
   - 内部寄存器：同步器、边沿检测器、移位寄存器、位计数器

2. **状态机**：采用简单的控制逻辑，通过位计数器判断当前状态
   - 计数范围：0-7，表示当前传输的位位置

3. **关键设计**：
   - 2级同步器处理异步SPI信号
   - 边沿检测基于同步后信号
   - cs_n下降沿装载tx_data并清零位计数器
   - sclk上升沿采样mosi，下降沿切换miso输出
   - 第8位接收完成后产生rx_valid脉冲

4. **时序要求**：
   - 4个clk周期延迟实现miso切换和rx_valid输出
   - 异步信号2级同步确保时序安全

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output reg miso,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg rx_valid
);

    // 同步器
    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;
    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        cs_n_sync <= {cs_n_sync[0], cs_n};
        mosi_sync <= {mosi_sync[0], mosi};
    end

    // 边沿检测
    wire sclk_pos_edge = ~sclk_sync[1] & sclk_sync[0];
    wire sclk_neg_edge = sclk_sync[1] & ~sclk_sync[0];
    wire cs_n_neg_edge = cs_n_sync[1] & ~cs_n_sync[0];

    // 控制信号
    reg [2:0] bit_cnt;
    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg cs_active;

    // 4周期延迟控制
    reg [3:0] delay_cnt;
    reg load_tx, sample_rx, update_miso, valid_pulse;

    always @(posedge clk) begin
        if (!rst_n) begin
            cs_active <= 1'b0;
            bit_cnt <= 3'b0;
            rx_valid <= 1'b0;
            miso <= 1'b0;
            delay_cnt <= 4'h0;
            load_tx <= 1'b0;
            sample_rx <= 1'b0;
            update_miso <= 1'b0;
            valid_pulse <= 1'b0;
        end else begin
            // 检测片选变化
            if (cs_n_neg_edge) begin
                cs_active <= 1'b1;
                bit_cnt <= 3'b0;
                load_tx <= 1'b1;  // 标记需要加载tx_data
                delay_cnt <= 4'h1;  // 开始4周期延迟
            end else if (~cs_n_sync[0]) begin  // cs_n为低，SPI通信进行中
                if (sclk_pos_edge && cs_active) begin
                    sample_rx <= 1'b1;  // 标记需要采样mosi
                    bit_cnt <= bit_cnt + 1'b1;
                    if (bit_cnt == 3'd7) begin  // 第8个上升沿后，准备产生valid
                        valid_pulse <= 1'b1;
                        delay_cnt <= 4'h1;
                        bit_cnt <= 3'b0;  // 准备下一字节
                    end else begin
                        delay_cnt <= 4'h1;
                    end
                end else if (sclk_neg_edge && cs_active) begin
                    update_miso <= 1'b1;  // 标记需要更新miso
                    delay_cnt <= 4'h1;
                end
            end else begin  // cs_n为高，结束当前传输
                cs_active <= 1'b0;
                bit_cnt <= 3'b0;
                rx_valid <= 1'b0;
                miso <= 1'b0;
                load_tx <= 1'b0;
                sample_rx <= 1'b0;
                update_miso <= 1'b0;
                valid_pulse <= 1'b0;
            end

            // 延迟控制逻辑
            if (delay_cnt > 0 && delay_cnt < 4) begin
                delay_cnt <= delay_cnt + 1;
            end else if (delay_cnt == 4) begin
                delay_cnt <= 4'h0;
                if (load_tx) begin
                    tx_shift_reg <= tx_data;
                    miso <= tx_data[7];
                    load_tx <= 1'b0;
                end
                if (sample_rx) begin
                    rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[0]};
                    sample_rx <= 1'b0;
                end
                if (update_miso) begin
                    if (bit_cnt < 7) begin
                        miso <= tx_shift_reg[6-bit_cnt];
                    end else begin
                        miso <= 1'b0;  // 最后一位发送完后输出0
                    end
                    update_miso <= 1'b0;
                end
                if (valid_pulse) begin
                    rx_data <= rx_shift_reg;
                    rx_valid <= 1'b1;
                    valid_pulse <= 1'b0;
                end
            end else if (delay_cnt == 0 && !valid_pulse) begin
                rx_valid <= 1'b0;
            end
        end
    end

