```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output reg miso,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg rx_valid
);

    // 同步寄存器
    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;

    // 内部信号
    wire sclk_pos_edge, sclk_neg_edge, cs_n_neg_edge;
    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg, rx_shift_reg;
    reg cs_active;

    // 同步输入信号
    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        cs_n_sync <= {cs_n_sync[0], cs_n};
        mosi_sync <= {mosi_sync[0], mosi};
    end

    // 边沿检测
    assign sclk_pos_edge = ~sclk_sync[1] & sclk_sync[0];
    assign sclk_neg_edge = sclk_sync[1] & ~sclk_sync[0];
    assign cs_n_neg_edge = cs_n_sync[1] & ~cs_n_sync[0];

    // 主逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            miso <= 1'b0;
            rx_data <= 8'b0;
            rx_valid <= 1'b0;
            bit_count <= 3'b0;
            tx_shift_reg <= 8'b0;
            rx_shift_reg <= 8'b0;
            cs_active <= 1'b0;
        end else begin
            // 检测片选下降沿
            if (cs_n_neg_edge) begin
                cs_active <= 1'b1;
                tx_shift_reg <= tx_data;
                bit_count <= 3'b0;
                rx_shift_reg <= 8'b0;
                rx_valid <= 1'b0;
                // 在4个周期内设置miso为tx_data[7]
                miso <= tx_data[7];
            end else if (!cs_n_sync[0]) begin // cs_n为低，SPI通信进行中
                // 发送：在sclk下降沿后4个周期切换到下一位
                if (sclk_neg_edge) begin
                    if (bit_count < 3'd7) begin
                        bit_count <= bit_count + 1'b1;
                        miso <= tx_shift_reg[6]; // 设置下一位
                        tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
                    end else begin
                        bit_count <= 3'b0;
                        miso <= 1'b0; // 8位发完后输出0
                        tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
                    end
                end

                // 接收：在sclk上升沿采样mosi
                if (sclk_pos_edge) begin
                    rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[0]};

                    if (bit_count == 3'd7) begin // 第8个上升沿后处理接收完成
                        rx_data <= {rx_shift_reg[6:0], mosi_sync[0]};
                        rx_valid <= 1'b1;
                    end else begin
                        rx_valid <= 1'b0;
                    end
                end else if (bit_count != 3'd7 || !sclk_pos_edge) begin
                    rx_valid <= 1'b0;
                end
            end else begin // cs_n为高，停止通信
                cs_active <= 1'b0;
                miso <= 1'b0;
                rx_valid <= 1'b0;
            end

            // 如果cs_n在接收过程中被拉高，则取消当前传输
            if (cs_n_sync[0] && cs_active && bit_count != 0 && bit_count != 3'd7) begin
                cs_active <= 1'b0;
                miso <= 1'b0;
                rx_valid <= 1'b0;
                bit_count <= 3'b0;
            end
        end
    end

