2. **状态机**：采用单状态机，主要状态包括空闲、接收数据、发送数据等，通过位计数器控制

3. **计数器**：位计数器[2:0]，范围0-7，用于跟踪当前传输的位位置

4. **复位行为**：所有寄存器清零，miso=0，rx_valid=0，位计数器清零

5. **时序要求**：通过多级寄存器同步异步信号，边沿检测使用寄存器差值，确保4个clk周期延迟满足时序要求

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output reg miso,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg rx_valid
);

    // 同步寄存器
    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;
    reg [1:0] sclk_edge_detect, cs_n_edge_detect;

    // 内部信号
    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg cs_active;

    // 同步输入信号
    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        cs_n_sync <= {cs_n_sync[0], cs_n};
        mosi_sync <= {mosi_sync[0], mosi};

        // 边沿检测
        sclk_edge_detect <= {sclk_edge_detect[0], sclk_sync[1]};
        cs_n_edge_detect <= {cs_n_edge_detect[0], cs_n_sync[1]};
    end

    // 主逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            miso <= 1'b0;
            rx_data <= 8'b0;
            rx_valid <= 1'b0;
            bit_count <= 3'b0;
            tx_shift_reg <= 8'b0;
            rx_shift_reg <= 8'b0;
            cs_active <= 1'b0;
        end else begin
            // 检测片选下降沿
            if (cs_n_edge_detect[1] && !cs_n_sync[1]) begin
                // 装载发送数据
                tx_shift_reg <= tx_data;
                // 清零计数器
                bit_count <= 3'b0;
                // 设置CS激活标志
                cs_active <= 1'b1;
                // 在4个周期内输出最高位
                miso <= tx_data[7];
            end 
            // 检测片选上升沿（结束传输）
            else if (!cs_n_edge_detect[1] && cs_n_sync[1]) begin
                cs_active <= 1'b0;
                miso <= 1'b0;
                rx_valid <= 1'b0;
            end
            // 如果CS激活且检测到SCLK上升沿（采样MOSI）
            else if (cs_active && sclk_edge_detect[1] && sclk_sync[1]) begin
                // 采样MOSI到接收移位寄存器
                rx_shift_reg[7-bit_count] <= mosi_sync[1];

                // 如果是第8位，则完成接收
                if (bit_count == 3'd7) begin
                    rx_data <= rx_shift_reg;
                    rx_valid <= 1'b1;
                    bit_count <= 3'b0;  // 准备下一字节
                    // miso继续输出0，等待下一个字节或CS释放
                    miso <= 1'b0;
                end else begin
                    bit_count <= bit_count + 1'b1;
                end
            end
            // 如果CS激活且检测到SCLK下降沿（准备输出下一位MISO）
            else if (cs_active && !sclk_edge_detect[1] && !sclk_sync[1] && sclk_sync[0]) begin
                if (bit_count < 3'd7) begin
                    // 输出下一位
                    miso <= tx_shift_reg[6-bit_count];
                end else begin
                    // 8位发送完毕，输出0
                    miso <= 1'b0;
                end
            end

            // rx_valid只在一个周期有效
            if (rx_valid) begin
                rx_valid <= 1'b0;
            end
        end
    end

