            // 在cs_n下降沿后4个周期设置miso
            if (state_change && delay_cnt == 3'd3 && cs_n_sync[1] == 1'b0) begin
                miso <= tx_shift_reg[7];
            end

            // sclk上升沿采样mosi
            if (sclk_posedge && cs_n_sync[1] == 1'b0) begin
                rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[1]};
                bit_cnt <= bit_cnt + 1'b1;

                // 第8位接收完成
                if (bit_cnt == 3'd7) begin
                    rx_data <= {rx_shift_reg[6:0], mosi_sync[1]};
                    rx_valid <= 1'b1;
                    delay_active <= 1'b1;
                    delay_cnt <= 3'b0;
                    bit_cnt <= 3'b0; // 准备下一字节
                end else begin
                    rx_valid <= 1'b0;
                end
            end else if (delay_active && delay_cnt == 3'd3 && bit_cnt == 3'd7) begin
                // 清除rx_valid
                rx_valid <= 1'b0;
            end else if (cs_n_sync[1]) begin
                // cs_n为高时清除rx_valid
                rx_valid <= 1'b0;
            end

            // sclk下降沿切换miso
            if (sclk_negedge && cs_n_sync[1] == 1'b0) begin
                if (bit_cnt < 3'd7) begin
                    miso <= tx_shift_reg[6]; // 下一位
                    tx_shift_reg <= {tx_shift_reg[6:0], 1'b0}; // 左移
                end else begin
                    miso <= 1'b0; // 8位发完后输出0
                end
            end

            // cs_n为高时miso输出0
            if (cs_n_sync[1]) begin
                miso <= 1'b0;
            end
        end
    end

