            if (cs_n_edge[0] && !cs_n_sync[1]) begin
                tx_shift_reg <= tx_data;
                bit_count <= 3'b0;
                rx_shift_reg <= 8'b0;
                rx_valid <= 1'b0;
                // 在4个clk内设置miso为tx_data[7]
                miso <= tx_data[7];
