                    if (bit_count == 3'd7) begin
                        rx_data <= {rx_shift_reg[6:0], mosi_sync[1]};
                        rx_valid <= 1'b1;
                        bit_count <= 3'b0; // 准备下一字节
                        rx_shift_reg <= 8'b0;
                    end else begin
                        rx_valid <= 1'b0;
                    end
                end

                // sclk下降沿后4个clk内切换miso输出下一位
                if (sclk_edge[0] && !sclk_sync[1]) begin
                    if (bit_count < 3'd7) begin
                        miso <= tx_shift_reg[6]; // 输出下一位
                        tx_shift_reg <= {tx_shift_reg[6:0], 1'b0}; // 左移
                    end else begin
                        miso <= 1'b0; // 8位发送完毕后输出0
                    end
                end
            end
        end
    end

