   - 边沿检测基于同步后的信号
   - miso在cs_n下降沿后3个clk内切换到tx_data[7]
   - rx_valid在第8位接收完成后1个clk周期内置高

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output reg miso,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg rx_valid
);

    // 同步器
    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;

    // 边沿检测
    reg sclk_pos_edge, cs_n_neg_edge;

    // 内部信号
    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg;
    reg [7:0] rx_shift_reg;
    reg cs_n_prev;

    // 同步异步信号
    always @(posedge clk) begin
        sclk_sync <= {sclk_sync[0], sclk};
        cs_n_sync <= {cs_n_sync[0], cs_n};
        mosi_sync <= {mosi_sync[0], mosi};

        cs_n_prev <= cs_n_sync[1];

        // 边沿检测
        sclk_pos_edge <= (sclk_sync[1] == 0 && sclk_sync[0] == 1);
        cs_n_neg_edge <= (cs_n_prev == 1 && cs_n_sync[1] == 0);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            miso <= 1'b0;
            rx_data <= 8'b0;
            rx_valid <= 1'b0;
            bit_count <= 3'b0;
            tx_shift_reg <= 8'b0;
            rx_shift_reg <= 8'b0;
        end else begin
            // 检测片选下降沿
            if (cs_n_neg_edge) begin
                tx_shift_reg <= tx_data;
                bit_count <= 3'b0;
                rx_shift_reg <= 8'b0;
                rx_valid <= 1'b0;
                miso <= tx_data[7];  // 在cs_n下降沿后设置miso
            end else if (!cs_n_sync[1]) begin  // cs_n为低，SPI通信进行中
                // 发送：在sclk下降沿后更新miso
                if (sclk_sync[1] == 1 && sclk_sync[0] == 0) begin
                    if (bit_count < 3'd7) begin
                        miso <= tx_shift_reg[6:0] << 1;  // 准备下一位
                    end else begin
                        miso <= 1'b0;  // 8位发送完毕后输出0
                    end
                end

                // 接收：在sclk上升沿采样mosi
                if (sclk_pos_edge) begin
                    rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[1]};
                    bit_count <= bit_count + 1'b1;

                    // 更新发送寄存器（准备下一位发送）
                    tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};

                    // 第8位接收完成
                    if (bit_count == 3'd7) begin
                        rx_data <= {rx_shift_reg[6:0], mosi_sync[1]};
                        rx_valid <= 1'b1;
                        bit_count <= 3'b0;  // 重置位计数器，准备下一字节
                        tx_shift_reg <= tx_data;  // 装载新数据
                        miso <= tx_data[7];  // 开始发送新字节的第一位
                    end else begin
                        rx_valid <= 1'b0;
                    end
                end else if (bit_count == 3'd7) begin
                    // 如果不是sclk上升沿但已经完成了8位传输，清除rx_valid
                    rx_valid <= 1'b0;
                end
            end else begin  // cs_n为高，停止通信
                miso <= 1'b0;
                rx_valid <= 1'b0;
                bit_count <= 3'b0;
            end
        end
    end

endmodule
