module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data_r;
    reg valid_r, err_r;
    assign data = data_r;
    assign valid = valid_r;
    assign err = err_r;

    // 同步器
    reg ps2_clk_sync, ps2_data_sync;
    reg ps2_clk_sync_d;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 1'b1;
            ps2_data_sync <= 1'b1;
        end else begin
            ps2_clk_sync <= ps2_clk;
            ps2_data_sync <= ps2_data;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync_d <= 1'b1;
        end else begin
            ps2_clk_sync_d <= ps2_clk_sync;
        end
    end

    wire ps2_clk_negedge = !ps2_clk_sync & ps2_clk_sync_d;

    // 状态机
    parameter IDLE = 3'd0,
              START = 3'd1,
              BIT0 = 3'd2,
              BIT1 = 3'd3,
              BIT2 = 3'd4,
              BIT3 = 3'd5,
              BIT4 = 3'd6,
              BIT5 = 3'd7,
              BIT6 = 3'd8,
              BIT7 = 3'd9,
              PARITY = 3'd10,
              STOP = 3'd11;

    reg [3:0] state;
    reg [3:0] next_state;

    // 计数器和寄存器
    reg [7:0] shift_reg;
    reg parity_bit;
    reg [TIMEOUT+3:0] timeout_counter;
    reg [3:0] bit_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            shift_reg <= 8'h0;
            parity_bit <= 1'b0;
            timeout_counter <= {(TIMEOUT+4){1'b0}};
            bit_count <= 4'h0;
            data_r <= 8'h0;
            valid_r <= 1'b0;
            err_r <= 1'b0;
        end else begin
            state <= next_state;
            valid_r <= 1'b0;
            err_r <= 1'b0;

            if (ps2_clk_negedge) begin
                timeout_counter <= 0;
                case (state)
                    IDLE: begin
                        if (ps2_data_sync == 1'b0) begin  // 起始位
                            next_state <= START;
                            shift_reg <= 8'h0;
                            parity_bit <= 1'b0;
                            bit_count <= 4'h0;
                        end else begin
                            next_state <= IDLE;
                        end
                    end
                    START: begin
                        next_state <= BIT0;
                    end
                    BIT0: begin
                        shift_reg[0] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT1;
                    end
                    BIT1: begin
                        shift_reg[1] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT2;
                    end
                    BIT2: begin
                        shift_reg[2] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT3;
                    end
                    BIT3: begin
                        shift_reg[3] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT4;
                    end
                    BIT4: begin
                        shift_reg[4] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT5;
                    end
                    BIT5: begin
                        shift_reg[5] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT6;
                    end
                    BIT6: begin
                        shift_reg[6] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= BIT7;
                    end
                    BIT7: begin
                        shift_reg[7] <= ps2_data_sync;
                        parity_bit <= parity_bit ^ ps2_data_sync;
                        next_state <= PARITY;
                    end
                    PARITY: begin
                        // 检查奇校验
                        if ((parity_bit ^ ps2_data_sync) == 1'b1) begin
                            next_state <= STOP;  // 校验正确
                        end else begin
                            next_state <= IDLE;  // 校验错误
                            err_r <= 1'b1;
                        end
                    end
                    STOP: begin
                        if (ps2_data_sync == 1'b1) begin  // 停止位正确
                            data_r <= shift_reg;
                            valid_r <= 1'b1;
                            next_state <= IDLE;
                        end else begin  // 停止位错误
                            err_r <= 1'b1;
                            next_state <= IDLE;
                        end
                    end
                    default: next_state <= IDLE;
                endcase
            end else begin
                timeout_counter <= timeout_counter + 1;
                if (timeout_counter >= TIMEOUT) begin
                    next_state <= IDLE;
                    err_r <= 1'b1;
                end
            end
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = IDLE;
            default: next_state = state;
        endcase
    end

endmodule
