    wire ps2_clk_negedge;

    // 状态机和计数器
    reg [3:0] bit_count;  // 0-10 表示接收第0-10位
    reg [7:0] shift_reg;
    reg [TIMEOUT:0] timeout_counter;
    reg [2:0] state;  // 0-idle, 1-wait_start, 2-receive_bits

    // 同步输入
    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync <= 1'b1;
            ps2_clk_sync2 <= 1'b1;
            ps2_data_sync <= 1'b1;
            ps2_data_sync2 <= 1'b1;
        end else begin
            ps2_clk_sync <= ps2_clk;
            ps2_clk_sync2 <= ps2_clk_sync;
            ps2_data_sync <= ps2_data;
            ps2_data_sync2 <= ps2_data_sync;
        end
    end

    // 检测PS2时钟下降沿
    always @(posedge clk) begin
        if (!rst_n)
            ps2_clk_prev <= 1'b1;
        else
            ps2_clk_prev <= ps2_clk_sync2;
    end

    assign ps2_clk_negedge = ps2_clk_prev & ~ps2_clk_sync2;

    // 超时计数器
    always @(posedge clk) begin
        if (!rst_n)
            timeout_counter <= 0;
        else if (state == 0)  // idle状态
            timeout_counter <= 0;
        else if (ps2_clk_negedge)
            timeout_counter <= 0;
        else
            timeout_counter <= timeout_counter + 1'b1;
    end

    // 主状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= 0;
            bit_count <= 0;
            shift_reg <= 0;
            data_reg <= 0;
            valid_reg <= 0;
            err_reg <= 0;
        end else begin
            valid_reg <= 0;
            err_reg <= 0;

            case (state)
                0: begin  // idle - 等待起始位
                    if (ps2_clk_negedge && ps2_data_sync2 == 0) begin  // 检测到起始位(0)
                        state <= 2;  // 直接进入接收状态
                        bit_count <= 9;  // 还需接收9位 (8数据+1校验)
                        shift_reg <= 0;
                    end
                end

                2: begin  // 接收位
                    if (ps2_clk_negedge) begin
                        shift_reg <= {ps2_data_sync2, shift_reg[7:1]};
                        bit_count <= bit_count - 1;

                        if (bit_count == 0) begin  // 已接收完9位数据+校验位
                            // 现在等待停止位
                            if (~ps2_clk_sync2) begin  // 如果当前时钟仍为低，等待下一个边沿来读停止位
                                // 等待停止位的边沿
                            end else begin
                                // 当前处于高电平，下一个下降沿将采样停止位
                                state <= 3;  // 转到检查停止位状态
                                bit_count <= 0;  // 标记已接收完数据
                            end
                        end
                    end
                end

                3: begin  // 检查停止位
                    if (ps2_clk_negedge) begin
                        // 此时ps2_data_sync2是停止位
                        if (ps2_data_sync2 != 1) begin  // 停止位应该是1
                            err_reg <= 1;
                            state <= 0;
                        end else begin
                            // 验证奇校验
                            // shift_reg[0]是校验位，shift_reg[7:1]是数据位
                            reg parity_ok;
                            parity_ok = shift_reg[0];  // 校验位
                            integer i;
                            for (i = 1; i <= 8; i = i + 1) begin
                                parity_ok = parity_ok ^ shift_reg[i-1];
                            end

                            if (parity_ok) begin  // 奇校验正确
                                data_reg <= {shift_reg[0], shift_reg[6:0]};  // 数据位是后8位
                                valid_reg <= 1;
                            end else begin  // 奇校验错误
                                err_reg <= 1;
                            end
                            state <= 0;
                        end
                    end
                end
            endcase

            // 超时处理
            if (timeout_counter > TIMEOUT) begin
                state <= 0;
                err_reg <= 1;
            end
        end
    end

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

