            state <= IDLE;
            bit_cnt <= 4'd0;
            frame_reg <= 11'd0;
            timeout_cnt <= {(TIMEOUT+6){1'b0}};
            start_flag <= 1'b0;
            data_reg <= 8'd0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
        end else begin
            valid_reg <= 1'b0;
            err_reg <= 1'b0;

