                        state <= RECEIVING;
                        bit_cnt <= 4'd0;
                        frame_reg <= 11'd0;
                        timeout_cnt <= {(TIMEOUT+6){1'b0}};
                        start_flag <= 1'b1;
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_edge) begin
                        frame_reg[bit_cnt] <= ps2_data_sync2;
                        bit_cnt <= bit_cnt + 1'd1;
                        timeout_cnt <= {(TIMEOUT+6){1'b0}};

                        if (bit_cnt == 4'd9) begin // Received 10 bits (start + 8 data + parity)
                            state <= CHECKING;
                        end
