    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data_reg;
    reg valid_reg;
    reg err_reg;

    // 同步输入信号
    reg ps2_clk_sync, ps2_clk_sync1;
    reg ps2_data_sync, ps2_data_sync1;

    // 采样边沿检测
    wire ps2_clk_negedge;
    assign ps2_clk_negedge = ps2_clk_sync1 & ~ps2_clk_sync;

    // 状态机
    parameter IDLE = 3'd0,
              START = 3'd1,
              DATA = 3'd2,
              PARITY = 3'd3,
              STOP = 3'd4,
              TIMEOUT_STATE = 3'd5;

    reg [2:0] state, next_state;

    // 计数器
    reg [7:0] bit_count;
    reg [7:0] timeout_count;

    // 数据移位寄存器和校验
    reg [9:0] frame_data;  // [0]: parity, [1]: stop, [2-9]: data, [10]: start
    reg [3:0] parity_count;

    // 同步输入
    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync <= 1'b1;
            ps2_clk_sync1 <= 1'b1;
            ps2_data_sync <= 1'b0;
            ps2_data_sync1 <= 1'b0;
        end else begin
            ps2_clk_sync <= ps2_clk;
            ps2_clk_sync1 <= ps2_clk_sync;
            ps2_data_sync <= ps2_data;
            ps2_data_sync1 <= ps2_data_sync;
        end
    end

    // 状态转移
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // 计数器逻辑
    always @(posedge clk) begin
        if (!rst_n || state == IDLE) begin
            bit_count <= 8'd0;
            timeout_count <= 8'd0;
        end else if (state != TIMEOUT_STATE) begin
            if (ps2_clk_negedge) begin
                bit_count <= bit_count + 1'b1;
                timeout_count <= 8'd0;
            end else begin
                timeout_count <= timeout_count + 1'b1;
            end
        end
    end

    // 帧数据移位
    always @(posedge clk) begin
        if (!rst_n || state == IDLE) begin
            frame_data <= 10'd0;
        end else if (state != TIMEOUT_STATE && ps2_clk_negedge) begin
            frame_data <= {ps2_data_sync1, frame_data[9:1]};
        end
    end

    // 校验计算
    integer i;
    always @(*) begin
        parity_count = 4'd0;
        for (i = 0; i < 8; i = i + 1) begin
            parity_count = parity_count + frame_data[i+2];
        end
        parity_count = parity_count + frame_data[0];  // Include parity bit in count to check odd parity
    end

    // 状态机逻辑
    always @(*) begin
        case (state)
            IDLE: begin
                if (ps2_clk_negedge && !ps2_data_sync1)  // Start bit is 0
                    next_state = START;
                else
                    next_state = IDLE;
            end

            START: begin
                if (bit_count == 6)  // Sampled start bit
                    next_state = DATA;
                else if (timeout_count >= TIMEOUT)
                    next_state = TIMEOUT_STATE;
                else
                    next_state = START;
            end

            DATA: begin
                if (bit_count == 10)  // Sampled all 8 data bits
                    next_state = PARITY;
                else if (timeout_count >= TIMEOUT)
                    next_state = TIMEOUT_STATE;
                else
                    next_state = DATA;
            end

            PARITY: begin
                if (bit_count == 11)  // Sampled parity bit
                    next_state = STOP;
                else if (timeout_count >= TIMEOUT)
                    next_state = TIMEOUT_STATE;
                else
                    next_state = PARITY;
            end

            STOP: begin
                if (bit_count == 12) begin  // Sampled stop bit
                    if (frame_data[1] == 1'b1)  // Stop bit should be 1
                        next_state = IDLE;  // Valid frame
                    else
                        next_state = IDLE;  // Invalid stop bit
                end else if (timeout_count >= TIMEOUT)
                    next_state = TIMEOUT_STATE;
                else
                    next_state = STOP;
            end

            TIMEOUT_STATE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // 输出逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            data_reg <= 8'd0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
        end else begin
            valid_reg <= 1'b0;
            err_reg <= 1'b0;

            if (state == STOP && bit_count == 12) begin
                if (frame_data[1] == 1'b1) begin  // Valid stop bit
                    // Check odd parity - total number of 1s in data + parity bit should be odd
                    if (parity_count[0] == 1'b1) begin  // Odd parity correct
                        data_reg <= frame_data[9:2];
                        valid_reg <= 1'b1;
                    end else begin  // Parity error
                        err_reg <= 1'b1;
                    end
                end else begin  // Stop bit error
                    err_reg <= 1'b1;
                end
            end else if (state == TIMEOUT_STATE) begin
                err_reg <= 1'b1;
            end
        end
    end

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

