                PARITY: begin
                    if (ps2_clk_negedge) begin
                        // 检查奇校验
                        // 奇校验：数据位和校验位总和为奇数
                        if ((parity_count[0] ^ ps2_data_sync1) == 1'b0) begin  // 校验失败
