## 设计思路

1. **信号分析**：
   - 输入：clk(1bit), rst_n(1bit), ps2_clk(1bit), ps2_data(1bit)
   - 输出：data[7:0](8bit寄存器), valid(1bit组合), err(1bit组合)

2. **状态机设计**：
   - IDLE: 等待起始位(0)
   - RECEIVING: 接收11位数据(起始位+8数据位+奇校验+停止位)
   - 状态转移：IDLE→RECEIVING(检测到起始位)→IDLE(接收完成或超时)
   - 计数器：位计数器[3:0]范围0-10，超时计数器[TIMEOUT_BITS-1:0]

3. **复位行为**：异步复位，输出清零，状态机回到IDLE

4. **时序要求**：在ps2_clk下降沿采样数据，保持输出valid/err为1个系统时钟周期

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data_r;
    reg valid_r, err_r;
    reg [3:0] bit_cnt;
    reg [9:0] timeout_cnt; // Assuming max TIMEOUT fits in 10 bits
    reg ps2_clk_d, ps2_clk_dd;
    reg ps2_data_d, ps2_data_dd;
    reg [3:0] state;

    parameter IDLE = 0, RECEIVING = 1;

    assign data = data_r;
    assign valid = valid_r;
    assign err = err_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_r <= 8'b0;
            valid_r <= 1'b0;
            err_r <= 1'b0;
            bit_cnt <= 4'b0;
            timeout_cnt <= 10'b0;
            ps2_clk_d <= 1'b0;
            ps2_clk_dd <= 1'b0;
            ps2_data_d <= 1'b0;
            ps2_data_dd <= 1'b0;
            state <= IDLE;
        end else begin
            ps2_clk_d <= ps2_clk;
            ps2_clk_dd <= ps2_clk_d;
            ps2_data_d <= ps2_data;
            ps2_data_dd <= ps2_data_d;

            valid_r <= 1'b0;
            err_r <= 1'b0;

            case (state)
                IDLE: begin
                    if (~ps2_clk_dd & ps2_clk_d) begin // Falling edge of PS2 clock
                        if (~ps2_data_d) begin // Start bit is 0
                            bit_cnt <= 4'd0;
                            timeout_cnt <= 10'd1;
                            state <= RECEIVING;
                        end
                    end else begin
                        timeout_cnt <= 10'd0;
                    end
                end

                RECEIVING: begin
                    if (~ps2_clk_dd & ps2_clk_d) begin // Falling edge of PS2 clock
                        if (bit_cnt < 4'd10) begin
                            if (bit_cnt >= 4'd1 && bit_cnt <= 4'd8) begin // Data bits (LSB first)
                                data_r[bit_cnt-1] <= ps2_data_d;
                            end
                            bit_cnt <= bit_cnt + 1'b1;
                            timeout_cnt <= 10'd1;
                        end else if (bit_cnt == 4'd10) begin // Stop bit check
                            // Check stop bit (should be 1) and parity
                            if (ps2_data_d) begin // Stop bit is 1
                                // Calculate parity (odd parity - total 1s should be odd)
                                reg parity_ok;
                                parity_ok = ~(^data_r ^ ps2_data_dd); // ps2_data_dd is the parity bit

                                if (parity_ok) begin
                                    valid_r <= 1'b1;
                                end else begin
                                    err_r <= 1'b1;
                                end
                            end else begin
                                err_r <= 1'b1; // Stop bit error
                            end
                            state <= IDLE;
                        end
