                        if (timeout_cnt < TIMEOUT) begin
                            timeout_cnt <= timeout_cnt + 1'b1;
                        end else begin
                            err_r <= 1'b1;
                            state <= IDLE;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

