## 设计思路

1. **信号分析**：
   - 输入：clk(1bit), rst_n(1bit), ps2_clk(1bit), ps2_data(1bit)
   - 输出：data[7:0](8bit寄存器), valid(1bit组合), err(1bit组合)

2. **状态机**：IDLE→START→RECEIVE_BITS(0-9)→CHECK_PARITY→STOP
   - 计数器：位计数器[3:0]范围0-10，超时计数器[7:0]范围0-TIMEOUT

3. **复位行为**：所有寄存器清零，回到IDLE状态；valid和err为组合输出，根据当前状态产生脉冲

## 完整代码

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [3:0] bit_cnt;
    reg [7:0] timeout_cnt;
    reg [7:0] rx_data_reg;
    reg [7:0] data_out;
    reg valid_reg, err_reg;
    reg ps2_clk_sync, ps2_clk_sync2;
    reg ps2_data_sync, ps2_data_sync2;
    reg start_flag;
    reg parity_check;

    wire ps2_clk_negedge;
    wire timeout_occurred;

    // 同步PS2信号
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 1'b1;
            ps2_clk_sync2 <= 1'b1;
            ps2_data_sync <= 1'b1;
            ps2_data_sync2 <= 1'b1;
        end else begin
            ps2_clk_sync <= ps2_clk;
            ps2_clk_sync2 <= ps2_clk_sync;
            ps2_data_sync <= ps2_data;
            ps2_data_sync2 <= ps2_data_sync;
        end
    end

    assign ps2_clk_negedge = ps2_clk_sync2 & ~ps2_clk_sync;

    // 超时检测
    assign timeout_occurred = (timeout_cnt >= TIMEOUT);

    // 状态机
    parameter IDLE = 3'd0,
              START = 3'd1,
              RECEIVE_BITS = 3'd2,
              CHECK_PARITY = 3'd3,
              STOP = 3'd4;

    reg [2:0] state, next_state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (ps2_clk_negedge && !ps2_data_sync2) // 起始位检测
                    next_state = START;
                else
                    next_state = IDLE;
            end
            START: begin
                if (ps2_clk_negedge)
                    next_state = RECEIVE_BITS;
                else
                    next_state = START;
            end
            RECEIVE_BITS: begin
                if (ps2_clk_negedge && bit_cnt == 4'd9) // 已接收10位(8数据+1校验+1停止前)
                    next_state = CHECK_PARITY;
                else if (ps2_clk_negedge)
                    next_state = RECEIVE_BITS;
                else if (timeout_occurred)
                    next_state = IDLE;
                else
                    next_state = RECEIVE_BITS;
            end
            CHECK_PARITY: begin
                if (ps2_clk_negedge)
                    next_state = STOP;
                else
                    next_state = CHECK_PARITY;
            end
            STOP: begin
                if (ps2_clk_negedge)
                    next_state = IDLE;
                else
                    next_state = STOP;
            end
            default: next_state = IDLE;
        endcase
    end

    // 计数器和数据处理
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 4'd0;
            timeout_cnt <= 8'd0;
            rx_data_reg <= 8'd0;
            parity_check <= 1'b0;
