## 设计思路

1. **信号分析**：
   - 输入：clk(1位), rst_n(1位), ps2_clk(1位), ps2_data(1位)
   - 输出：data[7:0](8位寄存器), valid(1位脉冲), err(1位脉冲)

2. **状态机设计**：
   - IDLE: 等待起始位(0)
   - RECEIVING: 接收11位数据(起始位+8位数据+奇校验+停止位)
   - 状态转移：IDLE→RECEIVING(检测到起始位下降沿)，RECEIVING→IDLE(接收完成或超时)
   - 计数器：位计数器(0-10, 4位)，超时计数器(log2(TIMEOUT), 8位)

3. **复位行为**：异步复位，所有寄存器清零，输出无效

## 完整代码

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [3:0] bit_cnt;
    reg [7:0] data_reg;
    reg [7:0] timeout_cnt;
    reg ps2_clk_sync, ps2_clk_sync2;
    reg ps2_data_sync, ps2_data_sync2;
    reg start_flag;
    reg [2:0] state;

    // 同步PS2信号
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 1'b1;
            ps2_clk_sync2 <= 1'b1;
            ps2_data_sync <= 1'b1;
            ps2_data_sync2 <= 1'b1;
        end else begin
            ps2_clk_sync <= ps2_clk;
            ps2_clk_sync2 <= ps2_clk_sync;
            ps2_data_sync <= ps2_data;
            ps2_data_sync2 <= ps2_data_sync;
        end
    end

    // 检测PS2时钟下降沿
    wire ps2_clk_negedge = ps2_clk_sync2 & ~ps2_clk_sync;

    // 状态定义
    parameter IDLE = 3'd0;
    parameter RECEIVING = 3'd1;

    // 主状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 4'd0;
            data_reg <= 8'd0;
            start_flag <= 1'b0;
            timeout_cnt <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (ps2_clk_negedge && !ps2_data_sync2) begin // 检测起始位(0)
                        state <= RECEIVING;
                        bit_cnt <= 4'd0;
                        data_reg <= {ps2_data_sync, 7'd0};
                        start_flag <= 1'b1;
                        timeout_cnt <= 8'd0;
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_negedge) begin
                        if (bit_cnt < 4'd9) begin // 接收数据位和校验位
                            data_reg <= {ps2_data_sync, data_reg[7:1]};
                            bit_cnt <= bit_cnt + 1'd1;
                            timeout_cnt <= 8'd0;
                        end else if (bit_cnt == 4'd9) begin // 接收停止位
                            bit_cnt <= bit_cnt + 1'd1;
                            timeout_cnt <= 8'd0;
                        end else begin // 完成11位接收
                            state <= IDLE;
                        end
                    end else if (timeout_cnt >= TIMEOUT) begin
                        state <= IDLE;
                    end else if (start_flag) begin
                        timeout_cnt <= timeout_cnt + 1'd1;
                    end
                end

                default: state <= IDLE;
            endcase

            if (state == IDLE)
                start_flag <= 1'b0;
        end
    end

    // 奇校验检查
    wire parity_check = ^{data_reg, ps2_data_sync2} ^ 1'b1; // 奇校验应为1

    // 输出逻辑
    assign data = data_reg;
    assign valid = (state == RECEIVING) && (bit_cnt == 4'd10) && 
                   (parity_check == 1'b1) && (ps2_data_sync2 == 1'b1); // 校验位正确且停止位为1
    assign err = (state == RECEIVING) && (bit_cnt == 4'd10) && 
                 ((parity_check != 1'b1) || (ps2_data_sync2 != 1'b1)) || 
                 ((state == RECEIVING) && (timeout_cnt >= TIMEOUT));

endmodule
