    reg [7:0] data_reg;
    reg [7:0] timeout_cnt;
    reg [1:0] ps2_clk_sync;
    reg [9:0] rx_shift_reg; // 10 bits for start+8data+parity
    reg [1:0] ps2_data_sync;
    reg rx_busy;
    reg parity_error;
    reg stop_bit_error;

