    wire ps2_clk_neg_edge;
    wire ps2_clk_sample_edge;

    assign ps2_clk_pos_edge = ~ps2_clk_sync[1] & ps2_clk_sync[0];
    assign ps2_clk_neg_edge = ps2_clk_sync[1] & ~ps2_clk_sync[0];
    assign ps2_clk_sample_edge = ps2_clk_neg_edge;

    assign data = data_reg;
    assign valid = ps2_clk_sample_edge & (bit_cnt == 4'd10) & ~parity_error & ~stop_bit_error & rx_busy;
    assign err = (parity_error | stop_bit_error) & (bit_cnt == 4'd10) & rx_busy;

    always @(posedge clk or negedge rst_n) begin
