            ps2_clk_sync <= 2'b00;
            ps2_data_sync <= 2'b00;
            bit_cnt <= 4'd0;
            data_reg <= 8'h00;
            timeout_cnt <= 8'h00;
            rx_shift_reg <= 10'h000;
            rx_busy <= 1'b0;
            parity_error <= 1'b0;
            stop_bit_error <= 1'b0;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

            if (ps2_clk_sample_edge) begin
                timeout_cnt <= 8'h00;

                if (rx_busy) begin
                    rx_shift_reg <= {ps2_data_sync[1], rx_shift_reg[9:1]};
                    bit_cnt <= bit_cnt + 1'b1;

                    if (bit_cnt == 4'd10) begin // Complete frame received
                        parity_error <= ^{rx_shift_reg[8:1]} != rx_shift_reg[9]; // Odd parity check
                        stop_bit_error <= ~ps2_data_sync[1]; // Stop bit should be 1

                        if (~parity_error & ~stop_bit_error) begin
