- RECV: 接收11位数据(起始位+8位数据+校验位+停止位)
- 计数器：bit_cnt(4位, 0-11), timeout_cnt(8位, 0-TIMEOUT)

**3. 复位行为**
- 所有寄存器复位为初始值，进入IDLE状态

**4. 时序要求**
- 在ps2_clk下降沿采样数据
- 超时检测：无下降沿超过TIMEOUT周期则放弃当前帧

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data;
    reg valid;
    reg err;

    reg [3:0] bit_cnt;
    reg [7:0] timeout_cnt;
    reg [10:0] frame_reg;
    reg [1:0] ps2_clk_sync;
    reg [1:0] ps2_data_sync;
    reg ps2_clk_fall;
    reg rx_busy;

    parameter IDLE = 2'b00;
    parameter RECV = 2'b01;
    parameter CHECK = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 4'h0;
            timeout_cnt <= 8'h0;
            frame_reg <= 11'h0;
            data <= 8'h0;
            valid <= 1'b0;
            err <= 1'b0;
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
            rx_busy <= 1'b0;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

            ps2_clk_fall <= (ps2_clk_sync == 2'b10);

            valid <= 1'b0;
            err <= 1'b0;

            case (state)
                IDLE: begin
                    if (ps2_clk_fall) begin
                        if (ps2_data_sync[1] == 1'b0) begin // Start bit detected
                            bit_cnt <= 4'h0;
                            frame_reg <= 11'h0;
                            frame_reg[0] <= ps2_data_sync[1]; // Start bit
                            rx_busy <= 1'b1;
                            state <= RECV;
                            timeout_cnt <= 8'h0;
                        end
                    end
                end

                RECV: begin
                    if (ps2_clk_fall) begin
                        bit_cnt <= bit_cnt + 1'b1;
                        frame_reg[bit_cnt + 1] <= ps2_data_sync[1];
                        timeout_cnt <= 8'h0; // Reset timeout counter

                        if (bit_cnt == 4'd10) begin // All 11 bits received
                            state <= CHECK;
                        end
                    end else begin
                        if (timeout_cnt < TIMEOUT) begin
                            timeout_cnt <= timeout_cnt + 1'b1;
                        end else begin
                            // Timeout - abort current frame
                            state <= IDLE;
                            rx_busy <= 1'b0;
                        end
                    end
                end

                CHECK: begin
                    // Check stop bit (should be 1) and parity
                    if (frame_reg[10] != 1'b1) begin // Stop bit error
                        err <= 1'b1;
                    end else begin
                        // Calculate parity (odd parity - should have odd number of 1s in data+parity)
                        // Data bits are [8:1], parity bit is [9]
                        reg [3:0] ones_count;
                        integer i;
                        ones_count = 5'h0;
                        for (i = 1; i <= 9; i = i + 1) begin
                            if (frame_reg[i]) begin
                                ones_count <= ones_count + 1'b1;
                            end
                        end

                        if (ones_count[0] != 1'b1) begin // Parity error (should be odd)
                            err <= 1'b1;
                        end else begin
                            data <= frame_reg[8:1]; // Extract data bits
                            valid <= 1'b1;
                        end
                    end
                    state <= IDLE;
                    rx_busy <= 1'b0;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
