## 设计思路

1. **信号分析**：
   - 输入：clk(1位), rst_n(1位), ps2_clk(1位), ps2_data(1位)
   - 输出：data[7:0](8位寄存器), valid(1位组合), err(1位组合)

2. **状态机设计**：
   - IDLE: 等待起始位(0)
   - RECEIVING: 接收11位数据(起始位+8位数据+奇校验+停止位)
   - 状态转移：IDLE→RECEIVING(检测到下降沿且数据为0)，RECEIVING→IDLE(接收完成或超时)
   - 计数器：位计数器[3:0]范围0-11，超时计数器[TIMEOUT-1:0]

3. **复位行为**：异步复位，所有寄存器清零，输出无效状态

4. **时序要求**：在ps2_clk下降沿采样数据，确保同步处理

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data_r;
    reg valid_r, err_r;
    reg [3:0] bit_cnt;
    reg [TIMEOUT-1:0] timeout_cnt;
    reg [1:0] ps2_clk_sync, ps2_data_sync;
    reg rx_busy;

    wire ps2_clk_posedge = ~ps2_clk_sync[1] & ps2_clk_sync[0];
    wire ps2_clk_negedge = ps2_clk_sync[1] & ~ps2_clk_sync[0];
    wire start_bit = ~ps2_data_sync[0]; // 起始位为0

    parameter IDLE = 1'b0, RECEIVING = 1'b1;
    reg state, next_state;

    assign data = data_r;
    assign valid = valid_r;
    assign err = err_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b00;
            ps2_data_sync <= 2'b00;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (ps2_clk_negedge && start_bit && !rx_busy)
                    next_state = RECEIVING;
                else
                    next_state = IDLE;
            end
            RECEIVING: begin
                if ((bit_cnt == 4'd11 && ps2_clk_negedge) || (timeout_cnt >= TIMEOUT-1))
                    next_state = IDLE;
                else
                    next_state = RECEIVING;
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 4'd0;
            timeout_cnt <= {TIMEOUT{1'b0}};
            rx_busy <= 1'b0;
        end else begin
            if (state == IDLE && ps2_clk_negedge && start_bit && !rx_busy) begin
                bit_cnt <= 4'd1;  // 开始接收第1位(起始位后第一位)
                timeout_cnt <= {TIMEOUT{1'b0}};
                rx_busy <= 1'b1;
            end else if (state == RECEIVING && ps2_clk_negedge) begin
                if (bit_cnt < 4'd11) begin
                    bit_cnt <= bit_cnt + 1'd1;
                    timeout_cnt <= {TIMEOUT{1'b0}};  // 重置超时计数器
                end else begin
                    bit_cnt <= 4'd0;
                    rx_busy <= 1'b0;
                end
            end else if (state == RECEIVING && ps2_clk_posedge) begin
                // 在上升沿也更新超时计数器
                timeout_cnt <= timeout_cnt + 1'd1;
            end else if (state == RECEIVING) begin
                timeout_cnt <= timeout_cnt + 1'd1;
            end else begin
                timeout_cnt <= {TIMEOUT{1'b0}};
            end
        end
    end

    reg [7:0] shift_reg;
    reg parity_calc;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 8'd0;
            parity_calc <= 1'b0;
        end else if (state == RECEIVING && ps2_clk_negedge) begin
            if (bit_cnt >= 4'd1 && bit_cnt <= 4'd8) begin
                shift_reg[bit_cnt-1] <= ps2_data_sync[0];
                // 计算接收到的数据的奇偶校验
                if (bit_cnt == 4'd1)
                    parity_calc <= ps2_data_sync[0];
                else
                    parity_calc <= parity_calc ^ ps2_data_sync[0];
            end
        end
    end

    reg stop_bit_check, parity_check;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_r <= 8'd0;
            valid_r <= 1'b0;
            err_r <= 1'b0;
        end else begin
            valid_r <= 1'b0;
            err_r <= 1'b0;

            if (state == RECEIVING && ps2_clk_negedge && bit_cnt == 4'd9) begin
                // 检查奇校验位 (第9位)
                parity_check <= (parity_calc ^ ps2_data_sync[0]) == 1'b1; // 奇校验应为1
            end

            if (state == RECEIVING && ps2_clk_negedge && bit_cnt == 4'd10) begin
                // 检查停止位 (第10位)
                stop_bit_check <= ps2_data_sync[0]; // 停止位应为1
            end

            if (state == RECEIVING && ps2_clk_negedge && bit_cnt == 4'd11) begin
                // 完成一帧接收
                if (parity_check && stop_bit_check) begin
                    data_r <= shift_reg;
                    valid_r <= 1'b1;
                end else begin
                    err_r <= 1'b1;
                end
            end

            if (timeout_cnt >= TIMEOUT-1 && state == RECEIVING) begin
                err_r <= 1'b1;
            end
        end
    end

endmodule
