```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [1:0] ps2_clk_sync;
    reg [1:0] ps2_data_sync;
    reg ps2_clk_dly;
    reg ps2_edge_detected;
    reg [7:0] data_reg;
    reg valid_reg;
    reg err_reg;

    // Synchronization
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};
        end
    end

    // Edge detection (falling edge of ps2_clk)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_dly <= 1'b1;
        end else begin
            ps2_clk_dly <= ps2_clk_sync[1];
        end
    end

    assign ps2_edge_detected = (ps2_clk_dly == 1'b1) && (ps2_clk_sync[1] == 1'b0);

    // Timeout counter
    reg [15:0] timeout_counter;
    reg [3:0] bit_count;
    reg [8:0] shift_reg;  // For data bits + parity
    reg [3:0] state;      // 0: idle, 1: receiving
    reg [3:0] parity_count;

    parameter IDLE = 0;
    parameter RECEIVING = 1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_counter <= 16'd0;
            bit_count <= 4'd0;
            shift_reg <= 9'd0;
            state <= IDLE;
            data_reg <= 8'd0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
            parity_count <= 4'd0;
        end else begin
            valid_reg <= 1'b0;
            err_reg <= 1'b0;

            if (ps2_edge_detected) begin
                timeout_counter <= 16'd0;

                case (state)
                    IDLE: begin
                        // Check for start bit (ps2_data should be 0)
                        if (ps2_data_sync[1] == 1'b0) begin
                            state <= RECEIVING;
                            bit_count <= 4'd0;
                            shift_reg <= 9'd0;
                            parity_count <= 4'd0;
                        end
                    end

                    RECEIVING: begin
                        // Sample the current bit
                        shift_reg <= {shift_reg[7:0], ps2_data_sync[1]};

                        // Update parity count only for data bits (not parity itself yet)
                        if (bit_count < 8) begin
                            if (ps2_data_sync[1])
                                parity_count <= parity_count + 1'b1;
                            else
                                parity_count <= parity_count;
                        end

                        bit_count <= bit_count + 1'b1;

                        if (bit_count == 4'd10) begin  // After sampling stop bit (11th bit total)
                            // Now check both stop bit and parity
                            // Stop bit should be 1
                            // Parity should be odd (total 1's in data+parity should be odd)
                            // So parity bit value should make total 1's odd

                            // Calculate expected parity - XOR all data bits
                            reg temp_parity;
                            temp_parity = shift_reg[0] ^ shift_reg[1] ^ shift_reg[2] ^ 
                                         shift_reg[3] ^ shift_reg[4] ^ shift_reg[5] ^ 
                                         shift_reg[6] ^ shift_reg[7];

                            // The received parity bit is shift_reg[8]
                            // For odd parity: data_bits_1s + parity_bit should be odd
                            // So (parity_count + shift_reg[8]) should be odd
                            if ((parity_count + shift_reg[8]) % 2 == 1'b1 && ps2_data_sync[1] == 1'b1) begin
                                // Both stop bit and parity are correct
                                data_reg <= {shift_reg[7], shift_reg[6], shift_reg[5], shift_reg[4], 
                                            shift_reg[3], shift_reg[2], shift_reg[1], shift_reg[0]};
                                valid_reg <= 1'b1;
                            end else begin
                                // Either stop bit is wrong or parity is wrong
                                err_reg <= 1'b1;
                            end

                            state <= IDLE;
                        end
                    end
                endcase
            end else begin
                // Increment timeout counter when no edge detected
                if (state != IDLE) begin
                    if (timeout_counter < TIMEOUT) begin
                        timeout_counter <= timeout_counter + 1'b1;
                    end else begin
                        // Timeout occurred - reset to idle without generating any outputs
                        state <= IDLE;
                        timeout_counter <= 16'd0;
                    end
                end
            end
        end
    end

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

endmodule
