module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data;
    reg valid;
    reg err;

    // 同步ps2_clk和ps2_data
    reg [1:0] ps2_clk_sync, ps2_data_sync;
    wire ps2_clk_posedge, ps2_clk_negedge;

    assign ps2_clk_posedge = ~ps2_clk_sync[1] & ps2_clk_sync[0];
    assign ps2_clk_negedge = ps2_clk_sync[1] & ~ps2_clk_sync[0];

    // 状态定义
    parameter IDLE = 2'b00;
    parameter RECEIVING = 2'b01;
    parameter CHECK = 2'b10;

    reg [1:0] state;
    reg [3:0] bit_cnt;  // 0-10 for 11 bits
    reg [7:0] shift_reg;
    reg parity_calc;
    integer timeout_cnt;
    reg timeout_flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b00;
            ps2_data_sync <= 2'b00;
            state <= IDLE;
            bit_cnt <= 4'd0;
            shift_reg <= 8'h00;
            parity_calc <= 1'b0;
            timeout_cnt <= 0;
            timeout_flag <= 1'b0;
            data <= 8'h00;
            valid <= 1'b0;
            err <= 1'b0;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

            valid <= 1'b0;
            err <= 1'b0;

            case (state)
                IDLE: begin
                    bit_cnt <= 4'd0;
                    shift_reg <= 8'h00;
                    parity_calc <= 1'b0;
                    timeout_cnt <= 0;
                    timeout_flag <= 1'b0;

                    // 检测起始位(0)且ps2_clk为低电平
                    if (~ps2_data_sync[1] && ~ps2_clk_sync[1]) begin
                        state <= RECEIVING;
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_negedge) begin
                        // 采样数据位
                        shift_reg <= {ps2_data_sync[1], shift_reg[7:1]};

                        // 计算奇校验（包括数据位和当前采样的位）
                        if (bit_cnt < 9) begin  // 前9位包括起始位和8个数据位
                            if (bit_cnt > 0) begin  // 不包括起始位(固定为0)
                                parity_calc <= parity_calc ^ ps2_data_sync[1];
                            end
                        end

                        bit_cnt <= bit_cnt + 1'b1;
                        timeout_cnt <= 0;

                        if (bit_cnt == 4'd10) begin  // 已接收完11位
                            state <= CHECK;
                        end
                    end else begin
                        timeout_cnt <= timeout_cnt + 1;
                        if (timeout_cnt >= TIMEOUT) begin
                            timeout_flag <= 1'b1;
                            state <= IDLE;
                            err <= 1'b1;
                        end
                    end
                end

                CHECK: begin
                    // 验证停止位(应为1)和奇校验
                    if (ps2_data_sync[1] !== 1'b1) begin  // 停止位错误
                        err <= 1'b1;
                    end else if (parity_calc !== ~ps2_data_sync[1]) begin  // 校验位错误
                        err <= 1'b1;
                    end else begin  // 正确
                        data <= shift_reg[7:0];  // 数据位是中间8位
                        valid <= 1'b1;
                    end
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase

            // 超时处理
            if (timeout_flag) begin
                timeout_flag <= 1'b0;
            end
        end
    end

endmodule
