                        timeout_cnt <= timeout_cnt + 1'b1;
                        if (timeout_reached) begin
                            state_idle <= 1'b1;
                            state_receiving <= 1'b0;
                            state_counting <= 1'b0;
                            err_r <= 1'b1;
                        end
                    end
