                    state_idle <= 1'b1;
                    state_receiving <= 1'b0;
                    state_counting <= 1'b0;
                    timeout_cnt <= 10'h0;
                end

                default: begin
                    state_idle <= 1'b1;
                    state_receiving <= 1'b0;
                    state_counting <= 1'b0;
                end
            endcase
        end
    end

