    reg [7:0] data_reg;
    reg valid_reg;
    reg err_reg;

    reg [3:0] bit_count;
    reg [8:0] shift_reg; // D0-D7 + parity
    reg [9:0] state; // 0=idle, 1=waiting_start, 2=receiving_bit[0:9], 3=checking
    reg [19:0] timeout_counter;
    reg timeout_detected;

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

