        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
            ps2_clk_prev <= 1'b1;
            ps2_clk_negedge <= 1'b0;

            data_reg <= 8'h0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;

            bit_count <= 4'd0;
            shift_reg <= 9'h0;
            state <= 10'h0;
            timeout_counter <= 20'h0;
            timeout_detected <= 1'b0;
        end else begin
            // Synchronize inputs
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

