            ps2_clk_prev <= ps2_clk_sync[1];
            ps2_clk_negedge <= (~ps2_clk_sync[1]) & ps2_clk_prev;

            // Timeout counter
            if (state == 10'h0 || state == 10'h1) begin
                timeout_counter <= 20'h0;
            end else if (ps2_clk_negedge) begin
                timeout_counter <= 20'h0;
            end else begin
