            if (timeout_flag) begin
                // Do nothing - remain silent
            end
            // Check for complete frame with result ready
            else if (state == RESULT_STATE && result_wait_counter == 3'd6) begin
                if (stop_bit == 1'b1 && odd_parity_ok) begin
