            bit_count <= 4'd0;
            shift_reg <= 8'd0;
            parity_count <= 4'd0;
            stop_bit <= 1'b0;
            in_receive_state <= 1'b0;
            data_out <= 8'd0;
            valid_out <= 1'b0;
            err_out <= 1'b0;
