                            parity_count <= parity_count + (ps2_data_sync[1] ? 4'd1 : 4'd0);
                            bit_count <= bit_count + 1'b1;
                        end
                        4'd9: begin // Parity bit
                            parity_count <= parity_count + (ps2_data_sync[1] ? 4'd1 : 4'd0);
                            bit_count <= bit_count + 1'b1;
                        end
                        4'd10: begin // Stop bit
                            bit_count <= bit_count + 1'b1;

