    reg [1:0] ps2_data_sync;
    reg ps2_clk_negedge;

    // Synchronization
    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};
        end
    end

    assign ps2_clk_negedge = ps2_clk_sync[1] & ~ps2_clk_sync[0];

    // State machine
    parameter IDLE = 2'd0, RECEIVING = 2'd1, WAITING_RESULT = 2'd2;
    reg [1:0] state;
    reg [3:0] bit_count;
    reg [7:0] shift_reg;
    reg parity_bit;
    reg stop_bit;
    reg [7:0] received_data;
    reg [10:0] timeout_counter;  // Need to count up to TIMEOUT (200)
    reg valid_pulse;
    reg err_pulse;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_count <= 4'd0;
            shift_reg <= 8'd0;
            parity_bit <= 1'b0;
            stop_bit <= 1'b0;
            received_data <= 8'd0;
            timeout_counter <= 11'd0;
            valid_pulse <= 1'b0;
            err_pulse <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    valid_pulse <= 1'b0;
                    err_pulse <= 1'b0;
                    if (ps2_clk_negedge && ps2_data_sync[1] == 1'b0) begin  // Start bit detected
                        state <= RECEIVING;
                        bit_count <= 4'd0;
                        timeout_counter <= 11'd0;
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_negedge) begin
                        case (bit_count)
                            4'd0: begin  // Start bit - already checked in IDLE
                                bit_count <= bit_count + 1'b1;
                                timeout_counter <= 11'd0;
                            end
                            4'd1, 4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8: begin  // Data bits D0-D7
                                shift_reg <= {ps2_data_sync[1], shift_reg[7:1]};
                                bit_count <= bit_count + 1'b1;
                                timeout_counter <= 11'd0;
                            end
                            4'd9: begin  // Parity bit
                                parity_bit <= ps2_data_sync[1];
                                bit_count <= bit_count + 1'b1;
                                timeout_counter <= 11'd0;
                            end
                            4'd10: begin  // Stop bit
                                stop_bit <= ps2_data_sync[1];
                                received_data <= {shift_reg[0], shift_reg[1], shift_reg[2], shift_reg[3], 
                                                 shift_reg[4], shift_reg[5], shift_reg[6], shift_reg[7]};
                                state <= WAITING_RESULT;
                                timeout_counter <= 11'd0;
                            end
                            default: begin
