                        if (timeout_counter < TIMEOUT - 1) begin
                            timeout_counter <= timeout_counter + 1'b1;
                        end else begin
                            // Timeout occurred, return to idle without any pulse
                            state <= IDLE;
                            timeout_counter <= 11'd0;
                        end
                    end
                end

                WAITING_RESULT: begin
                    timeout_counter <= timeout_counter + 1'b1;
                    if (timeout_counter == 5) begin  // At most 6 cycles after the 11th edge
                        // Calculate odd parity check: D0-D7 + parity bit should have odd number of 1s
                        // Count 1's in data and parity bit
                        reg [3:0] ones_count;
                        integer i;

                        ones_count = 4'd0;
                        for (i = 0; i < 8; i = i + 1) begin
