                        valid_pulse <= 1'b0;
                        err_pulse <= 1'b0;
                    end
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    assign data = received_data;
    assign valid = valid_pulse;
    assign err = err_pulse;

