## 设计思路

1. **信号分类**：输入包括clk、rst_n、ps2_clk、ps2_data；输出包括data[7:0]（寄存器）、valid（组合输出）、err（组合输出）

2. **状态机**：IDLE（空闲）、RECEIVING（接收）两个状态；使用3位计数器count[3:0]记录bit位置(0-10)；timeout计数器[7:0]检测超时

3. **复位行为**：同步复位，valid=0，err=0，回到IDLE状态；通过多级寄存器同步ps2信号并检测边沿

4. **时序要求**：ps2_clk下降沿采样数据，11位帧结构，超时检测TIMEOUT周期无边沿则返回空闲

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data;
    reg valid;
    reg err;

    // 同步ps2信号
    reg [1:0] ps2_clk_sync, ps2_data_sync;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};
        end
    end

    // 检测ps2_clk下降沿
    wire ps2_clk_neg_edge = ~ps2_clk_sync[1] & ps2_clk_sync[0];

    // 状态定义
    parameter IDLE = 1'b0;
    parameter RECEIVING = 1'b1;

    reg state;
    reg [3:0] count; // 计数0-10，共11位
    reg [7:0] rx_data_reg;
    reg [3:0] parity_count;
    reg timeout_flag;
    reg [7:0] timeout_counter;

    // 超时检测
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_counter <= 0;
        end else if (state == IDLE) begin
            timeout_counter <= 0;
        end else if (ps2_clk_neg_edge) begin
            timeout_counter <= 0;
        end else begin
            timeout_counter <= timeout_counter + 1;
        end
    end

    assign timeout_flag = (timeout_counter >= TIMEOUT);

    // 主状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            count <= 0;
            rx_data_reg <= 0;
            parity_count <= 0;
            data <= 0;
            valid <= 0;
            err <= 0;
        end else begin
            valid <= 0;
            err <= 0;

            if (timeout_flag) begin
                state <= IDLE;
                count <= 0;
            end else if (state == IDLE) begin
                if (ps2_clk_neg_edge && ps2_data_sync[1] == 0) begin // 起始位检测
                    state <= RECEIVING;
                    count <= 1; // 已收到起始位
                    rx_data_reg <= 0;
                    parity_count <= 0;
                end
            end else if (state == RECEIVING) begin
                if (ps2_clk_neg_edge) begin
                    case (count)
                        4'd1: begin // D0
                            rx_data_reg[0] <= ps2_data_sync[1];
                            parity_count <= ps2_data_sync[1];
                        end
                        4'd2: begin // D1
                            rx_data_reg[1] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd3: begin // D2
                            rx_data_reg[2] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd4: begin // D3
                            rx_data_reg[3] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd5: begin // D4
                            rx_data_reg[4] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd6: begin // D5
                            rx_data_reg[5] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd7: begin // D6
                            rx_data_reg[6] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd8: begin // D7
                            rx_data_reg[7] <= ps2_data_sync[1];
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd9: begin // 奇校验位
                            parity_count <= parity_count + ps2_data_sync[1];
                        end
                        4'd10: begin // 停止位
                            if (ps2_data_sync[1] == 1 && parity_count[0] == 1) begin // 停止位为1且奇校验正确
                                data <= rx_data_reg;
                                valid <= 1;
                            end else begin
                                err <= 1;
                            end
                            state <= IDLE;
                            count <= 0;
                        end
                        default: begin
                            count <= count + 1;
