            bit_cnt <= 0;
            shift_reg <= 0;
            parity_bit <= 0;
            stop_bit <= 0;
            data_r <= 0;
            valid_r <= 0;
            err_r <= 0;
            timeout_cnt <= 0;
            data_count <= 0;
