                            4: shift_reg[4] <= ps2_data_sync[0];  // D4
                            5: shift_reg[5] <= ps2_data_sync[0];  // D5
                            6: shift_reg[6] <= ps2_data_sync[0];  // D6
                            7: shift_reg[7] <= ps2_data_sync[0];  // D7
