   - 输入：clk(1), rst_n(1), ps2_clk(1), ps2_data(1)
   - 输出：data(8位寄存器), valid(1位脉冲), err(1位脉冲)

2. **状态机设计**：
   - IDLE: 空闲状态，等待起始位
   - RECEIVE: 接收状态，接收11位数据
   - 状态转移：IDLE->RECEIVE(检测到起始位0)，RECEIVE->IDLE(完成接收或超时)

3. **计数器**：
   - bit_cnt: 计数已接收位数(0-10)
   - timeout_cnt: 超时计数器(0-TIMEOUT)

4. **复位行为**：同步复位，清零所有寄存器，输出置0

## 完整代码

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] data_r;
    reg valid_r;
    reg err_r;
    reg [2:0] ps2_clk_sync;
    reg [2:0] ps2_data_sync;
    reg ps2_clk_edge;
    reg [3:0] bit_cnt;
    reg [10:0] rx_data_reg;
    reg [7:0] timeout_cnt;
    reg in_receive;

    assign data = data_r;
    assign valid = valid_r;
    assign err = err_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 3'b111;
            ps2_data_sync <= 3'b111;
            ps2_clk_edge <= 1'b0;
            bit_cnt <= 4'd0;
            rx_data_reg <= 11'b0;
            timeout_cnt <= 8'd0;
            in_receive <= 1'b0;
            data_r <= 8'h0;
            valid_r <= 1'b0;
            err_r <= 1'b0;
        end else begin
            // Synchronize PS/2 signals
            ps2_clk_sync <= {ps2_clk_sync[1:0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[1:0], ps2_data};

            // Detect falling edge of ps2_clk
            ps2_clk_edge <= (ps2_clk_sync[2:1] == 2'b10);

            // Timeout counter
            if (ps2_clk_edge) begin
                timeout_cnt <= 8'd0;
            end else if (in_receive && timeout_cnt < TIMEOUT) begin
                timeout_cnt <= timeout_cnt + 1'b1;
            end

            // Valid and err are single cycle pulses
            valid_r <= 1'b0;
            err_r <= 1'b0;

            if (timeout_cnt == TIMEOUT) begin
                // Timeout occurred, reset to idle
                in_receive <= 1'b0;
                bit_cnt <= 4'd0;
            end else if (ps2_clk_edge) begin
                if (!in_receive) begin
                    // Check for start condition: ps2_clk falling edge with ps2_data = 0
                    if (ps2_data_sync[1]) begin
                        // Still idle if data is high
                    end else begin
                        // Start receiving
                        in_receive <= 1'b1;
                        bit_cnt <= 4'd0;
                        rx_data_reg <= 11'b0;
                    end
                end else begin
                    // Shift in the current data bit
                    rx_data_reg <= {ps2_data_sync[1], rx_data_reg[10:1]};
                    bit_cnt <= bit_cnt + 1'b1;

                    if (bit_cnt == 4'd10) begin // After 11th bit (stop bit)
                        in_receive <= 1'b0;

                        // Check stop bit (should be 1) and parity
                        if (rx_data_reg[0] != 1'b1) begin
                            // Stop bit error
                            err_r <= 1'b1;
                        end else begin
                            // Check odd parity: D0-D7 + P should have odd number of 1s
                            // rx_data_reg[1:9] contains P, D7, D6, ..., D0
                            reg [3:0] ones_count;
                            integer i;

                            ones_count = 4'd0;
                            for (i = 1; i <= 9; i = i + 1) begin
                                if (rx_data_reg[i])
                                    ones_count = ones_count + 1'b1;
                            end

                            if (ones_count[0] == 1'b0) begin // Even number of 1s -> parity error
                                err_r <= 1'b1;
                            end else begin
                                // Valid frame: extract data bits D0-D7 from rx_data_reg[1:8]
                                // rx_data_reg[1:8] has D0, D1, ..., D7 (LSB first)
                                data_r <= {rx_data_reg[8], rx_data_reg[7], rx_data_reg[6], rx_data_reg[5],
                                           rx_data_reg[4], rx_data_reg[3], rx_data_reg[2], rx_data_reg[1]};
                                valid_r <= 1'b1;
                            end
                        end
                    end
                end
            end
        end
    end

