module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [2:0] state;
    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter RECEIVE = 3'b010;

    reg [2:0] bit_count;
    reg [7:0] timeout_count;
    reg [2:0] ps2_clk_sync, ps2_clk_prev;
    reg [2:0] ps2_data_sync;
    reg [7:0] temp_data;
    reg [3:0] parity_count;
    reg valid_reg, err_reg;
    reg [7:0] data_reg;

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_count <= 0;
            timeout_count <= 0;
            ps2_clk_sync <= 3'b111;
            ps2_clk_prev <= 3'b111;
            ps2_data_sync <= 3'b111;
            temp_data <= 0;
            parity_count <= 0;
            valid_reg <= 0;
            err_reg <= 0;
            data_reg <= 0;
        end else begin
            // Synchronize PS/2 signals
            ps2_clk_sync <= {ps2_clk_sync[1:0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[1:0], ps2_data};

            ps2_clk_prev <= ps2_clk_sync;
            valid_reg <= 0;
            err_reg <= 0;

            case (state)
                IDLE: begin
                    if (~ps2_clk_prev[1] & ps2_clk_sync[1]) begin // Falling edge of ps2_clk
                        if (ps2_data_sync[2] == 1'b0) begin // Start bit is 0
                            state <= START;
                            bit_count <= 0;
                            timeout_count <= 0;
                            temp_data <= 0;
                            parity_count <= 0;
                        end
                    end else begin
                        timeout_count <= 0;
                    end
                end

                START: begin
                    if (~ps2_clk_prev[1] & ps2_clk_sync[1]) begin // Falling edge
                        temp_data[bit_count] <= ps2_data_sync[2];
                        if (bit_count < 7) begin
                            parity_count <= parity_count + ps2_data_sync[2];
                        end else if (bit_count == 7) begin
                            parity_count <= parity_count + ps2_data_sync[2]; // Add parity bit
                        end

                        if (bit_count < 10) begin
                            bit_count <= bit_count + 1;
                            state <= RECEIVE;
                            timeout_count <= 0;
                        end else begin
                            // Check stop bit and parity at the 11th bit
                            if (ps2_data_sync[2] == 1'b1 && parity_count[0] == 1'b1) begin // Stop bit=1 and odd parity correct
                                data_reg <= {ps2_data_sync[2], temp_data[7:1]}; // D7...D0
                                valid_reg <= 1;
                            end else begin
                                err_reg <= 1;
                            end
                            state <= IDLE;
                        end
                    end else if (timeout_count >= TIMEOUT - 1) begin
                        state <= IDLE;
                        timeout_count <= 0;
                    end else begin
                        timeout_count <= timeout_count + 1;
                    end
                end

                RECEIVE: begin
                    if (~ps2_clk_prev[1] & ps2_clk_sync[1]) begin // Falling edge
                        if (bit_count < 7) begin
                            temp_data[bit_count] <= ps2_data_sync[2];
                            parity_count <= parity_count + ps2_data_sync[2];
                            bit_count <= bit_count + 1;
                            timeout_count <= 0;
                        end else if (bit_count == 7) begin
                            temp_data[7] <= ps2_data_sync[2];
                            parity_count <= parity_count + ps2_data_sync[2]; // Add parity bit
                            bit_count <= bit_count + 1;
                            timeout_count <= 0;
                        end else if (bit_count == 8) begin
                            parity_count <= parity_count + ps2_data_sync[2]; // Include parity bit in count
                            bit_count <= bit_count + 1;
                            timeout_count <= 0;
                        end else if (bit_count == 9) begin
                            // Check stop bit and parity
                            if (ps2_data_sync[2] == 1'b1 && parity_count[0] == 1'b1) begin // Stop bit=1 and odd parity correct
                                data_reg <= {ps2_data_sync[2], temp_data[7:1]}; // D7...D0
                                valid_reg <= 1;
                            end else begin
                                err_reg <= 1;
                            end
                            state <= IDLE;
                        end
                    end else if (timeout_count >= TIMEOUT - 1) begin
                        state <= IDLE;
                        timeout_count <= 0;
                    end else begin
                        timeout_count <= timeout_count + 1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

