    reg [7:0] timeout_cnt;
    reg [2:0] ps2_clk_sync;
    reg [2:0] ps2_data_sync;
    reg [7:0] rx_data;
    reg [3:0] ones_count;
    reg valid_reg, err_reg;
    reg [7:0] data_reg;

