        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 0;
            timeout_cnt <= 0;
            ps2_clk_sync <= 3'b111;
            ps2_data_sync <= 3'b111;
            rx_data <= 0;
            ones_count <= 0;
            valid_reg <= 0;
            err_reg <= 0;
            data_reg <= 0;
        end else begin
            // Synchronize PS/2 signals with 2-stage synchronizer
            ps2_clk_sync <= {ps2_clk_sync[1:0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[1:0], ps2_data};

            valid_reg <= 0;
            err_reg <= 0;

            case (state)
                IDLE: begin
                    timeout_cnt <= 0;
                    if (ps2_clk_sync[1] & ~ps2_clk_sync[0]) begin // Falling edge on ps2_clk
                        if (~ps2_data_sync[1]) begin // Start bit is 0
                            state <= RECEIVING;
                            bit_cnt <= 0;
                            rx_data <= 0;
                            ones_count <= 0;
                        end
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_sync[1] & ~ps2_clk_sync[0]) begin // Falling edge
                        if (bit_cnt < 8) begin // Data bits D0-D7 (LSB first)
                            rx_data[bit_cnt] <= ps2_data_sync[2]; // Use delayed data
                            if (ps2_data_sync[2])
                                ones_count <= ones_count + 1;
                        end
                        else if (bit_cnt == 8) begin // Parity bit
                            if (ps2_data_sync[2])
                                ones_count <= ones_count + 1;
                        end
                        else if (bit_cnt == 9) begin // Stop bit - move to checking
                            state <= CHECKING;
                        end
                        bit_cnt <= bit_cnt + 1;
                        timeout_cnt <= 0;
                    end
                    else if (timeout_cnt >= TIMEOUT - 1) begin
                        state <= IDLE;
                        timeout_cnt <= 0;
                    end
                    else begin
                        timeout_cnt <= timeout_cnt + 1;
                    end
                end

                CHECKING: begin
                    // Check parity and stop bit when entering this state
                    if (ps2_data_sync[2] && (ones_count[0] == 1'b1)) begin // Stop bit=1 and odd parity
                        data_reg <= rx_data; // Store received byte (already in correct order D0-D7)
                        valid_reg <= 1;
                    end else begin
                        err_reg <= 1;
                    end
                    state <= IDLE; // Go back to idle
                end

                default: state <= IDLE;
            endcase
        end
    end

