## 设计思路

1. **信号分类**：输入包括clk、rst_n、ps2_clk、ps2_data；输出包括data[7:0]（寄存器）、valid（组合）、err（组合）

2. **状态机**：IDLE（空闲）→ RECV（接收）→ DONE（完成处理）
   - 计数器：bit_cnt（3位，0-10表示接收位序号）、timeout_cnt（需要log2(TIMEOUT+1)位）

3. **复位行为**：同步复位，valid=0，err=0，回到IDLE状态
   - 使用2级寄存器同步ps2_clk和ps2_data
   - 检测ps2_clk下降沿来触发接收
   - TIMEOUT计数器监控超时

## 完整代码

```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [1:0] ps2_clk_sync, ps2_data_sync;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] data_r;
    reg valid_r, err_r;
    reg [9:0] timeout_cnt; // ceil(log2(200+1)) = 8 bits, but use 10 for safety
    reg in_receive;

    wire ps2_clk_fall = (ps2_clk_sync == 2'b10); // falling edge detected

    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
            bit_cnt <= 3'd0;
            shift_reg <= 8'h00;
            data_r <= 8'h00;
            valid_r <= 1'b0;
            err_r <= 1'b0;
            timeout_cnt <= 10'h000;
            in_receive <= 1'b0;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

            valid_r <= 1'b0;
            err_r <= 1'b0;

            if (ps2_clk_fall) begin
                timeout_cnt <= 10'h000;

                if (!in_receive) begin
                    // Check start bit: ps2_data should be 0 at falling edge of clk
                    if (ps2_data_sync[0] == 1'b0) begin
                        in_receive <= 1'b1;
                        bit_cnt <= 3'd0;
                        shift_reg <= 8'h00;
                    end
                end else begin
                    // In receive state, collect bits
                    if (bit_cnt < 3'd8) begin
                        // Collect data bits D0-D7
                        shift_reg <= {ps2_data_sync[0], shift_reg[7:1]};
                        bit_cnt <= bit_cnt + 1'b1;
                    end else if (bit_cnt == 3'd8) begin
                        // Collect parity bit
                        shift_reg <= {ps2_data_sync[0], shift_reg[7:1]};
                        bit_cnt <= bit_cnt + 1'b1;
                    end else if (bit_cnt == 3'd9) begin
                        // Collect stop bit and finish frame
                        if (ps2_data_sync[0] == 1'b1) begin
                            // Stop bit is 1, check parity
                            // Count number of 1s in data bits + parity bit (9 bits total)
                            reg [3:0] ones_count;
                            ones_count = 4'd0;
                            integer i;
                            for (i = 0; i < 8; i = i + 1) begin
                                if (shift_reg[i] == 1'b1)
                                    ones_count = ones_count + 1'b1;
                            end
                            if (ps2_data_sync[0] == 1'b1) // Parity bit
                                ones_count = ones_count + 1'b1;

                            if (ones_count[0] == 1'b1) begin // Odd parity check passed
                                data_r <= {shift_reg[0], shift_reg[1], shift_reg[2], shift_reg[3],
                                          shift_reg[4], shift_reg[5], shift_reg[6], shift_reg[7]};
                                valid_r <= 1'b1;
                            end else begin
                                err_r <= 1'b1;
                            end
                        end else begin
                            // Stop bit is 0, error
                            err_r <= 1'b1;
                        end
                        in_receive <= 1'b0;
                    end
                end
            end

            // Timeout handling
            if (in_receive) begin
                if (ps2_clk_fall) begin
                    timeout_cnt <= 10'h000;
                end else begin
                    if (timeout_cnt < TIMEOUT) begin
                        timeout_cnt <= timeout_cnt + 1'b1;
                    end else begin
                        // Timeout occurred, reset to idle without any output
                        in_receive <= 1'b0;
                        timeout_cnt <= 10'h000;
                    end
                end
            end else begin
                timeout_cnt <= 10'h000;
            end
        end
    end

    assign data = data_r;
    assign valid = valid_r;
    assign err = err_r;

endmodule
