```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [1:0] ps2_clk_sync, ps2_data_sync;
    reg [1:0] ps2_clk_d;
    reg ps2_clk_negedge;

    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] data_r;
    reg parity_bit;
    reg stop_bit;
    reg [9:0] timeout_cnt; // 至少需要能计数到TIMEOUT
    reg in_receive;

    reg state_idle, state_recv, state_wait;
    reg [2:0] wait_cnt;

    wire start_condition;

    // 同步PS2信号
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};
        end
    end

    // 检测ps2_clk下降沿
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ps2_clk_d <= 2'b11;
        end else begin
            ps2_clk_d <= ps2_clk_sync;
        end
    end

    assign ps2_clk_negedge = (ps2_clk_d == 2'b10); // 下降沿

    // 起始位检测条件
    assign start_condition = ps2_clk_negedge & !ps2_data_sync[1] & state_idle;

    // 主状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_idle <= 1;
            state_recv <= 0;
            state_wait <= 0;
            bit_cnt <= 0;
            shift_reg <= 0;
            parity_bit <= 0;
            stop_bit <= 0;
            timeout_cnt <= 0;
            in_receive <= 0;
            data_r <= 0;
            wait_cnt <= 0;
        end else begin
            if (start_condition) begin
                state_idle <= 0;
                state_recv <= 1;
                state_wait <= 0;
                bit_cnt <= 0;
                shift_reg <= 0;
                timeout_cnt <= 0;
                in_receive <= 1;
            end else if (state_recv && ps2_clk_negedge) begin
                case (bit_cnt)
                    3'd0: shift_reg[0] <= ps2_data_sync[1];
                    3'd1: shift_reg[1] <= ps2_data_sync[1];
                    3'd2: shift_reg[2] <= ps2_data_sync[1];
                    3'd3: shift_reg[3] <= ps2_data_sync[1];
                    3'd4: shift_reg[4] <= ps2_data_sync[1];
                    3'd5: shift_reg[5] <= ps2_data_sync[1];
                    3'd6: shift_reg[6] <= ps2_data_sync[1];
                    3'd7: shift_reg[7] <= ps2_data_sync[1];
                    3'd8: parity_bit <= ps2_data_sync[1];
                    3'd9: stop_bit <= ps2_data_sync[1];
                    default: ;
                endcase

                if (bit_cnt < 3'd10) begin
                    bit_cnt <= bit_cnt + 1;
                    timeout_cnt <= 0;
                end else begin
                    // 第11个边沿，准备进入等待状态
                    state_recv <= 0;
                    state_wait <= 1;
                    wait_cnt <= 0;
                    // 计算校验和更新数据
                    data_r <= {shift_reg[0], shift_reg[1], shift_reg[2], shift_reg[3],
                               shift_reg[4], shift_reg[5], shift_reg[6], shift_reg[7]};
                end
            end else if (state_wait) begin
                if (wait_cnt < 3'd6) begin
                    wait_cnt <= wait_cnt + 1;
                end else begin
                    state_wait <= 0;
                    state_idle <= 1;
                    in_receive <= 0;
                end
            end

            // 超时处理
            if (in_receive) begin
                if (ps2_clk_negedge) begin
                    timeout_cnt <= 0;
                end else begin
                    if (timeout_cnt < TIMEOUT) begin
                        timeout_cnt <= timeout_cnt + 1;
                    end else begin
                        // 超时，回到空闲状态
                        state_idle <= 1;
                        state_recv <= 0;
                        state_wait <= 0;
                        in_receive <= 0;
                    end
                end
            end else begin
                timeout_cnt <= 0;
            end
        end
    end

    // 计算奇校验是否正确
    wire parity_ok;
    assign parity_ok = ^{shift_reg, parity_bit}; // 9位异或，奇校验正确时结果为1

    // valid和err输出
    assign valid = state_wait & (wait_cnt == 3'd0) & (stop_bit == 1) & parity_ok;
    assign err = state_wait & (wait_cnt == 3'd0) & ((stop_bit == 0) | !parity_ok);

    assign data = data_r;

endmodule
