    always @(*) begin
        ps2_clk_negedge = (ps2_clk_prev == 2'b11) && (ps2_clk_sync == 2'b00);
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 3'd0;
            timeout_cnt <= 10'd0;
            valid_r <= 1'b0;
            err_r <= 1'b0;
            data_r <= 8'h00;
            temp_data <= 8'h00;
            parity_count <= 4'd0;
        end else begin
            valid_r <= 1'b0;
            err_r <= 1'b0;

            case (state)
                IDLE: begin
                    if (ps2_clk_negedge && ps2_data_sync[1] == 1'b0) begin
                        state <= RECEIVING;
                        bit_cnt <= 3'd0;
                        timeout_cnt <= 10'd0;
                        temp_data <= 8'h00;
                        parity_count <= 4'd0;
                    end else if (ps2_clk_negedge) begin
                        timeout_cnt <= 10'd0;
                    end else begin
                        timeout_cnt <= timeout_cnt + 1'b1;
                        if (timeout_cnt >= TIMEOUT - 1) begin
                            timeout_cnt <= 10'd0;
                        end
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_negedge) begin
                        if (bit_cnt < 3'd8) begin
                            temp_data[bit_cnt] <= ps2_data_sync[1];
                            if (ps2_data_sync[1]) begin
                                parity_count <= parity_count + 1'b1;
                            end
                        end else if (bit_cnt == 3'd8) begin // Parity bit
                            if (ps2_data_sync[1]) begin
                                parity_count <= parity_count + 1'b1;
                            end
                        end else if (bit_cnt == 3'd9) begin // Stop bit
                            // Check parity and stop bit
                            if (ps2_data_sync[1] && (parity_count[0] == 1'b1)) begin // Odd parity correct and stop bit is 1
                                data_r <= {temp_data[0], temp_data[1], temp_data[2], temp_data[3], 
                                          temp_data[4], temp_data[5], temp_data[6], temp_data[7]};
                                valid_r <= 1'b1;
                            end else begin
                                err_r <= 1'b1;
                            end
                            state <= IDLE;
                        end
                        bit_cnt <= bit_cnt + 1'b1;
                        timeout_cnt <= 10'd0;
                    end else begin
                        timeout_cnt <= timeout_cnt + 1'b1;
                        if (timeout_cnt >= TIMEOUT - 1) begin
                            state <= IDLE;
                            timeout_cnt <= 10'd0;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

