    input rst_n,
    output reg hsync,
    output reg vsync,
    output reg de,
    output reg [9:0] x,
    output reg [9:0] y
);

    wire [9:0] H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;
    wire [9:0] V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;

    reg [9:0] h_count;
    reg [9:0] v_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            h_count <= 10'd0;
            v_count <= 10'd0;
            x <= 10'd0;
            y <= 10'd0;
            hsync <= 1'b0;
            vsync <= 1'b0;
            de <= 1'b0;
        end else begin
            if (h_count == H_TOTAL - 1) begin
                if (v_count == V_TOTAL - 1) begin
                    v_count <= 10'd0;
                end else begin
                    v_count <= v_count + 1'b1;
                end
                h_count <= 10'd0;
            end else begin
                h_count <= h_count + 1'b1;
            end

            // Update x and y coordinates when in active display area
            if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin
                x <= h_count;
                y <= v_count;
                de <= 1'b1;
            end else begin
                x <= 10'd0;
                y <= 10'd0;
                de <= 1'b0;
            end

            // Generate hsync signal (active low)
            if (h_count >= H_ACTIVE + H_FP && h_count < H_ACTIVE + H_FP + H_SYNC) begin
                hsync <= 1'b0;
