## 设计思路

**1. 信号分析**
- 输入：clk(1bit), rst_n(1bit)
- 输出：hsync(1bit, 寄存器), vsync(1bit, 寄存器), de(1bit, 寄存器), x(10bit, 寄存器), y(10bit, 寄存器)
- 内部需要行计数器和场计数器来跟踪当前像素位置

**2. 计数器设计**
- 行计数器范围：0 到 (H_ACTIVE + H_FP + H_SYNC + H_BP - 1)，即 0 到 799
- 场计数器范围：0 到 (V_ACTIVE + V_FP + V_SYNC + V_BP - 1)，即 0 到 524
- 计数器位宽：10位足够表示最大值

**3. 复位行为**
- 复位时所有输出初始化为默认值，计数器归零
- hsync/vsync在复位后保持无效状态(高电平)

**4. 时序逻辑**
- 根据当前计数值判断同步信号和使能信号的状态
- 在有效显示区域内输出坐标，在非显示区域x,y为0

```verilog
module vga_timing #(parameter H_ACTIVE = 640, parameter H_FP = 16, parameter H_SYNC = 96, parameter H_BP = 48, parameter V_ACTIVE = 480, parameter V_FP = 10, parameter V_SYNC = 2, parameter V_BP = 33) (
    input clk,
    input rst_n,
    output hsync,
    output vsync,
    output de,
    output [9:0] x,
    output [9:0] y
);

    wire [9:0] H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;
    wire [9:0] V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;

    reg [9:0] h_count;
    reg [9:0] v_count;
    reg hsync_r;
    reg vsync_r;
    reg de_r;
    reg [9:0] x_r;
    reg [9:0] y_r;

    assign hsync = hsync_r;
    assign vsync = vsync_r;
    assign de = de_r;
    assign x = x_r;
    assign y = y_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            h_count <= 10'd0;
            v_count <= 10'd0;
            hsync_r <= 1'b1;
            vsync_r <= 1'b1;
            de_r <= 1'b0;
            x_r <= 10'd0;
            y_r <= 10'd0;
        end else begin
            // Update horizontal counter
            if (h_count == H_TOTAL - 1) begin
                h_count <= 10'd0;
                if (v_count == V_TOTAL - 1) 
                    v_count <= 10'd0;
                else 
                    v_count <= v_count + 1'b1;
            end else begin
                h_count <= h_count + 1'b1;
            end

            // Generate hsync
            if (h_count >= H_ACTIVE + H_FP && h_count < H_ACTIVE + H_FP + H_SYNC)
                hsync_r <= 1'b0;
            else
                hsync_r <= 1'b1;

            // Generate vsync
            if (v_count >= V_ACTIVE + V_FP && v_count < V_ACTIVE + V_FP + V_SYNC)
                vsync_r <= 1'b0;
            else
                vsync_r <= 1'b1;

            // Generate DE and coordinates
            if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin
                de_r <= 1'b1;
                x_r <= h_count;
                y_r <= v_count;
            end else begin
                de_r <= 1'b0;
                x_r <= 10'd0;
                y_r <= 10'd0;
            end
        end
    end

endmodule
