module vga_timing #(
    parameter H_ACTIVE = 640,
    parameter H_FP = 16,
    parameter H_SYNC = 96,
    parameter H_BP = 48,
    parameter V_ACTIVE = 480,
    parameter V_FP = 10,
    parameter V_SYNC = 2,
    parameter V_BP = 33
) (
    input clk,
    input rst_n,
    output hsync,
    output vsync,
    output de,
    output [9:0] x,
    output [9:0] y
);

    wire [9:0] H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;
    wire [9:0] V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;

    reg [9:0] h_count;
    reg [9:0] v_count;
    reg hsync_reg;
    reg vsync_reg;
    reg de_reg;

    assign hsync = ~hsync_reg;
    assign vsync = ~vsync_reg;
    assign de = de_reg;

    // Calculate x and y coordinates
    wire [9:0] h_start_active = H_FP + H_SYNC + H_BP;
    wire [9:0] v_start_active = V_FP + V_SYNC + V_BP;

    assign x = de ? (h_count - h_start_active) : 10'd0;
    assign y = de ? (v_count - v_start_active) : 10'd0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            h_count <= 10'd0;
            v_count <= 10'd0;
            hsync_reg <= 1'b0;
            vsync_reg <= 1'b0;
            de_reg <= 1'b0;
        end else begin
            if (h_count == H_TOTAL - 1) begin
                h_count <= 10'd0;
                if (v_count == V_TOTAL - 1) 
                    v_count <= 10'd0;
                else 
                    v_count <= v_count + 1;
            end else begin
                h_count <= h_count + 1;
            end

            // Generate horizontal sync
            if (h_count >= H_ACTIVE + H_FP && h_count < H_ACTIVE + H_FP + H_SYNC)
                hsync_reg <= 1'b1;
            else
                hsync_reg <= 1'b0;

            // Generate vertical sync
            if (v_count >= V_ACTIVE + V_FP && v_count < V_ACTIVE + V_FP + V_SYNC)
                vsync_reg <= 1'b1;
            else
                vsync_reg <= 1'b0;

            // Generate data enable
            if (h_count < H_ACTIVE && v_count < V_ACTIVE)
                de_reg <= 1'b1;
            else
                de_reg <= 1'b0;
        end
    end

endmodule

