module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output busy,
    output done,
    output [7:0] mem_addr,
    output [7:0] mem_wdata,
    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    reg [2:0] state;
    reg [7:0] current_src;
    reg [7:0] current_dst;
    reg [7:0] remaining_len;
    reg [8:0] counter;
    reg done_reg;

    parameter IDLE = 3'b000;
    parameter READ = 3'b001;
    parameter WRITE = 3'b010;
    parameter WAIT_WRITE = 3'b011;

    assign busy = (state != IDLE);
    assign done = done_reg;
    assign mem_addr = (state == READ) ? current_src : current_dst;
    assign mem_wdata = mem_rdata;
    assign mem_we = (state == WRITE);
    assign mem_re = (state == READ);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            current_src <= 8'h00;
            current_dst <= 8'h00;
            remaining_len <= 8'h00;
            counter <= 9'h000;
            done_reg <= 1'b0;
        end else begin
            done_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        current_src <= src;
                        current_dst <= dst;
                        remaining_len <= len;
                        state <= (len == 8'h00) ? IDLE : READ;
                        counter <= 9'h000;
                    end
                end

                READ: begin
                    state <= WRITE;
                end

                WRITE: begin
                    state <= WAIT_WRITE;
                end

                WAIT_WRITE: begin
                    counter <= counter + 1;
                    if (counter == 9'h001) begin // One cycle after write
                        counter <= 9'h000;
                        if (remaining_len > 8'h01) begin
                            current_src <= current_src + 8'h01;
                            current_dst <= current_dst + 8'h01;
                            remaining_len <= remaining_len - 8'h01;
                            state <= READ;
                        end else begin
                            state <= IDLE;
                            done_reg <= 1'b1;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
