    reg [7:0] src_reg, dst_reg, len_reg;
    reg [7:0] counter;
    reg [7:0] read_data;
    reg [1:0] delay_counter;

    parameter IDLE = 3'b000;
    parameter READ = 3'b001;
    parameter WRITE = 3'b010;
    parameter DONE_PULSE = 3'b011;
    parameter WAIT_DONE = 3'b100;

    assign busy = (state != IDLE);
    assign done = (state == DONE_PULSE);
    assign mem_addr = (state == READ) ? (src_reg + counter) : 
                     (state == WRITE) ? (dst_reg + counter) : 8'h00;
    assign mem_wdata = read_data;
    assign mem_re = (state == READ);
    assign mem_we = (state == WRITE);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            src_reg <= 8'h00;
            dst_reg <= 8'h00;
            len_reg <= 8'h00;
            counter <= 8'h00;
            read_data <= 8'h00;
            delay_counter <= 2'h00;
        end else begin
            case (state)
                IDLE: begin
