                READ: begin
                    read_data <= mem_rdata; // Capture data from previous read
                    state <= WRITE;
                end

                WRITE: begin
                    if (counter == len_reg - 1) begin
                        state <= DONE_PULSE;
                        delay_counter <= 2'h00;
                    end else begin
                        counter <= counter + 1;
                        state <= READ;
                    end
                end

                DONE_PULSE: begin
                    state <= WAIT_DONE;
                    delay_counter <= delay_counter + 1;
                end

                WAIT_DONE: begin
                    if (delay_counter < 2'h02) begin
                        delay_counter <= delay_counter + 1;
                    end else begin
                        state <= IDLE;
                    end
