    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    reg state_busy;
    reg state_done;
    reg [2:0] fsm_state; // 0: idle, 1: read, 2: write_wait, 3: write
    reg [7:0] current_src_addr;
    reg [7:0] current_dst_addr;
    reg [7:0] remaining_len;
    reg [7:0] saved_data;
    reg [2:0] counter;

    assign busy = state_busy;
    assign done = state_done;

    parameter IDLE = 3'b000;
    parameter READ = 3'b001;
    parameter WRITE_WAIT = 3'b010;
    parameter WRITE = 3'b011;

    always @(posedge clk) begin
        if (!rst_n) begin
            state_busy <= 1'b0;
            state_done <= 1'b0;
            fsm_state <= IDLE;
            current_src_addr <= 8'h00;
            current_dst_addr <= 8'h00;
            remaining_len <= 8'h00;
            saved_data <= 8'h00;
            counter <= 3'h0;
        end else begin
