## 设计思路

1. **信号分类**：输入信号包括控制(start)和数据(src/dst/len)，输出包括状态(busy/done)和存储器接口(mem_addr/mem_wdata/mem_we/mem_re)。其中busy/done/mem_addr/mem_wdata/mem_we/mem_re是寄存器输出，mem_rdata是输入。

2. **状态机设计**：采用三段式状态机 - IDLE(等待启动) -> READ(读取) -> WRITE(写入)。使用计数器跟踪当前处理的字节位置(0到len-1)。

3. **计数器**：使用3位计数器cnt[2:0]，范围0到7，支持最多256字节的分批处理。

4. **复位与时序**：同步复位清零所有状态；对于len=0特殊处理，快速返回；确保读操作后至少一个周期才进行写操作，满足1周期延迟要求。

```verilog
module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output reg busy,
    output reg done,
    output reg [7:0] mem_addr,
    output reg [7:0] mem_wdata,
    output reg mem_we,
    output reg mem_re,
    input [7:0] mem_rdata
);

    parameter IDLE = 2'b00;
    parameter READ = 2'b01;
    parameter WRITE = 2'b10;

    reg [1:0] state;
    reg [7:0] src_reg, dst_reg;
    reg [7:0] len_reg;
    reg [7:0] read_data;
    reg [7:0] cnt;
    reg read_phase;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy <= 0;
            done <= 0;
            mem_we <= 0;
            mem_re <= 0;
            mem_addr <= 0;
            mem_wdata <= 0;
            src_reg <= 0;
            dst_reg <= 0;
            len_reg <= 0;
            read_data <= 0;
            cnt <= 0;
            read_phase <= 0;
        end else begin
            case (state)
                IDLE: begin
                    busy <= 0;
                    done <= 0;
                    mem_we <= 0;
                    mem_re <= 0;
                    if (start && !busy) begin
                        busy <= 1;
                        src_reg <= src;
                        dst_reg <= dst;
                        len_reg <= len;
                        if (len == 0) begin
                            done <= 1;
                        end else begin
                            state <= READ;
                            cnt <= 0;
                            mem_addr <= src; // First address to read
                            mem_re <= 1;
                            read_phase <= 1;
                        end
                    end
                end

                READ: begin
                    mem_re <= 0;
                    if (read_phase) begin
                        read_data <= mem_rdata; // Capture the data from previous read
                        mem_addr <= dst_reg + cnt; // Prepare write address
                        mem_wdata <= mem_rdata; // Prepare write data
                        mem_we <= 1;
                        read_phase <= 0;
                    end else begin
                        mem_we <= 0;
                        if (cnt == len_reg - 1) begin
                            // Last byte written, go to done
                            state <= IDLE;
                            busy <= 0;
                            done <= 1;
                        end else begin
                            cnt <= cnt + 1;
                            mem_addr <= src_reg + (cnt + 1); // Next read address
                            mem_re <= 1;
                            read_phase <= 1;
                        end
                    end
                end

                default: begin
                    state <= IDLE;
                    busy <= 0;
                    done <= 0;
                    mem_we <= 0;
                    mem_re <= 0;
                end
            endcase

            // On reset, immediately clear everything
            if (!rst_n) begin
                state <= IDLE;
                busy <= 0;
                done <= 0;
                mem_we <= 0;
                mem_re <= 0;
            end
        end
    end

endmodule
