```verilog
module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output busy,
    output done,
    output [7:0] mem_addr,
    output [7:0] mem_wdata,
    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    reg [2:0] state;
    parameter IDLE = 3'b000;
    parameter READ = 3'b001;
    parameter WRITE = 3'b010;
    parameter DONE_PULSE = 3'b011;

    reg [7:0] current_count;
    reg [7:0] src_reg, dst_reg, len_reg;
    reg [7:0] read_data;
    reg busy_reg, done_reg;
    reg mem_we_reg, mem_re_reg;
    reg [7:0] mem_addr_reg;
    reg [7:0] mem_wdata_reg;

    assign busy = busy_reg;
    assign done = done_reg;
    assign mem_addr = mem_addr_reg;
    assign mem_wdata = mem_wdata_reg;
    assign mem_we = mem_we_reg;
    assign mem_re = mem_re_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            mem_we_reg <= 1'b0;
            mem_re_reg <= 1'b0;
            mem_addr_reg <= 8'h00;
            mem_wdata_reg <= 8'h00;
            current_count <= 8'h00;
        end else begin
            case (state)
                IDLE: begin
                    done_reg <= 1'b0;
                    mem_we_reg <= 1'b0;
                    mem_re_reg <= 1'b0;
                    if (start && !busy_reg) begin
                        busy_reg <= 1'b1;
                        src_reg <= src;
                        dst_reg <= dst;
                        len_reg <= len;
                        if (len == 8'h00) begin
                            state <= DONE_PULSE;
                        end else begin
                            current_count <= 8'h00;
                            mem_addr_reg <= src; // src + 0
                            mem_re_reg <= 1'b1;
                            state <= READ;
                        end
                    end
                end

                READ: begin
                    mem_re_reg <= 1'b0;
                    read_data <= mem_rdata;
                    mem_addr_reg <= {dst_reg[7:0]} + current_count;
                    mem_wdata_reg <= mem_rdata;
                    mem_we_reg <= 1'b1;
                    state <= WRITE;
                end

                WRITE: begin
                    mem_we_reg <= 1'b0;
                    current_count <= current_count + 1'b1;

                    if (current_count == len_reg - 1) begin
                        state <= DONE_PULSE;
                    end else begin
                        mem_addr_reg <= {src_reg[7:0]} + current_count + 1'b1;
                        mem_re_reg <= 1'b1;
                        state <= READ;
                    end
                end

                DONE_PULSE: begin
                    done_reg <= 1'b1;
                    busy_reg <= 1'b0;
                    mem_we_reg <= 1'b0;
                    mem_re_reg <= 1'b0;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                    busy_reg <= 1'b0;
                    done_reg <= 1'b0;
                    mem_we_reg <= 1'b0;
                    mem_re_reg <= 1'b0;
                end
            endcase
        end
    end

endmodule
