```verilog
module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output busy,
    output done,
    output [7:0] mem_addr,
    output [7:0] mem_wdata,
    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    reg [2:0] state;
    parameter IDLE = 3'b000;
    parameter READ = 3'b001;
    parameter WRITE = 3'b010;
    parameter DONE = 3'b011;

    reg [9:0] count; // 10位足够覆盖256*2的计算
    reg [7:0] current_src, current_dst, current_len;
    reg [7:0] read_data;
    reg busy_reg, done_reg;
    reg [7:0] mem_addr_reg, mem_wdata_reg;
    reg mem_we_reg, mem_re_reg;

    assign busy = busy_reg;
    assign done = done_reg;
    assign mem_addr = mem_addr_reg;
    assign mem_wdata = mem_wdata_reg;
    assign mem_we = mem_we_reg;
    assign mem_re = mem_re_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            count <= 0;
            busy_reg <= 0;
            done_reg <= 0;
            mem_addr_reg <= 0;
            mem_wdata_reg <= 0;
            mem_we_reg <= 0;
            mem_re_reg <= 0;
            current_src <= 0;
            current_dst <= 0;
            current_len <= 0;
            read_data <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done_reg <= 0;
                    if (!busy_reg && start) begin
                        current_src <= src;
                        current_dst <= dst;
                        current_len <= len;
                        busy_reg <= 1;
                        if (len == 0) begin
                            state <= DONE;
                        end else begin
                            state <= READ;
                            count <= 0;
                        end
                    end
                end

                READ: begin
                    mem_addr_reg <= (current_src + count[7:0]) % 8'd256;
                    mem_re_reg <= 1;
                    mem_we_reg <= 0;
                    state <= WRITE;
                end

                WRITE: begin
                    mem_re_reg <= 0;
                    mem_addr_reg <= (current_dst + count[7:0]) % 8'd256;
                    mem_wdata_reg <= read_data;
                    mem_we_reg <= 1;

                    if (count == current_len - 1) begin
                        state <= DONE;
                    end else begin
                        state <= READ;
                        count <= count + 1;
                    end
                end

                DONE: begin
                    mem_we_reg <= 0;
                    mem_re_reg <= 0;
                    done_reg <= 1;
                    busy_reg <= 0;
                    state <= IDLE;
                end

