                            busy_reg <= 0;
                            done_reg <= 1;
                        end else begin
                            state <= READ;
                            count <= 0;
                            mem_re_reg <= 1;
                        end
                    end
                end

                READ: begin
                    mem_re_reg <= 0;
                    state <= WAIT_READ;
                end

                WAIT_READ: begin
                    read_data <= mem_rdata;
                    state <= WRITE;
                    mem_we_reg <= 1;
                end

                WRITE: begin
                    mem_we_reg <= 0;
                    state <= WAIT_WRITE;
                end

                WAIT_WRITE: begin
                    if (count == len_reg - 1) begin
                        state <= IDLE;
                        busy_reg <= 0;
                        done_reg <= 1;
                    end else begin
                        count <= count + 1;
                        state <= READ;
                        mem_re_reg <= 1;
                    end
                end

                default: state <= IDLE;
