## 设计思路

1. **信号分类**：输入信号包括控制(start)和数据(src/dst/len)，输出包括状态(busy/done)和存储器接口(mem_addr/mem_wdata/mem_we/mem_re)。其中busy/done/mem_we/mem_re是组合输出，其他输出是寄存器。

2. **状态机设计**：采用三状态FSM - IDLE(空闲)、READ(读取)、WRITE(写入)。使用计数器跟踪当前处理的字节位置(0到len-1)。

3. **复位与时序**：同步复位清零所有寄存器，busy在start有效时置1，任务完成后done脉冲持续1周期。对于len=0特殊处理，避免访问存储器。

```verilog
module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output busy,
    output done,
    output [7:0] mem_addr,
    output [7:0] mem_wdata,
    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    reg [1:0] state;
    reg [7:0] current_count;
    reg [7:0] src_reg, dst_reg, len_reg;
    reg [7:0] read_data;
    reg busy_reg, done_reg;
    reg mem_we_reg, mem_re_reg;

    parameter IDLE = 2'b00;
    parameter READ = 2'b01;
    parameter WRITE = 2'b10;

    assign busy = busy_reg;
    assign done = done_reg;
    assign mem_addr = (state == READ) ? (src_reg + current_count) : 
                     (state == WRITE) ? (dst_reg + current_count) : 8'h00;
    assign mem_wdata = read_data;
    assign mem_we = mem_we_reg;
    assign mem_re = mem_re_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            current_count <= 8'h00;
            src_reg <= 8'h00;
            dst_reg <= 8'h00;
            len_reg <= 8'h00;
            read_data <= 8'h00;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            mem_we_reg <= 1'b0;
            mem_re_reg <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done_reg <= 1'b0;
                    mem_we_reg <= 1'b0;
                    mem_re_reg <= 1'b0;
                    if (start && !busy_reg) begin
                        src_reg <= src;
                        dst_reg <= dst;
                        len_reg <= len;
                        busy_reg <= 1'b1;
                        if (len == 8'h00) begin
                            // Special case for len = 0
                            busy_reg <= 1'b0;
                            done_reg <= 1'b1;
                        end else begin
                            current_count <= 8'h00;
                            state <= READ;
                            mem_re_reg <= 1'b1;
                        end
                    end
                end

                READ: begin
                    mem_re_reg <= 1'b0;
                    read_data <= mem_rdata;
                    state <= WRITE;
                    mem_we_reg <= 1'b1;
                end

                WRITE: begin
                    mem_we_reg <= 1'b0;
                    if (current_count == len_reg - 1) begin
                        // Last byte written, finish the task
                        busy_reg <= 1'b0;
                        done_reg <= 1'b1;
                        state <= IDLE;
                    end else begin
                        // Move to next byte
                        current_count <= current_count + 1;
                        state <= READ;
                        mem_re_reg <= 1'b1;
                    end
                end

                default: begin
                    state <= IDLE;
                end
            endcase

            // Clear done after one cycle
            if (done_reg)
                done_reg <= 1'b0;

            // Reset on rst_n
            if (!rst_n) begin
                state <= IDLE;
                current_count <= 8'h00;
                read_data <= 8'h00;
                busy_reg <= 1'b0;
                done_reg <= 1'b0;
                mem_we_reg <= 1'b0;
                mem_re_reg <= 1'b0;
            end
        end
    end

endmodule
