                        if (wstrb[3]) reg2[31:24] <= write_data_reg[31:24];
                        write_resp <= 2'b00;  // OKAY
                    end
                    8'h0C: begin
                        // Write to read-only register - return SLVERR
                        write_resp <= 2'b10;  // SLVERR
                    end
                    default: begin
                        if ((addr_reg >= 8'h10) && (addr_reg < 8'h100)) begin
                            // Address out of range - return DECERR
                            write_resp <= 2'b11;  // DECERR
                        end else begin
                            // Other addresses - return DECERR
                            write_resp <= 2'b11;  // DECERR
                        end
                    end
                endcase
            end

            // Start B response when write is processed
            if (write_pending && !b_valid_reg) begin
                b_valid_reg <= 1'b1;
            end

            // Clear B valid when B ready is asserted
            if (b_valid_reg && bready) begin
                b_valid_reg <= 1'b0;
                write_pending <= 1'b0;
                aw_ready_reg <= 1'b1;
                w_ready_reg <= 1'b1;
            end

            // Handle read address channel
            if (arvalid && ar_ready_reg) begin
                addr_reg <= araddr;
                ar_ready_reg <= 1'b0;

                // Process read immediately
                case (araddr[7:0])
                    8'h00: begin
                        read_data_reg <= reg0;
                        read_resp <= 2'b00;  // OKAY
                    end
                    8'h04: begin
                        read_data_reg <= reg1;
                        read_resp <= 2'b00;  // OKAY
                    end
                    8'h08: begin
                        read_data_reg <= reg2;
                        read_resp <= 2'b00;  // OKAY
                    end
                    8'h0C: begin
                        read_data_reg <= 32'h5A5A0003;  // ID register
                        read_resp <= 2'b00;  // OKAY
                    end
                    default: begin
                        if ((araddr >= 8'h10) && (araddr < 8'h100)) begin
                            // Address out of range - return DECERR with 0 data
                            read_data_reg <= 32'h0;
                            read_resp <= 2'b11;  // DECERR
                        end else begin
                            // Other addresses - return DECERR with 0 data
                            read_data_reg <= 32'h0;
                            read_resp <= 2'b11;  // DECERR
                        end
                    end
                endcase

                read_pending <= 1'b1;
            end

            // Start R response when read is processed
            if (read_pending && !r_valid_reg) begin
                r_valid_reg <= 1'b1;
            end

            // Clear R valid when R ready is asserted
            if (r_valid_reg && rready) begin
                r_valid_reg <= 1'b0;
                read_pending <= 1'b0;
                ar_ready_reg <= 1'b1;
            end
        end
    end

    // Output assignments
    assign bresp = write_resp;
    assign rdata = read_data_reg;
    assign rresp = read_resp;

