    // Write response state
    reg bvalid_reg;
    reg [1:0] bresp_reg;

    // Read state
    reg [7:0] araddr_reg;
    reg arvalid_reg;
    reg rvalid_reg;
    reg [31:0] rdata_reg;
    reg [1:0] rresp_reg;

    // Register storage
    reg [31:0] reg_00, reg_04, reg_08;

    // Write channel handshake control
    wire write_addr_phase_ready = !awvalid_reg || (awready && awvalid);
    wire write_data_phase_ready = !wvalid_reg || (wready && wvalid);

    // Response handshake control
    wire write_response_phase_ready = !bvalid_reg || (bready && bvalid);
    wire read_response_phase_ready = !rvalid_reg || (rready && rvalid);

    // Address decode
    wire [1:0] addr_decode_write = awaddr[3:2];
    wire [1:0] addr_decode_read = araddr[3:2];

    // Check if address is in valid range (0x00-0x0F)
    wire addr_in_range_write = (awaddr[7:4] == 4'h0) && (awaddr[3:2] <= 2'd3);
    wire addr_in_range_read = (araddr[7:4] == 4'h0) && (araddr[3:2] <= 2'd3);

    // Check if register is read-only (only 0x0C is read-only)
    wire is_read_only = (addr_decode_write == 2'd3); // 0x0C

    assign awready = write_addr_phase_ready && write_data_phase_ready && write_response_phase_ready;
    assign wready = write_addr_phase_ready && write_data_phase_ready && write_response_phase_ready;
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;
    assign arready = !arvalid_reg || (arready_internal && arvalid);
    assign rvalid = rvalid_reg;
    assign rdata = rdata_reg;
    assign rresp = rresp_reg;

    // Internal signal for arready
    wire arready_internal = !rvalid_reg || (rready && rvalid);

    always @(posedge clk) begin
        if (!rst_n) begin
            awvalid_reg <= 1'b0;
            wvalid_reg <= 1'b0;
            bvalid_reg <= 1'b0;
            rvalid_reg <= 1'b0;

            reg_00 <= 32'h0;
            reg_04 <= 32'h0;
            reg_08 <= 32'h0;
        end else begin
            // Handle AW and W handshakes
            if (awvalid && awready) begin
                awaddr_reg <= awaddr;
                awvalid_reg <= 1'b1;
            end else if (write_addr_phase_ready && write_data_phase_ready && write_response_phase_ready) begin
                awvalid_reg <= awvalid;
            end

            if (wvalid && wready) begin
                wdata_reg <= wdata;
                wstrb_reg <= wstrb;
                wvalid_reg <= 1'b1;
            end else if (write_addr_phase_ready && write_data_phase_ready && write_response_phase_ready) begin
                wvalid_reg <= wvalid;
            end

            // Handle write transaction completion
            if (awvalid_reg && wvalid_reg && !bvalid_reg) begin
                if (!addr_in_range_write) begin
                    bresp_reg <= 2'b11; // DECERR
                end else if (is_read_only) begin
                    bresp_reg <= 2'b10; // SLVERR
                end else begin
                    bresp_reg <= 2'b00; // OKAY
                    case (addr_decode_write)
                        2'd0: begin
                            if (wstrb_reg[0]) reg_00[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg_00[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg_00[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg_00[31:24] <= wdata_reg[31:24];
                        end
                        2'd1: begin
                            if (wstrb_reg[0]) reg_04[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg_04[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg_04[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg_04[31:24] <= wdata_reg[31:24];
                        end
                        2'd2: begin
                            if (wstrb_reg[0]) reg_08[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg_08[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg_08[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg_08[31:24] <= wdata_reg[31:24];
                        end
                        default: begin
                            // Should not happen due to address check above
                        end
                    endcase
                end
                bvalid_reg <= 1'b1;
            end

            // Handle write response handshake
            if (bready && bvalid) begin
                bvalid_reg <= 1'b0;
                awvalid_reg <= 1'b0;
                wvalid_reg <= 1'b0;
            end

            // Handle AR handshake
            if (arvalid && arready_internal) begin
                araddr_reg <= araddr;
                arvalid_reg <= 1'b1;
            end else if (read_response_phase_ready) begin
                arvalid_reg <= arvalid;
            end

            // Handle read transaction
            if (arvalid_reg && !rvalid_reg) begin
                if (!addr_in_range_read) begin
                    rresp_reg <= 2'b11; // DECERR
                    rdata_reg <= 32'h0;
                end else begin
                    rresp_reg <= 2'b00; // OKAY
                    case (addr_decode_read)
                        2'd0: rdata_reg <= reg_00;
                        2'd1: rdata_reg <= reg_04;
                        2'd2: rdata_reg <= reg_08;
                        2'd3: rdata_reg <= 32'h5A5A0003; // ID register
                        default: rdata_reg <= 32'h0;
                    endcase
                end
                rvalid_reg <= 1'b1;
            end

            // Handle read response handshake
            if (rready && rvalid) begin
                rvalid_reg <= 1'b0;
                arvalid_reg <= 1'b0;
            end
        end
    end

