## 设计思路

**1. 信号分析**
- 输入：clk, rst_n, awvalid, awaddr[7:0], wvalid, wdata[31:0], wstrb[3:0], bready, arvalid, araddr[7:0], rready
- 输出：awready, wready, bvalid, bresp[1:0], arready, rvalid, rdata[31:0], rresp[1:0]
- 寄存器输出：awready, wready, bvalid, bresp, arready, rvalid, rdata, rresp
- 组合输出：无

**2. 状态机设计**
- 读路径：IDLE -> AR_WAIT -> R_SEND
- 写路径：IDLE -> AW_W_WAIT -> B_SEND (其中AW_W_WAIT等待W通道到达)
- 使用标志位记录AW和W是否都已接收

**3. 复位行为**
- 所有寄存器复位为初始状态
- ID寄存器预设为0x5A5A0003

**4. 时序要求**
- 遵循AXI4-Lite valid/ready握手协议
- 响应延迟满足协议要求

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // Internal registers
    reg [1:0] write_state;
    reg [1:0] read_state;
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] id_reg;
    reg [7:0] addr_reg;
    reg aw_received;
    reg w_received;
    reg [31:0] read_data;
    reg [1:0] read_resp;
    reg [1:0] write_resp;

    // State encoding
    parameter IDLE = 2'b00;
    parameter AW_W_WAIT = 2'b01;
    parameter B_SEND = 2'b10;
    parameter AR_WAIT = 2'b00;  // Same encoding as read state
    parameter R_SEND = 2'b11;   // Different from write states

    // Address decode
    wire [1:0] addr_offset;
    assign addr_offset = awaddr[3:2];
    wire is_valid_addr = (awaddr[7:6] == 2'b00) && (awaddr[5:4] == 2'b00) && (awaddr[3:2] < 4'd4);
    wire is_readonly_addr = (awaddr[7:2] == 6'h0C);
    wire is_readonly_ar = (araddr[7:2] == 6'h0C);
    wire is_valid_ar_addr = (araddr[7:6] == 2'b00) && (araddr[5:4] == 2'b00) && (araddr[3:2] < 4'd4);

    // Outputs
    assign awready = (write_state == IDLE) && !aw_received;
    assign wready = (write_state == IDLE) && !w_received;
    assign arready = (read_state == IDLE);
    assign bvalid = (write_state == B_SEND);
    assign rvalid = (read_state == R_SEND);
    assign bresp = write_resp;
    assign rresp = read_resp;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_state <= IDLE;
            read_state <= IDLE;
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
            id_reg <= 32'h5A5A0003;
            aw_received <= 1'b0;
            w_received <= 1'b0;
            addr_reg <= 8'h0;
            read_data <= 32'h0;
            read_resp <= 2'b00;  // OKAY
            write_resp <= 2'b00; // OKAY
        end else begin
            // Write state machine
            case (write_state)
                IDLE: begin
                    if (awvalid && awready) begin
                        aw_received <= 1'b1;
                        addr_reg <= awaddr;
                    end
                    if (wvalid && wready) begin
                        w_received <= 1'b1;
                        // Perform write operation based on wstrb
                        if (is_valid_addr && !is_readonly_addr) begin
                            if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                            if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                            if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                            if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                        end else if (is_valid_addr && awaddr[3:2] == 2'd1) begin
