    parameter WRITE_IDLE = 2'b00;
    parameter WRITE_WAIT_W = 2'b01;
    parameter WRITE_RESP = 2'b10;

    // Read channel state machine  
    reg [1:0] read_state, next_read_state;
    parameter READ_IDLE = 2'b00;
    parameter READ_RESP = 2'b01;

    // Response signals
    reg [1:0] pending_bresp;
    reg [1:0] pending_rresp;
    reg [31:0] pending_rdata;
    reg write_complete;
    reg read_complete;

