    reg aw_handled;
    reg w_handled;
    reg [7:0] saved_awaddr;
    reg [31:0] saved_wdata;
    reg [3:0] saved_wstrb;

    // Write response ready
    assign awready = (write_state == WRITE_IDLE) && !aw_handled;
    assign wready = (write_state == WRITE_IDLE || write_state == WRITE_WAIT_W) && !w_handled;

    // Read response ready
    assign arready = (read_state == READ_IDLE) && !read_complete;

    // B channel
    assign bvalid = write_complete;
    assign bresp = pending_bresp;

    // R channel
    assign rvalid = read_complete;
    assign rdata = pending_rdata;
    assign rresp = pending_rresp;

