    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] state;
    parameter IDLE = 2'b00, WRITE = 2'b01, READ = 2'b10;

    reg [31:0] reg0, reg1, reg2, reg3; // 0x00, 0x04, 0x08, 0x0C
    reg [31:0] write_addr_reg;
    reg [31:0] read_data_reg;
    reg [1:0] write_resp_reg;
    reg [1:0] read_resp_reg;

    assign awready = (state == IDLE) && (wvalid || awvalid);
    assign wready = (state == IDLE) && (awvalid || wvalid);
    assign arready = (state == IDLE) && arvalid;
    assign bvalid = (state == WRITE);
    assign bresp = write_resp_reg;
    assign rvalid = (state == READ);
    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
            reg3 <= 32'h5A5A0003; // ID register
            write_resp_reg <= 2'b00;
            read_resp_reg <= 2'b00;
            read_data_reg <= 32'h0;
        end else begin
            case (state)
                IDLE: begin
                    if (awvalid && wvalid) begin
                        write_addr_reg <= {24'h0, awaddr};
                        state <= WRITE;

                        // Check address range and write to registers
                        if (awaddr >= 8'h10) begin
                            write_resp_reg <= 2'b10; // DECERR
                        end else if ((awaddr == 8'h0C) && wvalid) begin
                            write_resp_reg <= 2'b10; // SLVERR for write to read-only register
                        end else begin
                            write_resp_reg <= 2'b00; // OKAY

                            // Handle byte-wise writes using wstrb
                            if (awaddr == 8'h00) begin
                                if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg0[31:24] <= wdata[31:24];
