                                if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                            end else if (awaddr == 8'h08) begin
                                if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                            end
                        end
                    end else if (arvalid) begin
                        state <= READ;

                        if (araddr >= 8'h10) begin
                            read_data_reg <= 32'h0;
                            read_resp_reg <= 2'b10; // DECERR
                        end else if (araddr == 8'h00) begin
                            read_data_reg <= reg0;
                            read_resp_reg <= 2'b00; // OKAY
                        end else if (araddr == 8'h04) begin
                            read_data_reg <= reg1;
                            read_resp_reg <= 2'b00; // OKAY
                        end else if (araddr == 8'h08) begin
                            read_data_reg <= reg2;
                            read_resp_reg <= 2'b00; // OKAY
                        end else if (araddr == 8'h0C) begin
                            read_data_reg <= reg3; // ID register
                            read_resp_reg <= 2'b00; // OKAY
                        end else begin
                            read_data_reg <= 32'h0;
                            read_resp_reg <= 2'b10; // DECERR
                        end
                    end
                end

                WRITE: begin
                    if (bready) begin
                        state <= IDLE;
                    end
                end

                READ: begin
                    if (rready) begin
                        state <= IDLE;
                    end
                end
            endcase
