                B_RESP: begin
                    if (bready) begin
                        bvalid <= 1'b0;
                        write_state <= IDLE;
                    end
                end
            endcase

            // 更新读状态
            case (read_state)
                R_IDLE: begin
                    if (arvalid && arready) begin
                        read_addr_valid <= 1'b1;
                        read_saved_addr <= araddr;
                        read_state <= R_RESP;
                        read_delay_cnt <= 3'h0;
                    end
                end
                R_RESP: begin
                    read_delay_cnt <= read_delay_cnt + 1'b1;
                    if (read_delay_cnt == 3'd3) begin
                        rvalid <= 1'b1;
                    end
                end
            endcase

            // 处理写操作
            if (write_state == AW_W && write_delay_cnt == 3'd0) begin
                selected_reg <= saved_addr[3:2];
                if (saved_addr[7:4] != 4'h0) begin
                    write_resp_reg <= 2'b11; // DECERR
                end
                else if (saved_addr[3:2] == 3'h3) begin
                    write_resp_reg <= 2'b10; // SLVERR
                end
