                    if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg1[31:24] <= wdata[31:24];

                    if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                end
            end

            // 处理读操作
            if (read_state == R_RESP && read_delay_cnt == 3'd0) begin
                if (read_saved_addr[7:4] != 4'h0) begin
                    read_data_reg <= 32'h00000000;
                    read_resp_reg <= 2'b11; // DECERR
                end
                else if (read_saved_addr[3:2] == 3'h0) begin
                    read_data_reg <= reg0;
                    read_resp_reg <= 2'b00; // OKAY
                end
                else if (read_saved_addr[3:2] == 3'h1) begin
                    read_data_reg <= reg1;
                    read_resp_reg <= 2'b00; // OKAY
                end
                else if (read_saved_addr[3:2] == 3'h2) begin
                    read_data_reg <= reg2;
                    read_resp_reg <= 2'b00; // OKAY
                end
                else if (read_saved_addr[3:2] == 3'h3) begin
                    read_data_reg <= 32'h5A5A0003;
                    read_resp_reg <= 2'b00; // OKAY
                end
                else begin
                    read_data_reg <= 32'h00000000;
                    read_resp_reg <= 2'b11; // DECERR
                end
            end

            // 处理读响应握手
            if (rready && rvalid) begin
                rvalid <= 1'b0;
                read_state <= R_IDLE;
            end
        end
    end

    // 组合逻辑输出
    assign awready = (write_state == IDLE) && !write_addr_valid;
    assign wready = (write_state == IDLE) && !write_data_valid;
    assign arready = (read_state == R_IDLE) && !read_addr_valid;

    assign bresp = write_resp_reg;
    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

endmodule
