```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state; // 0: idle, 1: got_aw, 2: got_w, 3: waiting_to_respond
    reg [1:0] read_state;  // 0: idle, 1: got_ar, 2-5: waiting_to_respond
