                case ({awaddr[3:2], 2'b00})
                    4'h0: begin
                        if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                    end
                    4'h4: begin
                        if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                    end
                    4'h8: begin
                        if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                    end
                    default: ; // No write for invalid addresses
                endcase
            end

            // Read handling
            if (ar_handshake) begin
                read_start <= 1;
                read_delay_counter <= 1; // Start counting from 1 to 4
            end

            if (read_delay_counter > 0 && read_delay_counter < 5) begin
                read_delay_counter <= read_delay_counter + 1;
            end

            if (read_delay_counter == 4) begin
                rvalid <= 1;
                rdata <= current_rdata;
                rresp <= current_rresp;
                read_delay_counter <= 0;
            end

            if (rvalid & rready) begin
                rvalid <= 0;
            end

            // Set read data and response when starting read
            if (read_start) begin
                read_start <= 0;
                if (araddr[7:4] != 0) begin
                    current_rdata <= 0;
                    current_rresp <= 2'b11; // DECERR
                end else begin
                    case (araddr[3:2])
                        2'b00: begin
                            current_rdata <= reg0;
                            current_rresp <= 2'b00; // OKAY
                        end
                        2'b01: begin
                            current_rdata <= reg1;
                            current_rresp <= 2'b00; // OKAY
                        end
                        2'b10: begin
                            current_rdata <= reg2;
                            current_rresp <= 2'b00; // OKAY
                        end
                        2'b11: begin
                            current_rdata <= 32'h5A5A0003;
                            current_rresp <= 2'b00; // OKAY
                        end
                        default: begin
                            current_rdata <= 0;
                            current_rresp <= 2'b00; // OKAY
                        end
                    endcase
                end
            end

            // Determine write response
            if (both_complete) begin
                if (awaddr[7:4] != 0) begin
                    write_resp <= 2'b11; // DECERR
                end else if (awaddr[3:2] == 3) begin
                    write_resp <= 2'b10; // SLVERR (ID register is read-only)
                end else begin
                    write_resp <= 2'b00; // OKAY
                end
            end
        end
    end

    // Reset write state when not busy
    always @(posedge clk) begin
        if (~rst_n) begin
            write_state[1:0] <= 0;
        end else if (current_bvalid & bready) begin
            write_state[1:0] <= 0;
        end
    end

    assign bvalid = current_bvalid;
    assign bresp = current_bresp;

endmodule

