                     (~a_neg & b_neg) ? 1'b0 :
                     (a[2:0] < b[2:0]);

    assign eq = (a == b);
    assign gt = signed_mode ? gt_signed : gt_unsigned;
    assign lt = signed_mode ? lt_signed : lt_unsigned;
