module seq_detector_1011 (
    input clk,
    input rst_n,
    input din,
    output det
);
    reg [2:0] shift_reg;
    reg det_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg <= 3'b000;
            det_reg <= 1'b0;
        end else begin
            // 检查当前 shift_reg 与 din 是否构成 1011
            if (shift_reg[2:0] == 3'b101 && din == 1'b1)
                det_reg <= 1'b1;
            else
                det_reg <= 1'b0;

            // 更新移位寄存器
            shift_reg <= {shift_reg[1:0], din};
        end
    end

    assign det = det_reg;

