module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output reg tx_busy,
    output reg tx,
    input rx,
    output reg [7:0] rx_data,
    output reg rx_valid,
    output reg rx_err
);

    // 发送状态机
    localparam TX_IDLE = 2'd0;
    localparam TX_START = 2'd1;
    localparam TX_DATA = 2'd2;
    localparam TX_STOP = 2'd3;

    reg [1:0] tx_state;
    reg [3:0] tx_bit_cnt;
    reg [15:0] tx_clk_cnt;
    reg [7:0] tx_shift_reg;

