    localparam RX_IDLE = 2'd0;
    localparam RX_START = 2'd1;
    localparam RX_DATA = 2'd2;
    localparam RX_STOP = 2'd3;

    reg [1:0] rx_state;
    reg [3:0] rx_bit_cnt;
    reg [15:0] rx_clk_cnt;
    reg [7:0] rx_shift_reg;
    reg rx_prev;

    // 发送逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx_busy <= 1'b0;
            tx <= 1'b1;
            tx_bit_cnt <= 4'd0;
            tx_clk_cnt <= 16'd0;
            tx_shift_reg <= 8'd0;
        end else begin
            case (tx_state)
                TX_IDLE: begin
                    tx <= 1'b1;
                    tx_busy <= 1'b0;
                    if (tx_start) begin
                        tx_busy <= 1'b1;
                        tx_shift_reg <= tx_data;
                        tx_state <= TX_START;
                        tx_clk_cnt <= 16'd0;
                        tx <= 1'b0;  // 起始位
                    end
                end

                TX_START: begin
                    tx_busy <= 1'b1;
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 16'd0;
                        tx_state <= TX_DATA;
                        tx_bit_cnt <= 4'd0;
                        tx <= tx_shift_reg[0];  // 第一位数据
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 16'd1;
                    end
                end

                TX_DATA: begin
                    tx_busy <= 1'b1;
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 16'd0;
                        if (tx_bit_cnt == 4'd7) begin
                            tx_state <= TX_STOP;
                            tx <= 1'b1;  // 停止位
                        end else begin
                            tx_bit_cnt <= tx_bit_cnt + 4'd1;
                            tx <= tx_shift_reg[tx_bit_cnt + 1];
                        end
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 16'd1;
                    end
                end

                TX_STOP: begin
                    tx_busy <= 1'b1;
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 16'd0;
                        tx_state <= TX_IDLE;
                        tx_busy <= 1'b0;
                        tx <= 1'b1;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 16'd1;
                    end
                end

                default: begin
                    tx_state <= TX_IDLE;
                    tx_busy <= 1'b0;
                    tx <= 1'b1;
                end
            endcase
        end
    end

    // 接收逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_data <= 8'd0;
            rx_valid <= 1'b0;
            rx_err <= 1'b0;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= 16'd0;
            rx_shift_reg <= 8'd0;
