                    if (rx_prev == 1'b1 && rx == 1'b0) begin
                        // 检测到起始位下降沿
                        rx_state <= RX_START;
                        rx_clk_cnt <= 16'd0;
                    end
                end

                RX_START: begin
                    if (rx_clk_cnt == (CLKS_PER_BIT / 2) - 1) begin
                        // 起始位中点采样
                        if (rx == 1'b0) begin
                            // 有效起始位
                            rx_state <= RX_DATA;
                            rx_bit_cnt <= 4'd0;
                            rx_clk_cnt <= 16'd0;
                        end else begin
                            // 毛刺，返回空闲
                            rx_state <= RX_IDLE;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 16'd1;
                    end
                end

                RX_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 16'd0;
                        rx_shift_reg[rx_bit_cnt] <= rx;
                        if (rx_bit_cnt == 4'd7) begin
                            rx_state <= RX_STOP;
                        end else begin
                            rx_bit_cnt <= rx_bit_cnt + 4'd1;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 16'd1;
                    end
                end

                RX_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 16'd0;
                        if (rx == 1'b1) begin
                            rx_data <= rx_shift_reg;
                            rx_valid <= 1'b1;
                        end else begin
                            rx_err <= 1'b1;
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 16'd1;
                    end
                end

                default: begin
                    rx_state <= RX_IDLE;
                end
            endcase
        end
    end

