                    done <= 1'b0;
                    busy <= 1'b0;
                    cs_n <= 1'b1;
                    sclk <= 1'b0;
                    sclk_int <= 1'b0;
                    sclk_prev <= 1'b0;
                    mosi <= 1'b0;
                    state <= IDLE;
                end
            endcase
        end
