    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regs [0:31];
    integer i;

    // 输出寄存器
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

    // 组合读口
    assign dbg_data = (dbg_addr == 5'd0) ? 32'd0 : regs[dbg_addr];

    // 指令字段
    wire [6:0] opcode = instr[6:0];
    wire [4:0] rd = instr[11:7];
    wire [2:0] funct3 = instr[14:12];
    wire [4:0] rs1 = instr[19:15];
    wire [4:0] rs2 = instr[24:20];
    wire [6:0] funct7 = instr[31:25];
    wire [11:0] imm = instr[31:20];

    // 立即数符号扩展
    wire [31:0] imm_sext = {{20{imm[11]}}, imm};

    // 操作数
    wire [31:0] op1 = (rs1 == 5'd0) ? 32'd0 : regs[rs1];
    wire [31:0] op2 = (rs2 == 5'd0) ? 32'd0 : regs[rs2];

    // 移位量
    wire [4:0] shamt_r = op2[4:0];
    wire [4:0] shamt_i = imm[4:0];

    // 指令合法性判断
    reg is_legal;
    reg [31:0] alu_out;

    always @(*) begin
        is_legal = 1'b0;
        alu_out = 32'd0;

        case (opcode)
            7'b0110011: begin // R-type
                case (funct3)
                    3'b000: begin // ADD / SUB
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 + op2;
                        end else if (funct7 == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out = op1 - op2;
                        end
                    end
                    3'b001: begin // SLL
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 << shamt_r;
                        end
                    end
                    3'b010: begin // SLT
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = ($signed(op1) < $signed(op2)) ? 32'd1 : 32'd0;
                        end
                    end
                    3'b011: begin // SLTU
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = (op1 < op2) ? 32'd1 : 32'd0;
                        end
                    end
                    3'b100: begin // XOR
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 ^ op2;
                        end
                    end
                    3'b101: begin // SRL / SRA
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 >> shamt_r;
                        end else if (funct7 == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out = $signed(op1) >>> shamt_r;
                        end
                    end
                    3'b110: begin // OR
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 | op2;
                        end
                    end
                    3'b111: begin // AND
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 & op2;
                        end
                    end
                endcase
            end

            7'b0010011: begin // I-type
                case (funct3)
                    3'b000: begin // ADDI
                        is_legal = 1'b1;
                        alu_out = op1 + imm_sext;
                    end
                    3'b001: begin // SLLI
                        if (imm[11:5] == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 << shamt_i;
                        end
                    end
                    3'b010: begin // SLTI
                        is_legal = 1'b1;
                        alu_out = ($signed(op1) < $signed(imm_sext)) ? 32'd1 : 32'd0;
                    end
                    3'b011: begin // SLTIU
                        is_legal = 1'b1;
                        alu_out = (op1 < imm_sext) ? 32'd1 : 32'd0;
                    end
                    3'b100: begin // XORI
                        is_legal = 1'b1;
                        alu_out = op1 ^ imm_sext;
                    end
                    3'b101: begin // SRLI / SRAI
                        if (imm[11:5] == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out = op1 >> shamt_i;
                        end else if (imm[11:5] == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out = $signed(op1) >>> shamt_i;
                        end
                    end
                    3'b110: begin // ORI
                        is_legal = 1'b1;
                        alu_out = op1 | imm_sext;
                    end
                    3'b111: begin // ANDI
                        is_legal = 1'b1;
                        alu_out = op1 & imm_sext;
                    end
                endcase
            end
        endcase
    end

    // 时序逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= 32'd0;
            alu_result_reg <= 32'd0;
            illegal_reg <= 1'b0;
        end else if (valid) begin
            if (is_legal) begin
                if (rd != 5'd0)
                    regs[rd] <= alu_out;
                alu_result_reg <= alu_out;
                illegal_reg <= 1'b0;
            end else begin
                alu_result_reg <= 32'd0;
                illegal_reg <= 1'b1;
            end
        end
    end

