module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    // 状态机定义
    localparam IDLE       = 4'd0;
    localparam START      = 4'd1;
    localparam ADDR       = 4'd2;
    localparam ADDR_ACK   = 4'd3;
    localparam WR_DATA    = 4'd4;
    localparam WR_ACK     = 4'd5;
    localparam RD_DATA    = 4'd6;
    localparam RD_NACK    = 4'd7;
    localparam STOP       = 4'd8;

    reg [3:0] state, next_state;
    reg [7:0] shift_reg;
    reg [2:0] bit_cnt;
    reg rw_reg;
    reg [6:0] addr_reg;
    reg [7:0] wdata_reg;
    reg [7:0] rdata_reg;

    // 相位计数器
    reg [15:0] phase_cnt;
    reg [1:0] phase;

    // 相位计数
    always @(posedge clk) begin
        if (!rst_n) begin
            phase_cnt <= 16'd0;
            phase <= 2'd0;
        end else if (state == IDLE) begin
            phase_cnt <= 16'd0;
            phase <= 2'd0;
        end else begin
            if (phase_cnt == CLK_DIV - 1) begin
                phase_cnt <= 16'd0;
                phase <= phase + 1'b1;
            end else begin
                phase_cnt <= phase_cnt + 1'b1;
            end
        end
    end

    // 状态寄存器
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // 事务寄存器
    always @(posedge clk) begin
        if (!rst_n) begin
            busy <= 1'b0;
            done <= 1'b0;
            ack_err <= 1'b0;
            scl_o <= 1'b1;
            sda_o <= 1'b1;
            rdata <= 8'd0;
            shift_reg <= 8'd0;
            bit_cnt <= 3'd0;
            rw_reg <= 1'b0;
            addr_reg <= 7'd0;
            wdata_reg <= 8'd0;
            rdata_reg <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    scl_o <= 1'b1;
                    sda_o <= 1'b1;
                    if (start && !busy) begin
                        busy <= 1'b1;
                        ack_err <= 1'b0;
                        rw_reg <= rw;
                        addr_reg <= addr;
                        wdata_reg <= wdata;
                        rdata_reg <= 8'd0;
                    end
                end

                START: begin
                    if (phase == 2'd0) begin
                        scl_o <= 1'b1;
                        sda_o <= 1'b0;
                    end else if (phase == 2'd2) begin
                        scl_o <= 1'b0;
                    end
                end

                ADDR: begin
                    if (phase == 2'd0) begin
                        if (bit_cnt == 3'd0) begin
                            shift_reg <= {addr_reg, rw_reg};
                        end else begin
                            shift_reg <= {shift_reg[6:0], 1'b0};
                        end
                        sda_o <= shift_reg[7];
                    end else if (phase == 2'd2) begin
                        if (bit_cnt == 3'd7) begin
                            sda_o <= 1'b1; // 释放SDA准备ACK
                        end
                    end
                end

                ADDR_ACK: begin
                    if (phase == 2'd2) begin
                        if (sda_i == 1'b1) begin
                            ack_err <= 1'b1;
                        end
                    end
                end

                WR_DATA: begin
                    if (phase == 2'd0) begin
                        if (bit_cnt == 3'd0) begin
                            shift_reg <= wdata_reg;
                        end else begin
                            shift_reg <= {shift_reg[6:0], 1'b0};
                        end
                        sda_o <= shift_reg[7];
                    end else if (phase == 2'd2) begin
                        if (bit_cnt == 3'd7) begin
                            sda_o <= 1'b1;
                        end
                    end
                end

                WR_ACK: begin
                    if (phase == 2'd2) begin
                        if (sda_i == 1'b1) begin
                            ack_err <= 1'b1;
                        end
                    end
                end

                RD_DATA: begin
                    if (phase == 2'd0) begin
                        sda_o <= 1'b1; // 释放SDA
                    end else if (phase == 2'd2) begin
                        rdata_reg <= {rdata_reg[6:0], sda_i};
                    end
                end

                RD_NACK: begin
                    if (phase == 2'd0) begin
                        sda_o <= 1'b1; // 主机发送NACK
                    end
                end

                STOP: begin
                    if (phase == 2'd0) begin
                        scl_o <= 1'b0;
                        sda_o <= 1'b0;
                    end else if (phase == 2'd1) begin
                        scl_o <= 1'b1;
                    end else if (phase == 2'd2) begin
                        sda_o <= 1'b1;
                    end else if (phase == 2'd3) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        rdata <= rdata_reg;
                    end
                end
            endcase
        end
    end

    // 位计数器
    always @(posedge clk) begin
        if (!rst_n) begin
            bit_cnt <= 3'd0;
        end else if (state == IDLE) begin
            bit_cnt <= 3'd0;
        end else if ((state == ADDR || state == WR_DATA || state == RD_DATA) && phase == 2'd3) begin
            if (bit_cnt == 3'd7) begin
                bit_cnt <= 3'd0;
            end else begin
                bit_cnt <= bit_cnt + 1'b1;
            end
        end
    end

    // 下一状态逻辑
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start && !busy) begin
                    next_state = START;
                end
            end
            START: begin
                if (phase == 2'd3) begin
                    next_state = ADDR;
                end
            end
            ADDR: begin
                if (phase == 2'd3 && bit_cnt == 3'd7) begin
                    next_state = ADDR_ACK;
                end
            end
            ADDR_ACK: begin
                if (phase == 2'd3) begin
                    if (ack_err) begin
                        next_state = STOP;
                    end else if (rw_reg == 1'b0) begin
                        next_state = WR_DATA;
                    end else begin
                        next_state = RD_DATA;
                    end
                end
            end
            WR_DATA: begin
                if (phase == 2'd3 && bit_cnt == 3'd7) begin
