    wire [31:0] rs1_data = (rs1 == 5'd0) ? 32'd0 : regs[rs1];
    wire [31:0] rs2_data = (rs2 == 5'd0) ? 32'd0 : regs[rs2];

    // 立即数符号扩展
    wire [31:0] imm_sext = {{20{imm[11]}}, imm};

    // 移位量
    wire [4:0] shamt_r = rs2_data[4:0];
    wire [4:0] shamt_i = imm[4:0];

