            7'b0110011: begin // R-type
                case (funct3)
                    3'b000: begin
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data + rs2_data; // ADD
                        end else if (funct7 == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data - rs2_data; // SUB
