                    3'b100: begin
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data ^ rs2_data; // XOR
                        end
                    end
                    3'b101: begin
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data >> shamt_r; // SRL
                        end else if (funct7 == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out  = $signed(rs1_data) >>> shamt_r; // SRA
                        end
                    end
                    3'b110: begin
                        if (funct7 == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data | rs2_data; // OR
