                            is_legal = 1'b1;
                            alu_out  = rs1_data << shamt_i; // SLLI
                        end
                    end
                    3'b010: begin
                        is_legal = 1'b1;
                        alu_out  = ($signed(rs1_data) < $signed(imm_sext)) ? 32'd1 : 32'd0; // SLTI
                    end
                    3'b011: begin
                        is_legal = 1'b1;
                        alu_out  = (rs1_data < imm_sext) ? 32'd1 : 32'd0; // SLTIU
                    end
                    3'b100: begin
                        is_legal = 1'b1;
                        alu_out  = rs1_data ^ imm_sext; // XORI
                    end
                    3'b101: begin
                        if (imm[11:5] == 7'b0000000) begin
                            is_legal = 1'b1;
                            alu_out  = rs1_data >> shamt_i; // SRLI
                        end else if (imm[11:5] == 7'b0100000) begin
                            is_legal = 1'b1;
                            alu_out  = $signed(rs1_data) >>> shamt_i; // SRAI
                        end
                    end
                    3'b110: begin
                        is_legal = 1'b1;
                        alu_out  = rs1_data | imm_sext; // ORI
                    end
                    3'b111: begin
                        is_legal = 1'b1;
                        alu_out  = rs1_data & imm_sext; // ANDI
                    end
                    default: begin
                        is_legal = 1'b0;
                        alu_out  = 32'd0;
                    end
                endcase
            end

            default: begin
                is_legal = 1'b0;
                alu_out  = 32'd0;
            end
        endcase
    end

    // 时序逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= 32'd0;
            alu_result <= 32'd0;
            illegal    <= 1'b0;
