module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output reg [7:0] data,
    output reg valid,
    output reg err
);

    // 同步寄存器
    reg ps2_clk_sync1, ps2_clk_sync2;
    reg ps2_data_sync1, ps2_data_sync2;
    reg ps2_clk_prev;

    // 状态定义
    localparam IDLE = 2'd0;
    localparam RECV = 2'd1;

    reg [1:0] state;
    reg [3:0] bit_cnt;       // 0~10，共11位
    reg [7:0] shift_reg;     // 接收数据移位寄存器
    reg parity;              // 计算奇校验
    reg [15:0] timeout_cnt;  // 超时计数器

    wire ps2_clk_fall;

    // 同步 ps2_clk 和 ps2_data
    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync1 <= 1'b1;
            ps2_clk_sync2 <= 1'b1;
            ps2_data_sync1 <= 1'b1;
            ps2_data_sync2 <= 1'b1;
            ps2_clk_prev <= 1'b1;
        end else begin
            ps2_clk_sync1 <= ps2_clk;
            ps2_clk_sync2 <= ps2_clk_sync1;
            ps2_data_sync1 <= ps2_data;
            ps2_data_sync2 <= ps2_data_sync1;
            ps2_clk_prev <= ps2_clk_sync2;
        end
    end

    // 检测下降沿
    assign ps2_clk_fall = (ps2_clk_prev == 1'b1) && (ps2_clk_sync2 == 1'b0);

    // 主状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 4'd0;
            shift_reg <= 8'd0;
            parity <= 1'b0;
            timeout_cnt <= 16'd0;
            data <= 8'd0;
            valid <= 1'b0;
            err <= 1'b0;
        end else begin
            // 默认输出
            valid <= 1'b0;
            err <= 1'b0;

            case (state)
                IDLE: begin
                    timeout_cnt <= 16'd0;
                    if (ps2_clk_fall && ps2_data_sync2 == 1'b0) begin
                        // 起始位正确，进入接收状态
                        state <= RECV;
                        bit_cnt <= 4'd0;
                        shift_reg <= 8'd0;
                        parity <= 1'b0;
                        timeout_cnt <= 16'd0;
                    end
                end

                RECV: begin
                    // 超时检测
                    if (timeout_cnt >= TIMEOUT) begin
                        // 超时，放弃当前帧
                        state <= IDLE;
                        bit_cnt <= 4'd0;
                        timeout_cnt <= 16'd0;
                    end else if (ps2_clk_fall) begin
                        timeout_cnt <= 16'd0;
                        if (bit_cnt == 4'd0) begin
                            // 起始位已在IDLE检测，这里跳过起始位
                            // 实际上起始位在IDLE状态已经处理，进入RECV后第一个下降沿是D0
                            // 但为了统一，这里bit_cnt=0时对应D0
                            shift_reg[0] <= ps2_data_sync2;
                            parity <= ps2_data_sync2;
                            bit_cnt <= bit_cnt + 1'b1;
                        end else if (bit_cnt >= 4'd1 && bit_cnt <= 4'd7) begin
                            // D1~D7
                            shift_reg[bit_cnt] <= ps2_data_sync2;
                            parity <= parity ^ ps2_data_sync2;
                            bit_cnt <= bit_cnt + 1'b1;
                        end else if (bit_cnt == 4'd8) begin
                            // 校验位
                            parity <= parity ^ ps2_data_sync2;
                            bit_cnt <= bit_cnt + 1'b1;
                        end else if (bit_cnt == 4'd9) begin
                            // 停止位
                            bit_cnt <= bit_cnt + 1'b1;
                            // 检查停止位和奇校验
                            if (ps2_data_sync2 == 1'b1 && parity == 1'b1) begin
                                // 正确帧
                                data <= shift_reg;
                                valid <= 1'b1;
                            end else begin
                                // 错误帧
                                err <= 1'b1;
                            end
                            state <= IDLE;
                        end
                    end else begin
                        timeout_cnt <= timeout_cnt + 1'b1;
                    end
                end
            endcase
        end
    end

