                                end else begin
                                    err <= 1'b1;
                                end
                                state <= IDLE;
                                bit_cnt <= 4'd0;
                            end
                        end
                    end
                end

                default: begin
                    state <= IDLE;
                    bit_cnt <= 4'd0;
                    timeout_cnt <= 16'd0;
                end
            endcase
        end
    end

