    reg [7:0] count, next_count;
    reg [7:0] src_reg, dst_reg, len_reg;
    reg [7:0] next_src_reg, next_dst_reg, next_len_reg;
    reg [7:0] mem_addr_reg, next_mem_addr;
    reg [7:0] mem_wdata_reg, next_mem_wdata;
    reg mem_we_reg, next_mem_we;
    reg mem_re_reg, next_mem_re;
    reg busy_reg, next_busy;
    reg done_reg, next_done;

