            count <= 8'd0;
            src_reg <= 8'd0;
            dst_reg <= 8'd0;
            len_reg <= 8'd0;
            mem_addr_reg <= 8'd0;
            mem_wdata_reg <= 8'd0;
            mem_we_reg <= 1'b0;
            mem_re_reg <= 1'b0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
        end else begin
            state <= next_state;
            count <= next_count;
            src_reg <= next_src_reg;
            dst_reg <= next_dst_reg;
            len_reg <= next_len_reg;
            mem_addr_reg <= next_mem_addr;
            mem_wdata_reg <= next_mem_wdata;
            mem_we_reg <= next_mem_we;
            mem_re_reg <= next_mem_re;
            busy_reg <= next_busy;
            done_reg <= next_done;
