module simple_dma (
    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output busy,
    output done,
    output [7:0] mem_addr,
    output [7:0] mem_wdata,
    output mem_we,
    output mem_re,
    input [7:0] mem_rdata
);

    // State encoding
    localparam IDLE     = 3'd0;
    localparam READ     = 3'd1;
    localparam WRITE    = 3'd2;
    localparam DONE_S   = 3'd3;

    reg [2:0] state, next_state;
    reg [7:0] count, next_count;
    reg [7:0] src_reg, dst_reg, len_reg;
    reg [7:0] next_src_reg, next_dst_reg, next_len_reg;
    reg [7:0] mem_addr_r, next_mem_addr;
    reg [7:0] mem_wdata_r, next_mem_wdata;
    reg mem_we_r, next_mem_we;
    reg mem_re_r, next_mem_re;
    reg busy_r, next_busy;
    reg done_r, next_done;

    assign busy = busy_r;
    assign done = done_r;
    assign mem_addr = mem_addr_r;
    assign mem_wdata = mem_wdata_r;
    assign mem_we = mem_we_r;
    assign mem_re = mem_re_r;

    // Sequential logic
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            count <= 8'd0;
            src_reg <= 8'd0;
            dst_reg <= 8'd0;
            len_reg <= 8'd0;
            mem_addr_r <= 8'd0;
            mem_wdata_r <= 8'd0;
            mem_we_r <= 1'b0;
            mem_re_r <= 1'b0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
        end else begin
            state <= next_state;
            count <= next_count;
            src_reg <= next_src_reg;
            dst_reg <= next_dst_reg;
            len_reg <= next_len_reg;
            mem_addr_r <= next_mem_addr;
            mem_wdata_r <= next_mem_wdata;
            mem_we_r <= next_mem_we;
            mem_re_r <= next_mem_re;
            busy_r <= next_busy;
            done_r <= next_done;
        end
    end

    // Combinational logic
    always @* begin
        // Defaults
        next_state = state;
        next_count = count;
        next_src_reg = src_reg;
        next_dst_reg = dst_reg;
        next_len_reg = len_reg;
        next_mem_addr = mem_addr_r;
        next_mem_wdata = mem_wdata_r;
        next_mem_we = 1'b0;
        next_mem_re = 1'b0;
        next_busy = busy_r;
        next_done = 1'b0;

        case (state)
            IDLE: begin
                next_busy = 1'b0;
                next_done = 1'b0;
                next_mem_we = 1'b0;
                next_mem_re = 1'b0;
                if (start && !busy_r) begin
                    next_src_reg = src;
                    next_dst_reg = dst;
                    next_len_reg = len;
                    next_count = 8'd0;
                    if (len == 8'd0) begin
                        // len = 0: no memory access, done within 3 cycles
                        next_state = DONE_S;
                        next_busy = 1'b0;
                    end else begin
                        next_state = READ;
                        next_busy = 1'b1;
                    end
                end
            end

            READ: begin
                next_busy = 1'b1;
                next_mem_re = 1'b1;
                next_mem_addr = src_reg + count;
                next_state = WRITE;
            end

            WRITE: begin
                next_busy = 1'b1;
                next_mem_we = 1'b1;
                next_mem_addr = dst_reg + count;
                next_mem_wdata = mem_rdata;
                if (count == len_reg - 8'd1) begin
                    // Last write
                    next_state = DONE_S;
                end else begin
                    next_count = count + 8'd1;
                    next_state = READ;
                end
            end

            DONE_S: begin
                next_busy = 1'b0;
                next_done = 1'b1;
                next_mem_we = 1'b0;
                next_mem_re = 1'b0;
                next_state = IDLE;
            end

            default: begin
                next_state = IDLE;
                next_busy = 1'b0;
                next_done = 1'b0;
                next_mem_we = 1'b0;
                next_mem_re = 1'b0;
            end
        endcase
    end

endmodule

