    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // 寄存器
    reg [31:0] reg0, reg1, reg2;
    wire [31:0] id_reg;
    assign id_reg = 32'h5A5A_0003;

    // 写地址通道状态
    reg aw_done;
    reg [7:0] awaddr_reg;
    reg aw_pending;

    // 写数据通道状态
    reg w_done;
    reg [31:0] wdata_reg;
    reg [3:0] wstrb_reg;
    reg w_pending;

    // 写响应通道状态
    reg bvalid_reg;
    reg [1:0] bresp_reg;
    reg b_pending;

    // 读地址通道状态
    reg ar_done;
    reg [7:0] araddr_reg;
    reg ar_pending;

    // 读数据通道状态
    reg rvalid_reg;
    reg [31:0] rdata_reg;
    reg [1:0] rresp_reg;
    reg r_pending;

    // 地址译码函数
    wire [1:0] aw_reg_sel;
    wire aw_unmapped;
    assign aw_reg_sel = awaddr_reg[3:2];
    assign aw_unmapped = (awaddr_reg[7:4] != 4'b0000);

    wire [1:0] ar_reg_sel;
    wire ar_unmapped;
    assign ar_reg_sel = araddr_reg[3:2];
    assign ar_unmapped = (araddr_reg[7:4] != 4'b0000);

    // awready: 当没有未完成的写地址事务时接受
    assign awready = !aw_pending;

    // wready: 当没有未完成的写数据事务时接受
    assign wready = !w_pending;

    // arready: 当没有未完成的读地址事务时接受
    assign arready = !ar_pending;

    // 写地址通道握手
    always @(posedge clk) begin
        if (!rst_n) begin
            aw_pending <= 1'b0;
            awaddr_reg <= 8'b0;
        end else begin
            if (awvalid && awready) begin
                awaddr_reg <= awaddr;
                aw_pending <= 1'b1;
            end else if (aw_pending && w_pending && !b_pending) begin
                // 当写地址和写数据都已接收，且写响应未挂起时，清除写地址挂起
                aw_pending <= 1'b0;
            end
        end
    end

    // 写数据通道握手
    always @(posedge clk) begin
        if (!rst_n) begin
            w_pending <= 1'b0;
            wdata_reg <= 32'b0;
            wstrb_reg <= 4'b0;
        end else begin
            if (wvalid && wready) begin
                wdata_reg <= wdata;
                wstrb_reg <= wstrb;
                w_pending <= 1'b1;
            end else if (aw_pending && w_pending && !b_pending) begin
                w_pending <= 1'b0;
            end
        end
    end

    // 写响应通道
    always @(posedge clk) begin
        if (!rst_n) begin
            bvalid_reg <= 1'b0;
            bresp_reg <= 2'b00;
            b_pending <= 1'b0;
        end else begin
            if (bvalid_reg && bready) begin
                bvalid_reg <= 1'b0;
                b_pending <= 1'b0;
            end else if (aw_pending && w_pending && !b_pending) begin
                // 写地址和写数据都已接收，产生写响应
                bvalid_reg <= 1'b1;
                b_pending <= 1'b1;
                if (aw_unmapped) begin
                    bresp_reg <= 2'b11; // DECERR
                end else if (aw_reg_sel == 2'b11) begin
                    bresp_reg <= 2'b10; // SLVERR (地址0x0C)
                end else begin
                    bresp_reg <= 2'b00; // OKAY
                    // 执行写操作
                    case (aw_reg_sel)
                        2'b00: begin
                            if (wstrb_reg[0]) reg0[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg0[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg0[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg0[31:24] <= wdata_reg[31:24];
                        end
                        2'b01: begin
                            if (wstrb_reg[0]) reg1[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg1[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg1[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg1[31:24] <= wdata_reg[31:24];
                        end
                        2'b10: begin
                            if (wstrb_reg[0]) reg2[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg2[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg2[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg2[31:24] <= wdata_reg[31:24];
                        end
                        default: ;
                    endcase
                end
            end
        end
    end

    // 读地址通道握手
    always @(posedge clk) begin
        if (!rst_n) begin
            ar_pending <= 1'b0;
            araddr_reg <= 8'b0;
        end else begin
            if (arvalid && arready) begin
                araddr_reg <= araddr;
                ar_pending <= 1'b1;
            end else if (ar_pending && !r_pending) begin
                ar_pending <= 1'b0;
            end
        end
    end

    // 读数据通道
    always @(posedge clk) begin
        if (!rst_n) begin
            rvalid_reg <= 1'b0;
            rdata_reg <= 32'b0;
            rresp_reg <= 2'b00;
            r_pending <= 1'b0;
        end else begin
            if (rvalid_reg && rready) begin
                rvalid_reg <= 1'b0;
                r_pending <= 1'b0;
            end else if (ar_pending && !r_pending) begin
                rvalid_reg <= 1'b1;
                r_pending <= 1'b1;
                if (ar_unmapped) begin
                    rdata_reg <= 32'b0;
                    rresp_reg <= 2'b11; // DECERR
                end else begin
                    rresp_reg <= 2'b00; // OKAY
                    case (ar_reg_sel)
                        2'b00: rdata_reg <= reg0;
                        2'b01: rdata_reg <= reg1;
                        2'b10: rdata_reg <= reg2;
                        2'b11: rdata_reg <= id_reg;
                        default: rdata_reg <= 32'b0;
                    endcase
                end
            end
        end
    end

    // 寄存器复位
    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'b0;
            reg1 <= 32'b0;
            reg2 <= 32'b0;
        end
    end

    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;
    assign rvalid = rvalid_reg;
    assign rdata = rdata_reg;
    assign rresp = rresp_reg;

endmodule
