module shift_reg (
    input clk,
    input rst_n,
    input [1:0] mode,
    input [7:0] d_in,
    input s_in,
    output [7:0] q,
    output s_out
);
    reg [7:0] q_reg;
    wire [7:0] next_q;
    wire s_out_wire;

    // 组合逻辑：计算下一个状态
    assign next_q = (mode == 2'b11) ? d_in :
                   (mode == 2'b01) ? {q_reg[6:0], s_in} :
                   (mode == 2'b10) ? {s_in, q_reg[7:1]} :
                                     q_reg;

    // 组合逻辑：计算 s_out
    assign s_out_wire = (mode == 2'b01) ? q_reg[7] :
                       (mode == 2'b10) ? q_reg[0] :
                                         1'b0;

    // 时序逻辑：在时钟上升沿更新寄存器
    always @(posedge clk) begin
        if (!rst_n)
            q_reg <= 8'b0;
        else
            q_reg <= next_q;
    end

    // 输出赋值
    assign q = q_reg;
    assign s_out = s_out_wire;
endmodule
