module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // 发送相关信号
    reg tx_busy;
    reg tx;
    reg [31:0] tx_counter;
    reg [3:0] tx_bit_index;
    reg [7:0] tx_shifter;
    reg tx_start_d;

    // 接收相关信号
    reg [31:0] rx_counter;
    reg [3:0] rx_bit_index;
    reg [7:0] rx_shifter;
    reg rx_start_detected;
    reg rx_sample_point;
    reg rx_valid_reg;
    reg rx_err_reg;

    // 状态机
    localparam TX_IDLE = 4'd0;
    localparam TX_START = 4'd1;
    localparam TX_DATA = 4'd2;
    localparam TX_STOP = 4'd3;

    localparam RX_IDLE = 4'd0;
    localparam RX_START = 4'd1;
    localparam RX_DATA = 4'd2;
    localparam RX_STOP = 4'd3;

    reg [3:0] tx_state, rx_state;

    // 发送逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_busy <= 1'b0;
            tx <= 1'b1;
            tx_counter <= 0;
            tx_bit_index <= 0;
            tx_shifter <= 0;
            tx_state <= TX_IDLE;
            tx_start_d <= 1'b0;
        end else begin
            tx_start_d <= tx_start;

            case (tx_state)
                TX_IDLE: begin
                    if (tx_start && !tx_busy && !tx_start_d) begin
                        tx_busy <= 1'b1;
                        tx_shifter <= tx_data;
                        tx_counter <= 0;
                        tx_bit_index <= 0;
                        tx_state <= TX_START;
                    end
                end

                TX_START: begin
                    if (tx_counter == CLKS_PER_BIT/2 - 1) begin
                        tx <= 1'b0;
                        tx_counter <= 0;
                        tx_state <= TX_DATA;
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                end

                TX_DATA: begin
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx <= tx_shifter[0];
                        tx_shifter <= {1'b0, tx_shifter[7:1]};
                        tx_counter <= 0;
                        tx_bit_index <= tx_bit_index + 1;

                        if (tx_bit_index == 7) begin
                            tx_state <= TX_STOP;
                        end
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                end

                TX_STOP: begin
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx <= 1'b1;
                        tx_busy <= 1'b0;
                        tx_state <= TX_IDLE;
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                end
            endcase
        end
    end

    // 接收逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_counter <= 0;
            rx_bit_index <= 0;
            rx_shifter <= 0;
            rx_start_detected <= 1'b0;
            rx_sample_point <= 1'b0;
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;
            rx_state <= RX_IDLE;
        end else begin
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;

