parameter TX_DELAY = 3'd1;
parameter RX_SAMPLE = 3'd2;
parameter RX_DONE = 3'd3;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sclk_sync <= 2'b00;
        cs_n_sync <= 2'b11;
        mosi_sync <= 2'b00;
        shift_reg <= 8'h00;
        bit_count <= 4'd0;
        state <= IDLE;
        miso_out <= 1'b0;
        rx_data_out <= 8'h00;
        rx_valid_out <= 1'b0;
