module vga_timing #(
    parameter H_ACTIVE = 640,
    parameter H_FP = 16,
    parameter H_SYNC = 96,
    parameter H_BP = 48,
    parameter V_ACTIVE = 480,
    parameter V_FP = 10,
    parameter V_SYNC = 2,
    parameter V_BP = 33
) (
    input clk,
    input rst_n,
    output hsync,
    output vsync,
    output de,
    output [9:0] x,
    output [9:0] y
);

    // 计算总长度
    localparam H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;
    localparam V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;

    // 内部信号
    reg [9:0] hcnt;
    reg [9:0] vcnt;
    reg hsync_reg;
    reg vsync_reg;
    reg de_reg;
    reg [9:0] x_reg;
    reg [9:0] y_reg;

    // 行同步和场同步生成
    wire hsync_pulse = (hcnt >= H_ACTIVE + H_FP) && (hcnt < H_ACTIVE + H_FP + H_SYNC);
    wire vsync_pulse = (vcnt >= V_ACTIVE + V_FP) && (vcnt < V_ACTIVE + V_FP + V_SYNC);

    // 显示使能
    wire de_pulse = (hcnt < H_ACTIVE) && (vcnt < V_ACTIVE);

    // 复位逻辑
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hcnt <= 0;
            vcnt <= 0;
            hsync_reg <= 1;
            vsync_reg <= 1;
            de_reg <= 0;
            x_reg <= 0;
            y_reg <= 0;
        end else begin
            // 更新行计数器
            if (hcnt == H_TOTAL - 1) begin
                hcnt <= 0;
                if (vcnt == V_TOTAL - 1)
                    vcnt <= 0;
                else
                    vcnt <= vcnt + 1;
            end else begin
                hcnt <= hcnt + 1;
            end

            // 更新输出信号
            hsync_reg <= ~hsync_pulse;
            vsync_reg <= ~vsync_pulse;
            de_reg <= de_pulse;
            x_reg <= de_pulse ? hcnt : 0;
            y_reg <= de_pulse ? vcnt : 0;
        end
    end

    // 输出赋值
    assign hsync = hsync_reg;
    assign vsync = vsync_reg;
    assign de = de_reg;
    assign x = x_reg;
    assign y = y_reg;

endmodule
