module vga_timing #(
    parameter H_ACTIVE = 640,
    parameter H_FP = 16,
    parameter H_SYNC = 96,
    parameter H_BP = 48,
    parameter V_ACTIVE = 480,
    parameter V_FP = 10,
    parameter V_SYNC = 2,
    parameter V_BP = 33
) (
    input clk,
    input rst_n,
    output hsync,
    output vsync,
    output de,
    output [9:0] x,
    output [9:0] y
);

    // 计算总长度
    localparam H_TOTAL = H_ACTIVE + H_FP + H_SYNC + H_BP;
    localparam V_TOTAL = V_ACTIVE + V_FP + V_SYNC + V_BP;

    // 内部信号
    reg [9:0] hcnt;
    reg [9:0] vcnt;
    reg hsync_reg;
    reg vsync_reg;
    reg de_reg;
    reg [9:0] x_reg;
    reg [9:0] y_reg;

    // 行同步和场同步生成逻辑
    assign hsync = hsync_reg;
    assign vsync = vsync_reg;
    assign de = de_reg;
    assign x = x_reg;
    assign y = y_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hcnt <= 0;
            vcnt <= 0;
            hsync_reg <= 1;
            vsync_reg <= 1;
            de_reg <= 0;
            x_reg <= 0;
            y_reg <= 0;
        end else begin
            // 更新行计数器
            if (hcnt == H_TOTAL - 1) begin
                hcnt <= 0;
                if (vcnt == V_TOTAL - 1)
                    vcnt <= 0;
                else
                    vcnt <= vcnt + 1;
            end else begin
                hcnt <= hcnt + 1;
            end

            // 行同步信号
            if (hcnt >= H_ACTIVE + H_FP && hcnt < H_ACTIVE + H_FP + H_SYNC)
                hsync_reg <= 0;
            else
                hsync_reg <= 1;

            // 场同步信号
            if (vcnt >= V_ACTIVE + V_FP && vcnt < V_ACTIVE + V_FP + V_SYNC)
                vsync_reg <= 0;
            else
                vsync_reg <= 1;

            // 显示使能信号及坐标更新
            if (hcnt < H_ACTIVE && vcnt < V_ACTIVE) begin
                de_reg <= 1;
                x_reg <= hcnt;
                y_reg <= vcnt;
            end else begin
                de_reg <= 0;
                x_reg <= 0;
                y_reg <= 0;
            end
        end
    end

