    input clk,
    input rst_n,
    input start,
    input [7:0] src,
    input [7:0] dst,
    input [7:0] len,
    output reg busy,
    output reg done,
    output reg [7:0] mem_addr,
    output reg [7:0] mem_wdata,
    output reg mem_we,
    output reg mem_re,
    input [7:0] mem_rdata
);

reg [7:0] src_reg, dst_reg, len_reg;
reg [7:0] count;
reg [7:0] addr_src, addr_dst;
reg read_done;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        busy <= 0;
        done <= 0;
        mem_we <= 0;
        mem_re <= 0;
        count <= 0;
        read_done <= 0;
    end else begin
        done <= 0;
        if (!busy && start) begin
            busy <= 1;
            src_reg <= src;
            dst_reg <= dst;
            len_reg <= len;
            count <= 0;
            read_done <= 0;
            mem_re <= 1;
            addr_src <= src;
            addr_dst <= dst;
        end else if (busy) begin
            if (len_reg == 0) begin
                busy <= 0;
                done <= 1;
            end else if (!read_done) begin
                mem_re <= 1;
                addr_src <= src_reg + count;
                read_done <= 1;
