module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

reg [31:0] reg0, reg1, reg2;
reg [31:0] id_reg;

// State machine for write response
reg wr_state;
reg [1:0] wr_resp;
reg wr_valid;
reg [1:0] rd_resp;
reg rd_valid;

// Write address and data handling
reg [7:0] awaddr_reg;
reg [31:0] wdata_reg;
reg [3:0] wstrb_reg;
reg aw_valid_reg;
reg w_valid_reg;

// Read address handling
reg [7:0] araddr_reg;
reg ar_valid_reg;

// Ready signals
wire awready_wire;
wire wready_wire;
wire arready_wire;

// Internal signals
wire [1:0] addr_sel;
wire addr_valid;
wire is_id_addr;
wire is_unmapped;

// Address decoding
assign addr_sel = awaddr[3:2];
assign is_id_addr = (awaddr[3:0] == 4'h0C);
assign is_unmapped = (awaddr[7:4] != 4'd0);
assign addr_valid = (awaddr[1:0] == 2'd0); // Word aligned

// Write address channel
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        aw_valid_reg <= 1'b0;
        awaddr_reg <= 8'd0;
    end else if (awvalid && awready_wire) begin
        aw_valid_reg <= 1'b0;
        awaddr_reg <= awaddr;
    end else if (awvalid) begin
        aw_valid_reg <= 1'b1;
    end
end

// Write data channel
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        w_valid_reg <= 1'b0;
        wdata_reg <= 32'd0;
        wstrb_reg <= 4'd0;
    end else if (wvalid && wready_wire) begin
        w_valid_reg <= 1'b0;
        wdata_reg <= wdata;
        wstrb_reg <= wstrb;
    end else if (wvalid) begin
        w_valid_reg <= 1'b1;
    end
end

// Read address channel
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ar_valid_reg <= 1'b0;
        araddr_reg <= 8'd0;
    end else if (arvalid && arready_wire) begin
        ar_valid_reg <= 1'b0;
        araddr_reg <= araddr;
    end else if (arvalid) begin
        ar_valid_reg <= 1'b1;
    end
end

// Write response logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        wr_state <= 1'b0;
        wr_resp <= 2'b00;
        wr_valid <= 1'b0;
    end else begin
        case (wr_state)
            1'b0: begin
                if (aw_valid_reg && w_valid_reg && awready_wire && wready_wire) begin
                    wr_state <= 1'b1;
                    wr_resp <= 2'b00; // Default to OKAY
                    wr_valid <= 1'b1;
                end
            end
            1'b1: begin
                if (bready) begin
                    wr_state <= 1'b0;
                    wr_valid <= 1'b0;
                end
            end
        endcase
    end
end

// Read response logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rd_resp <= 2'b00;
        rd_valid <= 1'b0;
    end else begin
        if (ar_valid_reg && arready_wire) begin
            rd_resp <= 2'b00; // Default to OKAY
            rd_valid <= 1'b1;
        end else if (rready) begin
            rd_valid <= 1'b0;
        end
    end
end

// Register writes
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        reg0 <= 32'd0;
        reg1 <= 32'd0;
        reg2 <= 32'd0;
    end else begin
        if (aw_valid_reg && w_valid_reg && awready_wire && wready_wire) begin
            case (addr_sel)
                2'd0: begin
                    if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                end
                2'd1: begin
                    if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                end
                2'd2: begin
                    if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                end
            endcase
        end
    end
end

// ID register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        id_reg <= 32'h5A5A0003;
    end
end

// Read data logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rdata <= 32'd0;
    end else begin
        if (ar_valid_reg && arready_wire) begin
            case (araddr_reg[3:2])
                2'd0: rdata <= reg0;
                2'd1: rdata <= reg1;
                2'd2: rdata <= reg2;
                2'd3: rdata <= id_reg;
            endcase
        end
    end
end

// Ready signals
assign awready = ~(aw_valid_reg && !addr_valid) && ~is_unmapped;
assign wready = ~(w_valid_reg && !addr_valid) && ~is_unmapped;
assign arready = ~ar_valid_reg || (ar_valid_reg && addr_valid && !is_unmapped);

// Response signals
assign bresp = wr_resp;
assign rresp = rd_resp;

// Valid signals
assign bvalid = wr_valid;
assign rvalid = rd_valid;

endmodule
