module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg tx_busy_r;
    reg tx_r;
    reg [9:0] tx_shift_reg; // 包含起始位(0) + 8位数据 + 停止位(1)
    reg [3:0] tx_state;     // 0:IDLE, 1:START, 2-9:DATA0-7, 10:STOP
    reg [CLKS_PER_BIT-1:0] tx_counter;

    reg [9:0] rx_shift_reg;
    reg [3:0] rx_state;     // 0:IDLE, 1:WAIT_START, 2:SAMPLE_START, 3-10:DATA0-7+STOP
    reg [CLKS_PER_BIT-1:0] rx_counter;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    // 发送逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1;
            tx_shift_reg <= 10'b0;
            tx_state <= 4'd0;
            tx_counter <= {CLKS_PER_BIT{1'b0}};
        end else begin
            case (tx_state)
                4'd0: begin // IDLE
                    if (tx_start && !tx_busy_r) begin
                        tx_shift_reg <= {1'b1, tx_data, 1'b0}; // stop=1, data, start=0
                        tx_busy_r <= 1'b1;
                        tx_r <= 1'b0; // start bit
                        tx_state <= 4'd1;
                        tx_counter <= 1'b1; // start counting from 1 to CLKS_PER_BIT-1
                    end
                end
                4'd1: begin // START BIT
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_r <= tx_shift_reg[1]; // next bit
                        tx_shift_reg <= {1'b1, tx_shift_reg[9:1]}; // shift left and pad with 1
                        tx_state <= 4'd2;
                        tx_counter <= 1'b1;
                    end else begin
                        tx_counter <= tx_counter + 1'b1;
                    end
                end
                4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9: begin // DATA BITS 0-7
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_r <= tx_shift_reg[1];
                        tx_shift_reg <= {1'b1, tx_shift_reg[9:1]};
                        tx_state <= tx_state + 1'b1;
                        tx_counter <= 1'b1;
                    end else begin
                        tx_counter <= tx_counter + 1'b1;
                    end
                end
                4'd10: begin // STOP BIT
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_r <= 1'b1; // idle state
                        tx_busy_r <= 1'b0;
                        tx_state <= 4'd0;
                        tx_counter <= {CLKS_PER_BIT{1'b0}};
                    end else begin
                        tx_counter <= tx_counter + 1'b1;
                    end
                end
                default: begin
                    tx_state <= 4'd0;
                end
            endcase
        end
    end

    // 接收逻辑
    reg rx_prev;
    reg rx_edge;

    always @(posedge clk) begin
        rx_prev <= rx;
        rx_edge <= (rx_prev == 1'b1) && (rx == 1'b0); // falling edge detection
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            rx_shift_reg <= 10'b0;
            rx_state <= 4'd0;
            rx_counter <= {CLKS_PER_BIT{1'b0}};
            rx_data_r <= 8'b0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
        end else begin
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

