                    if (rx_edge) begin
                        rx_state <= 4'd1; // WAIT_START
                        rx_counter <= 1'b1;
                    end
                end
                4'd1: begin // WAIT_START - wait for half bit period to sample start bit center
                    if (rx_counter == (CLKS_PER_BIT >> 1) - 1) begin
                        if (rx == 0) begin // confirmed valid start bit
                            rx_state <= 4'd2; // SAMPLE_START
                            rx_counter <= 1'b1;
                        end else begin
                            rx_state <= 4'd0; // false trigger, return to idle
                            rx_counter <= {CLKS_PER_BIT{1'b0}};
                        end
                    end else begin
                        rx_counter <= rx_counter + 1'b1;
                    end
                end
                4'd2: begin // SAMPLE_START - this is actually sampling bit 0
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_shift_reg[0] <= rx;
                        rx_state <= 4'd3;
                        rx_counter <= 1'b1;
                    end else begin
                        rx_counter <= rx_counter + 1'b1;
                    end
                end
                4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9: begin // SAMPLE DATA BITS 1-7
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};
                        rx_state <= rx_state + 1'b1;
                        rx_counter <= 1'b1;
                    end else begin
                        rx_counter <= rx_counter + 1'b1;
                    end
                end
                4'd10: begin // SAMPLE STOP BIT
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};
                        if (rx_shift_reg[9] == 1'b1) begin // stop bit should be 1
                            rx_data_r <= rx_shift_reg[8:1];
                            rx_valid_r <= 1'b1;
                        end else begin
                            rx_err_r <= 1'b1;
                        end
                        rx_state <= 4'd0; // return to idle immediately
                        rx_counter <= {CLKS_PER_BIT{1'b0}};
                    end else begin
                        rx_counter <= rx_counter + 1'b1;
                    end
                end
                default: begin
                    rx_state <= 4'd0;
                end
            endcase
        end
    end

