## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, tx_start, tx_data[7:0], rx
   - 寄存器输出：tx_busy, tx, rx_data[7:0], rx_valid, rx_err
   - tx, rx_data是组合逻辑+寄存器，其他输出是纯寄存器

2. **状态机与计数器**：
   - 发送：用计数器控制10位发送（起始位+8数据位+停止位），每CLKS_PER_BIT个周期发送一位
   - 接收：检测起始位下降沿→验证起始位中点→采样8位数据→检查停止位→输出结果
   - 计数器：位计数(0-9)、时钟计数(0到CLKS_PER_BIT-1)

3. **复位行为**：tx=1, tx_busy=0, rx_valid=0, rx_err=0, rx_data保持不变

## 完整代码

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg tx_busy_r;
    reg tx_r;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    // 发送部分
    reg [3:0] tx_bit_cnt;
    reg [4:0] tx_clk_cnt;
    reg [7:0] tx_shift_reg;
    reg tx_start_d;
    reg tx_start_edge;

    always @(posedge clk) begin
        tx_start_d <= tx_start;
    end

    assign tx_start_edge = tx_start & ~tx_start_d & ~tx_busy_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1;
            tx_bit_cnt <= 4'd0;
            tx_clk_cnt <= 5'd0;
            tx_shift_reg <= 8'd0;
        end else begin
            if (tx_start_edge) begin
                tx_busy_r <= 1'b1;
                tx_r <= 1'b0;  // 起始位
                tx_bit_cnt <= 4'd0;
                tx_clk_cnt <= 5'd1;  // 从1开始计数，因为当前周期算作第一位的一部分
                tx_shift_reg <= tx_data;
            end else if (tx_busy_r) begin
                if (tx_clk_cnt < CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= tx_clk_cnt + 1'b1;
                end else begin
                    tx_clk_cnt <= 5'd0;
                    if (tx_bit_cnt < 9) begin
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                        if (tx_bit_cnt == 0) begin
                            // 起始位结束，发送第0位
                            tx_r <= tx_shift_reg[0];
                        end else if (tx_bit_cnt < 8) begin
                            // 发送数据位
                            tx_r <= tx_shift_reg[tx_bit_cnt];
                        end else begin
                            // 发送停止位
                            tx_r <= 1'b1;
                        end
                        if (tx_bit_cnt < 8) begin
                            tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                        end
                    end else begin
                        // 发送完成
                        tx_busy_r <= 1'b0;
                        tx_r <= 1'b1;
                    end
                end
            end
        end
    end

    // 接收部分
    reg [3:0] rx_bit_cnt;
    reg [4:0] rx_clk_cnt;
    reg [7:0] rx_shift_reg;
    reg rx_prev;
    reg rx_start_sampled;
    reg rx_sample_point;
    reg rx_idle;
    reg [4:0] rx_timer;

    always @(posedge clk) begin
        rx_prev <= rx;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_idle <= 1'b1;
            rx_start_sampled <= 1'b0;
            rx_sample_point <= 1'b0;
            rx_timer <= 5'd0;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= 5'd0;
            rx_shift_reg <= 8'd0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
        end else begin
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            if (rx_idle && !rx && rx_prev) begin
                // 检测到起始位下降沿
                rx_idle <= 1'b0;
                rx_start_sampled <= 1'b0;
                rx_timer <= 5'd0;
            end else if (!rx_idle) begin
                if (!rx_start_sampled) begin
                    // 等待起始位中点
                    if (rx_timer < CLKS_PER_BIT/2 - 1) begin
                        rx_timer <= rx_timer + 1'b1;
                    end else begin
                        // 在起始位中点采样
                        if (!rx) begin
                            // 起始位确认有效
                            rx_start_sampled <= 1'b1;
                            rx_bit_cnt <= 4'd0;
                            rx_clk_cnt <= 5'd0;
                            rx_shift_reg <= 8'd0;
                            rx_timer <= 5'd0;
                        end else begin
                            // 毛刺，回到空闲
                            rx_idle <= 1'b1;
                        end
                    end
                end else begin
                    // 已经开始接收数据
                    if (rx_timer < CLKS_PER_BIT - 1) begin
                        rx_timer <= rx_timer + 1'b1;
                    end else begin
                        rx_timer <= 5'd0;
                        if (rx_bit_cnt < 9) begin
                            // 采样当前位
                            if (rx_bit_cnt < 8) begin
                                // 数据位
                                rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                            end else begin
                                // 停止位
                                if (rx) begin
                                    // 正确停止位
                                    rx_data_r <= rx_shift_reg;
                                    rx_valid_r <= 1'b1;
                                end else begin
                                    // 错误停止位
                                    rx_err_r <= 1'b1;
                                end
                            end
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;

