    reg [3:0] rx_bit_cnt;
    reg [4:0] rx_clk_cnt;
    reg [7:0] rx_shift_reg;
    reg rx_prev;
    reg rx_start_sampled;
    reg rx_sample_point;
    reg rx_idle;
    reg [4:0] rx_timer;

    always @(posedge clk) begin
        rx_prev <= rx;
    end

    always @(posedge clk or negedge rst_n) begin
