            rx_idle <= 1'b1;
            rx_start_sampled <= 1'b0;
            rx_sample_point <= 1'b0;
            rx_timer <= 5'd0;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= 5'd0;
            rx_shift_reg <= 8'd0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
        end else begin
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

