                        if (!rx) begin
                            // 起始位确认有效
                            rx_start_sampled <= 1'b1;
                            rx_bit_cnt <= 4'd0;
                            rx_clk_cnt <= 5'd0;
                            rx_shift_reg <= 8'd0;
                            rx_timer <= 5'd0;
                        end else begin
                            // 毛刺，回到空闲
                            rx_idle <= 1'b1;
                        end
                    end
                end else begin
                    // 已经开始接收数据
                    if (rx_timer < CLKS_PER_BIT - 1) begin
                        rx_timer <= rx_timer + 1'b1;
                    end else begin
                        rx_timer <= 5'd0;
                        if (rx_bit_cnt < 9) begin
                            // 采样当前位
                            if (rx_bit_cnt < 8) begin
                                // 数据位
                                rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                            end else begin
                                // 停止位
                                if (rx) begin
                                    // 正确停止位
                                    rx_data_r <= rx_shift_reg;
                                    rx_valid_r <= 1'b1;
                                end else begin
                                    // 错误停止位
                                    rx_err_r <= 1'b1;
                                end
                            end
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;

                            if (rx_bit_cnt == 9) begin
                                // 接收完成，回到空闲
                                rx_idle <= 1'b1;
                            end
                        end
                    end
                end
            end
        end
    end

