## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, tx_start(寄存器), tx_data(寄存器), rx(组合)
   - 输出：tx_busy(寄存器), tx(寄存器), rx_data(寄存器), rx_valid(脉冲), rx_err(脉冲)

2. **状态机与计数器**：
   - 发送状态机：IDLE -> START -> DATA0~7 -> STOP
   - 接收状态机：IDLE -> WAIT_START -> SAMPLE_START -> DATA0~7 -> STOP
   - 发送计数器：0到CLKS_PER_BIT-1，每CLKS_PER_BIT个周期切换一位
   - 接收计数器：用于检测起始边沿和采样位中点

3. **复位行为**：tx=1, tx_busy=0, rx_data保持不变，rx_valid/rx_err=0

## 完整代码

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg tx_busy_r;
    reg tx_r;
    reg [9:0] tx_shift_reg; // start(0) + data[0:7] + stop(1)
    reg [3:0] tx_bit_cnt;   // 0-9 for 10 bits total
    reg [4:0] tx_clk_cnt;   // 0 to CLKS_PER_BIT-1
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg [3:0] rx_bit_cnt;   // 0-9 for 10 bits (start + 8 data + stop)
    reg [4:0] rx_clk_cnt;   // counter for sampling
    reg rx_prev;
    reg rx_start_edge_det;
    reg [4:0] rx_sample_cnt; // for timing the sampling

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    // Transmit logic
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_r <= 1'b1;
            tx_busy_r <= 1'b0;
            tx_clk_cnt <= 0;
            tx_bit_cnt <= 0;
            tx_shift_reg <= 10'b1111111111; // idle state
        end else begin
            if (!tx_busy_r && tx_start) begin
                tx_busy_r <= 1'b1;
                tx_shift_reg <= {1'b1, tx_data, 1'b0}; // stop bit, data, start bit
                tx_clk_cnt <= 0;
                tx_bit_cnt <= 0;
                tx_r <= 1'b0; // start bit
            end else if (tx_busy_r) begin
                if (tx_clk_cnt < CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= tx_clk_cnt + 1;
                end else begin
                    tx_clk_cnt <= 0;
                    if (tx_bit_cnt < 9) begin
                        tx_bit_cnt <= tx_bit_cnt + 1;
                        tx_r <= tx_shift_reg[tx_bit_cnt]; // shift out next bit
                    end else begin
                        tx_r <= 1'b1; // stop bit done, back to idle
                        tx_busy_r <= 1'b0;
                    end
                end
            end
        end
    end

    // Receive logic
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_prev <= 1'b1;
            rx_data_r <= 8'b0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            rx_bit_cnt <= 0;
            rx_clk_cnt <= 0;
            rx_start_edge_det <= 1'b0;
            rx_sample_cnt <= 0;
        end else begin
            rx_prev <= rx;
            rx_start_edge_det <= (rx_prev == 1'b1 && rx == 1'b0); // detect falling edge
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            if (rx_start_edge_det) begin
                // Start sampling at middle of start bit
                rx_sample_cnt <= CLKS_PER_BIT/2;
                rx_bit_cnt <= 0;
            end else if (rx_sample_cnt > 0) begin
                rx_sample_cnt <= rx_sample_cnt - 1;

                if (rx_sample_cnt == 1) begin
                    // Sample at the middle of start bit
                    if (rx == 0) begin
                        // Valid start bit, continue sampling
                        rx_clk_cnt <= 0;
                        rx_sample_cnt <= CLKS_PER_BIT - 1;
                    end else begin
                        // False start, reset
                        rx_sample_cnt <= 0;
                    end
                end
            end else if (rx_sample_cnt == 0 && rx_bit_cnt < 10) begin
                if (rx_clk_cnt < CLKS_PER_BIT - 1) begin
                    rx_clk_cnt <= rx_clk_cnt + 1;
                end else begin
                    rx_clk_cnt <= 0;
                    rx_sample_cnt <= CLKS_PER_BIT - 1;

                    if (rx_bit_cnt < 8) begin
                        // Sample data bits
                        rx_data_r[rx_bit_cnt] <= rx;
                        rx_bit_cnt <= rx_bit_cnt + 1;
                    end else if (rx_bit_cnt == 8) begin
                        // This is the stop bit
                        rx_bit_cnt <= rx_bit_cnt + 1;
                    end else begin
                        // Stop bit sampled
                        if (rx == 1'b1) begin
                            rx_valid_r <= 1'b1;
                        end else begin
                            rx_err_r <= 1'b1;
                        end
                        rx_sample_cnt <= 0; // Go back to idle
                    end
                end
            end
        end
    end

endmodule
