## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, tx_start, tx_data[7:0], rx
   - 寄存器输出：tx_busy, tx, rx_data[7:0], rx_valid, rx_err
   - tx_start是脉冲信号，tx_data在tx_start=1且tx_busy=0时被锁存

2. **状态机设计**：
   - 发送部分：IDLE -> START -> DATA[0-7] -> STOP
   - 接收部分：IDLE -> WAIT_START -> SAMPLE_START -> DATA_SAMPLE[0-7] -> STOP_CHECK
   - 计数器：位时钟计数器(0到CLKS_PER_BIT-1)，位计数器(0到9)

3. **复位行为**：tx=1, tx_busy=0, rx_valid=0, rx_err=0, rx_data保持不变

4. **时序要求**：通过精确的计数器控制位宽度和采样时机，确保在CLKS_PER_BIT/2时刻采样起始位中点

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // Internal registers
    reg tx_busy_r;
    reg tx_r;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;

    // Transmit counters and state
    reg [3:0] tx_state;  // 0: IDLE, 1: START, 2-9: DATA0-DATA7, 10: STOP
    reg [4:0] tx_bit_cnt;  // 0 to 9 for 10 bits total
    reg [4:0] tx_clk_cnt;  // 0 to CLKS_PER_BIT-1

    // Receive counters and state
    reg [3:0] rx_state;  // 0: IDLE, 1: WAIT_START, 2: SAMPLE_START, 3-10: DATA0-DATA7, 11: STOP_CHECK
    reg [4:0] rx_bit_cnt;  // 0 to 9 for 10 bits total
    reg [4:0] rx_clk_cnt;  // 0 to CLKS_PER_BIT-1
    reg [7:0] rx_shift_reg;
    reg prev_rx;

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    // Transmit logic
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1;
            tx_state <= 4'd0;
            tx_bit_cnt <= 5'd0;
            tx_clk_cnt <= 5'd0;
        end else begin
            case (tx_state)
                4'd0: begin  // IDLE
                    if (tx_start && !tx_busy_r) begin
                        tx_busy_r <= 1'b1;
                        tx_r <= 1'b0;  // Start bit
                        tx_state <= 4'd1;
                        tx_bit_cnt <= 5'd0;
                        tx_clk_cnt <= 5'd1;  // Start counting from 1 to CLKS_PER_BIT-1
                    end
                end
                4'd1: begin  // START bit
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_r <= tx_data[0];
                        tx_state <= 4'd2;
                        tx_clk_cnt <= 5'd0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9: begin  // DATA bits
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_r <= tx_data[tx_bit_cnt];  // tx_bit_cnt is current data bit index
                        tx_bit_cnt <= tx_bit_cnt + 1;
                        if (tx_bit_cnt == 7) begin  // Next is stop bit
                            tx_state <= 4'd10;
                        end else begin
                            tx_state <= tx_state + 1;
                        end
                        tx_clk_cnt <= 5'd0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                4'd10: begin  // STOP bit
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_r <= 1'b1;  // Stop bit
                        tx_busy_r <= 1'b0;
                        tx_state <= 4'd0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                default: begin
                    tx_state <= 4'd0;
                    tx_busy_r <= 1'b0;
                end
            endcase
        end
    end

    // Receive logic
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_state <= 4'd0;
            rx_bit_cnt <= 5'd0;
            rx_clk_cnt <= 5'd0;
            rx_data_r <= 8'h00;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            prev_rx <= 1'b1;
            rx_shift_reg <= 8'h00;
        end else begin
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            prev_rx <= rx;

            case (rx_state)
                4'd0: begin  // IDLE - wait for start bit
                    if (prev_rx && ~rx) begin  // Falling edge detected
                        rx_state <= 4'd2;  // Go directly to sample start
                        rx_clk_cnt <= CLKS_PER_BIT/2 - 1;  // Wait for middle of start bit
                    end
                end
                4'd2: begin  // SAMPLE_START - wait for middle of start bit
                    if (rx_clk_cnt == CLKS_PER_BIT/2 - 1) begin
                        if (~rx) begin  // Valid start bit
                            rx_state <= 4'd3;  // Go to first data bit
                            rx_bit_cnt <= 5'd0;
                            rx_clk_cnt <= CLKS_PER_BIT - 1;  // Will be reset to 0 after sampling
                        end else begin
                            rx_state <= 4'd0;  // False start, go back to idle
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9, 4'd10: begin  // DATA bits
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                        rx_bit_cnt <= rx_bit_cnt + 1;
                        if (rx_bit_cnt == 7) begin  // Next is stop bit
                            rx_state <= 4'd11;
                        end else begin
                            rx_state <= rx_state + 1;
                        end
                        rx_clk_cnt <= 5'd0;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                4'd11: begin  // STOP_CHECK - check stop bit
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        if (rx) begin  // Valid stop bit
                            rx_data_r <= rx_shift_reg;
                            rx_valid_r <= 1'b1;
                        end else begin  // Invalid stop bit
                            rx_err_r <= 1'b1;
                        end
                        rx_state <= 4'd0;  // Go back to idle immediately
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                default: begin
                    rx_state <= 4'd0;
                end
            endcase
        end
    end

endmodule
