```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // 发送相关信号
    reg [3:0] tx_state;  // 0: IDLE, 1: START, 2-9: DATA0-DATA7, 10: STOP
    reg [CLKS_PER_BIT-1:0] tx_counter;
    reg [3:0] tx_bit_cnt;
    reg [7:0] tx_shift_reg;
    reg tx_busy_r;
    reg tx_r;

    // 接收相关信号
    reg [3:0] rx_state;  // 0: IDLE, 1: WAIT_START_MID, 2-9: DATA0-DATA7, 10: STOP_CHECK
    reg [CLKS_PER_BIT-1:0] rx_counter;
    reg [3:0] rx_bit_cnt;
    reg [7:0] rx_shift_reg;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;

    // 内部信号
    wire tx_start_pulse = tx_start & ~tx_busy_r;
    wire tx_done = (tx_state == 4'd10) & (tx_counter == CLKS_PER_BIT - 1);
    wire rx_start_edge = (~rx & rx) & (rx_state == 4'd0);  // falling edge of rx when idle

    // 发送状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_state <= 4'd0;
            tx_counter <= 0;
            tx_bit_cnt <= 0;
            tx_shift_reg <= 0;
            tx_busy_r <= 0;
            tx_r <= 1;  // idle state is high
        end else begin
            case (tx_state)
                4'd0: // IDLE
                    if (tx_start_pulse) begin
                        tx_shift_reg <= tx_data;
                        tx_busy_r <= 1;
                        tx_state <= 4'd1;  // go to start bit
                        tx_counter <= 0;
                        tx_bit_cnt <= 0;
                        tx_r <= 0;  // start bit is low
                    end
                4'd1: // START BIT
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_state <= 4'd2;  // go to data bit 0
                        tx_counter <= 0;
                        tx_r <= tx_shift_reg[0];
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9: // DATA BITS 0-7
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_state <= tx_state + 1;
                        tx_counter <= 0;
                        tx_bit_cnt <= tx_bit_cnt + 1;
                        if (tx_state < 4'd9) begin
                            tx_r <= tx_shift_reg[tx_bit_cnt + 1];
                        end
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                4'd10: // STOP BIT
                    if (tx_counter == CLKS_PER_BIT - 1) begin
                        tx_state <= 4'd0;  // back to idle
                        tx_busy_r <= 0;
                        tx_r <= 1;  // stop bit is high
                    end else begin
                        tx_counter <= tx_counter + 1;
                    end
                default:
                    tx_state <= 4'd0;
            endcase
        end
    end

    // 接收状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_state <= 4'd0;
            rx_counter <= 0;
            rx_bit_cnt <= 0;
            rx_shift_reg <= 0;
            rx_data_r <= 0;
            rx_valid_r <= 0;
            rx_err_r <= 0;
        end else begin
            rx_valid_r <= 0;
            rx_err_r <= 0;

            case (rx_state)
                4'd0: // IDLE - wait for start bit
                    if (rx_start_edge) begin
                        rx_state <= 4'd1;  // go to wait for start bit mid point
                        rx_counter <= 0;
                    end
                4'd1: // WAIT_START_MID - wait half bit time to sample start bit center
                    if (rx_counter == (CLKS_PER_BIT >> 1) - 1) begin
                        if (rx == 0) begin  // confirm it's a valid start bit
                            rx_state <= 4'd2;  // go to data bit 0
                            rx_counter <= 0;
                            rx_bit_cnt <= 0;
                        end else begin
                            rx_state <= 4'd0;  // false start, return to idle
                        end
                    end else begin
                        rx_counter <= rx_counter + 1;
                    end
                4'd2, 4'd3, 4'd4, 4'd5, 4'd6, 4'd7, 4'd8, 4'd9: // DATA BITS 0-7
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_shift_reg[rx_bit_cnt] <= rx;
                        rx_state <= rx_state + 1;
                        rx_counter <= 0;
                        rx_bit_cnt <= rx_bit_cnt + 1;
                    end else begin
                        rx_counter <= rx_counter + 1;
                    end
                4'd10: // STOP CHECK - sample stop bit
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        if (rx == 1) begin  // valid stop bit
                            rx_data_r <= rx_shift_reg;
                            rx_valid_r <= 1;
                        end else begin  // invalid stop bit
                            rx_err_r <= 1;
                        end
                        rx_state <= 4'd0;  // return to idle immediately
                    end else begin
                        rx_counter <= rx_counter + 1;
                    end
                default:
                    rx_state <= 4'd0;
            endcase
        end
    end

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

endmodule
