## 设计思路

1. **信号分类**：输入信号包括clk, rst_n, tx_start, tx_data, rx；输出信号中tx_busy, tx, rx_data, rx_valid, rx_err为寄存器输出，tx为组合逻辑输出但需要寄存器存储。

2. **状态机设计**：发送部分用3位状态机(0-9表示10个位)，接收部分用2位状态机(空闲/等待起始位/采样/停止)。计数器用于位时序控制，发送计数器范围[0:CLKS_PER_BIT-1]，接收在起始位中点后每CLKS_PER_BIT周期采样。

3. **复位行为**：复位时tx=1, tx_busy=0, rx_valid=0, rx_err=0。发送在tx_start且非busy时启动，接收检测rx下降沿开始。

4. **时序要求**：通过精确的计数器控制每位宽度，接收在CLKS_PER_BIT/2时刻采样起始位中点验证，然后每CLKS_PER_BIT周期采样数据位和停止位。

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output reg tx_busy,
    output reg tx,
    input rx,
    output reg [7:0] rx_data,
    output reg rx_valid,
    output reg rx_err
);

    // 发送相关信号
    reg [2:0] tx_state;      // 0-9: 起始位到停止位
    reg [3:0] tx_bit_cnt;
    reg [7:0] tx_shift_reg;
    reg [9:0] tx_counter;

    // 接收相关信号
    reg [1:0] rx_state;      // 0: idle, 1: wait_start, 2: sample, 3: stop
    reg [9:0] rx_counter;
    reg [2:0] rx_bit_cnt;
    reg [7:0] rx_shift_reg;
    reg rx_prev;
    reg rx_edge_det;

    always @(posedge clk) begin
        if (!rst_n) begin
            tx <= 1'b1;
            tx_busy <= 1'b0;
            tx_state <= 3'd0;
            tx_bit_cnt <= 4'd0;
            tx_shift_reg <= 8'h0;
            tx_counter <= 10'd0;

            rx_data <= 8'h0;
            rx_valid <= 1'b0;
            rx_err <= 1'b0;
            rx_state <= 2'd0;
            rx_counter <= 10'd0;
            rx_bit_cnt <= 3'd0;
            rx_shift_reg <= 8'h0;
            rx_prev <= 1'b1;
        end else begin
            // 接收边沿检测
            rx_prev <= rx;
            rx_edge_det <= (~rx_prev) & rx;  // 下降沿

            // 发送逻辑
            if (tx_start && !tx_busy) begin
                tx_busy <= 1'b1;
                tx_state <= 3'd0;  // 起始位
                tx_shift_reg <= tx_data;
                tx_counter <= 10'd0;
                tx <= 1'b0;  // 起始位
            end else if (tx_busy) begin
                tx_counter <= tx_counter + 1'b1;

                if (tx_counter == CLKS_PER_BIT - 1) begin
                    tx_counter <= 10'd0;

                    if (tx_state < 9) begin
                        tx_state <= tx_state + 1'b1;

                        case (tx_state)
                            0: tx <= 1'b0;  // 起始位
                            1,2,3,4,5,6,7,8: begin
                                tx <= tx_shift_reg[0];
                                tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            end
                            9: begin
                                tx <= 1'b1;  // 停止位
                                tx_busy <= 1'b0;
                            end
                        endcase
                    end else begin
                        tx <= 1'b1;  // 空闲
                        tx_busy <= 1'b0;
                    end
                end
            end else begin
                tx <= 1'b1;  // 空闲状态
            end

            // 接收逻辑
            rx_valid <= 1'b0;
            rx_err <= 1'b0;

            case (rx_state)
                2'd0: begin  // IDLE
                    if (rx_edge_det) begin
                        rx_state <= 2'd1;  // 进入等待起始位中点
                        rx_counter <= 10'd0;
                    end
                end

                2'd1: begin  // 等待起始位中点
                    rx_counter <= rx_counter + 1'b1;
                    if (rx_counter == (CLKS_PER_BIT >> 1) - 1) begin
                        rx_counter <= 10'd0;
                        if (rx == 1'b0) begin  // 验证起始位中点
                            rx_state <= 2'd2;
                            rx_bit_cnt <= 3'd0;
                        end else begin
                            rx_state <= 2'd0;  // 毛刺，返回idle
                        end
                    end
                end

                2'd2: begin  // 采样数据位
                    rx_counter <= rx_counter + 1'b1;
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_counter <= 10'd0;
                        if (rx_bit_cnt < 8) begin  // 数据位
                            rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                        end else begin  // 停止位
                            if (rx == 1'b1) begin  // 正确停止位
                                rx_data <= rx_shift_reg;
                                rx_valid <= 1'b1;
                            end else begin  // 错误停止位
                                rx_err <= 1'b1;
                            end
                            rx_state <= 2'd0;  // 返回idle
                        end
                    end
                end
            endcase
        end
    end

endmodule
