            end else if (tx_busy) begin
                tx_counter <= tx_counter + 1'b1;

                if (tx_counter == CLKS_PER_BIT - 1) begin
                    tx_counter <= 10'd0;

                    if (tx_state < 9) begin
                        tx_state <= tx_state + 1'b1;

                        case (tx_state)
                            0: tx <= 1'b0;  // 起始位
                            1,2,3,4,5,6,7,8: begin
                                tx <= tx_shift_reg[0];
                                tx_shift_reg <= {1'b0, tx_shift_reg[7:1]};
                            end
                            9: begin
                                tx <= 1'b1;  // 停止位
                                tx_busy <= 1'b0;
                            end
                        endcase
                    end else begin
                        tx <= 1'b1;  // 空闲
                        tx_busy <= 1'b0;
                    end
                end
            end else begin
                tx <= 1'b1;  // 空闲状态
            end

            // 接收逻辑
            rx_valid <= 1'b0;
            rx_err <= 1'b0;

            case (rx_state)
