                end

                2'd2: begin  // 采样数据位
                    rx_counter <= rx_counter + 1'b1;
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_counter <= 10'd0;
                        if (rx_bit_cnt < 8) begin  // 数据位
                            rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                        end else begin  // 停止位
                            if (rx == 1'b1) begin  // 正确停止位
                                rx_data <= rx_shift_reg;
                                rx_valid <= 1'b1;
                            end else begin  // 错误停止位
                                rx_err <= 1'b1;
                            end
                            rx_state <= 2'd0;  // 返回idle
                        end
                    end
                end
            endcase
