## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, tx_start, tx_data[7:0], rx
   - 寄存器输出：tx_busy, tx, rx_data[7:0], rx_valid, rx_err
   - tx_start是脉冲信号，需要内部锁存

2. **状态机设计**：
   - 发送部分：IDLE -> START -> DATA[0-7] -> STOP
   - 接收部分：IDLE -> WAIT_START -> SAMPLE_START -> DATA_SAMPLE[0-7] -> STOP_SAMPLE
   - 使用计数器控制位时间，计数范围[0:CLKS_PER_BIT-1]

3. **计数器**：
   - 位计数器：[0:CLKS_PER_BIT-1]，用于定位位中点
   - 位索引计数器：[0:9]，用于跟踪当前发送/接收第几位(起始位+8数据位+停止位)

4. **复位行为**：所有寄存器初始化为默认值，tx=1, tx_busy=0等

## 完整代码

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    // 发送相关信号
    reg tx_busy_r;
    reg tx_r;
    reg [3:0] tx_bit_cnt;      // 0-9: start + data0-7 + stop
    reg [4:0] tx_clk_cnt;      // 0 to CLKS_PER_BIT-1
    reg [7:0] tx_shift_reg;
    reg tx_start_d;
    reg tx_start_pulse;

    // 接收相关信号
    reg [3:0] rx_state;
    reg [3:0] rx_bit_cnt;      // 0-9: start + data0-7 + stop
    reg [4:0] rx_clk_cnt;      // 0 to CLKS_PER_BIT-1
    reg [7:0] rx_shift_reg;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg rx_prev;
    reg rx_rising_edge;
    reg rx_falling_edge;

    // 状态定义
    parameter TX_IDLE = 4'd0,
              TX_START = 4'd1,
              TX_DATA = 4'd2,
              TX_STOP = 4'd3;

    parameter RX_IDLE = 4'd0,
              RX_WAIT_START = 4'd1,
              RX_SAMPLE_START = 4'd2,
              RX_DATA_SAMPLE = 4'd3,
              RX_STOP_SAMPLE = 4'd4;

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1;
            tx_bit_cnt <= 4'd0;
            tx_clk_cnt <= 5'd0;
            tx_shift_reg <= 8'd0;
            tx_start_d <= 1'b0;
            tx_start_pulse <= 1'b0;
        end else begin
            tx_start_d <= tx_start;
            tx_start_pulse <= tx_start & ~tx_start_d & ~tx_busy_r;

            if (tx_start_pulse) begin
                tx_shift_reg <= tx_data;
                tx_bit_cnt <= 4'd0;
                tx_clk_cnt <= 5'd0;
                tx_r <= 1'b0;  // Start bit
                tx_busy_r <= 1'b1;
            end else if (tx_busy_r) begin
                if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= 5'd0;
                    if (tx_bit_cnt < 9) begin  // 0-8: start + data bits
                        tx_bit_cnt <= tx_bit_cnt + 1;
                        if (tx_bit_cnt == 0) begin  // Just finished start bit
                            tx_r <= tx_shift_reg[0];
                        end else begin
                            tx_r <= tx_shift_reg[tx_bit_cnt];  // Data bits
                        end
                    end else if (tx_bit_cnt == 9) begin  // Stop bit
                        tx_bit_cnt <= 4'd0;
                        tx_r <= 1'b1;  // Stop bit
                        tx_busy_r <= 1'b0;
                    end
                end else begin
                    tx_clk_cnt <= tx_clk_cnt + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= 5'd0;
            rx_shift_reg <= 8'd0;
            rx_prev <= 1'b1;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            rx_data_r <= 8'd0;
        end else begin
            rx_prev <= rx;
            rx_falling_edge <= (~rx & rx_prev);  // Detect falling edge of rx

            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            case (rx_state)
                RX_IDLE: begin
                    if (rx_falling_edge) begin
                        rx_state <= RX_SAMPLE_START;
                        rx_clk_cnt <= 5'd0;
                    end
                end

                RX_SAMPLE_START: begin
                    if (rx_clk_cnt == (CLKS_PER_BIT >> 1) - 1) begin  // Half bit time
                        if (rx == 0) begin  // Valid start bit
                            rx_state <= RX_DATA_SAMPLE;
                            rx_bit_cnt <= 4'd0;
                            rx_clk_cnt <= 5'd0;
                        end else begin  // Glitch
                            rx_state <= RX_IDLE;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end

                RX_DATA_SAMPLE: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 5'd0;
                        if (rx_bit_cnt < 7) begin  // Data bits 0-7
                            rx_shift_reg[rx_bit_cnt] <= rx;
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end else if (rx_bit_cnt == 7) begin  // Last data bit
                            rx_shift_reg[7] <= rx;
                            rx_bit_cnt <= rx_bit_cnt + 1;  // Now 8
                            rx_state <= RX_STOP_SAMPLE;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end

                RX_STOP_SAMPLE: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        if (rx == 1) begin  // Valid stop bit
                            rx_data_r <= rx_shift_reg;
                            rx_valid_r <= 1'b1;
                        end else begin  // Frame error
                            rx_err_r <= 1'b1;
                        end
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end

                default: rx_state <= RX_IDLE;
            endcase
        end
    end

endmodule
