                            bit_cnt <= bit_cnt + 1;

                            if (bit_cnt == 7) begin // 已完成8位传输
                                state <= FINISH;
                            end
                        end
                    end else begin
                        clk_div_cnt <= clk_div_cnt + 1;
                    end
                end

                FINISH: begin
                    state <= IDLE;
                    done_r <= 1;
