module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    reg [7:0] rx_data_r;
    reg busy_r;
    reg done_r;
    reg sclk_r;
    reg mosi_r;
    reg cs_n_r;

    // 状态定义
    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter TRANSMIT = 2'b10;
    parameter FINISH = 2'b11;

    reg [1:0] state;
    reg [3:0] bit_cnt;
    reg [2:0] sclk_cnt;
    reg [7:0] shift_reg;

    assign rx_data = rx_data_r;
    assign busy = busy_r;
    assign done = done_r;
    assign sclk = sclk_r;
    assign mosi = mosi_r;
    assign cs_n = cs_n_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 0;
            sclk_cnt <= 0;
            shift_reg <= 0;
            rx_data_r <= 0;
            busy_r <= 0;
            done_r <= 0;
            sclk_r <= 0;
            mosi_r <= 0;
            cs_n_r <= 1;
        end else begin
            case (state)
                IDLE: begin
                    done_r <= 0;
                    if (start) begin
                        state <= START;
                        busy_r <= 1;
                        cs_n_r <= 0;
                        shift_reg <= tx_data;
                        bit_cnt <= 0;
                        sclk_cnt <= 0;
                        sclk_r <= 0;
                        mosi_r <= tx_data[7];
                    end
                end

                START: begin
                    if (sclk_cnt < CLK_DIV - 1) begin
                        sclk_cnt <= sclk_cnt + 1;
                    end else begin
                        sclk_cnt <= 0;
                        sclk_r <= ~sclk_r;  // 第一个上升沿
                        if (sclk_r == 0) begin
                            // 在下降沿采样数据
                            rx_data_r <= {rx_data_r[6:0], miso};
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1;
                                shift_reg <= {shift_reg[6:0], 1'b0};
                                mosi_r <= shift_reg[6];
                            end else begin
                                state <= FINISH;
                            end
                        end else begin
                            // 在上升沿发送数据
                        end
                    end
                end

                TRANSMIT: begin
                    if (sclk_cnt < CLK_DIV - 1) begin
                        sclk_cnt <= sclk_cnt + 1;
                    end else begin
                        sclk_cnt <= 0;
                        sclk_r <= ~sclk_r;
                        if (sclk_r == 0) begin
                            // 在下降沿采样数据
                            rx_data_r <= {rx_data_r[6:0], miso};
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1;
                                shift_reg <= {shift_reg[6:0], 1'b0};
                                mosi_r <= shift_reg[6];
                            end else begin
                                state <= FINISH;
                            end
                        end else begin
                            // 在上升沿发送数据
                        end
                    end
                end

                FINISH: begin
                    cs_n_r <= 1;
                    sclk_r <= 0;
                    busy_r <= 0;
                    done_r <= 1;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase

            // 如果在IDLE状态下重新启动，则进入START状态
            if (state == IDLE && start && !busy_r) begin
                state <= START;
                busy_r <= 1;
                cs_n_r <= 0;
                shift_reg <= tx_data;
                bit_cnt <= 0;
                sclk_cnt <= 0;
                sclk_r <= 0;
                mosi_r <= tx_data[7];
            end
        end
    end

    // 初始化TRANSMIT状态
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            if (CLK_DIV > 4) 
                state <= START;  // Just for reset, will be overridden
        end else begin
            if (state == START && sclk_cnt == 0 && sclk_r == 1) begin
                state <= TRANSMIT;
            end
        end
    end

