- 输出：rx_data(8位寄存器), busy(1位寄存器), done(1位寄存器), sclk(1位寄存器), mosi(1位寄存器), cs_n(1位寄存器)
- 双向：miso(1位输入)

**2. 状态机设计**
- 状态：IDLE, START, TRANSMIT, STOP
- 计数器：bit_cnt(4位，0-7)，sclk_cnt(3位，0到CLK_DIV-1)
- 转移：IDLE→START(start有效)，START→TRANSMIT(计数器归零)，TRANSMIT→STOP(8位传输完成)，STOP→IDLE

**3. 复位行为**
- 所有寄存器输出复位为默认值，cs_n=1(不选中)，busy=0，done=0

**4. 时序要求**
- CPHA=0：数据在sclk下降沿采样，在上升沿改变
- 每位传输需要CLK_DIV个系统时钟周期

```verilog
module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg busy,
    output reg done,
    output reg sclk,
    output reg mosi,
    input miso,
    output reg cs_n
);

    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter TRANSMIT = 2'b10;
    parameter STOP = 2'b11;

    reg [1:0] state, next_state;
    reg [2:0] sclk_cnt;
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg shift_en, load_en, sclk_en, sample_miso, update_done;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = start ? START : IDLE;
            START: next_state = TRANSMIT;
            TRANSMIT: next_state = (bit_cnt == 4'd7 && sclk_cnt == CLK_DIV - 1) ? STOP : TRANSMIT;
            STOP: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_cnt <= 0;
        end else if (load_en) begin
            sclk_cnt <= 0;
        end else if (sclk_en) begin
            sclk_cnt <= sclk_cnt + 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 0;
        end else if (load_en) begin
            bit_cnt <= 0;
        end else if (shift_en) begin
            bit_cnt <= bit_cnt + 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 0;
        end else if (load_en) begin
            shift_reg <= tx_data;
        end else if (shift_en) begin
            shift_reg <= {shift_reg[6:0], miso};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_data <= 0;
        end else if (sample_miso) begin
            rx_data <= {shift_reg[6:0], miso};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 0;
        end else begin
            busy <= (state != IDLE);
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
        end else begin
            done <= update_done;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk <= 0;
        end else if (state == IDLE) begin
            sclk <= 0;
        end else if (sclk_en) begin
            if (sclk_cnt < CLK_DIV/2)
                sclk <= 0;
            else
                sclk <= 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mosi <= 0;
        end else if (load_en) begin
            mosi <= tx_data[7];
        end else if (shift_en) begin
            mosi <= shift_reg[7];
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cs_n <= 1;
