    assign busy = busy_r;
    assign done = done_r;
    assign sclk = sclk_r;
    assign mosi = mosi_r;
    assign cs_n = cs_n_r;

    wire clk_div_end = (clk_div_cnt == (CLK_DIV * 2 - 1));
    wire bit_done = (bit_cnt == 3'd7) && clk_div_end && (state == TRANSMIT);

    always @(posedge clk or negedge rst_n) begin
