            clk_div_cnt <= 5'd0;
            rx_data_r <= 8'd0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            sclk_r <= 1'b0;
            mosi_r <= 1'b0;
            cs_n_r <= 1'b1;
        end else begin
            done_r <= 1'b0; // default to clear done pulse

            case (state)
                IDLE: begin
                    busy_r <= 1'b0;
                    cs_n_r <= 1'b1;
                    sclk_r <= 1'b0;
                    if (start) begin
                        state <= START;
                        busy_r <= 1'b1;
                        clk_div_cnt <= 5'd0;
                    end
