    assign sclk = sclk_r;
    assign mosi = mosi_r;
    assign cs_n = cs_n_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            sclk_r <= 1'b0;
            cs_n_r <= 1'b1;
            mosi_r <= 1'b0;
            shift_reg <= 8'b0;
            rx_shift_reg <= 8'b0;
            bit_cnt <= 3'b0;
            div_cnt <= 4'b0;
        end else begin
            state <= next_state;
            case (next_state)
                IDLE: begin
                    busy_r <= 1'b0;
                    done_r <= 1'b0;
                    cs_n_r <= 1'b1;
                    sclk_r <= 1'b0;
                    mosi_r <= 1'b0;
                    bit_cnt <= 3'b0;
                    div_cnt <= 4'b0;
                end
                SETUP: begin
                    busy_r <= 1'b1;
                    cs_n_r <= 1'b0;
                    shift_reg <= tx_data;
                    rx_shift_reg <= 8'b0;
                    bit_cnt <= 3'b0;
                    div_cnt <= 4'b0;
                    sclk_r <= 1'b0;
                    mosi_r <= shift_reg[7];
