    reg [31:0] sclk_cnt; // Use wide enough to handle CLK_DIV
    reg busy_r;
    reg done_r;
    reg sclk_r;
    reg cs_n_r;
    reg [7:0] tx_reg;
    reg [7:0] rx_reg;
    reg [7:0] mosi_r;

    assign busy = busy_r;
    assign done = done_r;
    assign sclk = sclk_r;
    assign cs_n = cs_n_r;
    assign mosi = mosi_r;
    assign rx_data = rx_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            sclk_r <= 1'b0;
            cs_n_r <= 1'b1;
            bit_cnt <= 3'b000;
            sclk_cnt <= 32'b0;
            tx_reg <= 8'b0;
            rx_reg <= 8'b0;
            mosi_r <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done_r <= 1'b0;
                    if (!busy_r && start) begin
                        busy_r <= 1'b1;
                        cs_n_r <= 1'b0;
                        tx_reg <= tx_data;
                        bit_cnt <= 3'b000;
                        sclk_cnt <= 32'b0;
                        sclk_r <= 1'b0;
                        mosi_r <= tx_reg[7];
                        state <= START;
                    end
                end

                START: begin
                    if (sclk_cnt == CLK_DIV - 1) begin
                        sclk_r <= ~sclk_r;
                        sclk_cnt <= 32'b0;
                        state <= TRANSMIT;
                    end else begin
                        sclk_cnt <= sclk_cnt + 1;
                    end
                end

                TRANSMIT: begin
                    if (sclk_r == 1'b0) begin // Falling edge of sclk
                        if (sclk_cnt == CLK_DIV - 1) begin
                            sclk_r <= ~sclk_r;
                            sclk_cnt <= 32'b0;

                            // Update MOSI for next bit
                            if (bit_cnt == 3'b111) begin
                                // Last bit transmission completed
                                mosi_r <= tx_reg[0]; // Keep the last bit
                            end else begin
                                mosi_r <= tx_reg[6-bit_cnt]; // Next bit to send
                            end
                        end else begin
                            sclk_cnt <= sclk_cnt + 1;
                        end
                    end else begin // Rising edge of sclk
                        if (sclk_cnt == CLK_DIV - 1) begin
                            // Sample MISO
                            rx_reg[7-bit_cnt] <= miso;

                            if (bit_cnt == 3'b111) begin
                                // All 8 bits transmitted
                                sclk_r <= 1'b0;
                                cs_n_r <= 1'b1;
                                state <= DONE;
                            end else begin
                                sclk_r <= ~sclk_r;
                                sclk_cnt <= 32'b0;
                                bit_cnt <= bit_cnt + 1;

                                // Update MOSI on falling edge, so prepare here
                                mosi_r <= tx_reg[6-bit_cnt]; // Current bit_cnt value
                            end
                        end else begin
                            sclk_cnt <= sclk_cnt + 1;
                        end
                    end
                end

                DONE: begin
                    done_r <= 1'b1;
                    state <= IDLE;
                    busy_r <= 1'b0;
                    cs_n_r <= 1'b1;
                    sclk_r <= 1'b0;
                end

                default: begin
                    state <= IDLE;
                end
            endcase

            // If reset during transmission, go back to idle
            if (!rst_n) begin
                state <= IDLE;
                busy_r <= 1'b0;
                done_r <= 1'b0;
                sclk_r <= 1'b0;
                cs_n_r <= 1'b1;
            end
        end
    end

endmodule

