    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    reg [2:0] state;
    reg [2:0] next_state;

    // 状态定义
    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter TRANSMIT = 3'b010;
    parameter DONE = 3'b011;

    reg [7:0] tx_reg;
    reg [7:0] rx_reg;
    reg [2:0] bit_cnt;
    reg [31:0] sclk_half_period_cnt;
    reg busy_reg;
    reg done_reg;
    reg sclk_reg;
    reg cs_n_reg;

    assign busy = busy_reg;
    assign done = done_reg;
    assign sclk = sclk_reg;
    assign cs_n = cs_n_reg;

    // mosi输出逻辑
    wire [7:0] shift_tx_data = {tx_reg[6:0], 1'b0};
    reg [7:0] current_tx_data;
    assign mosi = current_tx_data[7];

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            sclk_reg <= 1'b0;
            cs_n_reg <= 1'b1;
