            tx_reg <= 8'b0;
            bit_cnt <= 3'b0;
            sclk_half_period_cnt <= 32'b0;
            current_tx_data <= 8'b0;
        end else begin
            case (state)
                IDLE: begin
                    busy_reg <= 1'b0;
                    done_reg <= 1'b0;
                    sclk_reg <= 1'b0;
                    cs_n_reg <= 1'b1;
                    if (start && !busy_reg) begin
                        tx_reg <= tx_data;
                        busy_reg <= 1'b1;
                        cs_n_reg <= 1'b0;
                        bit_cnt <= 3'b0;
                        sclk_half_period_cnt <= 32'b0;
                        current_tx_data <= tx_data;
                        state <= START;
                    end
                end

