                    if (sclk_half_period_cnt == (CLK_DIV - 1)) begin
                        sclk_reg <= ~sclk_reg;  // 第一个sclk上升沿
                        sclk_half_period_cnt <= 32'b0;
                        state <= TRANSMIT;
                    end else begin
                        sclk_half_period_cnt <= sclk_half_period_cnt + 1;
                    end
