                            rx_reg <= {rx_reg[6:0], miso};
                            if (bit_cnt < 3'd7) begin
                                bit_cnt <= bit_cnt + 1;
                            end else begin
                                bit_cnt <= bit_cnt + 1;
                                state <= DONE;
