                        end else begin  // 下降沿更新mosi
                            current_tx_data <= shift_tx_data;
                        end
                    end else begin
                        sclk_half_period_cnt <= sclk_half_period_cnt + 1;
                    end
                end

                DONE: begin
                    sclk_reg <= 1'b0;
                    cs_n_reg <= 1'b1;
                    done_reg <= 1'b1;
                    rx_reg <= {rx_reg[6:0], miso};  // 最后一位采样
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase

            if (!rst_n) begin
                state <= IDLE;
                busy_reg <= 1'b0;
                done_reg <= 1'b0;
                sclk_reg <= 1'b0;
                cs_n_reg <= 1'b1;
                rx_reg <= 8'b0;
                bit_cnt <= 3'b0;
                sclk_half_period_cnt <= 32'b0;
                current_tx_data <= 8'b0;
            end
        end
    end

    assign rx_data = rx_reg;

