module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    // State definitions
    localparam IDLE = 3'd0;
    localparam START = 3'd1;
    localparam ADDR_SEND = 3'd2;
    localparam ADDR_ACK = 3'd3;
    localparam DATA_SEND = 3'd4;
    localparam DATA_ACK = 3'd5;
    localparam DATA_RECV = 3'd6;
    localparam SEND_NACK = 3'd7;
    localparam STOP = 3'd8;

    reg [2:0] state, next_state;
    reg [3:0] bit_cnt;
    reg [9:0] shift_reg;  // 10 bits: address(7) + R/W(1) + ACK(1) or data(8) + ACK(1)
    reg [3:0] clk_cnt;
    reg scl_int, sda_int;
    reg [7:0] temp_rdata;
    reg start_flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            clk_cnt <= 0;
            bit_cnt <= 0;
            shift_reg <= 0;
            scl_int <= 1;
            sda_int <= 1;
            temp_rdata <= 0;
            start_flag <= 0;
        end else begin
            if (clk_cnt == (CLK_DIV - 1)) begin
                clk_cnt <= 0;
                case (state)
                    IDLE: begin
                        if (start) begin
                            state <= START;
                            start_flag <= 1;
                            scl_int <= 1;
                            sda_int <= 1;
                            clk_cnt <= 0;
                            bit_cnt <= 0;
                            // Prepare address + R/W bit
                            shift_reg <= {addr, rw, 1'b0};
                        end
                    end
                    START: begin
                        sda_int <= 0;  // SDA falls while SCL is high -> START condition
                        scl_int <= 1;
                        state <= ADDR_SEND;
                        bit_cnt <= 0;
                    end
                    ADDR_SEND: begin
                        scl_int <= 0;  // Clock down
                        sda_int <= shift_reg[9];  // Output MSB of shift register
                        scl_int <= 1;  // Clock up
                        shift_reg <= {shift_reg[8:0], 1'b0};  // Shift left
                        bit_cnt <= bit_cnt + 1;
                        if (bit_cnt == 9) begin  // All 10 bits sent (addr+rw+ack)
                            state <= ADDR_ACK;
                            bit_cnt <= 0;
                        end else begin
                            state <= ADDR_SEND;
                        end
                    end
                    ADDR_ACK: begin
                        scl_int <= 0;  // Clock down to let slave drive ACK
                        sda_int <= 1;  // Release SDA for slave to ACK
                        scl_int <= 1;  // Clock up
                        if (sda_i == 1) begin  // No ACK received
                            state <= STOP;
                            ack_err <= 1;
                        end else begin  // ACK received
                            if (rw == 1'b0) begin  // Write mode
                                shift_reg <= {wdata, 1'b0};
                                state <= DATA_SEND;
                                bit_cnt <= 0;
                            end else begin  // Read mode
                                state <= DATA_RECV;
                                bit_cnt <= 0;
                                temp_rdata <= 0;
                            end
                        end
                    end
                    DATA_SEND: begin
                        scl_int <= 0;  // Clock down
                        sda_int <= shift_reg[9];  // Output MSB of data
                        scl_int <= 1;  // Clock up
                        shift_reg <= {shift_reg[8:0], 1'b0};  // Shift left
                        bit_cnt <= bit_cnt + 1;
                        if (bit_cnt == 8) begin  // All 8 bits sent
                            state <= DATA_ACK;
                        end else begin
                            state <= DATA_SEND;
                        end
                    end
                    DATA_ACK: begin
                        scl_int <= 0;  // Clock down to let slave drive ACK
                        sda_int <= 1;  // Release SDA for slave to ACK
                        scl_int <= 1;  // Clock up
                        if (sda_i == 1) begin  // No ACK received
                            state <= STOP;
                            ack_err <= 1;
                        end else begin  // ACK received
                            state <= STOP;
                        end
                    end
                    DATA_RECV: begin
                        scl_int <= 0;  // Clock down
                        sda_int <= 1;  // Release SDA for slave to drive
                        temp_rdata <= {temp_rdata[6:0], sda_i};  // Sample SDA
                        scl_int <= 1;  // Clock up
                        bit_cnt <= bit_cnt + 1;
                        if (bit_cnt == 7) begin  // 8th bit will be sampled in next cycle
                            state <= SEND_NACK;
                        end else begin
                            state <= DATA_RECV;
                        end
                    end
                    SEND_NACK: begin
                        scl_int <= 0;  // Clock down
                        sda_int <= 1;  // Send NACK (1)
                        scl_int <= 1;  // Clock up
                        rdata <= {temp_rdata[6:0], sda_i};  // Get last bit
                        state <= STOP;
                    end
                    STOP: begin
                        sda_int <= 0;  // Prepare SDA low
                        scl_int <= 1;  // SCL high
                        sda_int <= 1;  // SDA rises while SCL is high -> STOP condition
                        state <= IDLE;
                        start_flag <= 0;
                    end
                endcase
            end else begin
                clk_cnt <= clk_cnt + 1;
            end
        end
    end

    // Outputs
    assign scl_o = scl_int;
    assign sda_o = sda_int;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 0;
            done <= 0;
            ack_err <= 0;
        end else begin
            busy <= start_flag;
            done <= (state != IDLE && next_state == IDLE) ? 1 : 0;
            if (state == IDLE)
                ack_err <= 0;
        end
    end

    // Next state logic for done signal
    wire [2:0] next_state;
    assign next_state = 
        (state == IDLE) ? (start ? START : IDLE) :
        (state == START) ? ADDR_SEND :
        (state == ADDR_SEND) ? ((bit_cnt == 9) ? ADDR_ACK : ADDR_SEND) :
        (state == ADDR_ACK) ? ((sda_i == 1) ? STOP : (rw == 1'b0 ? DATA_SEND : DATA_RECV)) :
        (state == DATA_SEND) ? ((bit_cnt == 8) ? DATA_ACK : DATA_SEND) :
        (state == DATA_ACK) ? ((sda_i == 1) ? STOP : STOP) :  // In write mode, go to stop after ACK check
        (state == DATA_RECV) ? ((bit_cnt == 7) ? SEND_NACK : DATA_RECV) :
        (state == SEND_NACK) ? STOP :
        IDLE;

endmodule
