    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] next_state;
    reg [2:0] bit_cnt;
    reg [3:0] clk_cnt;
    reg [7:0] shift_reg;
    reg [7:0] temp_rdata;
    reg sda_out;
    reg scl_out;
    reg busy_reg;
    reg done_pulse;
    reg ack_err_reg;

    // State definitions
    parameter IDLE = 4'd0;
    parameter START = 4'd1;
    parameter ADDR_SEND = 4'd2;
    parameter ADDR_WAIT_ACK = 4'd3;
    parameter DATA_SEND = 4'd4;
    parameter DATA_WAIT_ACK = 4'd5;
    parameter DATA_RECV = 4'd6;
    parameter SEND_NACK = 4'd7;
    parameter STOP = 4'd8;
    parameter WAIT_DONE = 4'd9;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 3'd0;
            clk_cnt <= 4'd0;
            shift_reg <= 8'h00;
            temp_rdata <= 8'h00;
            sda_out <= 1'b1;
            scl_out <= 1'b1;
            busy_reg <= 1'b0;
            done_pulse <= 1'b0;
            ack_err_reg <= 1'b0;
        end else begin
            done_pulse <= 1'b0;  // Clear done pulse each cycle

            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                        busy_reg <= 1'b1;
                        ack_err_reg <= 1'b0;
                        clk_cnt <= 4'd0;
                        sda_out <= 1'b0;  // Start condition: SDA falls while SCL high
                    end
                end

                START: begin
                    clk_cnt <= clk_cnt + 1'b1;
                    if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        scl_out <= 1'b0;  // Clock down to prepare for data
                        shift_reg <= {addr, rw};
                        bit_cnt <= 3'd0;
                        state <= ADDR_SEND;
                    end
                end

                ADDR_SEND: begin
                    if (clk_cnt == 0) begin
                        sda_out <= shift_reg[7];  // Set data
                        scl_out <= 1'b1;  // Clock up
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        scl_out <= 1'b0;  // Clock down
                        shift_reg <= shift_reg << 1;  // Shift next bit
                        bit_cnt <= bit_cnt + 1'b1;
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                    if (bit_cnt == 3'd7 && clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        bit_cnt <= 3'd0;
                        state <= ADDR_WAIT_ACK;
                        sda_out <= 1'b1;  // Release SDA for ACK
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                    end
                end

                ADDR_WAIT_ACK: begin
                    if (clk_cnt == 0) begin
                        scl_out <= 1'b1;  // Clock up to sample ACK
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        if (sda_i) begin  // No ACK received
                            ack_err_reg <= 1'b1;
                            state <= STOP;
                        end else begin  // ACK received
                            if (rw) begin  // Read operation
                                state <= DATA_RECV;
                            end else begin  // Write operation
                                shift_reg <= wdata;
                                state <= DATA_SEND;
                            end
                        end
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        scl_out <= 1'b0;  // Clock down
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                end

                DATA_SEND: begin
                    if (clk_cnt == 0) begin
                        sda_out <= shift_reg[7];  // Set data
                        scl_out <= 1'b1;  // Clock up
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        scl_out <= 1'b0;  // Clock down
                        shift_reg <= shift_reg << 1;  // Shift next bit
                        bit_cnt <= bit_cnt + 1'b1;
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                    if (bit_cnt == 3'd7 && clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        bit_cnt <= 3'd0;
                        state <= DATA_WAIT_ACK;
                        sda_out <= 1'b1;  // Release SDA for ACK
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                    end
                end

                DATA_WAIT_ACK: begin
                    if (clk_cnt == 0) begin
                        scl_out <= 1'b1;  // Clock up to sample ACK
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        if (sda_i) begin  // No ACK received
                            ack_err_reg <= 1'b1;
                            state <= STOP;
                        end else begin  // ACK received
                            state <= STOP;
                        end
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        scl_out <= 1'b0;  // Clock down
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                end

                DATA_RECV: begin
                    if (clk_cnt == 0) begin
                        scl_out <= 1'b1;  // Clock up to sample data
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        temp_rdata <= {temp_rdata[6:0], sda_i};  // Sample bit
                        bit_cnt <= bit_cnt + 1'b1;
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        scl_out <= 1'b0;  // Clock down
                        if (bit_cnt == 3'd7) begin
                            state <= SEND_NACK;
                            bit_cnt <= 3'd0;
                        end
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                end

                SEND_NACK: begin
                    if (clk_cnt == 0) begin
                        sda_out <= 1'b1;  // Send NACK
                        scl_out <= 1'b1;  // Clock up
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        scl_out <= 1'b0;  // Clock down
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        clk_cnt <= 4'd0;
                        state <= STOP;
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                end

                STOP: begin
                    if (clk_cnt == 0) begin
                        sda_out <= 1'b0;  // Prepare for stop condition
                    end else if (clk_cnt == CLK_DIV/2 - 1) begin
                        scl_out <= 1'b1;  // SCL goes high
                    end else if (clk_cnt == CLK_DIV - 1) begin
                        sda_out <= 1'b1;  // SDA rises while SCL high - Stop condition
                        clk_cnt <= 4'd0;
                        state <= WAIT_DONE;
                    end

                    clk_cnt <= clk_cnt + 1'b1;
                end

                WAIT_DONE: begin
                    done_pulse <= 1'b1;
                    busy_reg <= 1'b0;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign busy = busy_reg;
    assign done = done_pulse;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_out;
    assign sda_o = sda_out;
    assign rdata = temp_rdata;

