## 设计思路

**1. 信号分析：**
- 输入：clk, rst_n, start(脉冲), rw, addr[6:0], wdata[7:0], sda_i
- 寄存器输出：busy, done(脉冲), ack_err, scl_o, sda_o
- 组合输出：rdata[7:0]

**2. 状态机：**
- 状态：IDLE, START, ADDR, ADDR_ACK, WRITE_DATA, WRITE_ACK, READ_DATA, READ_ACK, STOP
- 计数器：4位，计数0-15，用于SCL时序控制(4*CLK_DIV周期)

**3. 复位行为：**
- 所有寄存器输出复位为0，scl_o/sda_o释放(=1)
- 时序要求：SCL周期=4*CLK_DIV个时钟，通过状态机+计数器实现

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] cnt;
    reg [7:0] shift_reg;
    reg [2:0] bit_cnt;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;

    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter ADDR = 4'b0010;
    parameter ADDR_ACK = 4'b0011;
    parameter WRITE_DATA = 4'b0100;
    parameter WRITE_ACK = 4'b0101;
    parameter READ_DATA = 4'b0110;
    parameter READ_ACK = 4'b0111;
    parameter STOP = 4'b1000;

    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;
    assign rdata = shift_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            cnt <= 0;
            bit_cnt <= 0;
            shift_reg <= 0;
            busy_r <= 0;
            done_r <= 0;
            ack_err_r <= 0;
            scl_o_r <= 1;
            sda_o_r <= 1;
        end else begin
            done_r <= 0;

            case (state)
                IDLE: begin
                    if (start) begin
                        busy_r <= 1;
                        state <= START;
                        cnt <= 0;
                        scl_o_r <= 1;
                        sda_o_r <= 1;
                    end
                end

                START: begin
                    cnt <= cnt + 1;
                    if (cnt == CLK_DIV - 1) begin
                        sda_o_r <= 0; // SDA falls while SCL high
                    end else if (cnt == 2 * CLK_DIV - 1) begin
                        scl_o_r <= 0; // SCL falls
                        state <= ADDR;
                        cnt <= 0;
                        shift_reg <= {addr, rw};
                        bit_cnt <= 0;
                    end
                end

                ADDR: begin
