    reg [6:0] clk_counter;    // Counter for clock division
    reg [3:0] bit_count;      // Bit counter (0-7 for data, 8 for ACK/NACK)
    reg [7:0] shift_reg;      // Shift register for data transmission/reception
    reg [7:0] rdata_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg scl_o_reg;
    reg sda_o_reg;
    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;

