    parameter IDLE = 4'd0;
    parameter START = 4'd1;
    parameter ADDR_TX = 4'd2;
    parameter ADDR_ACK_RX = 4'd3;
    parameter DATA_TX = 4'd4;
    parameter DATA_ACK_RX = 4'd5;
    parameter DATA_RX = 4'd6;
    parameter DATA_ACK_TX = 4'd7;
    parameter STOP = 4'd8;

    // Phase definitions
    parameter PHASE_LOW = 4'd0;
    parameter PHASE_RISE = 4'd1;
    parameter PHASE_HIGH = 4'd2;
    parameter PHASE_FALL = 4'd3;

    assign rdata = rdata_reg;
    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            phase <= PHASE_LOW;
            clk_counter <= 0;
            bit_count <= 0;
            shift_reg <= 0;
            rdata_reg <= 0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            addr_reg <= 0;
            rw_reg <= 0;
            wdata_reg <= 0;
        end else begin
            done_reg <= 1'b0;

            if (clk_counter < CLK_DIV - 1) begin
                clk_counter <= clk_counter + 1;
            end else begin
                clk_counter <= 0;

                case (phase)
                    PHASE_LOW: begin
                        scl_o_reg <= 1'b0;
                        phase <= PHASE_RISE;
                    end
                    PHASE_RISE: begin
                        scl_o_reg <= 1'b1;
                        phase <= PHASE_HIGH;
                    end
