                        scl_o_reg <= 1'b1;
                        phase <= PHASE_FALL;

                        // Sample SDA during high phase
                        if ((state == ADDR_ACK_RX || state == DATA_ACK_RX || state == DATA_RX) && 
                            bit_count < 8) begin
                            shift_reg[7-bit_count] <= sda_i;
                        end

                        // For ACK sampling states
                        if ((state == ADDR_ACK_RX || state == DATA_ACK_RX) && bit_count == 8) begin
                            if (!sda_i) begin
                                // ACK received
                            end else begin
                                // NACK received
                                ack_err_reg <= 1'b1;
                            end
                        end
                    end
                    PHASE_FALL: begin
                        scl_o_reg <= 1'b0;
                        phase <= PHASE_LOW;

