                        case (state)
                            IDLE: begin
                                if (start && !busy_reg) begin
                                    busy_reg <= 1'b1;
                                    addr_reg <= addr;
                                    rw_reg <= rw;
                                    wdata_reg <= wdata;
                                    ack_err_reg <= 1'b0;
