                                state <= ADDR_TX;
                                bit_count <= 0;
                                shift_reg <= {addr_reg, rw_reg};
                                sda_o_reg <= shift_reg[7];
                            end

                            ADDR_TX: begin
                                if (bit_count < 7) begin
                                    bit_count <= bit_count + 1;
                                    shift_reg <= shift_reg << 1;
                                    sda_o_reg <= shift_reg[7];
                                end else begin
                                    bit_count <= 0;
                                    state <= ADDR_ACK_RX;
                                    sda_o_reg <= 1'b1;  // Release SDA to read ACK
                                end
                            end

                            ADDR_ACK_RX: begin
                                if (bit_count < 8) begin
                                    bit_count <= bit_count + 1;
                                end else begin
                                    bit_count <= 0;
                                    if (ack_err_reg) begin
                                        state <= STOP;
                                    end else if (rw_reg) begin
                                        state <= DATA_RX;
                                        sda_o_reg <= 1'b1;  // Release SDA for reading
                                    end else begin
                                        state <= DATA_TX;
                                        shift_reg <= wdata_reg;
                                        sda_o_reg <= shift_reg[7];
                                    end
                                end
                            end

                            DATA_TX: begin
                                if (bit_count < 7) begin
                                    bit_count <= bit_count + 1;
                                    shift_reg <= shift_reg << 1;
                                    sda_o_reg <= shift_reg[7];
                                end else begin
                                    bit_count <= 0;
                                    state <= DATA_ACK_RX;
                                    sda_o_reg <= 1'b1;  // Release SDA to read ACK
                                end
                            end

                            DATA_ACK_RX: begin
                                if (bit_count < 8) begin
                                    bit_count <= bit_count + 1;
                                end else begin
                                    bit_count <= 0;
                                    if (sda_i) begin
                                        ack_err_reg <= 1'b1;
                                    end
                                    state <= STOP;
                                end
                            end

                            DATA_RX: begin
                                if (bit_count < 7) begin
                                    bit_count <= bit_count + 1;
                                end else begin
                                    bit_count <= 0;
                                    rdata_reg <= shift_reg;
                                    state <= DATA_ACK_TX;
                                    sda_o_reg <= 1'b1;  // Send NACK
                                end
                            end

                            DATA_ACK_TX: begin
                                bit_count <= bit_count + 1;
                                if (bit_count == 8) begin
                                    state <= STOP;
                                end
                            end

                            STOP: begin
                                sda_o_reg <= 1'b0;  // Pull SDA low first
                                state <= IDLE;
                                busy_reg <= 1'b0;
                                done_reg <= 1'b1;
                                scl_o_reg <= 1'b1;
                                sda_o_reg <= 1'b1;  // Release both lines
                            end

                            default: begin
                                state <= IDLE;
                                busy_reg <= 1'b0;
                                scl_o_reg <= 1'b1;
                                sda_o_reg <= 1'b1;
                            end
                        end
                    end
                endcase
            end

            // Handle reset during transaction
            if (!rst_n) begin
                state <= IDLE;
                phase <= PHASE_LOW;
                clk_counter <= 0;
                bit_count <= 0;
                shift_reg <= 0;
                rdata_reg <= 0;
                busy_reg <= 1'b0;
                done_reg <= 1'b0;
                ack_err_reg <= 1'b0;
                scl_o_reg <= 1'b1;
                sda_o_reg <= 1'b1;
                addr_reg <= 0;
                rw_reg <= 0;
                wdata_reg <= 0;
            end
        end
    end

