## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, start, rw, addr[6:0], wdata[7:0], sda_i
   - 寄存器输出：busy, done, ack_err, scl_o, sda_o
   - 组合输出：rdata[7:0]

2. **状态机设计**：
   - 状态：IDLE, START, ADDR_TX, ADDR_ACK, DATA_TX/RX, DATA_ACK/NACK, STOP, DONE
   - 计数器：phase_cnt[3:0] (0-3相位), bit_cnt[3:0] (0-7位), byte_cnt[6:0] (0-9字节)

3. **时序控制**：
   - 每SCL周期4个相位，每相位CLK_DIV个时钟
   - 使用内部计数器控制相位切换

4. **复位**：同步复位，总线释放(scl_o=sda_o=1)，清空所有状态

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [2:0] state;
    reg [3:0] phase_cnt;
    reg [3:0] bit_cnt;
    reg [6:0] byte_cnt;
    reg [7:0] shift_reg;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;

    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter ADDR_TX = 3'b010;
    parameter ADDR_ACK = 3'b011;
    parameter DATA_TX = 3'b100;
    parameter DATA_RX = 3'b101;
    parameter DATA_ACK = 3'b110;
    parameter STOP = 3'b111;
    parameter DONE = 3'b000; // Same as IDLE but with done pulse

    assign rdata = rdata_r;
    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            phase_cnt <= 0;
            bit_cnt <= 0;
            byte_cnt <= 0;
            shift_reg <= 0;
            rdata_r <= 0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_o_r <= 1'b1;
            sda_o_r <= 1'b1;
        end else begin
            done_r <= 1'b0;

            if (state != IDLE && !rst_n) begin
                state <= IDLE;
                busy_r <= 1'b0;
                scl_o_r <= 1'b1;
                sda_o_r <= 1'b1;
            end else begin
                case (state)
                    IDLE: begin
                        if (start && !busy_r) begin
                            busy_r <= 1'b1;
                            ack_err_r <= 1'b0;
                            shift_reg <= {addr, rw};
                            byte_cnt <= 0;
                            bit_cnt <= 0;
                            phase_cnt <= 0;
                            scl_o_r <= 1'b1;
                            sda_o_r <= 1'b1;
                            state <= START;
                        end
                    end

                    START: begin
                        phase_cnt <= phase_cnt + 1'b1;
                        if (phase_cnt == CLK_DIV - 1) begin
                            phase_cnt <= 0;
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1'b1;
                            end else begin
                                bit_cnt <= 0;
                                state <= ADDR_TX;
                            end
                        end else if (phase_cnt == 0) begin
                            sda_o_r <= 1'b0; // Start condition
                        end else if (phase_cnt == CLK_DIV/2) begin
                            scl_o_r <= 1'b0;
                        end
                    end

                    ADDR_TX: begin
                        case (phase_cnt)
                            0: begin
                                if (bit_cnt == 0 && byte_cnt == 0) begin
                                    scl_o_r <= 1'b0;
                                end
                                sda_o_r <= shift_reg[7];
                            end
                            1: begin
                                scl_o_r <= 1'b1;
                            end
                            2: begin
                                scl_o_r <= 1'b1;
                            end
                            3: begin
                                scl_o_r <= 1'b0;
                                shift_reg <= {shift_reg[6:0], 1'b0};
                                if (bit_cnt == 7) begin
                                    bit_cnt <= 0;
                                    state <= ADDR_ACK;
                                end else begin
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                        endcase

                        if (phase_cnt == CLK_DIV - 1) begin
                            phase_cnt <= 0;
                        end else begin
                            phase_cnt <= phase_cnt + 1'b1;
                        end
                    end

                    ADDR_ACK: begin
                        case (phase_cnt)
                            0: begin
                                sda_o_r <= 1'b1; // Release SDA for ACK
                            end
                            1: begin
                                scl_o_r <= 1'b1;
                            end
                            2: begin
                                scl_o_r <= 1'b1;
                                if (sda_i) begin
                                    ack_err_r <= 1'b1;
                                    state <= STOP;
                                end else begin
                                    if (rw) begin
                                        state <= DATA_RX;
                                        bit_cnt <= 0;
                                    end else begin
                                        state <= DATA_TX;
                                        shift_reg <= wdata;
                                        bit_cnt <= 0;
                                    end
                                end
                            end
                            3: begin
                                scl_o_r <= 1'b0;
                            end
                        endcase

                        if (phase_cnt == CLK_DIV - 1) begin
                            phase_cnt <= 0;
                        end else begin
                            phase_cnt <= phase_cnt + 1'b1;
                        end
                    end

                    DATA_TX: begin
                        case (phase_cnt)
                            0: begin
                                sda_o_r <= shift_reg[7];
                            end
                            1: begin
                                scl_o_r <= 1'b1;
                            end
                            2: begin
                                scl_o_r <= 1'b1;
                            end
                            3: begin
                                scl_o_r <= 1'b0;
                                shift_reg <= {shift_reg[6:0], 1'b0};
                                if (bit_cnt == 7) begin
                                    bit_cnt <= 0;
                                    state <= DATA_ACK;
                                end else begin
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                        endcase

                        if (phase_cnt == CLK_DIV - 1) begin
                            phase_cnt <= 0;
                        end else begin
                            phase_cnt <= phase_cnt + 1'b1;
                        end
                    end

                    DATA_RX: begin
                        case (phase_cnt)
                            0: begin
                                sda_o_r <= 1'b1; // Release SDA for reading
                            end
                            1: begin
                                scl_o_r <= 1'b1;
                            end
                            2: begin
                                scl_o_r <= 1'b1;
                                shift_reg <= {shift_reg[6:0], sda_i};
                                if (bit_cnt == 7) begin
                                    rdata_r <= {shift_reg[6:0], sda_i};
                                    bit_cnt <= 0;
                                    state <= DATA_ACK;
                                end else begin
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                            3: begin
                                scl_o_r <= 1'b0;
                            end
                        endcase

                        if (phase_cnt == CLK_DIV - 1) begin
                            phase_cnt <= 0;
                        end else begin
                            phase_cnt <= phase_cnt + 1'b1;
                        end
                    end

                    DATA_ACK: begin
                        case (phase_cnt)
                            0: begin
                                if (rw) begin
                                    sda_o_r <= 1'b1; // Send NACK for read
                                end else begin
                                    sda_o_r <= 1'b1; // Release for ACK check
                                end
                            end
                            1: begin
                                scl_o_r <= 1'b1;
                            end
                            2: begin
