                    {7'b0100000, 3'b000}: alu_control_reg = 4'b0001; // SUB
                    {7'b0000000, 3'b001}: alu_control_reg = 4'b0010; // SLL
                    {7'b0000000, 3'b010}: alu_control_reg = 4'b0011; // SLT
                    {7'b0000000, 3'b011}: alu_control_reg = 4'b0100; // SLTU
                    {7'b0000000, 3'b100}: alu_control_reg = 4'b0101; // XOR
                    {7'b0000000, 3'b101}: alu_control_reg = 4'b0110; // SRL
