module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // Register file
    reg [31:0] regfile [0:31];
    wire [4:0] rs1, rs2, rd;
    wire [2:0] funct3;
    wire [6:0] opcode;
    wire [6:0] funct7;

    assign rs1 = instr[19:15];
    assign rs2 = instr[24:20];
    assign rd = instr[11:7];
    assign funct3 = instr[14:12];
    assign opcode = instr[6:0];
    assign funct7 = instr[31:25];

    // ALU signals
    wire [31:0] src_a, src_b;
    wire [3:0] alu_op;
    wire [31:0] alu_out;

    // Source A selection (rs1 or x0 for writes to x0)
    assign src_a = regfile[rs1];

    // Source B selection (rs2 for R-type, immediate for I-type)
    wire [31:0] imm_i;
    assign imm_i = {{20{instr[31]}}, instr[31:20]};

    assign src_b = (opcode == 7'b0010011) ? imm_i : regfile[rs2];  // I-type uses immediate

    // ALU operation decoding
    reg [3:0] alu_op_reg;
    reg illegal_reg;

    always @(*) begin
        illegal_reg = 0;
        alu_op_reg = 4'b0000;  // Default

        case(opcode)
            7'b0110011: begin  // R-type
                case({funct7, funct3})
                    {7'b0000000, 3'b000}: alu_op_reg = 4'b0000;  // ADD
                    {7'b0100000, 3'b000}: alu_op_reg = 4'b0001;  // SUB
                    {7'b0000000, 3'b001}: alu_op_reg = 4'b0010;  // SLL
                    {7'b0000000, 3'b010}: alu_op_reg = 4'b0011;  // SLT
                    {7'b0000000, 3'b011}: alu_op_reg = 4'b0100;  // SLTU
                    {7'b0000000, 3'b100}: alu_op_reg = 4'b0101;  // XOR
                    {7'b0000000, 3'b101}: alu_op_reg = 4'b0110;  // SRL
                    {7'b0100000, 3'b101}: alu_op_reg = 4'b0111;  // SRA
                    {7'b0000000, 3'b110}: alu_op_reg = 4'b1000;  // OR
                    {7'b0000000, 3'b111}: alu_op_reg = 4'b1001;  // AND
                    default: illegal_reg = 1;
                endcase
            end
            7'b0010011: begin  // I-type arithmetic
                case(funct3)
                    3'b000: alu_op_reg = 4'b0000;  // ADDI
                    3'b010: alu_op_reg = 4'b0011;  // SLTI
                    3'b011: alu_op_reg = 4'b0100;  // SLTIU
                    3'b100: alu_op_reg = 4'b0101;  // XORI
                    3'b110: alu_op_reg = 4'b1000;  // ORI
                    3'b111: alu_op_reg = 4'b1001;  // ANDI
                    3'b001: begin
                        if(funct7 == 7'b0000000) alu_op_reg = 4'b0010;  // SLLI
                        else illegal_reg = 1;
                    end
                    3'b101: begin
                        if(funct7 == 7'b0000000) alu_op_reg = 4'b0110;  // SRLI
                        else if(funct7 == 7'b0100000) alu_op_reg = 4'b0111;  // SRAI
                        else illegal_reg = 1;
                    end
                    default: illegal_reg = 1;
                endcase
            end
            default: illegal_reg = 1;
        endcase
    end

    assign illegal = illegal_reg;
    assign alu_op = alu_op_reg;

    // ALU implementation
    always @(*) begin
        case(alu_op)
            4'b0000: alu_out = src_a + src_b;      // ADD
            4'b0001: alu_out = src_a - src_b;      // SUB
            4'b0010: alu_out = src_a << src_b[4:0]; // SLL
            4'b0011: alu_out = {{31{1'b0}}, $signed(src_a) < $signed(src_b)}; // SLT
            4'b0100: alu_out = {{31{1'b0}}, src_a < src_b}; // SLTU
            4'b0101: alu_out = src_a ^ src_b;      // XOR
            4'b0110: alu_out = src_a >> src_b[4:0]; // SRL
            4'b0111: alu_out = $signed(src_a) >>> src_b[4:0]; // SRA
            4'b1000: alu_out = src_a | src_b;      // OR
            4'b1001: alu_out = src_a & src_b;      // AND
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    assign alu_result = alu_out;

    // Write register in next cycle if valid and not x0
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'b0;
            for (integer i = 1; i < 32; i = i + 1) begin
                regfile[i] <= 32'b0;
            end
        end else if (valid && !illegal_reg && rd != 5'b00000) begin
            regfile[rd] <= alu_out;
        end
    end

    // Debug read port
    assign dbg_data = regfile[dbg_addr];

