);

    reg [2:0] sclk_sync_0, sclk_sync_1;
    reg [2:0] cs_n_sync_0, cs_n_sync_1;
    reg [4:0] mosi_sync_0, mosi_sync_1;

    // 同步器
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_sync_0 <= 3'b0;
            sclk_sync_1 <= 3'b0;
            cs_n_sync_0 <= 5'b11111;
            cs_n_sync_1 <= 5'b11111;
            mosi_sync_0 <= 5'b0;
            mosi_sync_1 <= 5'b0;
        end else begin
            sclk_sync_0 <= {sclk_sync_0[1:0], sclk};
            sclk_sync_1 <= {sclk_sync_1[1:0], ~sclk};
            cs_n_sync_0 <= {cs_n_sync_0[3:0], cs_n};
            cs_n_sync_1 <= {cs_n_sync_1[3:0], cs_n};
            mosi_sync_0 <= {mosi_sync_0[3:0], mosi};
            mosi_sync_1 <= {mosi_sync_1[3:0], mosi};
        end
    end

    wire sclk_pos_edge = (sclk_sync_0[2:1] == 2'b01);
    wire sclk_neg_edge = (sclk_sync_1[2:1] == 2'b01);
    wire cs_n_fall = (cs_n_sync_0[4:3] == 2'b10);
    wire cs_n_rise = (cs_n_sync_1[4:3] == 2'b10);

    reg [2:0] bit_cnt;
    reg [7:0] shift_reg_tx;
    reg [6:0] shift_reg_rx;
    reg [7:0] rx_data_reg;
    reg rx_valid_reg;

    assign miso = cs_n ? 1'b0 : shift_reg_tx[7];
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 3'd0;
            shift_reg_tx <= 8'h00;
            shift_reg_rx <= 7'h00;
            rx_data_reg <= 8'h00;
            rx_valid_reg <= 1'b0;
        end else begin
            rx_valid_reg <= 1'b0;

            if (cs_n_fall) begin
                // CS下降沿，装载发送数据
                shift_reg_tx <= tx_data;
                bit_cnt <= 3'd0;
                shift_reg_rx <= 7'h00;
            end else if (!cs_n && sclk_pos_edge) begin
                // 在SCLK上升沿发送数据（SPI模式0，数据在SCLK上升沿改变）
                shift_reg_tx <= {shift_reg_tx[6:0], 1'b0};
            end else if (!cs_n && sclk_neg_edge) begin
                // 在SCLK下降沿接收数据（SPI模式0，数据在SCLK下降沿采样）
                shift_reg_rx <= {shift_reg_rx[5:0], mosi_sync_0[4]};
                bit_cnt <= bit_cnt + 1'b1;

