            bit_cnt <= 3'd0;
            shift_en <= 1'b0;
            load_tx <= 1'b0;
            rx_done <= 1'b0;
            rx_valid_reg <= 1'b0;
        end
        else begin
            rx_valid_reg <= 1'b0;

            if (cs_n_falling) begin
                bit_cnt <= 3'd0;
                shift_en <= 1'b1;
                load_tx <= 1'b1;
                rx_done <= 1'b0;
            end
            else if (cs_n_rising) begin
                shift_en <= 1'b0;
                load_tx <= 1'b0;
                rx_done <= 1'b0;
            end
            else if (shift_en && sclk_posedge) begin
                bit_cnt <= bit_cnt + 1'b1;
                if (bit_cnt == 3'd6) begin  // 第7个边沿后准备接收完成
