    reg [7:0] rx_shift_reg;
    reg [2:0] bit_cnt;
    reg miso_out;
    reg rx_valid_out;
    reg slave_active;

    assign sclk_posedge = (sclk_sync_reg[2:1] == 2'b01);
    assign cs_n_negedge = (cs_n_sync_reg[2:1] == 2'b10);

    assign miso = miso_out;
    assign rx_data = rx_shift_reg;
    assign rx_valid = rx_valid_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_sync_reg <= 3'b000;
            cs_n_sync_reg <= 3'b111;
            mosi_sync_reg <= 1'b0;
        end else begin
            sclk_sync_reg <= {sclk_sync_reg[1:0], sclk};
            cs_n_sync_reg <= {cs_n_sync_reg[1:0], cs_n};
            mosi_sync_reg <= {mosi_sync_reg[1:0], mosi};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_shift_reg <= 8'h00;
            rx_shift_reg <= 8'h00;
            bit_cnt <= 3'd0;
            miso_out <= 1'b0;
            rx_valid_out <= 1'b0;
            slave_active <= 1'b0;
        end else begin
            rx_valid_out <= 1'b0;

            if (cs_n_negedge) begin
                // Start of transaction - load TX data and activate slave
                tx_shift_reg <= tx_data;
                rx_shift_reg <= 8'h00;
                bit_cnt <= 3'd0;
                slave_active <= 1'b1;
                miso_out <= tx_shift_reg[7];
            end else if (slave_active && sclk_posedge) begin
                // Shift on SCLK positive edge
                rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync_reg[2]};

                if (bit_cnt == 3'd7) begin
                    // End of byte transmission
                    rx_valid_out <= 1'b1;
                    bit_cnt <= 3'd0;

                    if (!cs_n_sync_reg[2]) begin
                        // Still active, load next byte
                        tx_shift_reg <= tx_data;
                        miso_out <= tx_shift_reg[7];
                    end else begin
                        // Deactivate slave
                        slave_active <= 1'b0;
                        miso_out <= 1'b0;
                    end
                end else begin
                    // Continue shifting
                    bit_cnt <= bit_cnt + 1'b1;
                    miso_out <= tx_shift_reg[7-bit_cnt-1];
                end
            end else if (cs_n_sync_reg[2]) begin
                // CS is high, deactivate slave
                slave_active <= 1'b0;
                miso_out <= 1'b0;
            end
        end
    end

