## 设计思路

**1. 信号分析：**
- 输入：clk(1), rst_n(1), sclk(1), cs_n(1), mosi(1), tx_data(8)
- 输出：miso(1) - 组合输出, rx_data(8) - 寄存器, rx_valid(1) - 寄存器

**2. 状态机设计：**
- 状态：IDLE(空闲), TRANSMIT(发送), RECEIVE(接收)
- 计数器：3位计数器，范围0-7，用于跟踪8位数据传输

**3. 复位行为：**
- 复位时进入IDLE状态，rx_valid=0，计数器清零

**4. 时序要求：**
- 在sclk上升沿进行数据采样和移位
- cs_n拉低时装载tx_data并开始传输
- 接收完8位后产生rx_valid脉冲

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    reg [2:0] bit_cnt;
    reg [7:0] rx_shift_reg;
    reg [7:0] tx_shift_reg;
    reg rx_valid_reg;
    reg miso_reg;

    // 过采样sclk和cs_n
    reg sclk_d1, sclk_d2;
    reg cs_n_d1, cs_n_d2;
    reg mosi_sync;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_d1 <= 1'b0;
            sclk_d2 <= 1'b0;
            cs_n_d1 <= 1'b1;
            cs_n_d2 <= 1'b1;
            mosi_sync <= 1'b0;
        end else begin
            sclk_d1 <= sclk;
            sclk_d2 <= sclk_d1;
            cs_n_d1 <= cs_n;
            cs_n_d2 <= cs_n_d1;
            mosi_sync <= mosi;
        end
    end

    wire sclk_pos_edge = (~sclk_d2 & sclk_d1);
    wire cs_fall_edge = (~cs_n_d2 & cs_n_d1);
    wire cs_rise_edge = (cs_n_d2 & ~cs_n_d1);

    // 状态机
    parameter IDLE = 2'b00;
    parameter TRANSMIT = 2'b01;
    parameter RECEIVE = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 3'd0;
            rx_shift_reg <= 8'h00;
            tx_shift_reg <= 8'h00;
            rx_valid_reg <= 1'b0;
            miso_reg <= 1'b0;
        end else begin
            rx_valid_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (!cs_n_d2) begin  // cs_n is low
                        state <= TRANSMIT;
                        bit_cnt <= 3'd0;
                        tx_shift_reg <= tx_data;
                        rx_shift_reg <= 8'h00;
                        miso_reg <= tx_shift_reg[7];  // MSB first
                    end
                end

                TRANSMIT: begin
                    if (sclk_pos_edge) begin
                        // Shift out tx data to miso
                        miso_reg <= tx_shift_reg[7];
                        tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};

                        // Shift in rx data from mosi
                        rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync};
                        bit_cnt <= bit_cnt + 1'b1;

                        if (bit_cnt == 3'd7) begin
                            state <= RECEIVE;
                        end
                    end
                end

                RECEIVE: begin
                    if (sclk_pos_edge) begin
                        // Continue shifting
                        miso_reg <= tx_shift_reg[7];
                        tx_shift_reg <= {tx_shift_reg[6:0], 1'b0};
                        rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync};
                        bit_cnt <= bit_cnt + 1'b1;

                        if (bit_cnt == 3'd7) begin
                            if (cs_n_d2) begin  // cs_n is high now
                                state <= IDLE;
                            end
                        end
                    end

                    if (cs_rise_edge) begin
                        state <= IDLE;
                        rx_valid_reg <= 1'b1;  // Generate valid pulse
                    end
                end

                default: state <= IDLE;
            endcase

            // If cs_n rises without completing full 8 bits in RECEIVE state
            if (cs_rise_edge && (state != IDLE)) begin
                state <= IDLE;
                rx_valid_reg <= 1'b1;
            end
        end
    end

    // Handle case where cs_n goes high after partial transfer
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            if (cs_rise_edge && (state != IDLE)) begin
                rx_valid_reg <= 1'b1;
            end
        end else begin
            if (cs_rise_edge && (state != IDLE)) begin
                rx_valid_reg <= 1'b1;
            end
        end
    end

    assign miso = (state == IDLE) ? 1'b0 : miso_reg;
    assign rx_data = rx_shift_reg;
    assign rx_valid = rx_valid_reg;

endmodule
