**设计思路：**

1. **信号分析：**
   - 输入：clk(1), rst_n(1), sclk(1), cs_n(1), mosi(1), tx_data(8)
   - 输出：miso(1, 寄存器), rx_data(8, 寄存器), rx_valid(1, 寄存器)
   - sclk、cs_n、mosi需要同步到系统时钟域

2. **状态机：**
   - IDLE: cs_n=1时等待，miso=0
   - TRANSMIT: cs_n=0且sclk上升沿时发送tx_data的位
   - RECEIVE: cs_n=0且sclk上升沿时接收mosi数据
   - 计数器：3位计数器，范围0-7，用于跟踪8位传输

3. **复位行为：** 所有寄存器复位为0，输出初始值为0

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    reg [2:0] sclk_sync_reg;
    reg [2:0] cs_n_sync_reg;
    reg [2:0] mosi_sync_reg;

    reg [2:0] counter;
    reg [7:0] rx_shift_reg;
    reg [7:0] tx_shift_reg;
    reg miso_reg;
    reg [7:0] rx_data_reg;
    reg rx_valid_reg;

    wire sclk_posedge;
    wire cs_n_fall;
    wire cs_n_rise;

    assign sclk_posedge = (sclk_sync_reg[2:1] == 2'b01);
    assign cs_n_fall = (cs_n_sync_reg[2:1] == 2'b10);
    assign cs_n_rise = (cs_n_sync_reg[2:1] == 2'b01);

    assign miso = miso_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_sync_reg <= 3'b000;
            cs_n_sync_reg <= 3'b111; // cs_n is high by default
            mosi_sync_reg <= 1'b0;
        end else begin
            sclk_sync_reg <= {sclk_sync_reg[1:0], sclk};
            cs_n_sync_reg <= {cs_n_sync_reg[1:0], cs_n};
            mosi_sync_reg <= {mosi_sync_reg[1:0], mosi};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 3'd0;
            rx_shift_reg <= 8'b0;
            tx_shift_reg <= 8'b0;
            miso_reg <= 1'b0;
            rx_data_reg <= 8'b0;
            rx_valid_reg <= 1'b0;
        end else begin
            rx_valid_reg <= 1'b0;

            if (cs_n_rise) begin
                // CS deasserted, reset state
                counter <= 3'd0;
                miso_reg <= 1'b0;
                rx_shift_reg <= 8'b0;
            end else if (!cs_n_sync_reg[2]) begin // CS asserted
                if (cs_n_fall) begin
                    // Load tx_data when CS falls
                    tx_shift_reg <= tx_data;
                    counter <= 3'd0;
                    rx_shift_reg <= 8'b0;
                    miso_reg <= tx_shift_reg[7];
                end else if (sclk_posedge) begin
                    // On SCLK positive edge
                    if (counter < 3'd7) begin
                        // Continue transmission/reception
                        counter <= counter + 1'd1;
                        // Shift out next bit of tx_data
                        miso_reg <= tx_shift_reg[6:0] << 1;
                        // Shift in received bit
                        rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync_reg[2]};
                        tx_shift_reg <= tx_shift_reg << 1;
                    end else begin
                        // Last bit received, shift in and output
                        rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync_reg[2]};
                        rx_data_reg <= {rx_shift_reg[6:0], mosi_sync_reg[2]};
                        rx_valid_reg <= 1'b1;

                        // Prepare for next byte if CS still active
                        tx_shift_reg <= tx_data;
                        counter <= 3'd0;
                        miso_reg <= tx_shift_reg[7];
                    end
                end
            end else begin
                // CS not asserted, miso should be 0
                miso_reg <= 1'b0;
            end
        end
    end

endmodule
