module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    reg [1:0] sclk_sync, cs_n_sync, mosi_sync;
    reg sclk_pos_edge, sclk_neg_edge, cs_n_neg_edge;
    reg [2:0] bit_count;
    reg [7:0] tx_shift_reg, rx_shift_reg;
    reg [7:0] rx_data_reg;
