    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_sync <= 2'b00;
            cs_n_sync <= 2'b11;  // Default high
            mosi_sync <= 2'b00;
        end else begin
            sclk_sync <= {sclk_sync[0], sclk};
            cs_n_sync <= {cs_n_sync[0], cs_n};
            mosi_sync <= {mosi_sync[0], mosi};
        end
    end

    // Edge detection
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_pos_edge <= 1'b0;
            sclk_neg_edge <= 1'b0;
            cs_n_neg_edge <= 1'b0;
        end else begin
            sclk_pos_edge <= ~sclk_sync[1] & sclk_sync[0];
            sclk_neg_edge <= sclk_sync[1] & ~sclk_sync[0];
            cs_n_neg_edge <= ~cs_n_sync[1] & cs_n_sync[0];
        end
    end

    // Bit counter and shift registers
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_count <= 3'b000;
            tx_shift_reg <= 8'b00000000;
            rx_shift_reg <= 8'b00000000;
            rx_data_reg <= 8'b00000000;
            rx_valid_reg <= 1'b0;
        end else begin
            rx_valid_reg <= 1'b0;

            if (cs_n_neg_edge) begin
                // Load new TX data and reset counters when CS goes low
                tx_shift_reg <= tx_data;
                bit_count <= 3'b000;
                rx_shift_reg <= 8'b00000000;
            end else if (~cs_n_sync[0] && sclk_pos_edge) begin
                // Shift in received data on SCLK positive edge
                rx_shift_reg <= {rx_shift_reg[6:0], mosi_sync[0]};
                bit_count <= bit_count + 1'b1;

                if (bit_count == 3'd7) begin
                    // Last bit received - update rx_data and set valid pulse
                    rx_data_reg <= {rx_shift_reg[6:0], mosi_sync[0]};
                    rx_valid_reg <= 1'b1;
                    bit_count <= 3'b000;  // Reset for next byte
                    rx_shift_reg <= 8'b00000000;
                end
            end else if (cs_n_neg_edge) begin
                // Reset bit count immediately when CS goes low
                bit_count <= 3'b000;
            end
        end
    end

    // MISO output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            miso_reg <= 1'b0;
        end else begin
            if (cs_n_neg_edge) begin
                // When CS goes low, start sending MSB of TX data after a few cycles
                miso_reg <= tx_data[7];
            end else if (~cs_n_sync[0] && sclk_neg_edge) begin
                // On SCLK negative edge, prepare next bit to send
                case (bit_count)
                    3'd0: miso_reg <= tx_shift_reg[6];
                    3'd1: miso_reg <= tx_shift_reg[5];
                    3'd2: miso_reg <= tx_shift_reg[4];
                    3'd3: miso_reg <= tx_shift_reg[3];
                    3'd4: miso_reg <= tx_shift_reg[2];
                    3'd5: miso_reg <= tx_shift_reg[1];
                    3'd6: miso_reg <= tx_shift_reg[0];
                    3'd7: miso_reg <= 1'b0;  // After last bit, return to 0
                    default: miso_reg <= 1'b0;
                end
            end else if (cs_n_sync[0]) begin
                // When CS is high, MISO should be 0
                miso_reg <= 1'b0;
            end
        end
    end

    assign miso = miso_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

