## 设计思路

**1. 信号分析**
- 输入：clk(1), rst_n(1), sclk(1), cs_n(1), mosi(1), tx_data(8)
- 输出：miso(1, 寄存器), rx_data(8, 寄存器), rx_valid(1, 寄存器)
- 需要对异步信号sclk、cs_n、mosi进行双寄存器同步

**2. 状态机设计**
- 状态：IDLE(空闲), TRANSMIT(发送), RECEIVE(接收)
- 计数器：3位计数器，范围0-7，用于跟踪8位数据传输

**3. 复位行为**
- 复位时进入IDLE状态，输出清零，miso=0

**4. 时序要求**
- 在sclk上升沿采样mosi并移位输出tx_data到miso
- cs_n拉低时开始传输，拉高时完成接收并产生rx_valid脉冲

## 完整代码

```verilog
module spi_slave (
    input clk,
    input rst_n,
    input sclk,
    input cs_n,
    input mosi,
    output miso,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output rx_valid
);

    reg [1:0] sclk_sync, cs_n_sync;
    reg [2:0] bit_cnt;
    reg [7:0] rx_shift_reg;
    reg [7:0] rx_data_reg;
    reg miso_reg;
    reg rx_valid_reg;
    reg sclk_prev, cs_n_prev;
    reg sclk_posedge, cs_n_negedge, cs_n_posedge;

    typedef enum reg [1:0] {
        IDLE = 2'b00,
        TRANSMIT = 2'b01,
        RECEIVE = 2'b10
    } state_t;

    state_t current_state, next_state;

    // 同步异步信号
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_sync <= 2'b00;
            cs_n_sync <= 2'b11; // 假设复位时cs_n为高电平
        end else begin
            sclk_sync <= {sclk_sync[0], sclk};
            cs_n_sync <= {cs_n_sync[0], cs_n};
        end
    end

    assign sclk_posedge = (sclk_sync == 2'b01);
    assign cs_n_negedge = (cs_n_sync == 2'b10);
    assign cs_n_posedge = (cs_n_sync == 2'b01);

    // 状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // 状态转移逻辑
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (!cs_n_sync[1]) // cs_n is low
                    next_state = TRANSMIT;
                else
                    next_state = IDLE;
            end
            TRANSMIT: begin
                if (cs_n_sync[1]) // cs_n went high
                    next_state = RECEIVE;
                else
                    next_state = TRANSMIT;
            end
            RECEIVE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // 位计数器
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 3'h0;
        end else if (cs_n_negedge) begin
            bit_cnt <= 3'h0;
        end else if (current_state == TRANSMIT && sclk_posedge) begin
            bit_cnt <= bit_cnt + 1'b1;
        end else if (cs_n_posedge) begin
            bit_cnt <= 3'h0;
        end
    end

    // 接收移位寄存器
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_shift_reg <= 8'h00;
        end else if (current_state == TRANSMIT && sclk_posedge) begin
            rx_shift_reg <= {rx_shift_reg[6:0], mosi};
        end
    end

    // 发送移位寄存器 - miso输出
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            miso_reg <= 1'b0;
        end else if (current_state == TRANSMIT && sclk_posedge) begin
            miso_reg <= tx_data[7-bit_cnt];
        end else if (current_state == IDLE) begin
            miso_reg <= 1'b0;
        end
    end

    // 接收数据锁存
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_data_reg <= 8'h00;
        end else if (current_state == RECEIVE) begin
            rx_data_reg <= rx_shift_reg;
        end
    end

    // rx_valid脉冲
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_valid_reg <= 1'b0;
        end else begin
            rx_valid_reg <= (current_state == RECEIVE);
        end
    end

    assign miso = miso_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;

endmodule
