module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    // State encoding
    localparam IDLE = 3'd0;
    localparam LOAD = 3'd1;
    localparam SCLK_LOW = 3'd2;
    localparam SCLK_HIGH = 3'd3;
    localparam FINISH = 3'd4;

    reg [2:0] state;
    reg [15:0] clk_cnt;
    reg [3:0] bit_cnt;
    reg [7:0] tx_shift;
    reg [7:0] rx_shift;
    reg [7:0] rx_data_r;
    reg busy_r;
    reg done_r;
    reg sclk_r;
    reg mosi_r;
    reg cs_n_r;

    assign rx_data = rx_data_r;
    assign busy = busy_r;
    assign done = done_r;
    assign sclk = sclk_r;
    assign mosi = mosi_r;
    assign cs_n = cs_n_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            clk_cnt <= 16'd0;
            bit_cnt <= 4'd0;
            tx_shift <= 8'd0;
            rx_shift <= 8'd0;
            rx_data_r <= 8'd0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            sclk_r <= 1'b0;
            mosi_r <= 1'b0;
            cs_n_r <= 1'b1;
        end else begin
            done_r <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        tx_shift <= tx_data;
                        busy_r <= 1'b1;
                        cs_n_r <= 1'b0;
                        mosi_r <= tx_data[7];
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    if (clk_cnt >= CLK_DIV - 1) begin
                        clk_cnt <= 16'd0;
                        sclk_r <= 1'b1;
                        rx_shift[7 - bit_cnt] <= miso;
                        state <= SCLK_HIGH;
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end
                SCLK_HIGH: begin
                    if (clk_cnt >= CLK_DIV - 1) begin
                        clk_cnt <= 16'd0;
                        sclk_r <= 1'b0;
                        if (bit_cnt == 4'd7) begin
                            bit_cnt <= 4'd0;
                            state <= FINISH;
                        end else begin
                            bit_cnt <= bit_cnt + 4'd1;
                            mosi_r <= tx_shift[7 - (bit_cnt + 1)];
                            state <= SCLK_LOW;
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end
                SCLK_LOW: begin
                    if (clk_cnt >= CLK_DIV - 1) begin
                        clk_cnt <= 16'd0;
                        sclk_r <= 1'b1;
                        rx_shift[7 - bit_cnt] <= miso;
                        state <= SCLK_HIGH;
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end
                FINISH: begin
                    rx_data_r <= rx_shift;
                    done_r <= 1'b1;
                    busy_r <= 1'b0;
                    cs_n_r <= 1'b1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
