    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    localparam IDLE = 2'd0;
    localparam LOAD = 2'd1;
    localparam RUN  = 2'd2;
    localparam FIN  = 2'd3;

    reg [1:0]  state;
    reg [15:0] clk_cnt;
    reg [3:0]  edge_cnt;
    reg        sclk_r;
    reg        cs_n_r;
    reg        busy_r;
    reg        done_r;
    reg [7:0]  tx_shift;
    reg [7:0]  rx_shift;
    reg [7:0]  rx_data_r;
    reg        mosi_r;

    wire tick = (clk_cnt == CLK_DIV - 1);
    wire sclk_fall = tick & sclk_r;
    wire sclk_rise = tick & ~sclk_r;

    assign rx_data = rx_data_r;
    assign busy    = busy_r;
    assign done    = done_r;
    assign sclk    = sclk_r;
    assign mosi    = mosi_r;
    assign cs_n    = cs_n_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            state     <= IDLE;
            clk_cnt   <= 0;
            edge_cnt  <= 0;
            sclk_r    <= 1'b0;
            cs_n_r    <= 1'b1;
            busy_r    <= 1'b0;
            done_r    <= 1'b0;
            tx_shift  <= 8'h00;
            rx_shift  <= 8'h00;
            rx_data_r <= 8'h00;
            mosi_r    <= 1'b0;
        end else begin
            done_r <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        tx_shift <= tx_data;
                        mosi_r   <= tx_data[7];
                        busy_r   <= 1'b1;
                        cs_n_r   <= 1'b0;
                        state    <= LOAD;
                        clk_cnt  <= 0;
                        edge_cnt <= 0;
                    end
                end

                LOAD: begin
                    if (tick) begin
                        sclk_r   <= 1'b1;
                        rx_shift <= {rx_shift[6:0], miso};
                        clk_cnt  <= 0;
                        state    <= RUN;
                    end else begin
                        clk_cnt <= clk_cnt + 1'b1;
                    end
                end

                RUN: begin
                    if (tick) begin
                        clk_cnt <= 0;
                        if (sclk_r) begin
                            sclk_r <= 1'b0;
                            if (edge_cnt == 7) begin
                                state    <= FIN;
                            end else begin
                                mosi_r    <= tx_shift[6];
                                tx_shift  <= {tx_shift[6:0], 1'b0};
                                edge_cnt  <= edge_cnt + 1'b1;
                            end
                        end else begin
                            sclk_r   <= 1'b1;
                            rx_shift <= {rx_shift[6:0], miso};
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 1'b1;
                    end
                end

                FIN: begin
                    busy_r    <= 1'b0;
                    cs_n_r    <= 1'b1;
                    done_r    <= 1'b1;
                    rx_data_r <= rx_shift;
                    state     <= IDLE;
