                            rx_err_r   <= 1'b1;
                        end
                        rx_state <= RX_CLEAN;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 16'd1;
                    end
                end
                RX_CLEAN: begin
                    rx_state <= RX_IDLE;
                end
                default: begin
                    rx_state <= RX_IDLE;
                end
            endcase
        end
    end

