            data_reg    <= 8'd0;
            parity_acc  <= 9'd0;
            timer       <= 16'd0;
            valid_reg   <= 1'b0;
            err_reg     <= 1'b0;
        end else begin
            state       <= state_next;
            cnt         <= cnt_next;
            data_reg    <= data_next;
            parity_acc  <= parity_next;
            timer       <= timer_next;
            valid_reg   <= valid_next;
            err_reg     <= err_next;
        end
    end

    always @(*) begin
        state_next   = state;
        cnt_next     = cnt;
        data_next    = data_reg;
        parity_next  = parity_acc;
        timer_next   = timer;
