module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    // Synchronizer (2-stage)
    reg ps2_clk_s1, ps2_clk_s2;
    reg ps2_data_s1, ps2_data_s2;

    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_s1   <= 1'b1;
            ps2_clk_s2   <= 1'b1;
            ps2_data_s1  <= 1'b1;
            ps2_data_s2  <= 1'b1;
        end else begin
            ps2_clk_s1   <= ps2_clk;
            ps2_clk_s2   <= ps2_clk_s1;
            ps2_data_s1  <= ps2_data;
            ps2_data_s2  <= ps2_data_s1;
        end
    end

    // Falling-edge detection
    wire ps2_clk_fall = (ps2_clk_s3 == 1'b0) && (ps2_clk_s2 == 1'b1);
    reg ps2_clk_s3;
    always @(posedge clk) begin
        if (!rst_n)
            ps2_clk_s3 <= 1'b1;
        else
            ps2_clk_s3 <= ps2_clk_s2;
    end

    // State encoding
    localparam S_IDLE  = 3'd0;
    localparam S_RECV  = 3'd1;
    localparam S_DONE  = 3'd2;

    reg [2:0]  state;
    reg [3:0]  bit_cnt;
    reg [8:0]  shift_reg;   // {P, D7, D6, D5, D4, D3, D2, D1, D0}
    reg [8:0]  parity_cnt;  // 9-bit running parity (XOR of 9 received bits)
    reg [7:0]  data_reg;
    reg        valid_reg;
    reg        err_reg;

    // Timeout counter
    reg [(TIMEOUT > 1 ? 31 : 0):0] timeout_cnt;

    always @(posedge clk) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            bit_cnt     <= 4'd0;
            shift_reg   <= 9'd0;
            parity_cnt  <= 9'd0;
            data_reg    <= 8'd0;
            valid_reg   <= 1'b0;
            err_reg     <= 1'b0;
            timeout_cnt <= 0;
        end else begin
            valid_reg <= 1'b0;
            err_reg   <= 1'b0;

            case (state)
                S_IDLE: begin
                    timeout_cnt <= 0;
                    if (ps2_clk_fall) begin
                        if (ps2_data_s2 == 1'b0) begin
                            state      <= S_RECV;
                            bit_cnt    <= 4'd1;
                            shift_reg  <= 9'd0;
                            parity_cnt <= 9'd1; // start bit = 0, parity = 1
                        end
                    end
                end

                S_RECV: begin
                    if (ps2_clk_fall) begin
                        timeout_cnt <= 0;
                        shift_reg   <= {ps2_data_s2, shift_reg[8:1]};
                        parity_cnt  <= parity_cnt ^ ps2_data_s2;

                        if (bit_cnt == 4'd10) begin
                            state <= S_DONE;
                        end else begin
                            bit_cnt <= bit_cnt + 4'd1;
                        end
                    end else begin
                        if (timeout_cnt >= TIMEOUT - 1) begin
                            state       <= S_IDLE;
                            timeout_cnt <= 0;
                        end else begin
                            timeout_cnt <= timeout_cnt + 1;
                        end
                    end
                end

