    reg        r_valid;
    reg [31:0] r_data;
    reg [1:0]  r_resp;

    wire       raddr_decerr = (|ar_addr_reg[7:4]);

    // Register writes
    always @(posedge clk) begin
        if (!rst_n) begin
            aw_handshake_done <= 1'b0;
            aw_addr_reg       <= 8'd0;
            w_handshake_done  <= 1'b0;
            w_data_reg        <= 32'd0;
            w_strb_reg        <= 4'd0;
