            b_resp            <= 2'b00;
            ar_handshake_done<= 1'b0;
            ar_addr_reg       <= 8'd0;
            r_valid           <= 1'b0;
            r_data            <= 32'd0;
            r_resp            <= 2'b00;
            reg0              <= 32'd0;
            reg1              <= 32'd0;
            reg2              <= 32'd0;
