    reg [7:0] dst_r;
    reg [7:0] cnt_r;
    reg [7:0] len_r;
    reg [7:0] wdata_r;
    reg       busy_r;
    reg       done_r;
    reg       we_r;
    reg       re_r;

    wire last = (cnt_r == len_r);

    assign busy     = busy_r;
    assign done     = done_r;
    assign mem_addr = re_r ? (src_r + cnt_r) :
