module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    // State definitions
    localparam IDLE = 0,
               START_SETUP = 1,
               START_HOLD = 2,
               START_RELEASE = 3,
               TX_ADDR = 4,
               TX_ADDR_ACK = 5,
               TX_DATA = 6,
               TX_DATA_ACK = 7,
               RX_DATA = 8,
               RX_ACK = 9,
               STOP_SETUP = 10,
               STOP_HOLD = 11,
               STOP_RELEASE = 12;

    reg [3:0] state, next_state;
    reg [2:0] bit_cnt;
    reg [3:0] clk_cnt;
    reg [7:0] shift_reg;
    reg sda_prev;
    reg [7:0] temp_rdata;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            clk_cnt <= 0;
            bit_cnt <= 0;
            shift_reg <= 0;
            busy <= 0;
            done <= 0;
            ack_err <= 0;
            scl_o <= 1;
            sda_o <= 1;
            sda_prev <= 1;
            temp_rdata <= 0;
        end else begin
            sda_prev <= sda_i;

            if (done) done <= 0;

            if (start && !busy) begin
                busy <= 1;
                state <= START_SETUP;
                clk_cnt <= 0;
                bit_cnt <= 0;
                ack_err <= 0;
                scl_o <= 1;
                sda_o <= 1;
            end else if (busy) begin
                clk_cnt <= clk_cnt + 1;

                case (state)
                    IDLE: begin
                        busy <= 0;
                        scl_o <= 1;
                        sda_o <= 1;
                    end

                    START_SETUP: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            sda_o <= 0;  // Pull SDA low while SCL is high
                            state <= START_HOLD;
                            clk_cnt <= 0;
                        end
                    end

                    START_HOLD: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;  // Pull SCL low
                            state <= START_RELEASE;
                            clk_cnt <= 0;
                        end
                    end

                    START_RELEASE: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            state <= TX_ADDR;
                            clk_cnt <= 0;
                            bit_cnt <= 0;
                            shift_reg <= {addr, rw};
                            sda_o <= shift_reg[7];
                        end
                    end

                    TX_ADDR: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high for data setup
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;  // SCL low
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1;
                                shift_reg <= {shift_reg[6:0], 1'b0};  // Shift left
                                sda_o <= shift_reg[7];
                                clk_cnt <= 0;
                            end else begin
                                bit_cnt <= 0;
                                state <= TX_ADDR_ACK;
                                sda_o <= 1;  // Release SDA for ACK
                                clk_cnt <= 0;
                            end
                        end
                    end

                    TX_ADDR_ACK: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high to sample ACK
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;
                            if (sda_i == 0) begin  // Got ACK
                                if (rw == 1'b0) begin  // Write mode
                                    state <= TX_DATA;
                                    bit_cnt <= 0;
                                    shift_reg <= wdata;
                                    sda_o <= shift_reg[7];
                                end else begin  // Read mode
                                    state <= RX_DATA;
                                    bit_cnt <= 0;
                                    temp_rdata <= 0;
                                end
                                clk_cnt <= 0;
                            end else begin  // No ACK received
                                ack_err <= 1;
                                state <= STOP_SETUP;
                                clk_cnt <= 0;
                            end
                        end
                    end

                    TX_DATA: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high for data setup
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;  // SCL low
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1;
                                shift_reg <= {shift_reg[6:0], 1'b0};  // Shift left
                                sda_o <= shift_reg[7];
                                clk_cnt <= 0;
                            end else begin
                                bit_cnt <= 0;
                                state <= TX_DATA_ACK;
                                sda_o <= 1;  // Release SDA for ACK
                                clk_cnt <= 0;
                            end
                        end
                    end

                    TX_DATA_ACK: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high to sample ACK
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;
                            if (sda_i == 0) begin  // Got ACK
                                state <= STOP_SETUP;
                                clk_cnt <= 0;
                            end else begin  // No ACK received
                                ack_err <= 1;
                                state <= STOP_SETUP;
                                clk_cnt <= 0;
                            end
                        end
                    end

                    RX_DATA: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high for data hold
                            temp_rdata <= {temp_rdata[6:0], sda_i};  // Sample on rising edge
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;  // SCL low
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1;
                                clk_cnt <= 0;
                            end else begin
                                bit_cnt <= 0;
                                state <= RX_ACK;
                                sda_o <= 1;  // Send NACK
                                clk_cnt <= 0;
                            end
                        end
                    end

                    RX_ACK: begin
                        if (clk_cnt == CLK_DIV/2 - 1) begin
                            scl_o <= 1;  // SCL high for NACK
                        end else if (clk_cnt == CLK_DIV - 1) begin
                            scl_o <= 0;
                            rdata <= temp_rdata;
                            state <= STOP_SETUP;
                            clk_cnt <= 0;
                        end
                    end

                    STOP_SETUP: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            sda_o <= 0;  // Keep SDA low
                            scl_o <= 1;  // Release SCL first
                            state <= STOP_HOLD;
                            clk_cnt <= 0;
                        end
                    end

                    STOP_HOLD: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            sda_o <= 1;  // Release SDA to complete STOP
                            state <= STOP_RELEASE;
                            clk_cnt <= 0;
                        end
                    end

                    STOP_RELEASE: begin
                        if (clk_cnt == CLK_DIV - 1) begin
                            done <= 1;
                            state <= IDLE;
                        end
                    end
                endcase
            end
        end
    end

