    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg [3:0] tx_state;
    reg [3:0] tx_bit_cnt;
    reg [4:0] tx_clk_cnt;
    reg tx_busy_r;
    reg tx_r;

    reg [3:0] rx_state;
    reg [3:0] rx_bit_cnt;
    reg [4:0] rx_clk_cnt;
    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg [7:0] rx_shift_reg;

    // 发送状态定义
    parameter TX_IDLE = 4'b0000,
              TX_START = 4'b0001,
              TX_DATA = 4'b0010,
              TX_STOP = 4'b0011;

    // 接收状态定义
    parameter RX_IDLE = 4'b0000,
              RX_START = 4'b0001,
              RX_DATA = 4'b0010,
              RX_STOP = 4'b0011;

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_state <= TX_IDLE;
            tx_bit_cnt <= 0;
            tx_clk_cnt <= 0;
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1; // 空闲时为高电平
        end else begin
            case (tx_state)
                TX_IDLE: begin
                    if (tx_start) begin
                        tx_state <= TX_START;
                        tx_bit_cnt <= 0;
                        tx_clk_cnt <= 0;
                        tx_busy_r <= 1'b1;
                        tx_r <= 1'b0; // 起始位
                    end
                end
                TX_START: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        tx_state <= TX_DATA;
                        tx_r <= tx_data[0];
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                TX_DATA: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_clk_cnt <= 0;
                        if (tx_bit_cnt < 7) begin
                            tx_bit_cnt <= tx_bit_cnt + 1;
                            tx_r <= tx_data[tx_bit_cnt + 1];
                        end else begin
                            tx_bit_cnt <= 0;
                            tx_state <= TX_STOP;
                            tx_r <= 1'b1; // 停止位
                        end
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                TX_STOP: begin
                    if (tx_clk_cnt == CLKS_PER_BIT - 1) begin
                        tx_state <= TX_IDLE;
                        tx_busy_r <= 1'b0;
                    end else begin
                        tx_clk_cnt <= tx_clk_cnt + 1;
                    end
                end
                default: tx_state <= TX_IDLE;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_state <= RX_IDLE;
            rx_bit_cnt <= 0;
            rx_clk_cnt <= 0;
            rx_data_r <= 8'h00;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            rx_shift_reg <= 8'h00;
        end else begin
            rx_valid_r <= 1'b0;
            case (rx_state)
                RX_IDLE: begin
                    if (!rx) begin // 检测到起始位
                        rx_state <= RX_START;
                        rx_clk_cnt <= 0;
                    end
                end
                RX_START: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        rx_state <= RX_DATA;
                        rx_shift_reg <= 8'h00;
                        rx_bit_cnt <= 0;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_DATA: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_clk_cnt <= 0;
                        rx_shift_reg <= {rx, rx_shift_reg[7:1]};
                        if (rx_bit_cnt < 7) begin
                            rx_bit_cnt <= rx_bit_cnt + 1;
                        end else begin
                            rx_bit_cnt <= 0;
                            rx_state <= RX_STOP;
                        end
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                RX_STOP: begin
                    if (rx_clk_cnt == CLKS_PER_BIT - 1) begin
                        rx_data_r <= {rx, rx_shift_reg[7:1]};
                        rx_valid_r <= 1'b1;
                        rx_err_r <= !rx; // 如果停止位不是高电平，则错误
                        rx_state <= RX_IDLE;
                    end else begin
                        rx_clk_cnt <= rx_clk_cnt + 1;
                    end
                end
                default: rx_state <= RX_IDLE;
            endcase
        end
    end

endmodule
