## 设计思路

1. **信号分析**：输入包括clk, rst_n, tx_start, tx_data, rx；输出包括tx_busy(寄存器), tx(寄存器), rx_data(寄存器), rx_valid(组合), rx_err(组合)。

2. **状态机设计**：发送部分用计数器控制10位发送(起始位+8数据位+停止位)，接收部分用状态机检测起始位并采样10位数据。

3. **计数器**：发送计数器0到10*CLKS_PER_BIT-1，接收计数器用于位定时CLKS_PER_BIT/2后开始采样，每CLKS_PER_BIT周期采样一次。

4. **复位行为**：tx=1, tx_busy=0, rx_data清零，计数器归零。

## 完整代码

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg tx_busy_r;
    reg tx_r;
    reg [9:0] tx_shift_reg; // 10 bits: start + data[0]~data[7] + stop
    reg [15:0] tx_counter; // up to 10*CLKS_PER_BIT - 1
    reg [3:0] tx_bit_cnt;

    reg [7:0] rx_data_r;
    reg rx_valid_r;
    reg rx_err_r;
    reg [15:0] rx_counter;
    reg [3:0] rx_bit_cnt;
    reg [9:0] rx_shift_reg; // 10 bits: start + data[0]~data[7] + stop
    reg rx_sampled;
    reg rx_prev;
    reg [2:0] rx_state; // 0: idle, 1: wait_start_mid, 2: sample_bits

    assign tx_busy = tx_busy_r;
    assign tx = tx_r;
    assign rx_data = rx_data_r;
    assign rx_valid = rx_valid_r;
    assign rx_err = rx_err_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            tx_busy_r <= 1'b0;
            tx_r <= 1'b1;
            tx_counter <= 16'h0;
            tx_bit_cnt <= 4'h0;
            tx_shift_reg <= 10'b0;

            rx_data_r <= 8'h0;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;
            rx_counter <= 16'h0;
            rx_bit_cnt <= 4'h0;
            rx_shift_reg <= 10'b0;
            rx_sampled <= 1'b0;
            rx_prev <= 1'b1;
        end else begin
            // Transmit logic
            if (tx_start && !tx_busy_r) begin
                tx_busy_r <= 1'b1;
                tx_shift_reg <= {1'b1, tx_data, 1'b0}; // stop=1, data[7:0], start=0
                tx_counter <= 16'h0;
                tx_bit_cnt <= 4'h0;
                tx_r <= 1'b0; // start bit
            end else if (tx_busy_r) begin
                tx_counter <= tx_counter + 1'b1;
                if (tx_counter == CLKS_PER_BIT - 1) begin
                    tx_counter <= 16'h0;
                    tx_bit_cnt <= tx_bit_cnt + 1'b1;
                    tx_r <= tx_shift_reg[0];
                    tx_shift_reg <= {1'b1, tx_shift_reg[9:1]};

                    if (tx_bit_cnt == 4'd9) begin // after 10 bits (start + 8 data + stop)
                        tx_busy_r <= 1'b0;
                        tx_r <= 1'b1; // back to idle
                    end
                end
            end

            // Receive logic
            rx_prev <= rx;
            rx_valid_r <= 1'b0;
            rx_err_r <= 1'b0;

            case (rx_state)
                3'd0: begin // idle
                    if (rx_prev & ~rx) begin // falling edge detected
                        rx_state <= 3'd1;
                        rx_counter <= 16'h0;
                    end
                end

                3'd1: begin // wait for start bit middle
                    rx_counter <= rx_counter + 1'b1;
                    if (rx_counter == (CLKS_PER_BIT >> 1) - 1) begin
                        if (~rx) begin // confirmed start bit is low
                            rx_state <= 3'd2;
                            rx_counter <= 16'h0;
                            rx_bit_cnt <= 4'h0;
                            rx_shift_reg <= 10'b0;
                        end else begin
                            rx_state <= 3'd0; // false trigger, return to idle
                        end
                    end
                end

                3'd2: begin // sampling bits
                    rx_counter <= rx_counter + 1'b1;
                    if (rx_counter == CLKS_PER_BIT - 1) begin
                        rx_counter <= 16'h0;
                        rx_shift_reg <= {rx, rx_shift_reg[9:1]};
                        rx_bit_cnt <= rx_bit_cnt + 1'b1;

                        if (rx_bit_cnt == 4'd9) begin // received all 10 bits
                            if (rx == 1'b1) begin // valid stop bit
                                rx_data_r <= rx_shift_reg[8:1]; // data bits
                                rx_valid_r <= 1'b1;
                            end else begin // invalid stop bit
                                rx_err_r <= 1'b1;
                            end
                            rx_state <= 3'd0; // return to idle immediately
                        end
                    end
                end

                default: rx_state <= 3'd0;
            endcase
        end
    end

endmodule
