## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, tx_start(寄存器), tx_data(寄存器), rx(组合)
   - 输出：tx_busy(寄存器), tx(寄存器), rx_data(寄存器), rx_valid(组合), rx_err(组合)

2. **状态机与计数器**：
   - 发送：10个状态(起始+8数据+停止)，每状态持续CLKS_PER_BIT个周期
   - 接收：检测起始边沿→验证起始位→采样8位数据→检查停止位
   - 计数器：位内计数(0到CLKS_PER_BIT-1)，位索引计数

3. **复位行为**：tx=1, tx_busy=0, rx_data保持不变，其他清零

4. **时序要求**：通过精确计数CLKS_PER_BIT周期来控制每位传输时间

```verilog
module uart #(parameter CLKS_PER_BIT = 16) (
    input clk,
    input rst_n,
    input tx_start,
    input [7:0] tx_data,
    output tx_busy,
    output tx,
    input rx,
    output [7:0] rx_data,
    output rx_valid,
    output rx_err
);

    reg tx_reg;
    reg tx_busy_reg;
    reg [7:0] tx_shift_reg;
    reg [3:0] tx_bit_cnt;
    reg [4:0] tx_clk_cnt;
    reg [7:0] rx_data_reg;
    reg rx_valid_reg;
    reg rx_err_reg;
    reg [3:0] rx_bit_cnt;
    reg [4:0] rx_clk_cnt;
    reg rx_prev;
    reg rx_start_detected;
    reg [7:0] rx_shift_reg;

    assign tx = tx_reg;
    assign tx_busy = tx_busy_reg;
    assign rx_data = rx_data_reg;
    assign rx_valid = rx_valid_reg;
    assign rx_err = rx_err_reg;

    // 发送逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            tx_reg <= 1'b1;
            tx_busy_reg <= 1'b0;
            tx_shift_reg <= 8'h00;
            tx_bit_cnt <= 4'd0;
            tx_clk_cnt <= 5'd0;
        end else begin
            if (tx_busy_reg == 1'b0 && tx_start) begin
                tx_shift_reg <= tx_data;
                tx_bit_cnt <= 4'd0;
                tx_clk_cnt <= 5'd0;
                tx_reg <= 1'b0;  // 起始位
                tx_busy_reg <= 1'b1;
            end else if (tx_busy_reg == 1'b1) begin
                if (tx_clk_cnt < CLKS_PER_BIT - 1) begin
                    tx_clk_cnt <= tx_clk_cnt + 1'b1;
                end else begin
                    tx_clk_cnt <= 5'd0;
                    if (tx_bit_cnt < 9) begin  // 0-9: 起始位(0) + 数据位(1-8) + 停止位(9)
                        tx_bit_cnt <= tx_bit_cnt + 1'b1;
                        if (tx_bit_cnt == 0) begin  // 起始位结束，开始发数据
                            tx_reg <= tx_shift_reg[0];
                        end else if (tx_bit_cnt < 9) begin  // 数据位
                            tx_reg <= tx_shift_reg[tx_bit_cnt];
                        end else begin  // 停止位
                            tx_reg <= 1'b1;
                        end
                    end else begin  // 整帧发送完毕
                        tx_reg <= 1'b1;
                        tx_busy_reg <= 1'b0;
                    end
                end
            end
        end
    end

    // 接收逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            rx_prev <= 1'b1;
            rx_start_detected <= 1'b0;
            rx_bit_cnt <= 4'd0;
            rx_clk_cnt <= 5'd0;
            rx_shift_reg <= 8'h00;
            rx_data_reg <= 8'h00;
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;
        end else begin
            rx_prev <= rx;
            rx_valid_reg <= 1'b0;
            rx_err_reg <= 1'b0;

            if (!rx_prev & rx == 1'b0) begin  // 检测到下降沿
                rx_start_detected <= 1'b1;
                rx_clk_cnt <= CLKS_PER_BIT[4:0] >> 1;  // 半个位时间后采样
                rx_bit_cnt <= 4'd0;
            end else if (rx_start_detected) begin
                if (rx_clk_cnt < CLKS_PER_BIT - 1) begin
                    rx_clk_cnt <= rx_clk_cnt + 1'b1;
                end else begin
                    rx_clk_cnt <= 5'd0;
                    if (rx_bit_cnt == 0) begin  // 验证起始位中点
                        if (rx != 1'b0) begin  // 毛刺
                            rx_start_detected <= 1'b0;
                        end else begin  // 起始位有效，准备接收数据
                            rx_bit_cnt <= rx_bit_cnt + 1'b1;
                        end
                    end else if (rx_bit_cnt < 9) begin  // 接收数据位
                        rx_shift_reg[rx_bit_cnt - 1] <= rx;
                        rx_bit_cnt <= rx_bit_cnt + 1'b1;
                    end else if (rx_bit_cnt == 9) begin  // 接收停止位
                        if (rx == 1'b1) begin  // 帧正确
                            rx_data_reg <= rx_shift_reg;
                            rx_valid_reg <= 1'b1;
                        end else begin  // 帧错误
                            rx_err_reg <= 1'b1;
                        end
                        rx_start_detected <= 1'b0;
                    end
                end
            end
        end
    end

endmodule
