                sda_en = 1'b0;
                sda_out = 1'b1;
                busy = 1'b0;
                done = 1'b0;
                ack_err = 1'b0;
            end
        endcase
    end

    // Bit counter and shift register control
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 0;
            shift_reg <= 0;
