                            shift_reg <= {shift_reg[6:0], 1'b0};  // Shift left
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                    end
                end

                DATA_RECV: begin
                    if (clk_div_cnt == 0) begin  // Rising edge of SCL
                        temp_rdata <= {temp_rdata[6:0], sda_i};
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end

                ADDR_ACK_WAIT: begin
                    if (clk_div_cnt == 0) begin  // Check ACK at rising edge
                        if (sda_i != 0) begin  // No ACK received
                            ack_err <= 1'b1;
                        end
                    end
                end

                DATA_ACK_WAIT: begin
                    if (clk_div_cnt == 0) begin  // Check ACK at rising edge
                        if (sda_i != 0) begin  // No ACK received
                            ack_err <= 1'b1;
                        end
                    end
                end

                STOP_RELEASE: begin
                    if (clk_div_cnt == CLK_DIV - 1) begin
                        bit_cnt <= 0;
                        shift_reg <= 0;
                    end
                end

                default: begin
                    if (state == IDLE && start) begin
