    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    // State definitions
    localparam IDLE = 3'd0;
    localparam START = 3'd1;
    localparam ADDR_SEND = 3'd2;
    localparam ADDR_ACK = 3'd3;
    localparam DATA_SEND = 3'd4;
    localparam DATA_ACK = 3'd5;
    localparam DATA_RECV = 3'd6;
    localparam NACK_SEND = 3'd7;
    localparam STOP = 3'd8;

    reg [2:0] state, next_state;
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [9:0] clk_cnt;  // 10 bits for 4*CLK_DIV * 2.5 (for half cycles)
    reg scl_en;
    reg sda_en;
    reg [7:0] temp_rdata;

    // Clock divider
    wire clk_tick = (clk_cnt == (CLK_DIV - 1));

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_cnt <= 10'd0;
        end else if (scl_en || sda_en) begin
            if (clk_tick)
                clk_cnt <= 10'd0;
            else
                clk_cnt <= clk_cnt + 1'b1;
        end else
            clk_cnt <= 10'd0;
    end

    // FSM
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE:       next_state = start ? START : IDLE;
            START:      next_state = clk_tick ? ADDR_SEND : START;
            ADDR_SEND:  next_state = (clk_tick && bit_cnt == 4'd7) ? ADDR_ACK : ADDR_SEND;
            ADDR_ACK:   next_state = clk_tick ? (ack_err ? STOP : (rw ? DATA_RECV : DATA_SEND)) : ADDR_ACK;
            DATA_SEND:  next_state = (clk_tick && bit_cnt == 4'd7) ? DATA_ACK : DATA_SEND;
            DATA_ACK:   next_state = clk_tick ? (ack_err ? STOP : STOP) : DATA_ACK;
            DATA_RECV:  next_state = (clk_tick && bit_cnt == 4'd7) ? NACK_SEND : DATA_RECV;
            NACK_SEND:  next_state = clk_tick ? STOP : NACK_SEND;
            STOP:       next_state = clk_tick ? IDLE : STOP;
            default:    next_state = IDLE;
        endcase
    end

    // Control signals
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0;
            done <= 1'b0;
            ack_err <= 1'b0;
            scl_en <= 1'b0;
            sda_en <= 1'b0;
            bit_cnt <= 4'd0;
            shift_reg <= 8'd0;
            temp_rdata <= 8'd0;
            scl_o <= 1'b1;
            sda_o <= 1'b1;
