                        if (bit_cnt == 0) begin
                            shift_reg <= wdata;
                        end
                        sda_o <= shift_reg[7];
                        shift_reg <= {shift_reg[6:0], 1'b0};
                        if (bit_cnt < 7) 
                            bit_cnt <= bit_cnt + 1'b1;
                        else
                            bit_cnt <= 4'd0;
                    end
                end

                DATA_ACK: begin
                    scl_en <= 1'b1;
                    sda_en <= 1'b0;  // Release SDA to read ACK
                    if (clk_tick) begin
                        ack_err <= sda_i;  // If SDA is high, no ACK received
                    end
                end

                DATA_RECV: begin
                    scl_en <= 1'b1;
                    sda_en <= 1'b0;  // Release SDA for slave to drive
                    if (clk_tick) begin
                        temp_rdata <= {temp_rdata[6:0], sda_i};
                        if (bit_cnt < 7) 
                            bit_cnt <= bit_cnt + 1'b1;
                        else
                            bit_cnt <= 4'd0;
                    end
                end

                NACK_SEND: begin
                    scl_en <= 1'b1;
                    sda_en <= 1'b1;
                    if (clk_tick) begin
                        sda_o <= 1'b1;  // Send NACK
                    end
                end

                STOP: begin
                    scl_en <= 1'b1;
                    sda_en <= 1'b1;
                    if (clk_tick) begin
                        sda_o <= 1'b1;  // Stop condition
                    end else if (scl_o == 1'b0 && sda_o == 1'b0) begin
                        sda_o <= 1'b1;  // Generate stop condition on rising edge of SCL
                    end
                end

                default: begin
                    scl_en <= 1'b0;
                    sda_en <= 1'b0;
                end
            endcase

            // Set scl_o based on scl_en and current clock phase
            if (scl_en && clk_tick) begin
                scl_o <= ~scl_o;  // Toggle SCL on clock tick when enabled
            end else if (state != START && state != ADDR_SEND && state != ADDR_ACK && 
                         state != DATA_SEND && state != DATA_ACK && 
                         state != DATA_RECV && state != NACK_SEND && state != STOP) begin
                scl_o <= 1'b1;  // Release SCL when not actively driving
            end

            // Capture rdata when moving from DATA_RECV to NACK_SEND
            if (state == DATA_RECV && next_state == NACK_SEND) begin
                rdata <= temp_rdata;
            end

            // Generate done pulse when returning to IDLE
            if (state != IDLE && next_state == IDLE) begin
                done <= 1'b1;
            end
        end
    end

