                        sda_o <= 1'b1;
                    end else begin  // Last quarter
                        scl_o <= 1'b1;
                        sda_o <= 1'b1;
                    end
                end
                NACK_SEND: begin
                    // Send NACK by pulling SDA high during SCL high
                    if (clk_cnt < (CLK_DIV - 1)) begin
                        scl_o <= 1'b0;
                        sda_o <= 1'b1;
                    end else if (clk_cnt < (CLK_DIV * 2 - 1)) begin
                        scl_o <= 1'b0;
                        sda_o <= 1'b1;
                    end else if (clk_cnt < (CLK_DIV * 3 - 1)) begin
                        scl_o <= 1'b1;
                        sda_o <= 1'b1;  // Send NACK
                    end else begin  // Last quarter
                        scl_o <= 1'b1;
                        sda_o <= 1'b1;
                    end
                end
                STOP: begin
                    // Generate stop condition: SDA rises while SCL is high
                    if (clk_div_end && scl_en && sda_en) begin
                        scl_o <= 1'b1;
                        sda_o <= 1'b1;
                    end else if (clk_cnt < (CLK_DIV * 2 - 1)) begin
                        scl_o <= 1'b1;
                        sda_o <= 1'b0;
                    end else begin
                        scl_o <= 1'b1;
                        sda_o <= 1'b1;
                    end
                end
            endcase

