            if ((state == ADDR_ACK && next_state == STOP && sda_i) ||
                (state == DATA_ACK && next_state == STOP && sda_i)) begin
                ack_err <= 1'b1;
            end

            // Update rdata when transaction completes
            if (next_state == IDLE && state == STOP) begin
                rdata <= temp_rdata;
            end
        end
    end

