    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    // States for I2C transaction
    parameter IDLE = 0, START = 1, ADDR_SEND = 2, ADDR_WAIT_ACK = 3;
    parameter DATA_SEND = 4, DATA_WAIT_ACK = 5, DATA_RECV = 6, SEND_NACK = 7;
    parameter WAIT_STOP = 8, STOP = 9, ERROR_STOP = 10;

    reg [3:0] state, next_state;
    reg [3:0] bit_cnt;
    reg [2:0] clk_cnt;
    reg [7:0] shift_reg;
    reg [7:0] temp_rdata;
    reg sda_out, scl_out;
    reg busy_reg, done_pulse, ack_err_reg;

    // Counter for SCL timing
    wire clk_tick = (clk_cnt == (CLK_DIV - 1));

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            clk_cnt <= 0;
        end else begin
            if (clk_tick) begin
                clk_cnt <= 0;
                state <= next_state;
            end else begin
                clk_cnt <= clk_cnt + 1;
            end
        end
    end

    // Bit counter and shift register control
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 0;
            shift_reg <= 0;
            temp_rdata <= 0;
        end else if (state != next_state) begin // State transition
            case (next_state)
                ADDR_SEND: begin
                    bit_cnt <= 0;
                    shift_reg <= {addr, rw};
                end
                DATA_SEND: begin
                    bit_cnt <= 0;
                    shift_reg <= wdata;
                end
                DATA_RECV: begin
                    bit_cnt <= 0;
                    temp_rdata <= 0;
                end
                default: begin
                    if (state == DATA_RECV && next_state == DATA_RECV) begin
                        bit_cnt <= bit_cnt + 1;
                        temp_rdata <= {temp_rdata[6:0], sda_i};
                    end else if ((state == ADDR_SEND || state == DATA_SEND) && next_state != ADDR_WAIT_ACK && next_state != DATA_WAIT_ACK) begin
                        bit_cnt <= bit_cnt + 1;
                        shift_reg <= {shift_reg[6:0], 1'b0};
                    end
                end
            endcase
        end
    end

    // SDA and SCL outputs
    always @(*) begin
        case (state)
            IDLE: begin
                sda_out = 1; // Release bus
                scl_out = 1; // Release bus
            end
            START: begin
                sda_out = 0; // SDA falls while SCL high
                scl_out = 1;
            end
            ADDR_SEND, DATA_SEND: begin
                sda_out = shift_reg[7];
                scl_out = (clk_cnt < CLK_DIV/2) ? 0 : 1;
            end
            ADDR_WAIT_ACK, DATA_WAIT_ACK: begin
                sda_out = 1; // Release SDA to read ACK
                scl_out = (clk_cnt < CLK_DIV/2) ? 0 : 1;
            end
            DATA_RECV: begin
                sda_out = 1; // Release SDA to read data
                scl_out = (clk_cnt < CLK_DIV/2) ? 0 : 1;
            end
            SEND_NACK: begin
                sda_out = 0; // Send NACK
                scl_out = (clk_cnt < CLK_DIV/2) ? 0 : 1;
            end
            WAIT_STOP: begin
                sda_out = 1; // Prepare for stop condition
                scl_out = 1;
            end
            STOP: begin
                sda_out = 1; // SDA rises while SCL high
                scl_out = 1;
            end
            ERROR_STOP: begin
                sda_out = 1; // Stop on error
                scl_out = 1;
            end
            default: begin
                sda_out = 1;
                scl_out = 1;
            end
        endcase
    end

