    always @(*) begin
        case (state)
            IDLE: 
                next_state = start ? START : IDLE;

            START:
                next_state = clk_tick ? (rw ? ADDR_SEND : ADDR_SEND) : START;

            ADDR_SEND:
                next_state = (bit_cnt == 7 && clk_tick) ? ADDR_WAIT_ACK : ADDR_SEND;

            ADDR_WAIT_ACK:
                if (clk_tick) begin
                    if (!sda_i) // ACK received
                        next_state = rw ? DATA_RECV : DATA_SEND;
                    else // NACK received
                        next_state = ERROR_STOP;
                end else
                    next_state = ADDR_WAIT_ACK;

            DATA_SEND:
                next_state = (bit_cnt == 7 && clk_tick) ? DATA_WAIT_ACK : DATA_SEND;

            DATA_WAIT_ACK:
                if (clk_tick) begin
                    if (!sda_i) // ACK received
                        next_state = STOP;
                    else // NACK received
                        next_state = ERROR_STOP;
                end else
                    next_state = DATA_WAIT_ACK;

            DATA_RECV:
                if (clk_tick) begin
                    if (bit_cnt == 7)
                        next_state = SEND_NACK;
                    else
                        next_state = DATA_RECV;
                end else
                    next_state = DATA_RECV;

            SEND_NACK:
