module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    // State definitions
    typedef enum reg [3:0] {
        IDLE = 4'd0,
        START_SETUP = 4'd1,
        START_HOLD = 4'd2,
        ADDR_SEND = 4'd3,
        ADDR_ACK_WAIT = 4'd4,
        DATA_SEND = 4'd5,
        DATA_ACK_WAIT = 4'd6,
        DATA_RECV = 4'd7,
        NACK_SEND = 4'd8,
        STOP_SETUP = 4'd9,
        STOP_HOLD = 4'd10,
        ERROR_STOP = 4'd11
    } state_t;

    state_t current_state, next_state;

    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [2:0] scl_divider;
    reg [2:0] scl_phase; // 0: low, 1: setup, 2: high, 3: hold
    reg scl_int;
    reg sda_int;
    reg [7:0] rdata_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg [3:0] clk_count;

    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_int;
    assign sda_o = sda_int;
    assign rdata = rdata_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            bit_cnt <= 4'd0;
            scl_divider <= 3'd0;
            scl_phase <= 3'd0;
            scl_int <= 1'b1;
            sda_int <= 1'b1;
            shift_reg <= 8'd0;
            rdata_reg <= 8'd0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            clk_count <= 4'd0;
        end else begin
            done_reg <= 1'b0;

            if (scl_divider == (CLK_DIV - 1)) begin
                scl_divider <= 3'd0;

                case (scl_phase)
                    3'd0: begin // SCL low
                        scl_int <= 1'b0;
                        scl_phase <= 3'd1;
                    end
                    3'd1: begin // Setup phase
                        scl_phase <= 3'd2;
                    end
                    3'd2: begin // SCL high
                        scl_int <= 1'b1;
                        scl_phase <= 3'd3;
                    end
                    3'd3: begin // Hold phase
                        scl_int <= 1'b0;
                        scl_phase <= 3'd0;
                    end
                endcase
            end else begin
                scl_divider <= scl_divider + 1'b1;
            end

            current_state <= next_state;

            case (next_state)
                IDLE: begin
                    busy_reg <= 1'b0;
                    ack_err_reg <= 1'b0;
                    sda_int <= 1'b1;
                    scl_int <= 1'b1;
                end

                START_SETUP: begin
                    sda_int <= 1'b0; // Start condition: SDA falls while SCL is high
                end

                START_HOLD: begin
                    scl_int <= 1'b0;
                end

                ADDR_SEND: begin
                    if (scl_phase == 3'd1) begin // Setup data
                        sda_int <= addr[6-bit_cnt];
                    end else if (scl_phase == 3'd3 && bit_cnt < 7) begin // Clock out
                        bit_cnt <= bit_cnt + 1'b1;
                    end else if (scl_phase == 3'd3 && bit_cnt == 7) begin // Last bit sent
                        bit_cnt <= 4'd0;
                        sda_int <= 1'b1; // Release for ACK
                    end
                end

                ADDR_ACK_WAIT: begin
                    if (scl_phase == 3'd2) begin // Sample during SCL high
                        if (~sda_i) begin // Got ACK
                            if (rw) begin
                                next_state <= DATA_RECV;
                            end else begin
                                next_state <= DATA_SEND;
                                shift_reg <= wdata;
                            end
                        end else begin // No ACK
                            next_state <= ERROR_STOP;
                            ack_err_reg <= 1'b1;
                        end
                    end
                end

                DATA_SEND: begin
                    if (scl_phase == 3'd1) begin // Setup data
                        sda_int <= shift_reg[7-bit_cnt];
                    end else if (scl_phase == 3'd3 && bit_cnt < 7) begin // Clock out
                        bit_cnt <= bit_cnt + 1'b1;
                    end else if (scl_phase == 3'd3 && bit_cnt == 7) begin // Last bit sent
                        bit_cnt <= 4'd0;
                        sda_int <= 1'b1; // Release for ACK
                    end
                end

                DATA_ACK_WAIT: begin
                    if (scl_phase == 3'd2) begin // Sample during SCL high
                        if (~sda_i) begin // Got ACK
                            next_state <= STOP_SETUP;
                        end else begin // No ACK
                            next_state <= ERROR_STOP;
                            ack_err_reg <= 1'b1;
                        end
                    end
                end

                DATA_RECV: begin
                    if (scl_phase == 3'd2) begin // Sample during SCL high
                        shift_reg <= {shift_reg[6:0], sda_i};
                        if (bit_cnt < 7) begin
                            bit_cnt <= bit_cnt + 1'b1;
                        end else begin
                            rdata_reg <= {shift_reg[6:0], sda_i};
                            bit_cnt <= 4'd0;
                            next_state <= NACK_SEND;
                        end
                    end
                end

                NACK_SEND: begin
                    if (scl_phase == 3'd1) begin // Send NACK (SDA high)
                        sda_int <= 1'b1;
                    end else if (scl_phase == 3'd3) begin
                        next_state <= STOP_SETUP;
                    end
                end

                STOP_SETUP: begin
                    sda_int <= 1'b0; // Keep SDA low
                end

                STOP_HOLD: begin
                    sda_int <= 1'b1; // Stop condition: SDA rises while SCL is high
                    done_reg <= 1'b1;
                    busy_reg <= 1'b0;
                    next_state <= IDLE;
                end

                ERROR_STOP: begin
                    sda_int <= 1'b0; // Keep SDA low
                end

                default: begin
                    sda_int <= 1'b1;
                    scl_int <= 1'b1;
                end
            endcase

            if (start && current_state == IDLE) begin
                busy_reg <= 1'b1;
                next_state <= START_SETUP;
                bit_cnt <= 4'd0;
                scl_phase <= 3'd0;
                scl_divider <= 3'd0;
                scl_int <= 1'b1;
                sda_int <= 1'b1;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        case (current_state)
            IDLE: 
                if (start)
                    next_state = START_SETUP;

            START_SETUP:
                if (scl_phase == 3'd3)
                    next_state = START_HOLD;

            START_HOLD:
                if (scl_phase == 3'd3)
                    next_state = ADDR_SEND;

            ADDR_SEND:
                if (scl_phase == 3'd3 && bit_cnt == 7)
                    next_state = ADDR_ACK_WAIT;

            ADDR_ACK_WAIT:
                if (scl_phase == 3'd2) begin
                    if (~sda_i) begin // ACK received
                        if (rw)
                            next_state = DATA_RECV;
                        else
                            next_state = DATA_SEND;
                    end else
                        next_state = ERROR_STOP; // No ACK
                end

            DATA_SEND:
                if (scl_phase == 3'd3 && bit_cnt == 7)
                    next_state = DATA_ACK_WAIT;

            DATA_ACK_WAIT:
                if (scl_phase == 3'd2) begin
                    if (~sda_i) // ACK received
                        next_state = STOP_SETUP;
                    else
                        next_state = ERROR_STOP; // No ACK
                end

            DATA_RECV:
                if (scl_phase == 3'd2 && bit_cnt == 7)
                    next_state = NACK_SEND;

            NACK_SEND:
                if (scl_phase == 3'd3)
                    next_state = STOP_SETUP;

            STOP_SETUP:
                if (scl_phase == 3'd3)
                    next_state = STOP_HOLD;

            STOP_HOLD:
