        DONE_STATE = 4'b1001
    } state_t;

    state_t current_state, next_state;

    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [9:0] clk_divider;  // 10 bits to count up to 4*CLK_DIV
    reg [3:0] scl_state;    // SCL clock state machine

