    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;
    assign rdata = rdata_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            bit_cnt <= 3'h0;
            shift_reg <= 8'h0;
            clk_divider <= 10'h0;
            scl_state <= 4'h0;
