                    busy_r <= 1'b0;
                    ack_err_r <= 1'b0;
                    scl_o_r <= 1'b1;
                    sda_o_r <= 1'b1;
                    bit_cnt <= 3'h0;
                    clk_divider <= 10'h0;
                    scl_state <= 4'h0;
