                // This transition happens when SCL clocking begins
                if (scl_state != 4'd0)  // Clocking has started
                    next_state = ADDR_SEND;
            end

            ADDR_SEND: begin
                if (scl_state == 4'd0 && clk_divider == (CLK_DIV * 4 - 1) && bit_cnt == 7)  // All 8 bits sent
                    next_state = ADDR_WAIT_ACK;
            end

