    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    // State machine states
    localparam IDLE = 3'd0;
    localparam START = 3'd1;
    localparam ADDR_SEND = 3'd2;
    localparam ADDR_ACK = 3'd3;
    localparam DATA_SEND = 3'd4;
    localparam DATA_ACK = 3'd5;
    localparam DATA_RECV = 3'd6;
    localparam NACK_SEND = 3'd7;
    localparam STOP = 3'd8;

    reg [2:0] state, next_state;
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [9:0] scl_cnt;  // 0 to CLK_DIV*4-1
    reg scl_en;
    reg sda_start_stop;
    reg sda_data_out;
    reg sda_dir;  // 1 for output, 0 for input
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;

    // SCL counter
    wire scl_period_done = (scl_cnt == (CLK_DIV * 4 - 1));

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = START;
                else
                    next_state = IDLE;
            end
            START: begin
                if (scl_period_done && scl_cnt[1:0] == 2'b11)  // After start sequence
                    next_state = ADDR_SEND;
                else
                    next_state = START;
            end
            ADDR_SEND: begin
                if (scl_period_done && bit_cnt == 4'd7)  // All address bits sent
                    next_state = ADDR_ACK;
                else
                    next_state = ADDR_SEND;
            end
            ADDR_ACK: begin
                if (scl_period_done && scl_cnt[1:0] == 2'b11)  // After ACK check
                    next_state = (ack_err_r) ? STOP : 
                                (rw) ? DATA_RECV : DATA_SEND;
                else
                    next_state = ADDR_ACK;
            end
            DATA_SEND: begin
                if (scl_period_done && bit_cnt == 4'd7)  // All data bits sent
                    next_state = DATA_ACK;
                else
                    next_state = DATA_SEND;
            end
            DATA_ACK: begin
                if (scl_period_done && scl_cnt[1:0] == 2'b11)  // After ACK check
                    next_state = (ack_err_r) ? STOP : STOP;
                else
                    next_state = DATA_ACK;
            end
            DATA_RECV: begin
                if (scl_period_done && bit_cnt == 4'd7)  // All data bits received
                    next_state = NACK_SEND;
                else
                    next_state = DATA_RECV;
            end
            NACK_SEND: begin
                if (scl_period_done && scl_cnt[1:0] == 2'b11)  // After NACK send
                    next_state = STOP;
                else
                    next_state = NACK_SEND;
            end
            STOP: begin
                if (scl_period_done && scl_cnt[1:0] == 2'b11)  // After stop sequence
                    next_state = IDLE;
                else
                    next_state = STOP;
            end
            default: next_state = IDLE;
        endcase
    end

    // Bit counter and shift register control
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) begin
                    bit_cnt = 4'd0;
                    shift_reg = {addr, rw};
                end else begin
                    bit_cnt = bit_cnt;
                    shift_reg = shift_reg;
                end
            end
            ADDR_SEND: begin
                if (scl_period_done) begin
                    if (bit_cnt < 4'd7) begin
                        bit_cnt = bit_cnt + 1'b1;
                        shift_reg = {shift_reg[6:0], 1'b0};  // Shift left for next bit
                    end else begin
                        bit_cnt = bit_cnt;
                        shift_reg = shift_reg;
                    end
                end else begin
                    bit_cnt = bit_cnt;
                    shift_reg = shift_reg;
                end
            end
            ADDR_ACK: begin
                bit_cnt = 4'd0;  // Prepare for next phase
                shift_reg = shift_reg;
            end
            DATA_SEND: begin
                if (state != next_state) begin  // Just entered this state
                    bit_cnt = 4'd0;
                    shift_reg = wdata;
                end else if (scl_period_done) begin
                    if (bit_cnt < 4'd7) begin
                        bit_cnt = bit_cnt + 1'b1;
                        shift_reg = {shift_reg[6:0], 1'b0};  // Shift left for next bit
                    end else begin
                        bit_cnt = bit_cnt;
                        shift_reg = shift_reg;
                    end
                end else begin
                    bit_cnt = bit_cnt;
                    shift_reg = shift_reg;
                end
            end
            DATA_ACK: begin
                bit_cnt = 4'd0;
                shift_reg = shift_reg;
            end
            DATA_RECV: begin
                if (state != next_state) begin  // Just entered this state
                    bit_cnt = 4'd0;
                    shift_reg = shift_reg;  // Keep previous value
                end else if (scl_period_done) begin
                    if (bit_cnt < 4'd7) begin
                        bit_cnt = bit_cnt + 1'b1;
                        shift_reg = {shift_reg[6:0], sda_i};  // Shift in received bit
                    end else begin
                        bit_cnt = bit_cnt;
                        shift_reg = {shift_reg[6:0], sda_i};  // Last bit
                    end
                end else begin
                    bit_cnt = bit_cnt;
                    shift_reg = shift_reg;
                end
            end
            NACK_SEND: begin
                bit_cnt = bit_cnt;
                shift_reg = shift_reg;
            end
            STOP: begin
                bit_cnt = bit_cnt;
                shift_reg = shift_reg;
            end
            default: begin
                bit_cnt = bit_cnt;
                shift_reg = shift_reg;
            end
        endcase
    end

    // SDA control signals
    always @(*) begin
        case (state)
            IDLE: begin
                sda_start_stop = 1'b0;
                sda_data_out = 1'b1;  // Release bus when idle
                sda_dir = 1'b1;       // Output
            end
            START: begin
                if (scl_cnt[1:0] == 2'b00) begin  // First half of first clock cycle
                    sda_start_stop = 1'b1;  // Start condition: SDA falls while SCL high
                end else if (scl_cnt[1:0] == 2'b10) begin  // Second half of first cycle
                    sda_start_stop = 1'b0;  // Release SDA for data transmission
                    sda_data_out = shift_reg[7];  // Send MSB first
                    sda_dir = 1'b1;  // Output mode
                end else begin
                    sda_start_stop = 1'b0;
                    sda_data_out = shift_reg[7];
                    sda_dir = 1'b1;
                end
            end
            ADDR_SEND, DATA_SEND: begin
                if (scl_cnt[1:0] == 2'b00) begin  // Setup time before SCL rising edge
                    sda_data_out = shift_reg[7];
                    sda_dir = 1'b1;
                    sda_start_stop = 1'b0;
                end else if (scl_cnt[1:0] == 2'b10) begin  // Hold time after SCL falling edge
                    sda_data_out = (bit_cnt < 4'd7) ? shift_reg[6:0] << 1 : shift_reg[7];
                    sda_dir = 1'b1;
                    sda_start_stop = 1'b0;
                end else begin
                    sda_data_out = shift_reg[7];
                    sda_dir = 1'b1;
                    sda_start_stop = 1'b0;
                end
            end
            ADDR_ACK, DATA_ACK: begin
                if (scl_cnt[1:0] == 2'b00) begin  // Setup time for ACK sampling
                    sda_data_out = 1'b1;  // Release SDA to let slave drive
                    sda_dir = 1'b1;       // Initially output but will be changed to input
                    sda_start_stop = 1'b0;
                end else if (scl_cnt[1:0] == 2'b10) begin  // During ACK sampling period
                    sda_data_out = 1'b1;  // Keep released
                    sda_dir = 1'b0;       // Input mode to read ACK
                    sda_start_stop = 1'b0;
                end else begin
                    sda_data_out = 1'b1;
                    sda_dir = 1'b0;
                    sda_start_stop = 1'b0;
                end
            end
            DATA_RECV: begin
                if (scl_cnt[1:0] == 2'b00) begin  // Setup time for receiving
                    sda_data_out = 1'b1;  // Release SDA for slave to drive
                    sda_dir = 1'b0;       // Input mode
                    sda_start_stop = 1'b0;
                end else if (scl_cnt[1:0] == 2'b10) begin  // Hold time after SCL falling edge
                    sda_data_out = 1'b1;  // Still release
                    sda_dir = 1'b0;       // Input mode
                    sda_start_stop = 1'b0;
                end else begin
                    sda_data_out = 1'b1;
                    sda_dir = 1'b0;
                    sda_start_stop = 1'b0;
                end
            end
            NACK_SEND: begin
                if (scl_cnt[1:0] == 2'b00) begin  // Setup time for NACK
                    sda_data_out = 1'b1;  // Send NACK (high)
                    sda_dir = 1'b1;       // Output mode
                    sda_start_stop = 1'b0;
                end else if (scl_cnt[1:0] == 2'b10) begin  // Hold time
                    sda_data_out = 1'b1;  // Keep NACK
                    sda_dir = 1'b1;       // Output mode
                    sda_start_stop = 1'b0;
                end else begin
                    sda_data_out = 1'b1;
                    sda_dir = 1'b1;
                    sda_start_stop = 1'b0;
                end
            end
            STOP: begin
                if (scl_cnt[1:0] == 2'b00) begin  // Before SCL rising edge
                    sda_data_out = 1'b0;  // Hold SDA low
                    sda_dir = 1'b1;       // Output
                    sda_start_stop = 1'b0;
                end else if (scl_cnt[1:0] == 2'b10) begin  // Stop condition: SDA rises while SCL high
                    sda_data_out = 1'b1;  // Release SDA
                    sda_dir = 1'b1;       // Output
                    sda_start_stop = 1'b1;  // Stop condition
                end else begin
                    sda_data_out = 1'b1;
                    sda_dir = 1'b1;
                    sda_start_stop = 1'b0;
                end
            end
            default: begin
                sda_start_stop = 1'b0;
                sda_data_out = 1'b1;
                sda_dir = 1'b1;
            end
        endcase
    end

    // ACK error detection
    wire ack_received = !sda_i;  // ACK is low, so !sda_i means ACK received
    wire should_check_ack = (state == ADDR_ACK || state == DATA_ACK);
    wire current_ack_error = should_check_ack && scl_cnt[1:0] == 2'b11 && !ack_received;

    // SCL generation
    assign scl_en = (state != IDLE);

    // Outputs
    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign rdata = rdata_r;

    // SDA and SCL outputs
    assign sda_o = (sda_dir) ? sda_data_out : 1'bz;
    assign scl_o = (scl_en) ? (scl_cnt < (CLK_DIV * 2)) ? 1'b1 : 1'b0 : 1'b1;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            scl_cnt <= 10'd0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            rdata_r <= 8'h00;
        end else begin
            state <= next_state;

            // Update SCL counter
            if (next_state != state || start) begin  // Reset counter on state change
                scl_cnt <= 10'd0;
            end else if (scl_en) begin
                if (scl_period_done)
                    scl_cnt <= 10'd0;
                else
                    scl_cnt <= scl_cnt + 1'b1;
            end else begin
                scl_cnt <= 10'd0;
            end

            // Busy signal
            busy_r <= (next_state != IDLE);

            // Done pulse
            done_r <= (next_state == IDLE && state != IDLE);

            // ACK error
            if (start || state == IDLE)
                ack_err_r <= 1'b0;
            else if (current_ack_error)
                ack_err_r <= 1'b1;
            else
                ack_err_r <= ack_err_r;

            // Read data
            if (next_state == IDLE && state == STOP && rw)
                rdata_r <= shift_reg;
            else
                rdata_r <= rdata_r;
        end
    end

