    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;

    // Clock divider for SCL
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            scl_cnt <= 4'h0;
            scl_en <= 1'b0;
        end else begin
            if (scl_cnt == (CLK_DIV - 1)) begin
                scl_cnt <= 4'h0;
                scl_en <= 1'b1;
            end else begin
                scl_cnt <= scl_cnt + 1'b1;
                scl_en <= 1'b0;
            end
        end
    end

