    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
            bit_cnt <= 4'h0;
            shift_reg <= 8'h0;
            rdata_reg <= 8'h0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_o_reg <= 1'b1;  // Release SCL
            sda_o_reg <= 1'b1;  // Release SDA
