            case (next_state)
                STATE_IDLE: begin
                    busy_reg <= 1'b0;
                    scl_o_reg <= 1'b1;
                    sda_o_reg <= 1'b1;
                    ack_err_reg <= 1'b0;
                end

                STATE_START: begin
                    busy_reg <= 1'b1;
                    // Start condition: SDA goes low while SCL is high
                    if (scl_en && scl_o_reg) begin
                        sda_o_reg <= 1'b0;
                    end
                end

                STATE_ADDR: begin
                    // Send address + R/W bit
                    if (scl_en) begin
                        if (bit_cnt < 7) begin
                            sda_o_reg <= addr[6-bit_cnt];
                        end else begin
                            sda_o_reg <= rw;  // R/W bit
                        end
                        scl_o_reg <= 1'b0;  // SCL low to send data
                    end else if (scl_en && !scl_o_reg) begin
                        scl_o_reg <= 1'b1;  // SCL high after data
                        bit_cnt <= bit_cnt + 1'b1;
                    end
