                    if (scl_en) begin
                        sda_o_reg <= wdata[7-bit_cnt];
                        scl_o_reg <= 1'b0;  // SCL low to send data
                    end else if (scl_en && !scl_o_reg) begin
                        scl_o_reg <= 1'b1;  // SCL high after data
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end

