                    // Release SDA to read ACK
                    if (scl_en) begin
                        sda_o_reg <= 1'b1;  // Release SDA
                        scl_o_reg <= 1'b0;  // SCL low
                    end else if (scl_en && !scl_o_reg) begin
                        scl_o_reg <= 1'b1;  // SCL high
                    end
                end

                STATE_READ_DATA: begin
                    // Read data byte
                    if (scl_en && scl_o_reg) begin
                        scl_o_reg <= 1'b0;  // SCL low
                    end else if (scl_en && !scl_o_reg) begin
                        scl_o_reg <= 1'b1;  // SCL high
                        shift_reg <= {shift_reg[6:0], sda_i};
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                    sda_o_reg <= 1'b1;  // Keep SDA released for reading
                end

                STATE_SEND_NACK: begin
                    // Send NACK after read
                    if (scl_en) begin
                        sda_o_reg <= 1'b1;  // NACK is high
                        scl_o_reg <= 1'b0;  // SCL low
                    end else if (scl_en && !scl_o_reg) begin
                        scl_o_reg <= 1'b1;  // SCL high
                    end
                end

                STATE_STOP: begin
                    // Stop condition: SDA goes high while SCL is high
                    if (scl_en && scl_o_reg) begin
                        sda_o_reg <= 1'b1;  // SDA goes high
                    end
                    done_reg <= 1'b1;  // Signal completion
                end

                STATE_ERROR: begin
