    always @(*) begin
        next_state = state;

        case (state)
            STATE_IDLE: 
                next_state = start ? STATE_START : STATE_IDLE;

            STATE_START:
                next_state = (scl_en && scl_o_reg && !sda_o_reg) ? STATE_ADDR : STATE_START;

            STATE_ADDR:
                next_state = (bit_cnt == 4'd8 && scl_en && scl_o_reg) ? STATE_WAIT_ADDR_ACK : STATE_ADDR;

            STATE_WAIT_ADDR_ACK:
                next_state = (scl_en && scl_o_reg) ? 
                    (sda_i ? STATE_ERROR : (rw ? STATE_READ_DATA : STATE_WRITE_DATA)) : 
                    STATE_WAIT_ADDR_ACK;

            STATE_WRITE_DATA:
                next_state = (bit_cnt == 4'd8 && scl_en && scl_o_reg) ? STATE_WAIT_DATA_ACK : STATE_WRITE_DATA;

            STATE_WAIT_DATA_ACK:
                next_state = (scl_en && scl_o_reg) ? 
                    (sda_i ? STATE_ERROR : STATE_STOP) : 
                    STATE_WAIT_DATA_ACK;

            STATE_READ_DATA:
                next_state = (bit_cnt == 4'd8 && scl_en && scl_o_reg) ? STATE_SEND_NACK : STATE_READ_DATA;

            STATE_SEND_NACK:
                next_state = (scl_en && scl_o_reg) ? STATE_STOP : STATE_SEND_NACK;

            STATE_STOP:
                next_state = STATE_IDLE;

            STATE_ERROR:
                next_state = STATE_IDLE;

            default:
                next_state = STATE_IDLE;
        endcase
    end

    // Capture read data when in idle state after read
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata_reg <= 8'h0;
        end else begin
            if (state == STATE_READ_DATA && next_state == STATE_SEND_NACK) begin
                rdata_reg <= shift_reg;
            end
        end
    end

