    localparam STATE_DATA_TX = 3'd4;
    localparam STATE_WAIT_DATA_ACK = 3'd5;
    localparam STATE_DATA_RX = 3'd6;
    localparam STATE_SEND_NACK = 3'd7;
    localparam STATE_STOP = 3'd8;

    reg [2:0] state, next_state;
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [9:0] clk_cnt;  // 0 to CLK_DIV*4-1
