            state <= next_state;
            done_r <= 1'b0;  // Default to 0, pulse for one cycle

            if (start && (state == STATE_IDLE)) begin
                busy_r <= 1'b1;
                ack_err_r <= 1'b0;
                clk_cnt <= 10'h0;
                scl_int <= 1'b1;
                sda_int <= 1'b1;
                bit_cnt <= 4'h0;
                shift_reg <= {addr, rw};
            end else if (busy_r) begin
                clk_cnt <= clk_cnt + 1'b1;

