                        STATE_DATA_TX: begin
                            if (bit_cnt == 8) begin
                                next_state <= STATE_WAIT_DATA_ACK;
                                bit_cnt <= 4'h0;
                            end
                        end
                        STATE_WAIT_DATA_ACK: begin
                            if (!sda_i) begin  // Got ACK
                                next_state <= STATE_STOP;
                            end else begin  // No ACK
                                ack_err_r <= 1'b1;
                                next_state <= STATE_STOP;
                            end
                        end
                        STATE_DATA_RX: begin
                            if (bit_cnt == 8) begin
                                next_state <= STATE_SEND_NACK;
                                bit_cnt <= 4'h0;
                            end
                        end
                        STATE_SEND_NACK: begin
                            next_state <= STATE_STOP;
                        end
                        STATE_STOP: begin
                            busy_r <= 1'b0;
                            done_r <= 1'b1;
                            next_state <= STATE_IDLE;
                        end
                        default: next_state <= STATE_IDLE;
                    endcase
                end
            end
        end
    end

