module debounce #(parameter STABLE_CYCLES = 16) (
    input clk,
    input rst_n,
    input btn_in,
    output btn_out
);
    // 计数器位宽需能表示 STABLE_CYCLES
    localparam CNT_WIDTH = (STABLE_CYCLES > 1) ? clog2(STABLE_CYCLES) : 1;

    reg [CNT_WIDTH-1:0] cnt;
    reg btn_out_reg;

    assign btn_out = btn_out_reg;

    // 计算以2为底的对数（向上取整）
    function integer clog2;
        input integer value;
        integer i;
        begin
            i = 0;
            while ((1 << i) < value) i = i + 1;
            clog2 = i;
        end
    endfunction

    always @(posedge clk) begin
        if (!rst_n) begin
            btn_out_reg <= 1'b0;
            cnt <= {CNT_WIDTH{1'b0}};
        end else begin
            if (btn_in == btn_out_reg) begin
                cnt <= {CNT_WIDTH{1'b0}};
            end else begin
                if (cnt == STABLE_CYCLES - 1) begin
                    btn_out_reg <= btn_in;
                    cnt <= {CNT_WIDTH{1'b0}};
                end else begin
                    cnt <= cnt + 1'b1;
                end
            end
        end
    end
