module debounce #(parameter STABLE_CYCLES = 16) (
    input clk,
    input rst_n,
    input btn_in,
    output btn_out
);
    // 计数器位宽需要能表示 STABLE_CYCLES
    // 使用函数计算位宽，避免使用系统函数 $clog2（虽然可综合，但这里用参数化方式）
    localparam CNT_WIDTH = (STABLE_CYCLES <= 2) ? 1 :
                           (STABLE_CYCLES <= 4) ? 2 :
                           (STABLE_CYCLES <= 8) ? 3 :
                           (STABLE_CYCLES <= 16) ? 4 :
                           (STABLE_CYCLES <= 32) ? 5 :
                           (STABLE_CYCLES <= 64) ? 6 :
                           (STABLE_CYCLES <= 128) ? 7 : 8;

    reg btn_out_reg;
    reg [CNT_WIDTH-1:0] stable_cnt;

    assign btn_out = btn_out_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            btn_out_reg <= 1'b0;
            stable_cnt <= {CNT_WIDTH{1'b0}};
        end else begin
            if (btn_in == btn_out_reg) begin
                // 输入与输出相同，清零计数
                stable_cnt <= {CNT_WIDTH{1'b0}};
            end else begin
                // 输入与输出不同，计数加 1
                if (stable_cnt == STABLE_CYCLES - 1) begin
                    // 达到稳定周期数，更新输出并清零计数
                    btn_out_reg <= btn_in;
                    stable_cnt <= {CNT_WIDTH{1'b0}};
                end else begin
                    // 未达到稳定周期数，继续计数
                    stable_cnt <= stable_cnt + 1'b1;
                end
            end
        end
    end
