module clk_divider (
    input clk,
    input rst_n,
    input [7:0] div,
    output tick,
    output clk_out
);

    reg [7:0] counter;
    reg tick_reg;
    reg clk_out_reg;

    wire [7:0] div_minus_1;
    wire [7:0] half_div;

    assign div_minus_1 = div - 8'd1;
    assign half_div = div[7:1]; // floor(div/2)

    always @(posedge clk) begin
        if (!rst_n) begin
            counter <= 8'd0;
            tick_reg <= 1'b0;
            clk_out_reg <= 1'b0;
        end else begin
            if (counter >= div_minus_1) begin
                counter <= 8'd0;
                tick_reg <= 1'b1;
            end else begin
                counter <= counter + 8'd1;
                tick_reg <= 1'b0;
            end

            if (counter < half_div)
                clk_out_reg <= 1'b1;
            else
                clk_out_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
    assign clk_out = clk_out_reg;

endmodule
