    input clk,
    input rst_n,
    input en,
    input dir,
    output [3:0] q,
    output wrap
);

reg [3:0] q_reg;
reg wrap_reg;

always @(posedge clk) begin
    if (!rst_n) begin
        q_reg <= 4'b0001;
        wrap_reg <= 1'b0;
    end else begin
        if (en) begin
            if (dir == 1'b0) begin
                q_reg <= {q_reg[2:0], q_reg[3]};
            end else begin
                q_reg <= {q_reg[0], q_reg[3:1]};
            end
            if (q_reg == 4'b1000 && dir == 1'b0) begin
                wrap_reg <= 1'b1;
            end else if (q_reg == 4'b0010 && dir == 1'b1) begin
                wrap_reg <= 1'b1;
            end else begin
                wrap_reg <= 1'b0;
            end
        end else begin
            wrap_reg <= 1'b0;
        end
    end
end

assign q = q_reg;
assign wrap = wrap_reg;

