module edge_detect (
    input clk,
    input rst_n,
    input sig,
    input [1:0] mode,
    output pulse,
    output [7:0] cnt
);

reg sig_prev;
reg pulse_reg;
reg [7:0] cnt_reg;

wire rise_edge;
wire fall_edge;
wire edge_detected;

assign rise_edge = sig & ~sig_prev;
assign fall_edge = ~sig & sig_prev;

assign edge_detected = (mode[0] & rise_edge) | (mode[1] & fall_edge);

always @(posedge clk) begin
    if (!rst_n) begin
        sig_prev <= 1'b0;
        pulse_reg <= 1'b0;
        cnt_reg <= 8'd0;
    end else begin
        sig_prev <= sig;
        pulse_reg <= edge_detected;
        if (edge_detected)
            cnt_reg <= cnt_reg + 1'b1;
    end
end

assign pulse = pulse_reg;
assign cnt = cnt_reg;

endmodule
