module sync_fifo #(parameter DW = 8, parameter DEPTH = 16) (
    input clk,
    input rst_n,
    input wr_en,
    input [DW-1:0] wr_data,
    input rd_en,
    output [DW-1:0] rd_data,
    output full,
    output empty,
    output [4:0] count
);

    localparam AW = $clog2(DEPTH);
    localparam CW = AW + 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] rd_ptr;
    reg [CW-1:0] count_reg;
    reg [DW-1:0] rd_data_reg;

    wire wr_accepted;
    wire rd_accepted;

    assign wr_accepted = wr_en && !full;
    assign rd_accepted = rd_en && !empty;

    assign full = (count_reg == DEPTH);
    assign empty = (count_reg == 0);
    assign count = count_reg;
    assign rd_data = rd_data_reg;

    integer i;

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            count_reg <= 0;
            rd_data_reg <= 0;
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= 0;
        end else begin
            if (wr_accepted) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr <= wr_ptr + 1'b1;
