            if (rd_accepted) begin
                rd_data_reg <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1'b1;
            end

            if (wr_accepted && !rd_accepted)
                count_reg <= count_reg + 1'b1;
            else if (!wr_accepted && rd_accepted)
                count_reg <= count_reg - 1'b1;
            else
                count_reg <= count_reg;
