module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    // 状态机定义
    localparam IDLE       = 4'd0;
    localparam START_BIT  = 4'd1;
    localparam ADDR_BITS  = 4'd2;
    localparam ADDR_ACK   = 4'd3;
    localparam WR_BITS    = 4'd4;
    localparam WR_ACK     = 4'd5;
    localparam RD_BITS    = 4'd6;
    localparam RD_NACK    = 4'd7;
    localparam STOP_BIT   = 4'd8;

    reg [3:0] state, next_state;
    reg [7:0] shift_reg;
    reg [2:0] bit_cnt;
    reg [7:0] clk_cnt;
    reg [1:0] phase;
    reg rw_reg;
    reg [6:0] addr_reg;
    reg [7:0] wdata_reg;
    reg sda_i_sampled;

    // 时钟分频计数器
    wire clk_div_tick = (clk_cnt == CLK_DIV - 1);

    always @(posedge clk) begin
        if (!rst_n) begin
            clk_cnt <= 8'd0;
            phase <= 2'd0;
        end else if (busy) begin
            if (clk_div_tick) begin
                clk_cnt <= 8'd0;
                phase <= phase + 1'b1;
            end else begin
                clk_cnt <= clk_cnt + 1'b1;
            end
        end else begin
            clk_cnt <= 8'd0;
            phase <= 2'd0;
        end
    end

    // 状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start && !busy)
                    next_state = START_BIT;
            end
            START_BIT: begin
                if (phase == 2'd3 && clk_div_tick)
                    next_state = ADDR_BITS;
            end
            ADDR_BITS: begin
                if (bit_cnt == 3'd7 && phase == 2'd3 && clk_div_tick)
                    next_state = ADDR_ACK;
            end
            ADDR_ACK: begin
                if (phase == 2'd3 && clk_div_tick) begin
                    if (sda_i_sampled == 1'b1)
                        next_state = STOP_BIT;
                    else if (rw_reg == 1'b0)
                        next_state = WR_BITS;
                    else
                        next_state = RD_BITS;
                end
            end
            WR_BITS: begin
                if (bit_cnt == 3'd7 && phase == 2'd3 && clk_div_tick)
                    next_state = WR_ACK;
            end
            WR_ACK: begin
                if (phase == 2'd3 && clk_div_tick)
                    next_state = STOP_BIT;
            end
            RD_BITS: begin
                if (bit_cnt == 3'd7 && phase == 2'd3 && clk_div_tick)
                    next_state = RD_NACK;
            end
            RD_NACK: begin
                if (phase == 2'd3 && clk_div_tick)
                    next_state = STOP_BIT;
