                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= shift_reg[7];
                        end
                        2'd1: begin
                            scl_o <= 1'b1;
                            sda_o <= shift_reg[7];
                        end
                        2'd2: begin
                            scl_o <= 1'b1;
                            sda_o <= shift_reg[7];
                        end
                        2'd3: begin
                            scl_o <= 1'b0;
                            sda_o <= shift_reg[7];
                            if (clk_div_tick) begin
                                if (bit_cnt == 3'd7) begin
                                    bit_cnt <= 3'd0;
                                end else begin
                                    shift_reg <= {shift_reg[6:0], 1'b0};
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                        end
                    endcase
                end

                ADDR_ACK: begin
                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1; // 释放 SDA
                        end
                        2'd1: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
                        end
                        2'd2: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
