                                    ack_err <= 1'b1;
                                if (rw_reg == 1'b0) begin
                                    shift_reg <= wdata_reg;
                                    bit_cnt <= 3'd0;
                                end else begin
                                    rdata <= 8'd0;
                                    bit_cnt <= 3'd0;
                                end
                            end
                        end
                    endcase
                end

                WR_BITS: begin
                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= shift_reg[7];
                        end
                        2'd1: begin
                            scl_o <= 1'b1;
                            sda_o <= shift_reg[7];
                        end
                        2'd2: begin
                            scl_o <= 1'b1;
                            sda_o <= shift_reg[7];
                        end
                        2'd3: begin
                            scl_o <= 1'b0;
                            sda_o <= shift_reg[7];
                            if (clk_div_tick) begin
                                if (bit_cnt == 3'd7) begin
                                    bit_cnt <= 3'd0;
                                end else begin
                                    shift_reg <= {shift_reg[6:0], 1'b0};
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                        end
                    endcase
                end

                WR_ACK: begin
                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1;
                        end
                        2'd1: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
                        end
                        2'd2: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
                            if (clk_div_tick)
                                sda_i_sampled <= sda_i;
                        end
                        2'd3: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1;
                            if (clk_div_tick) begin
                                if (sda_i_sampled == 1'b1)
                                    ack_err <= 1'b1;
                            end
                        end
                    endcase
                end

                RD_BITS: begin
                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1;
                        end
                        2'd1: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
                        end
                        2'd2: begin
                            scl_o <= 1'b1;
                            sda_o <= 1'b1;
                            if (clk_div_tick) begin
                                rdata <= {rdata[6:0], sda_i};
                            end
                        end
                        2'd3: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1;
                            if (clk_div_tick) begin
                                if (bit_cnt == 3'd7) begin
                                    bit_cnt <= 3'd0;
                                end else begin
                                    bit_cnt <= bit_cnt + 1'b1;
                                end
                            end
                        end
                    endcase
                end

                RD_NACK: begin
                    case (phase)
                        2'd0: begin
                            scl_o <= 1'b0;
                            sda_o <= 1'b1;
