    reg rw_reg;
    reg [7:0] wdata_reg;
    reg [7:0] shift_reg;
    reg ack_err_reg;

    // 相位计数
    wire phase_tick;
    assign phase_tick = (phase_cnt == CLK_DIV - 1);

    // 相位计数器
    always @(posedge clk) begin
        if (!rst_n) begin
            phase_cnt <= 8'd0;
        end else if (state == IDLE) begin
            phase_cnt <= 8'd0;
        end else if (phase_tick) begin
            phase_cnt <= 8'd0;
        end else begin
            phase_cnt <= phase_cnt + 1'b1;
        end
    end

    // 状态机
    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // 下一状态逻辑
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start && !busy)
                    next_state = START_BIT;
            end
            START_BIT: begin
                if (phase_tick)
                    next_state = ADDR_BYTE;
            end
            ADDR_BYTE: begin
                if (phase_tick && bit_cnt == 8'd8)
                    next_state = ADDR_ACK;
            end
            ADDR_ACK: begin
                if (phase_tick) begin
                    if (sda_i == 1'b1)
                        next_state = STOP_BIT;
                    else if (rw_reg == 1'b0)
                        next_state = WR_BYTE;
                    else
                        next_state = RD_BYTE;
                end
            end
            WR_BYTE: begin
                if (phase_tick && bit_cnt == 8'd8)
                    next_state = WR_ACK;
            end
            WR_ACK: begin
                if (phase_tick)
                    next_state = STOP_BIT;
            end
            RD_BYTE: begin
                if (phase_tick && bit_cnt == 8'd8)
                    next_state = RD_NACK;
            end
            RD_NACK: begin
                if (phase_tick)
                    next_state = STOP_BIT;
            end
            STOP_BIT: begin
                if (phase_tick)
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // 位计数器
    always @(posedge clk) begin
