    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // 寄存器
    reg [31:0] REG0, REG1, REG2;
    wire [31:0] ID = 32'h5A5A_0003;

    // 写地址通道状态
    reg aw_done;
    reg [7:0] awaddr_reg;
    reg aw_pending;

    // 写数据通道状态
    reg w_done;
    reg [31:0] wdata_reg;
    reg [3:0] wstrb_reg;
    reg w_pending;

    // 写响应通道状态
    reg bvalid_reg;
    reg [1:0] bresp_reg;
    reg [1:0] b_resp_pending;
    reg b_pending;

    // 读地址通道状态
    reg ar_done;
    reg [7:0] araddr_reg;
    reg ar_pending;

    // 读数据通道状态
    reg rvalid_reg;
    reg [31:0] rdata_reg;
    reg [1:0] rresp_reg;
    reg [1:0] r_resp_pending;
    reg r_pending;

    // 地址译码函数
    function [1:0] decode_addr;
        input [7:0] addr;
        begin
            if (addr[7:4] != 4'h0)
                decode_addr = 2'b11; // DECERR
            else if (addr[3:2] == 2'b11)
                decode_addr = 2'b10; // SLVERR (ID register, read-only)
            else
                decode_addr = 2'b00; // OKAY
        end
    endfunction

    // 写地址通道
    assign awready = !aw_pending || aw_done;

    always @(posedge clk) begin
        if (!rst_n) begin
            aw_done <= 1'b0;
            awaddr_reg <= 8'h0;
            aw_pending <= 1'b0;
        end else begin
            if (awvalid && awready && !aw_done) begin
                awaddr_reg <= awaddr;
                aw_done <= 1'b1;
                aw_pending <= 1'b1;
            end
            if (aw_done && w_done) begin
                aw_done <= 1'b0;
                aw_pending <= 1'b0;
            end
        end
    end

    // 写数据通道
    assign wready = !w_pending || w_done;

    always @(posedge clk) begin
        if (!rst_n) begin
            w_done <= 1'b0;
            wdata_reg <= 32'h0;
            wstrb_reg <= 4'h0;
            w_pending <= 1'b0;
        end else begin
            if (wvalid && wready && !w_done) begin
                wdata_reg <= wdata;
                wstrb_reg <= wstrb;
                w_done <= 1'b1;
                w_pending <= 1'b1;
            end
            if (aw_done && w_done) begin
                w_done <= 1'b0;
                w_pending <= 1'b0;
            end
        end
    end

    // 写响应通道
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            bvalid_reg <= 1'b0;
            bresp_reg <= 2'b00;
            b_resp_pending <= 2'b00;
            b_pending <= 1'b0;
