            ar_done <= 1'b0;
            araddr_reg <= 8'h0;
            ar_pending <= 1'b0;
        end else begin
            if (arvalid && arready && !ar_done) begin
                araddr_reg <= araddr;
                ar_done <= 1'b1;
                ar_pending <= 1'b1;
            end
            if (ar_done && rvalid_reg && rready) begin
                ar_done <= 1'b0;
                ar_pending <= 1'b0;
