    reg        timeout_r;

    assign timeout = timeout_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            cnt       <= 32'd0;
            timeout_r <= 1'b0;
        end else if (!enable || kick) begin
            cnt       <= 32'd0;
            timeout_r <= 1'b0;
        end else begin
            if (cnt < TIMEOUT - 1) begin
                cnt       <= cnt + 32'd1;
                timeout_r <= 1'b0;
            end else begin
                cnt       <= cnt;
                timeout_r <= 1'b1;
            end
        end
    end

