module watchdog #(parameter TIMEOUT = 64) (
    input clk,
    input rst_n,
    input enable,
    input kick,
    output timeout
);

    // 计数器位宽推导：TIMEOUT-1 需要可表示
    function integer clogb2;
        input integer value;
        integer v;
        begin
            v = value - 1;
            for (clogb2 = 0; v > 0; clogb2 = clogb2 + 1)
                v = v >> 1;
        end
    endfunction

    localparam WIDTH = (TIMEOUT <= 2) ? 1 : clogb2(TIMEOUT);

    reg [WIDTH-1:0] cnt;
    reg             to_reg;

