module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    integer i;
    reg [31:0] regs [0:31];
    reg [31:0] alu_result_r;
    reg        illegal_r;

    wire [6:0] opcode = instr[6:0];
    wire [4:0] rd     = instr[11:7];
    wire [2:0] funct3 = instr[14:12];
    wire [6:0] funct7 = instr[31:25];
    wire [4:0] rs1    = instr[19:15];
    wire [4:0] rs2    = instr[24:20];

    wire [31:0] rs1_val = (rs1 == 5'd0) ? 32'd0 : regs[rs1];
    wire [31:0] rs2_val = (rs2 == 5'd0) ? 32'd0 : regs[rs2];

    wire [31:0] imm_i = {{20{instr[31]}}, instr[31:20]};
    wire [4:0]  shamt = instr[24:20];

    wire is_r     = (opcode == 7'b0110011);
    wire is_i     = (opcode == 7'b0010011);
    wire is_add   = is_r & (funct3 == 3'b000) & (funct7 == 7'b0000000);
    wire is_sub   = is_r & (funct3 == 3'b000) & (funct7 == 7'b0100000);
    wire is_sll   = is_r & (funct3 == 3'b001) & (funct7 == 7'b0000000);
    wire is_slt   = is_r & (funct3 == 3'b010) & (funct7 == 7'b0000000);
    wire is_sltu  = is_r & (funct3 == 3'b011) & (funct7 == 7'b0000000);
    wire is_xor   = is_r & (funct3 == 3'b100) & (funct7 == 7'b0000000);
    wire is_srl   = is_r & (funct3 == 3'b101) & (funct7 == 7'b0000000);
    wire is_sra   = is_r & (funct3 == 3'b101) & (funct7 == 7'b0100000);
    wire is_or    = is_r & (funct3 == 3'b110) & (funct7 == 7'b0000000);
    wire is_and   = is_r & (funct3 == 3'b111) & (funct7 == 7'b0000000);

    wire is_addi  = is_i & (funct3 == 3'b000);
    wire is_slti  = is_i & (funct3 == 3'b010);
    wire is_sltiu = is_i & (funct3 == 3'b011);
    wire is_xori  = is_i & (funct3 == 3'b100);
    wire is_ori   = is_i & (funct3 == 3'b110);
    wire is_andi  = is_i & (funct3 == 3'b111);
    wire is_slli = is_i & (funct3 == 3'b001) & (funct7 == 7'b0000000);
    wire is_srli = is_i & (funct3 == 3'b101) & (funct7 == 7'b0000000);
    wire is_srai = is_i & (funct3 == 3'b101) & (funct7 == 7'b0100000);

    wire legal = is_add | is_sub | is_sll | is_slt | is_sltu | is_xor |
                 is_srl | is_sra | is_or  | is_and |
                 is_addi | is_slti | is_sltiu | is_xori | is_ori | is_andi |
                 is_slli | is_srli | is_srai;

    wire [31:0] op1 = rs1_val;
    wire [31:0] op2 = is_i ? imm_i : rs2_val;
    wire [4:0]  sh  = is_i ? shamt : rs2_val[4:0];

    wire signed [31:0] s_op1 = op1;
    wire signed [31:0] s_op2 = op2;
    wire signed [31:0] s_res_sra = $signed(op1) >>> sh[4:0];

    reg [31:0] alu_val;

    always @(*) begin
        if (is_add | is_addi)
            alu_val = op1 + op2;
        else if (is_sub)
            alu_val = op1 - op2;
        else if (is_sll | is_slli)
            alu_val = op1 << sh;
        else if (is_slt | is_slti)
            alu_val = (s_op1 < s_op2) ? 32'd1 : 32'd0;
        else if (is_sltu | is_sltiu)
            alu_val = (op1 < op2) ? 32'd1 : 32'd0;
        else if (is_xor | is_xori)
            alu_val = op1 ^ op2;
        else if (is_or | is_ori)
            alu_val = op1 | op2;
        else if (is_and | is_andi)
            alu_val = op1 & op2;
        else if (is_srl | is_srli)
            alu_val = op1 >> sh;
        else if (is_sra | is_srai)
            alu_val = s_res_sra;
        else
            alu_val = 32'd0;
    end

    assign dbg_data = (dbg_addr == 5'd0) ? 32'd0 : regs[dbg_addr];

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= 32'd0;
            alu_result_r <= 32'd0;
            illegal_r   <= 1'b0;
        end else if (valid) begin
            if (legal) begin
                if (rd != 5'd0)
                    regs[rd] <= alu_val;
                alu_result_r <= alu_val;
                illegal_r   <= 1'b0;
            end else begin
                alu_result_r <= 32'd0;
                illegal_r   <= 1'b1;
            end
        end
    end

    assign alu_result = alu_result_r;
    assign illegal    = illegal_r;

