                div_cnt <= 0;
                phase   <= 0;
                bit_cnt <= 0;
                scl_r   <= 1'b1;
                sda_r   <= 1'b1;
                if (start && !busy_r) begin
                    rw_r      <= rw;
                    addr_r    <= addr;
                    wdata_r   <= wdata;
                    ack_err_r <= 1'b0;
                    busy_r    <= 1'b1;
                    state     <= S_START;
