module pwm_gen (
    input clk,
    input rst_n,
    input [7:0] duty,
    output pwm
);
    reg [7:0] counter;
    reg [7:0] D;
    reg pwm_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            counter <= 8'b0;
            D <= 8'b0;
            pwm_reg <= 1'b0;
        end else begin
            // 更新计数器
            if (counter == 8'hff)
                counter <= 8'b0;
            else
                counter <= counter + 1'b1;

            // 在计数器从255回到0时锁存duty值
            if (counter == 8'hff)
                D <= duty;

            // 更新pwm输出
            if (counter < D)
                pwm_reg <= 1'b1;
            else
                pwm_reg <= 1'b0;
        end
    end

    assign pwm = pwm_reg;
endmodule
