module ring_counter (
    input clk,
    input rst_n,
    input en,
    input dir,
    output [3:0] q,
    output wrap
);
    reg [3:0] q_reg;

    assign q = q_reg;
    assign wrap = en & (q_reg == 4'b0001) & (q_reg != 4'b0001 || !rst_n);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_reg <= 4'b0001;
        end else if (en) begin
            if (dir) begin
                // Right shift
                q_reg <= {q_reg[0], q_reg[3:1]};
            end else begin
                // Left shift
                q_reg <= {q_reg[2:0], q_reg[3]};
            end
        end
    end

    // Corrected wrap signal generation
    wire wrap_sig;
    assign wrap_sig = (q_reg == 4'b0001) && en;

    reg wrap_d;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wrap_d <= 0;
        end else begin
            wrap_d <= wrap_sig;
        end
    end

    assign wrap = wrap_sig & ~wrap_d;

endmodule
