```verilog
module ring_counter (
    input clk,
    input rst_n,
    input en,
    input dir,
    output [3:0] q,
    output wrap
);
    reg [3:0] q_reg;

    assign q = q_reg;
    assign wrap = en & (q_reg == 4'b0001) & (q_reg != 4'b0001); // 实际上需要检测从非0001到0001的变化

    // 更正wrap逻辑：检测是否从非0001状态变为0001状态
    wire wrap_pulse = en & (q_reg == 4'b0001) & 
                     ((dir == 0 & $past(q_reg, 1) == 4'b1000) | 
                      (dir == 1 & $past(q_reg, 1) == 4'b0010));

    // 由于不能使用$past，改用组合逻辑判断
    wire prev_state_for_wrap = dir ? 4'b0010 : 4'b1000; // 需要记录前一状态

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_reg <= 4'b0001;
        end else if (en) begin
            if (dir == 0) begin // 左移
                case (q_reg)
                    4'b0001: q_reg <= 4'b0010;
                    4'b0010: q_reg <= 4'b0100;
                    4'b0100: q_reg <= 4'b1000;
                    4'b1000: q_reg <= 4'b0001;
                    default: q_reg <= 4'b0001;
                endcase
            end else begin // 右移
                case (q_reg)
                    4'b0001: q_reg <= 4'b1000;
                    4'b1000: q_reg <= 4'b0100;
                    4'b0100: q_reg <= 4'b0010;
                    4'b0010: q_reg <= 4'b0001;
                    default: q_reg <= 4'b0001;
                endcase
            end
        end
    end

    // 重新定义wrap输出
    wire was_prev_state = (dir == 0) ? (q_reg == 4'b0001 && $past(q_reg, 1) == 4'b1000) :
                                        (q_reg == 4'b0001 && $past(q_reg, 1) == 4'b0010);

    // 实现wrap逻辑，基于当前状态和使能信号
    reg wrap_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wrap_reg <= 1'b0;
        end else begin
            // wrap在q从其他值变为0001时产生一个周期的脉冲
            if (en && q_reg == 4'b0001 && 
                ((dir == 0 && $past(q_reg, 1) == 4'b1000) || 
                 (dir == 1 && $past(q_reg, 1) == 4'b0010))) begin
                wrap_reg <= 1'b1;
            end else begin
                wrap_reg <= 1'b0;
            end
        end
    end

    assign wrap = wrap_reg;

    // 再次简化实现
    reg [3:0] q_reg;
    reg wrap_d;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_reg <= 4'b0001;
        end else if (en) begin
            if (dir == 0) begin // 左移
                q_reg <= {q_reg[2:0], q_reg[3]};
            end else begin // 右移
                q_reg <= {q_reg[0], q_reg[3:1]};
            end
        end
    end

    // wrap在q从1000(左移)或0010(右移)变为0001时产生
    always @(*) begin
        if (en && q_reg == 4'b0001) begin
            if ((dir == 0 && q_reg == 4'b0001 /*需要比较前一状态*/) ||
                (dir == 1 && q_reg == 4'b0001 /*需要比较前一状态*/)) begin
                wrap_d = 1'b1;
            end else begin
                wrap_d = 1'b0;
            end
        end else begin
            wrap_d = 1'b0;
        end
    end

    // 最终实现
    reg [3:0] q_reg;
    reg [3:0] q_next;

    always @(*) begin
        if (dir == 0) begin // 左移
            q_next = {q_reg[2:0], q_reg[3]};
        end else begin // 右移
            q_next = {q_reg[0], q_reg[3:1]};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q_reg <= 4'b0001;
        end else if (en) begin
            q_reg <= q_next;
        end
    end

    assign q = q_reg;
    assign wrap = en & (q_reg == 4'b0001) & (q_next != 4'b0001); // 当前是0001但下一个不是0001（即刚从其他状态转来）

endmodule
