always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sig_d <= 1'b0;
        pulse <= 1'b0;
        cnt <= 8'b0;
    end else begin
        sig_d <= sig;
        pulse <= 1'b0; // 默认为0

        case (mode)
