                if (sig & ~sig_d) begin
                    pulse <= 1'b1;
                    cnt <= cnt + 1'b1;
                end
            end
            2'b10: begin // 下降沿检测
                if (~sig & sig_d) begin
                    pulse <= 1'b1;
                    cnt <= cnt + 1'b1;
                end
            end
            2'b11: begin // 双边沿检测
                if ((sig & ~sig_d) | (~sig & sig_d)) begin
                    pulse <= 1'b1;
                    cnt <= cnt + 1'b1;
                end
            end
            default: begin
                pulse <= 1'b0;
            end
        endcase
    end
end

endmodule
