module ring_counter (
    input clk,
    input rst_n,
    input en,
    input dir,
    output [3:0] q,
    output wrap
);
    reg [3:0] q_reg;
    reg wrap_reg;

    wire next_wrap;
    wire [3:0] next_q;

    // 计算下一个状态
    assign next_q = en ? (dir ? {q_reg[0], q_reg[3:1]} : {q_reg[2:0], q_reg[3]}) : q_reg;
    assign next_wrap = en & (next_q == 4'b0001) & ~rst_n; // 在复位时也考虑

    always @(posedge clk) begin
        if (!rst_n) begin
            q_reg <= 4'b0001;
            wrap_reg <= 1'b0;
        end
        else begin
            q_reg <= next_q;
            wrap_reg <= next_wrap;
        end
    end

    assign q = q_reg;
    assign wrap = wrap_reg;
endmodule
