module edge_detect (
    input clk,
    input rst_n,
    input sig,
    input [1:0] mode,
    output pulse,
    output [7:0] cnt
);

    reg [7:0] cnt_reg;
    reg sig_d1;

    wire pos_edge = (sig & ~sig_d1) & (mode == 2'b01 | mode == 2'b11);
    wire neg_edge = (~sig & sig_d1) & (mode == 2'b10 | mode == 2'b11);
    wire any_edge = pos_edge | neg_edge;

    assign pulse = any_edge;
    assign cnt = cnt_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_reg <= 8'b0;
            sig_d1 <= 1'b0;
        end else begin
            sig_d1 <= sig;
            if (any_edge) begin
                cnt_reg <= cnt_reg + 1'b1;
            end
        end
    end

endmodule
