    input clk,
    input rst_n,
    input sig,
    input [1:0] mode,
    output pulse,
    output [7:0] cnt
);
    reg [7:0] cnt_reg;
    reg s_reg;
    reg pulse_reg;

    wire rising_edge = (sig == 1'b1) && (s_reg == 1'b0);
    wire falling_edge = (sig == 1'b0) && (s_reg == 1'b1);
    wire detected = ((mode[0] == 1'b1) && rising_edge) || 
                    ((mode[1] == 1'b1) && falling_edge);

