module watchdog #(parameter TIMEOUT = 64) (
    input clk,
    input rst_n,
    input enable,
    input kick,
    output timeout
);
    parameter CNT_WIDTH = $clog2(TIMEOUT);
    reg [CNT_WIDTH-1:0] counter;
    reg timeout_r;

    assign timeout = timeout_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            timeout_r <= 0;
        end else begin
            if (timeout_r) begin
                if (kick || !enable) begin
                    counter <= 0;
                    timeout_r <= 0;
                end
            end else if (enable) begin
                if (kick) begin
                    counter <= 0;
                    timeout_r <= 0;
                end else if (counter == TIMEOUT - 1) begin
                    timeout_r <= 1;
                end else begin
                    counter <= counter + 1;
                end
            end else begin
                counter <= 0;
                timeout_r <= 0;
            end
        end
    end
