module watchdog #(parameter TIMEOUT = 64) (
    input clk,
    input rst_n,
    input enable,
    input kick,
    output reg timeout
);

    // 计算计数器位宽
    localparam CNT_WIDTH = $clog2(TIMEOUT);

    // 内部计数器
    reg [CNT_WIDTH-1:0] counter;

    always @(posedge clk) begin
        if (!rst_n) begin
            counter <= {CNT_WIDTH{1'b0}};
            timeout <= 1'b0;
        end
        else begin
            if (!enable || kick) begin
                counter <= {CNT_WIDTH{1'b0}};
                timeout <= 1'b0;
            end
            else if (counter < TIMEOUT - 1) begin
                counter <= counter + 1'b1;
                timeout <= 1'b0;
            end
            else begin
                // counter == TIMEOUT - 1, keep counting and set timeout
                counter <= counter; // hold the value
                timeout <= 1'b1;
            end
        end
    end

