## 设计思路

1. **信号分析**：输入包括clk(1位), rst_n(1位), enable(1位), kick(1位)；输出timeout(1位)为寄存器输出
2. **计数器设计**：需要计数器记录连续无喂狗周期数，范围0到TIMEOUT-1，位宽为$ceil(log_2(TIMEOUT))$
3. **复位行为**：同步复位时计数器清零，timeout清零
4. **控制逻辑**：当enable=1且kick=0时计数器递增，达到TIMEOUT-1后timeout置1；当enable=0或kick=1的上升沿时计数器清零且timeout清零

```verilog
module watchdog #(parameter TIMEOUT = 64) (
    input clk,
    input rst_n,
    input enable,
    input kick,
    output timeout
);

    // 计算计数器位宽
    localparam CNT_WIDTH = $clog2(TIMEOUT);

    reg [CNT_WIDTH-1:0] counter;
    reg timeout_reg;

    wire clear_counter;
    wire increment_counter;

    // 清零条件：复位、enable=0或kick=1
    assign clear_counter = (~rst_n) || (~enable) || kick;

    // 递增条件：enable=1, kick=0, 且计数未达上限
    assign increment_counter = enable && (~kick) && (counter < (TIMEOUT - 1));

    always @(posedge clk) begin
        if (~rst_n) begin
            counter <= 0;
            timeout_reg <= 0;
        end
        else if (clear_counter) begin
            counter <= 0;
            timeout_reg <= 0;
        end
        else if (increment_counter) begin
            counter <= counter + 1;
            if (counter + 1 >= (TIMEOUT - 1)) begin
                timeout_reg <= 1;
            end
        end
        else if (enable && (~kick) && (counter == (TIMEOUT - 1))) begin
            // 计数已达上限，保持timeout=1
            timeout_reg <= 1;
        end
    end

    assign timeout = timeout_reg;

endmodule
