3. **计数器**：计数范围0到LEN-1，需要$ceil(log2(LEN))$位宽度。复位时清零，ACTIVE态下递增或重置。

4. **复位行为**：异步复位，rst_n=0时输出清零，计数器清零，状态回到IDLE。

## 完整代码

```verilog
module pulse_stretch #(parameter LEN = 8) (
    input clk,
    input rst_n,
    input in,
    output out
);
    reg [3:0] counter_width = $clog2(LEN + 1); // 计算所需位宽
    reg [31:0] counter; // 使用足够大的寄存器存储计数值
    reg active;

    wire should_reset_counter = !rst_n | (active & (counter >= LEN - 1));
    wire should_start = in | (active & in); // 可重触发

    assign out = active;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            active <= 0;
        end else begin
            if (should_start && !active) begin
                active <= 1;
                counter <= 0;
            end else if (active) begin
                if (counter < LEN - 1) begin
                    if (in) begin
                        counter <= 0; // 重触发，重置计数器
                    end else begin
                        counter <= counter + 1;
                    end
                end else begin
                    active <= 0;
                    counter <= 0;
                end
            end else if (in) begin
                active <= 1;
                counter <= 0;
            end
        end
    end
endmodule
