    input clk,
    input rst_n,
    input wr_en,
    input [DW-1:0] wr_data,
    input rd_en,
    output reg [DW-1:0] rd_data,
    output reg full,
    output reg empty,
    output reg [$clog2(DEPTH)+1-1:0] count
);

    // Calculate address width
    localparam ADDR_WIDTH = $clog2(DEPTH);

    // Memory array
    reg [DW-1:0] mem [0:DEPTH-1];

    // Read and write pointers
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [ADDR_WIDTH-1:0] wr_ptr;

    always @(posedge clk) begin
        if (!rst_n) begin
            rd_ptr <= {ADDR_WIDTH{1'b0}};
            wr_ptr <= {ADDR_WIDTH{1'b0}};
            rd_data <= {DW{1'b0}};
            count <= {($clog2(DEPTH)+1){1'b0}};
            full <= 1'b0;
            empty <= 1'b1;
        end else begin
            // Default values
            rd_ptr <= rd_ptr;
            wr_ptr <= wr_ptr;
            rd_data <= rd_data;
            count <= count;
            full <= full;
            empty <= empty;

            // Determine if read and write are accepted
            wire rd_accepted = rd_en & ~empty;
            wire wr_accepted = wr_en & ~full;

            // Update memory and pointers
            if (wr_accepted) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr <= wr_ptr + 1'b1;
            end

            if (rd_accepted) begin
                rd_data <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1'b1;
            end

            // Update count based on read/write acceptance
            if (wr_accepted & rd_accepted) begin
                // Both accepted - no change in count
                count <= count;
            end else if (wr_accepted) begin
                // Only write accepted - increment count
                count <= count + 1'b1;
            end else if (rd_accepted) begin
                // Only read accepted - decrement count
                count <= count - 1'b1;
            end

            // Update flags
