                // Was full before this cycle and a write was accepted (but not possible since full=1)
                // Actually, update when we reach DEPTH
                full <= 1'b1;
            end else if (rd_accepted && !wr_accepted) begin
                // Read but no write - can't be full anymore if it was
                full <= (count - 1'b1) == DEPTH;
            end else if (!rd_accepted && wr_accepted) begin
                // Write but no read - check if now full
                full <= (count + 1'b1) == DEPTH;
            end else begin
