            if (count == 1'b1 && !wr_accepted && rd_accepted) begin
                // Was one element and read occurred - now empty
                empty <= 1'b1;
            end else if (rd_accepted && !wr_accepted) begin
                // Read but no write - might become empty
                empty <= (count - 1'b1) == 0;
            end else if (!rd_accepted && wr_accepted) begin
                // Write but no read - can't be empty if it was
                empty <= (count + 1'b1) == 0;  // This will be false if count+1 > 0
            end else begin
                // No change in count
                empty <= count == 0;
            end
        end
    end

    // Recalculate flags based on current count for immediate update
    always @(*) begin
        full = (count == DEPTH);
        empty = (count == 0);
