module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    reg [3:0] bit_cnt;
    reg [$clog2(CLK_DIV*2)-1:0] clk_cnt;
    reg [2:0] state;
    reg [7:0] rx_reg;
    reg [6:0] tx_shift;
    reg busy_reg;
    reg done_reg;
    reg sclk_reg;
    reg mosi_reg;
    reg cs_n_reg;

    parameter IDLE = 3'b000;
    parameter SETUP = 3'b001;
    parameter SHIFT = 3'b010;
    parameter WAIT = 3'b011;

    assign rx_data = rx_reg;
    assign busy = busy_reg;
    assign done = done_reg;
    assign sclk = sclk_reg;
    assign mosi = mosi_reg;
    assign cs_n = cs_n_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 0;
            clk_cnt <= 0;
            state <= IDLE;
            rx_reg <= 8'h00;
            tx_shift <= 7'h00;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            sclk_reg <= 1'b0;
            mosi_reg <= 1'b0;
            cs_n_reg <= 1'b1;
        end else begin
            done_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        state <= SETUP;
                        busy_reg <= 1'b1;
                        cs_n_reg <= 1'b0;
                        rx_reg <= 8'h00;
                        tx_shift <= tx_data[6:0];
                        bit_cnt <= 0;
                        clk_cnt <= 0;
                        sclk_reg <= 1'b0;
                        mosi_reg <= tx_data[7];
                    end
                end

                SETUP: begin
                    sclk_reg <= 1'b0;
                    mosi_reg <= tx_shift[6];
                    clk_cnt <= clk_cnt + 1'b1;
                    if (clk_cnt == CLK_DIV - 1) begin
                        state <= SHIFT;
                        clk_cnt <= 0;
                    end
                end

                SHIFT: begin
                    sclk_reg <= 1'b1;
                    rx_reg <= {rx_reg[6:0], miso};
                    clk_cnt <= clk_cnt + 1'b1;
                    if (clk_cnt == CLK_DIV - 1) begin
                        state <= WAIT;
                        clk_cnt <= 0;
                        if (bit_cnt < 7) begin
                            bit_cnt <= bit_cnt + 1'b1;
                            tx_shift <= {tx_shift[5:0], 1'b0};
                            mosi_reg <= tx_shift[6];
                        end
                    end else begin
                        tx_shift <= {tx_shift[5:0], 1'b0};
                        mosi_reg <= tx_shift[6];
                    end
