        if (!rst_n) begin
            state <= IDLE;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            sclk_r <= 1'b0;
            cs_n_r <= 1'b1;
            mosi_r <= 1'b0;
            rx_data_r <= 8'b0;
            bit_counter <= 4'b0;
            sclk_counter <= 0;
            tx_shift_reg <= 8'b0;
            start_d <= 1'b0;
        end else begin
