                    busy_r <= 1'b0;
                    done_r <= 1'b0;
                    sclk_r <= 1'b0;
                    cs_n_r <= 1'b1;
                    if (!busy_r && start && !start_d) begin
                        state <= START;
                        busy_r <= 1'b1;
                        tx_shift_reg <= tx_data;
                        bit_counter <= 4'b0;
                        sclk_counter <= 0;
                    end
                end

                START: begin
                    cs_n_r <= 1'b0;
                    sclk_counter <= sclk_counter + 1'b1;
