## 设计思路

1. **信号分类**：
   - 寄存器输出：busy, done, sclk, mosi, cs_n, rx_data
   - 输入：clk, rst_n, start, tx_data, miso

2. **状态机设计**：
   - 状态：IDLE(空闲), START(启动), TRANSMIT(传输), DONE(完成)
   - 计数器：bit_cnt(3位，计数0-9)，sclk_cnt(用于半周期计数)

3. **计数器**：
   - sclk_half_period: 计数CLK_DIV个周期切换sclk
   - bit_cnt: 计数0-7表示8位传输，第8位后进入完成状态

4. **复位行为**：同步复位，所有输出清零，sclk=0, cs_n=1
5. **时序要求**：sclk在CS拉低后CLK_DIV个周期出现第一个上升沿，每个sclk周期传输1位，共8位

```verilog
module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output reg [7:0] rx_data,
    output reg busy,
    output reg done,
    output reg sclk,
    output reg mosi,
    input miso,
    output reg cs_n
);

    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter TRANSMIT = 2'b10;
    parameter DONE = 2'b11;

    reg [1:0] state, next_state;
    reg [2:0] bit_cnt;
    reg [3:0] sclk_half_period;
    reg [7:0] shift_tx, shift_rx;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy <= 1'b0;
            done <= 1'b0;
            sclk <= 1'b0;
            cs_n <= 1'b1;
            bit_cnt <= 3'd0;
            sclk_half_period <= 4'd0;
            shift_tx <= 8'd0;
            shift_rx <= 8'd0;
            rx_data <= 8'd0;
            mosi <= 1'b0;
        end else begin
            state <= next_state;
            case (next_state)
                IDLE: begin
                    busy <= 1'b0;
                    done <= 1'b0;
                    sclk <= 1'b0;
                    cs_n <= 1'b1;
                    bit_cnt <= 3'd0;
                    sclk_half_period <= 4'd0;
                end
                START: begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    bit_cnt <= 3'd0;
                    sclk_half_period <= 4'd0;
                    shift_tx <= tx_data;
                    shift_rx <= 8'd0;
                    mosi <= tx_data[7];
                    sclk <= 1'b0;  // Start with sclk low
                end
                TRANSMIT: begin
                    busy <= 1'b1;
                    if (sclk_half_period == (CLK_DIV - 1)) begin
                        sclk <= ~sclk;
                        sclk_half_period <= 4'd0;

                        if (sclk == 1'b0) begin  // Falling edge - update MOSI
                            if (bit_cnt < 7) begin
                                bit_cnt <= bit_cnt + 1'b1;
                                shift_tx <= {shift_tx[6:0], 1'b0};
                                mosi <= shift_tx[6];
                            end else begin
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                        end else begin  // Rising edge - sample MISO
                            shift_rx <= {shift_rx[6:0], miso};
                        end
                    end else begin
                        sclk_half_period <= sclk_half_period + 1'b1;
                    end
                end
                DONE: begin
                    done <= 1'b1;
                    sclk <= 1'b0;
                    cs_n <= 1'b1;
                    rx_data <= shift_rx;
                end
            endcase
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (!busy && start)
                    next_state = START;
                else
                    next_state = IDLE;
            end
            START: begin
                next_state = TRANSMIT;
            end
            TRANSMIT: begin
                if (bit_cnt == 7 && sclk_half_period == (CLK_DIV - 1) && sclk == 1'b0)
                    next_state = DONE;
                else
                    next_state = TRANSMIT;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase

        if (!rst_n)
            next_state = IDLE;
    end

endmodule
