   - 输入：clk, rst_n, start(寄存), tx_data(组合), miso(组合)
   - 输出：rx_data(寄存), busy(寄存), done(寄存), sclk(寄存), mosi(寄存), cs_n(寄存)

2. **状态机设计**：
   - 状态：IDLE(空闲), START(开始), TRANSMIT(传输中), DONE(完成)
   - 计数器：bit_cnt(3位，0-7表示当前传输位)，sclk_cnt(时钟分频计数器)

3. **时序控制**：
   - 使用sclk_cnt计数器实现CLK_DIV分频
   - bit_cnt记录当前传输的位(0-7共8位)
   - 在sclk上升沿采样miso，在下降沿更新mosi
   - 传输完成后cs_n拉高，产生done脉冲

4. **复位处理**：同步复位，所有寄存器清零，输出回到初始状态

```verilog
module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    reg [2:0] state;
    reg [2:0] bit_cnt;
    reg [31:0] sclk_cnt;
    reg [7:0] tx_reg;
    reg [7:0] rx_reg;
    reg busy_r;
    reg done_r;
    reg sclk_r;
    reg mosi_r;
    reg cs_n_r;

    // 状态定义
    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter TRANSMIT = 3'b010;
    parameter DONE = 3'b011;

    assign rx_data = rx_reg;
    assign busy = busy_r;
    assign done = done_r;
    assign sclk = sclk_r;
    assign mosi = mosi_r;
    assign cs_n = cs_n_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 0;
            sclk_cnt <= 0;
            tx_reg <= 0;
            rx_reg <= 0;
            busy_r <= 0;
            done_r <= 0;
            sclk_r <= 0;
            mosi_r <= 0;
            cs_n_r <= 1;
        end else begin
            case (state)
                IDLE: begin
                    done_r <= 0;
                    if (start && !busy_r) begin
                        tx_reg <= tx_data;
                        busy_r <= 1;
                        cs_n_r <= 0;
                        bit_cnt <= 0;
                        sclk_cnt <= 0;
                        sclk_r <= 0;
                        mosi_r <= tx_data[7];
                        state <= START;
                    end
                end

                START: begin
                    if (sclk_cnt == CLK_DIV - 1) begin
                        sclk_r <= 1;
                        sclk_cnt <= 0;
                        state <= TRANSMIT;
                    end else begin
                        sclk_cnt <= sclk_cnt + 1;
                    end
                end

                TRANSMIT: begin
                    if (sclk_r == 1) begin  // sclk上升沿 - 采样MISO
                        rx_reg[7-bit_cnt] <= miso;
                        if (bit_cnt == 7) begin  // 最后一位传输完成
                            sclk_r <= 0;
                            cs_n_r <= 1;
                            done_r <= 1;
                            state <= DONE;
                        end else begin
                            sclk_r <= 0;
                            sclk_cnt <= 0;
                            bit_cnt <= bit_cnt + 1;
                        end
                    end else begin  // sclk下降沿 - 更新MOSI
                        if (sclk_cnt == CLK_DIV - 1) begin
                            sclk_r <= 1;
                            mosi_r <= tx_reg[6-bit_cnt];  // 准备下一位
                            sclk_cnt <= 0;
                        end else begin
                            sclk_cnt <= sclk_cnt + 1;
                        end
                    end
                end

                DONE: begin
                    done_r <= 0;
                    busy_r <= 0;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule
