## 设计思路

**1. 信号分类：**
- 输入：clk, rst_n, start, rw, addr[6:0], wdata[7:0], sda_i (组合)
- 输出：rdata[7:0], busy, done, ack_err, scl_o, sda_o (其中done, ack_err, busy为寄存器，其余为组合)

**2. 状态机：**
- IDLE: 等待start
- START: 发送起始条件
- ADDR: 发送地址+读写位
- WAIT_ADDR_ACK: 等待地址ACK
- WRITE_DATA: 写数据(8位)
- WAIT_DATA_ACK: 等待数据ACK
- READ_DATA: 读数据(8位)
- SEND_NACK: 发送NACK
- STOP: 发送停止条件
- ERROR_STOP: 错误时停止

**3. 计数器：**
- 位传输计数器：3位(0-7)，用于8位数据传输
- SCL时钟分频计数器：根据CLK_DIV控制SCL周期

**4. 复位行为：**
- 所有寄存器复位为初始状态，总线释放(SCL=1, SDA=1)

## 完整代码

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    parameter IDLE = 4'b0000,
              START = 4'b0001,
              ADDR = 4'b0010,
              WAIT_ADDR_ACK = 4'b0011,
              WRITE_DATA = 4'b0100,
              WAIT_DATA_ACK = 4'b0101,
              READ_DATA = 4'b0110,
              SEND_NACK = 4'b0111,
              STOP = 4'b1000,
              ERROR_STOP = 4'b1001;

    reg [2:0] bit_cnt;
    reg [3:0] clk_cnt;
    reg [7:0] shift_reg;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_r;
    reg sda_r;

    assign rdata = rdata_r;
    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_r;
    assign sda_o = sda_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 0;
            clk_cnt <= 0;
            shift_reg <= 0;
            rdata_r <= 0;
            busy_r <= 0;
            done_r <= 0;
            ack_err_r <= 0;
            scl_r <= 1;
            sda_r <= 1;
        end else begin
            case (state)
                IDLE: begin
                    busy_r <= 0;
                    done_r <= 0;
                    ack_err_r <= 0;
                    scl_r <= 1;
                    sda_r <= 1;
                    if (start) begin
                        busy_r <= 1;
                        state <= START;
                        clk_cnt <= 0;
                    end
                end

                START: begin
                    if (clk_cnt < CLK_DIV * 2 - 1) begin
                        clk_cnt <= clk_cnt + 1;
                        if (clk_cnt == CLK_DIV - 1) begin
                            sda_r <= 0; // SDA falls while SCL is high
                        end
                        if (clk_cnt == CLK_DIV * 2 - 1) begin
                            scl_r <= 0; // SCL falls
                            sda_r <= 1; // Release SDA for address transmission
                            state <= ADDR;
                            bit_cnt <= 0;
                            shift_reg <= {addr, rw};
                            clk_cnt <= 0;
                        end
                    end else begin
                        clk_cnt <= 0;
                    end
                end

                ADDR: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        if (bit_cnt < 7) begin
                            sda_r <= shift_reg[7];
                            scl_r <= 1; // SCL rises
                            shift_reg <= {shift_reg[6:0], 1'b0};
                        end else begin
                            sda_r <= shift_reg[7];
                            scl_r <= 1; // Last bit SCL rises
                            state <= WAIT_ADDR_ACK;
                            sda_r <= 1; // Release SDA to read ACK
                        end
                        bit_cnt <= bit_cnt + 1;
                    end
                end

                WAIT_ADDR_ACK: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        scl_r <= 0; // SCL falls
                        if (!sda_i) begin // Got ACK
                            if (rw) begin
                                state <= READ_DATA;
                                bit_cnt <= 0;
                                rdata_r <= 0;
                            end else begin
                                state <= WRITE_DATA;
                                bit_cnt <= 0;
                                shift_reg <= wdata;
                            end
                        end else begin // No ACK received
                            ack_err_r <= 1;
                            state <= ERROR_STOP;
                        end
                    end
                end

                WRITE_DATA: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        if (bit_cnt < 7) begin
                            sda_r <= shift_reg[7];
                            scl_r <= 1; // SCL rises
                            shift_reg <= {shift_reg[6:0], 1'b0};
                        end else begin
                            sda_r <= shift_reg[7];
                            scl_r <= 1; // Last bit SCL rises
                            state <= WAIT_DATA_ACK;
                            sda_r <= 1; // Release SDA to read ACK
                        end
                        bit_cnt <= bit_cnt + 1;
                    end
                end

                WAIT_DATA_ACK: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        scl_r <= 0; // SCL falls
                        if (!sda_i) begin // Got ACK
                            state <= STOP;
                        end else begin // No ACK received
                            ack_err_r <= 1;
                            state <= ERROR_STOP;
                        end
                    end
                end

                READ_DATA: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        if (bit_cnt == 0) begin
                            scl_r <= 1; // SCL rises to get first bit
                        end else if (bit_cnt < 8) begin
                            rdata_r <= {rdata_r[6:0], sda_i}; // Sample on rising edge
                            scl_r <= 1; // SCL rises
                        end else begin
                            rdata_r <= {rdata_r[6:0], sda_i}; // Get last bit
                            scl_r <= 0; // SCL falls before NACK
                            state <= SEND_NACK;
                        end
                        bit_cnt <= bit_cnt + 1;
                    end
                end

                SEND_NACK: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        sda_r <= 1; // Send NACK (SDA high)
                        scl_r <= 1; // SCL rises
                        state <= STOP;
                    end
                end

                STOP: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        scl_r <= 0; // SCL falls
                        sda_r <= 0; // SDA low while SCL is low
                        state <= IDLE;
                        done_r <= 1;
                    end
                end

                ERROR_STOP: begin
                    if (clk_cnt < CLK_DIV - 1) begin
                        clk_cnt <= clk_cnt + 1;
                    end else begin
                        clk_cnt <= 0;
                        scl_r <= 0; // SCL falls
                        sda_r <= 0; // SDA low while SCL is low
                        state <= IDLE;
                        done_r <= 1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
