## 设计思路

1. **信号分类**：
   - 寄存器输出：busy, done, sclk, mosi, cs_n, rx_data
   - 输入：clk, rst_n, start, tx_data, miso

2. **状态机设计**：
   - 状态：IDLE(空闲), START(启动), TRANSMIT(传输中), DONE(完成)
   - 计数器：bit_cnt(3位，计数0-7)，sclk_cnt(用于时钟分频)

3. **计数器**：
   - sclk_cnt：0到CLK_DIV-1，用于生成sclk时序
   - bit_cnt：0到7，表示当前传输的位

4. **复位行为**：同步复位，所有输出清零或回到空闲状态
   - 时序要求：sclk空闲为0，CS拉高，数据在sclk上升沿采样，下降沿更新

```verilog
module spi_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output done,
    output sclk,
    output mosi,
    input miso,
    output cs_n
);

    reg [2:0] state;
    reg [2:0] next_state;

    // 状态定义
    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter TRANSMIT = 3'b010;
    parameter DONE = 3'b011;

    reg [2:0] bit_cnt;
    reg [3:0] sclk_cnt;  // 使用4位以支持较大的CLK_DIV
    reg [7:0] tx_reg;
    reg [7:0] rx_reg;
    reg busy_reg;
    reg done_reg;
    reg sclk_reg;
    reg mosi_reg;
    reg cs_n_reg;

    assign busy = busy_reg;
    assign done = done_reg;
    assign sclk = sclk_reg;
    assign mosi = mosi_reg;
    assign cs_n = cs_n_reg;
    assign rx_data = rx_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            sclk_reg <= 1'b0;
            cs_n_reg <= 1'b1;
            mosi_reg <= 1'b0;
            bit_cnt <= 3'b000;
            sclk_cnt <= 4'b0000;
