## 设计思路

**1. 信号分析**
- 输入：clk, rst_n, start(脉冲), rw, addr[6:0], wdata[7:0], sda_i
- 寄存器输出：busy, done, ack_err, scl_o, sda_o  
- 组合输出：rdata[7:0]
- 内部寄存器：状态机、位计数器、字节计数器、移位寄存器等

**2. 状态机设计**
- 状态：IDLE, START, ADDR, DATA_TX/RX, STOP, DONE, ERROR
- 计数器：4位分频计数器(0-CLK_DIV*4-1)，位计数器(0-7)

**3. 复位行为**
- 所有寄存器复位为初始状态，scl_o/sda_o释放(=1)

**4. 时序要求**
- SCL周期=4*CLK_DIV个时钟，通过分频计数器控制

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [2:0] state;
    reg [3:0] bit_cnt;
    reg [3:0] clk_cnt;
    reg [7:0] shift_reg;
    reg [8:0] temp_data;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_r;
    reg sda_r;

    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter ADDR = 3'b010;
    parameter DATA_TX = 3'b011;
    parameter DATA_RX = 3'b100;
    parameter STOP = 3'b101;
    parameter DONE = 3'b110;
    parameter ERROR = 3'b111;

    parameter PHASE0 = 2'b00;  // SCL low
    parameter PHASE1 = 2'b01;  // SCL rising
    parameter PHASE2 = 2'b10;  // SCL high
    parameter PHASE3 = 2'b11;  // SCL falling

    wire [3:0] clk_div_end = 4'd4 * CLK_DIV - 1'd1;
    wire clk_phase0 = (clk_cnt == 4'd0);
    wire clk_phase1 = (clk_cnt == CLK_DIV - 1'd1);
    wire clk_phase2 = (clk_cnt == 2'd2 * CLK_DIV - 1'd1);
    wire clk_phase3 = (clk_cnt == 3'd3 * CLK_DIV - 1'd1);

    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_r;
    assign sda_o = sda_r;
    assign rdata = rdata_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_cnt <= 4'h0;
            clk_cnt <= 4'h0;
            shift_reg <= 8'h0;
            temp_data <= 9'h0;
            rdata_r <= 8'h0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_r <= 1'b1;
            sda_r <= 1'b1;
        end else begin
            done_r <= 1'b0;

            if (clk_cnt < clk_div_end)
                clk_cnt <= clk_cnt + 1'b1;
            else
                clk_cnt <= 4'h0;

            case (state)
                IDLE: begin
                    busy_r <= 1'b0;
                    scl_r <= 1'b1;
                    sda_r <= 1'b1;
                    if (start) begin
                        busy_r <= 1'b1;
                        state <= START;
                        clk_cnt <= 4'h0;
                        bit_cnt <= 4'h0;
                        temp_data <= {addr, rw};
                        ack_err_r <= 1'b0;
                    end
                end

                START: begin
                    if (clk_cnt == clk_div_end) begin
                        case (bit_cnt)
                            4'd0: begin  // Start condition
                                sda_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                            4'd1: begin  // Send address
                                state <= ADDR;
                                bit_cnt <= 4'h0;
                                shift_reg <= temp_data[8:1];
                                sda_r <= shift_reg[7];
                            end
                        endcase
                    end
                end

                ADDR: begin
                    if (clk_cnt == clk_div_end) begin
                        if (bit_cnt < 4'd7) begin  // Send 7 address bits
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Rising edge - setup data
                                sda_r <= shift_reg[6];
                                shift_reg <= {shift_reg[6:0], 1'b0};
                            end else begin  // Falling edge - clock in
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                        end else if (bit_cnt == 4'd7) begin  // Send R/W bit
                            scl_r <= ~scl_r;
                            if (scl_r) begin
                                sda_r <= shift_reg[6];
                            end else begin
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                        end else if (bit_cnt == 4'd8) begin  // Receive ACK
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Setup for ACK
                                sda_r <= 1'bz;  // Release SDA for ACK
                            end else begin  // Check ACK
                                if (sda_i) begin  // No ACK received
                                    state <= ERROR;
                                    ack_err_r <= 1'b1;
                                end else begin  // ACK received
                                    bit_cnt <= 4'h0;
                                    if (rw) begin  // Read transaction
                                        state <= DATA_RX;
                                        shift_reg <= 8'h0;
                                    end else begin  // Write transaction
                                        state <= DATA_TX;
                                        shift_reg <= wdata;
                                    end
                                end
                            end
                        end
                    end
                end

                DATA_TX: begin
                    if (clk_cnt == clk_div_end) begin
                        if (bit_cnt < 4'd8) begin  // Send data byte
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Rising edge - setup data
                                sda_r <= shift_reg[7];
                                shift_reg <= {shift_reg[6:0], 1'b0};
                            end else begin  // Falling edge - clock out
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                        end else if (bit_cnt == 4'd8) begin  // Receive ACK
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Setup for ACK
                                sda_r <= 1'bz;  // Release SDA for ACK
                            end else begin  // Check ACK
                                if (sda_i) begin  // No ACK
                                    state <= ERROR;
                                    ack_err_r <= 1'b1;
                                end else begin  // ACK received
                                    state <= STOP;
                                    bit_cnt <= 4'h0;
                                end
                            end
                        end
                    end
                end

                DATA_RX: begin
                    if (clk_cnt == clk_div_end) begin
                        if (bit_cnt < 4'd8) begin  // Receive data byte
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Rising edge - sample data
                                shift_reg <= {shift_reg[6:0], sda_i};
                                sda_r <= 1'b1;  // Prepare to send NACK
                            end else begin  // Falling edge - clock in
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                        end else if (bit_cnt == 4'd8) begin  // Send NACK
                            scl_r <= ~scl_r;
                            if (scl_r) begin  // Send NACK
                                sda_r <= 1'b1;
                            end else begin  // Store received data
                                rdata_r <= shift_reg;
                                state <= STOP;
                                bit_cnt <= 4'h0;
                            end
                        end
                    end
                end

                STOP: begin
                    if (clk_cnt == clk_div_end) begin
                        case (bit_cnt)
                            4'd0: begin  // Keep SDA low
                                sda_r <= 1'b0;
                                scl_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                            4'd1: begin  // Release SCL
                                scl_r <= 1'b1;
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                            4'd2: begin  // Release SDA (stop condition)
                                sda_r <= 1'b1;
                                state <= DONE;
                            end
                        endcase
                    end
                end

                ERROR: begin
                    if (clk_cnt == clk_div_end) begin
                        case (bit_cnt)
                            4'd0: begin
                                sda_r <= 1'b0;
                                scl_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                            4'd1: begin
                                scl_r <= 1'b1;
                                bit_cnt <= bit_cnt + 1'b1;
                            end
                            4'd2: begin
                                sda_r <= 1'b1;
                                state <= DONE;
                            end
                        endcase
                    end
                end

                DONE: begin
                    done_r <= 1'b1;
                    state <= IDLE;
                end

            endcase
        end
    end

endmodule
