    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] next_state;
    reg [3:0] clk_cnt;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] rdata_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg scl_reg;
    reg sda_reg;

    // 状态定义
    parameter IDLE = 4'b0000,
              START = 4'b0001,
              ADDR = 4'b0010,
              ADDR_ACK = 4'b0011,
              DATA_TX = 4'b0100,
              DATA_RX = 4'b0101,
              DATA_ACK = 4'b0110,
              DATA_NACK = 4'b0111,
              STOP = 4'b1000,
              ERROR = 4'b1001;

    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_reg;
    assign sda_o = sda_reg;
    assign rdata = rdata_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            clk_cnt <= 0;
            bit_cnt <= 0;
            shift_reg <= 0;
            rdata_reg <= 0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_reg <= 1'b1;
            sda_reg <= 1'b1;
        end else begin
            done_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                        busy_reg <= 1'b1;
                        clk_cnt <= 0;
                        ack_err_reg <= 1'b0;
                        sda_reg <= 1'b0; // Start condition
                    end
                end

                START: begin
                    if (clk_cnt == CLK_DIV * 2 - 1) begin
                        state <= ADDR;
                        clk_cnt <= 0;
                        bit_cnt <= 0;
                        shift_reg <= {addr, rw};
                    end else begin
                        clk_cnt <= clk_cnt + 1;
                        scl_reg <= (clk_cnt >= CLK_DIV && clk_cnt < CLK_DIV * 2) ? 1'b0 : 1'b1;
                        if (clk_cnt == 0) sda_reg <= 1'b1; // Prepare for address
                    end
                end

                ADDR: begin
                    if (clk_cnt == CLK_DIV - 1) begin
                        sda_reg <= shift_reg[7];
                    end else if (clk_cnt == CLK_DIV * 2 - 1) begin
                        scl_reg <= 1'b1;
                    end else if (clk_cnt == CLK_DIV * 3 - 1) begin
                        sda_reg <= 1'bZ; // Release SDA for ACK
                    end else if (clk_cnt == CLK_DIV * 4 - 1) begin
                        scl_reg <= 1'b0;
                        if (bit_cnt == 7) begin
                            state <= ADDR_ACK;
                            bit_cnt <= 0;
                        end else begin
                            bit_cnt <= bit_cnt + 1;
                            shift_reg <= {shift_reg[6:0], 1'b0};
                        end
                        clk_cnt <= 0;
                    end else begin
                        clk_cnt <= clk_cnt + 1;
                        if (clk_cnt >= CLK_DIV && clk_cnt < CLK_DIV * 2) scl_reg <= 1'b0;
                        else if (clk_cnt >= CLK_DIV * 2 && clk_cnt < CLK_DIV * 3) scl_reg <= 1'b1;
                    end
                end

                ADDR_ACK: begin
                    if (clk_cnt == CLK_DIV - 1) begin
                        // Sample ACK
                    end else if (clk_cnt == CLK_DIV * 2 - 1) begin
                        scl_reg <= 1'b1;
                    end else if (clk_cnt == CLK_DIV * 3 - 1) begin
                        if (sda_i) begin // No ACK received
                            state <= ERROR;
                            ack_err_reg <= 1'b1;
                        end else begin
                            if (rw) state <= DATA_RX;
                            else begin
                                state <= DATA_TX;
                                shift_reg <= wdata;
                            end
                        end
                    end else if (clk_cnt == CLK_DIV * 4 - 1) begin
                        scl_reg <= 1'b0;
                        clk_cnt <= 0;
                        bit_cnt <= 0;
                    end else begin
                        clk_cnt <= clk_cnt + 1;
                        if (clk_cnt >= CLK_DIV && clk_cnt < CLK_DIV * 2) scl_reg <= 1'b0;
                        else if (clk_cnt >= CLK_DIV * 2 && clk_cnt < CLK_DIV * 3) scl_reg <= 1'b1;
                    end
                end

                DATA_TX: begin
                    if (clk_cnt == CLK_DIV - 1) begin
                        sda_reg <= shift_reg[7];
                    end else if (clk_cnt == CLK_DIV * 2 - 1) begin
                        scl_reg <= 1'b1;
                    end else if (clk_cnt == CLK_DIV * 3 - 1) begin
                        sda_reg <= 1'bZ; // Release SDA for ACK
                    end else if (clk_cnt == CLK_DIV * 4 - 1) begin
                        scl_reg <= 1'b0;
                        if (bit_cnt == 7) begin
                            state <= DATA_ACK;
                            bit_cnt <= 0;
                        end else begin
