## 设计思路

**1. 信号分析**
- 输入：clk(1), rst_n(1), start(1), rw(1), addr(7), wdata(8), sda_i(1)
- 输出：rdata(8,寄存器), busy(1,寄存器), done(1,组合), ack_err(1,寄存器), scl_o(1,寄存器), sda_o(1,寄存器)

**2. 状态机设计**
- 状态：IDLE, START, ADDR, ADDR_ACK, DATA_TX/RX, DATA_ACK/NACK, STOP, ERROR
- 计数器：4位，计数0-15，用于SCL时序控制（4*CLK_DIV周期）

**3. 复位行为**
- 所有寄存器复位为0，scl_o/sda_o复位为1（释放总线）

**4. 时序要求**
- SCL周期=4*CLK_DIV个时钟，通过计数器分频实现

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] cnt;
    reg [7:0] shift_reg;
    reg [2:0] bit_cnt;
    reg busy_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;
    reg [7:0] rdata_r;

    parameter IDLE = 4'b0000,
              START = 4'b0001,
              ADDR = 4'b0010,
              ADDR_ACK = 4'b0011,
              DATA_TX = 4'b0100,
              DATA_RX = 4'b0101,
              DATA_ACK = 4'b0110,
              DATA_NACK = 4'b0111,
              STOP = 4'b1000,
              ERROR = 4'b1001;

    assign busy = busy_r;
    assign done = (state == STOP && cnt == 4*CLK_DIV-1) ? 1'b1 : 1'b0;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;
    assign rdata = rdata_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            cnt <= 0;
            shift_reg <= 0;
            bit_cnt <= 0;
            busy_r <= 0;
            ack_err_r <= 0;
            scl_o_r <= 1;
            sda_o_r <= 1;
            rdata_r <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                        cnt <= 0;
                        busy_r <= 1;
                        ack_err_r <= 0;
                        scl_o_r <= 1;
                        sda_o_r <= 1;
                        shift_reg <= {addr, rw};
                        bit_cnt <= 0;
                    end
                end

                START: begin
                    cnt <= cnt + 1;
                    if (cnt < CLK_DIV) begin
                        sda_o_r <= 0; // Start condition: SDA falls while SCL high
                    end else if (cnt < 2*CLK_DIV) begin
                        scl_o_r <= 0;
                        sda_o_r <= 0;
                    end else if (cnt < 3*CLK_DIV) begin
                        scl_o_r <= 1;
                    end else begin
                        state <= ADDR;
                        cnt <= 0;
                        scl_o_r <= 1;
                    end
                end

                ADDR: begin
                    cnt <= cnt + 1;
                    if (cnt < CLK_DIV) begin
                        sda_o_r <= shift_reg[7]; // Setup data
