                        sda_r <= 1; // Send NACK
                    end else if (clk_cnt < 2*CLK_DIV) begin
                        scl_r <= 0;
                    end else if (clk_cnt < 3*CLK_DIV) begin
                        scl_r <= 1;
                        clk_cnt <= 0;
                        state <= STOP;
