## 设计思路

**1. 信号分析**
- 输入：clk, rst_n, start(脉冲), rw, addr[6:0], wdata[7:0], sda_i
- 寄存器输出：rdata[7:0], busy, done, ack_err, scl_o, sda_o
- sda_i为外部输入，scl_o/sda_o为开漏输出

**2. 状态机设计**
- 状态：IDLE, START, ADDR, ADDR_ACK, DATA_TX/RX, DATA_ACK/NACK, STOP, ERROR
- 计数器：4*CLK_DIV周期的SCL时钟分频，需要log2(4*CLK_DIV)位

**3. 复位行为**
- 复位时SCL/SDA释放(=1)，busy/done/ack_err=0
- 时序要求通过状态机控制SCL高低电平各2*CLK_DIV周期实现

## 完整代码

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    parameter IDLE = 4'b0000,
              START = 4'b0001,
              ADDR = 4'b0010,
              ADDR_ACK = 4'b0011,
              DATA_TX = 4'b0100,
              DATA_RX = 4'b0101,
              DATA_ACK = 4'b0110,
              DATA_NACK = 4'b0111,
              STOP = 4'b1000,
              ERROR = 4'b1001;

    reg [9:0] counter; // max 4*CLK_DIV - 1
    reg [3:0] bit_cnt;
    reg [7:0] rx_data_reg;
    reg busy_reg, done_reg, ack_err_reg;
    reg scl_reg, sda_reg;

    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_reg;
    assign sda_o = sda_reg;
    assign rdata = rx_data_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            counter <= 0;
            bit_cnt <= 0;
            rx_data_reg <= 0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_reg <= 1'b1;
            sda_reg <= 1'b1;
        end else begin
            done_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                        busy_reg <= 1'b1;
                        counter <= 0;
                        ack_err_reg <= 1'b0;
                    end
                end

                START: begin
                    if (counter < 2*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        sda_reg <= 0; // SDA falls while SCL high
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        scl_reg <= 0; // SCL falls
                    end else begin
                        counter <= 0;
                        scl_reg <= 1'b1;
                        sda_reg <= 1'b1;
                        bit_cnt <= 0;
                        state <= ADDR;
                    end
                end

                ADDR: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        sda_reg <= addr[6-bit_cnt];
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        counter <= 0;
                        if (bit_cnt < 7) begin
                            bit_cnt <= bit_cnt + 1;
                        end else begin
                            bit_cnt <= 0;
                            sda_reg <= rw; // Write R/W bit
                            state <= ADDR_ACK;
                        end
                    end
                end

                ADDR_ACK: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        counter <= 0;
                        if (sda_i) begin // No ACK received
                            state <= STOP;
                            ack_err_reg <= 1'b1;
                        end else if (rw) begin
                            state <= DATA_RX;
                            rx_data_reg <= 0;
                        } else begin
                            state <= DATA_TX;
                            bit_cnt <= 0;
                        end
                    end
                end

                DATA_TX: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        sda_reg <= wdata[7-bit_cnt];
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        counter <= 0;
                        if (bit_cnt < 7) begin
                            bit_cnt <= bit_cnt + 1;
                        end else begin
                            bit_cnt <= 0;
                            state <= DATA_ACK;
                        end
                    end
                end

                DATA_RX: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        sda_reg <= 1; // Release SDA for reading
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        rx_data_reg <= {rx_data_reg[6:0], sda_i};
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        counter <= 0;
                        if (bit_cnt < 7) begin
                            bit_cnt <= bit_cnt + 1;
                        end else begin
                            state <= DATA_NACK;
                        end
                    end
                end

                DATA_ACK: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        sda_reg <= 0; // Send ACK
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        state <= STOP;
                    end
                end

                DATA_NACK: begin
                    if (counter < CLK_DIV - 1) begin
                        counter <= counter + 1;
                    end else if (counter < 2*CLK_DIV - 1) begin
                        scl_reg <= 0;
                        sda_reg <= 1; // Send NACK
                        counter <= counter + 1;
                    end else if (counter < 3*CLK_DIV - 1) begin
                        scl_reg <= 1;
                        counter <= counter + 1;
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        if (counter == 4*CLK_DIV - 2) begin
                            scl_reg <= 0;
                        end
                    end else begin
                        state <= STOP;
                    end
                end

                STOP: begin
                    if (counter < 2*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        sda_reg <= 0; // Keep SDA low
                    end else if (counter < 4*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        scl_reg <= 1; // SCL rises first
                    end else if (counter < 5*CLK_DIV - 1) begin
                        counter <= counter + 1;
                        sda_reg <= 1; // Then SDA rises
                    end else begin
                        state <= IDLE;
                        busy_reg <= 1'b0;
                        done_reg <= 1'b1;
                        scl_reg <= 1'b1;
                        sda_reg <= 1'b1;
                    end
                end

                default: begin
                    state <= IDLE;
                    busy_reg <= 1'b0;
                    scl_reg <= 1'b1;
                    sda_reg <= 1'b1;
                end
            endcase
