```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output reg [7:0] rdata,
    output reg busy,
    output reg done,
    output reg ack_err,
    output reg scl_o,
    output reg sda_o,
    input sda_i
);

    localparam [3:0] IDLE = 4'b0000;
    localparam [3:0] START = 4'b0001;
    localparam [3:0] ADDR = 4'b0010;
    localparam [3:0] ADDR_ACK = 4'b0011;
    localparam [3:0] DATA_TX = 4'b0100;
    localparam [3:0] DATA_RX = 4'b0101;
    localparam [3:0] DATA_ACK = 4'b0110;
    localparam [3:0] DATA_NACK = 4'b0111;
    localparam [3:0] STOP = 4'b1000;
    localparam [3:0] ERROR = 4'b1001;

    reg [3:0] state, next_state;
    reg [9:0] bit_cnt; // 7(addr)+1(rw)+8(data)+1(ack/nack)=17 bits max
    reg [7:0] tx_data, rx_data;
    reg [10:0] scl_cnt; // Counter for SCL timing (4*CLK_DIV)
    reg [1:0] phase; // 0: setup, 1: sample, 2: hold, 3: release
    reg start_flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            busy <= 1'b0;
            done <= 1'b0;
            ack_err <= 1'b0;
            scl_o <= 1'b1;
            sda_o <= 1'b1;
            rdata <= 8'h00;
            bit_cnt <= 10'h000;
            scl_cnt <= 11'h000;
            phase <= 2'h0;
            tx_data <= 8'h00;
            rx_data <= 8'h00;
            start_flag <= 1'b0;
        end else begin
            state <= next_state;

            case (next_state)
                IDLE: begin
                    busy <= 1'b0;
                    done <= 1'b0;
                    ack_err <= 1'b0;
                    scl_o <= 1'b1;
                    sda_o <= 1'b1;
                    bit_cnt <= 10'h000;
                    scl_cnt <= 11'h000;
                    phase <= 2'h0;
                    start_flag <= start;
                end

                START: begin
                    busy <= 1'b1;
                    if (phase == 2'h0) begin // Setup phase - SDA goes low while SCL high
                        sda_o <= 1'b0;
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                ADDR: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase
                        // Output address bit
                        sda_o <= addr[6-bit_cnt[2:0]];
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                ADDR_ACK: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - sample ACK
                        sda_o <= 1'b1; // Release SDA for slave to drive
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                DATA_TX: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase
                        sda_o <= wdata[7-bit_cnt[2:0]];
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                DATA_RX: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - sample data bit
                        rx_data[7-bit_cnt[2:0]] <= sda_i;
                        sda_o <= 1'b1; // Release SDA for reading
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                DATA_ACK: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - send ACK
                        sda_o <= 1'b0;
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                DATA_NACK: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - send NACK
                        sda_o <= 1'b1;
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                STOP: begin
                    busy <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - SDA goes high while SCL high
                        sda_o <= 1'b1;
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end

                ERROR: begin
                    busy <= 1'b1;
                    ack_err <= 1'b1;
                    if (phase == 2'h1) begin // Sample phase - SDA goes high while SCL high
                        sda_o <= 1'b1;
                    end else if (phase == 2'h2) begin // Hold phase
                        scl_o <= 1'b0;
                    end else if (phase == 2'h3) begin // Release phase
                        scl_o <= 1'b1;
                    end
                end
            endcase

            // Update counter and phase
            if (scl_cnt < 4*CLK_DIV - 1) begin
                scl_cnt <= scl_cnt + 1;
            end else begin
                scl_cnt <= 0;
                if (phase < 2'h3) 
                    phase <= phase + 1;
                else 
                    phase <= 0;

                if (phase == 2'h3) begin // End of SCL cycle
                    if (state == ADDR || state == DATA_TX || state == DATA_RX) begin
                        if (bit_cnt < 7) 
                            bit_cnt <= bit_cnt + 1;
                    end
                end
            end

            // Handle done signal
            if (state != next_state && next_state == IDLE && state != IDLE) begin
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;

        case (state)
            IDLE: begin
                if (start && !busy)
                    next_state = START;
            end

            START: begin
                if (phase == 2'h3 && scl_cnt == 0) // Complete SCL cycle
                    next_state = ADDR;
            end

            ADDR: begin
                if (phase == 2'h3 && scl_cnt == 0 && bit_cnt == 7) // All 8 address bits sent
                    next_state = ADDR_ACK;
            end

            ADDR_ACK: begin
                if (phase == 2'h3 && scl_cnt == 0) begin // ACK sampled
                    if (sda_i == 1'b0) begin // Got ACK
                        if (rw == 1'b0) // Write
                            next_state = DATA_TX;
                        else // Read
                            next_state = DATA_RX;
                    end else // No ACK
                        next_state = ERROR;
                end
            end

            DATA_TX: begin
                if (phase == 2'h3 && scl_cnt == 0 && bit_cnt == 7) // All 8 data bits sent
                    next_state = DATA_ACK;
            end

            DATA_RX: begin
                if (phase == 2'h3 && scl_cnt == 0 && bit_cnt == 7) // All 8 data bits received
                    next_state = DATA_NACK;
            end

            DATA_ACK: begin
                if (phase == 2'h3 && scl_cnt == 0) begin // ACK sent
                    if (sda_i == 1'b0) // Got ACK from slave
                        next_state = STOP;
                    else // No ACK from slave
                        next_state = ERROR;
                end
            end

            DATA_NACK: begin
                if (phase == 2'h3 && scl_cnt == 0) begin // NACK sent
                    rdata <= rx_data;
                    next_state = STOP;
                end
            end

            STOP: begin
                if (phase == 2'h3 && scl_cnt == 0) // Stop condition completed
                    next_state = IDLE;
            end

            ERROR: begin
                if (phase == 2'h3 && scl_cnt == 0) // Stop condition after error
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule
