    reg [2:0] next_state;
    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;
    reg [7:0] rdata_reg;
    reg [3:0] bit_cnt;
    reg [CLK_DIV-1:0] clk_cnt;
    reg scl_o_reg;
    reg sda_o_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg [2:0] phase; // 0: SCL low, update SDA; 1: SCL high rising; 2: SCL high, sample SDA; 3: SCL high falling

    parameter IDLE = 3'b000;
    parameter START = 3'b001;
    parameter ADDR_TX = 3'b010;
    parameter ADDR_ACK = 3'b011;
    parameter DATA_TX = 3'b100;
    parameter DATA_RX = 3'b101;
    parameter DATA_ACK = 3'b110;
    parameter STOP = 3'b111;

    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;
    assign rdata = rdata_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            clk_cnt <= 0;
            phase <= 0;
            bit_cnt <= 0;
        end else begin
            done_reg <= 1'b0;

            if (state != IDLE && !rst_n) begin
                // On reset during transaction, release bus
                scl_o_reg <= 1'b1;
                sda_o_reg <= 1'b1;
                busy_reg <= 1'b0;
                state <= IDLE;
            end else begin
                case (phase)
                    2'b00: begin // SCL low, update SDA
                        clk_cnt <= clk_cnt + 1'b1;
                        if (clk_cnt == CLK_DIV - 1) begin
                            clk_cnt <= 0;
                            phase <= phase + 1'b1;
                            scl_o_reg <= 1'b1; // SCL goes high

