                            case (state)
                                IDLE: begin
                                    if (start && !busy_reg) begin
                                        busy_reg <= 1'b1;
                                        addr_reg <= addr;
                                        rw_reg <= rw;
                                        wdata_reg <= wdata;
                                        ack_err_reg <= 1'b0;
                                        state <= START;
                                        sda_o_reg <= 1'b0; // START condition
                                    end
                                end
                                START: begin
                                    sda_o_reg <= addr_reg[6]; // First bit of address
                                end
