                                    end else if (bit_cnt == 7) begin
                                        sda_o_reg <= wdata_reg[0]; // Last bit
                                    end
                                end
                                DATA_RX: begin
                                    sda_o_reg <= 1'b1; // Release for reading
                                end
                                DATA_ACK: begin
                                    sda_o_reg <= 1'b1; // Send NACK for read
                                end
                                STOP: begin
