                                        end else begin
                                            state <= DATA_TX;
                                            bit_cnt <= 0;
                                        end
                                    end
                                end
                                DATA_TX: begin
                                    if (bit_cnt < 7) begin
                                        bit_cnt <= bit_cnt + 1'b1;
                                        state <= DATA_TX;
                                    end else begin // Finished sending data byte
                                        state <= DATA_ACK;
                                        bit_cnt <= 0;
                                    end
                                end
                                DATA_RX: begin
                                    rdata_reg[7-bit_cnt] <= sda_i;
                                    if (bit_cnt < 7) begin
                                        bit_cnt <= bit_cnt + 1'b1;
                                    end else begin
                                        state <= DATA_ACK;
                                        bit_cnt <= 0;
                                    end
                                end
                                DATA_ACK: begin
                                    if (!rw_reg) begin // For write transactions, check ACK
                                        if (sda_i) begin // NACK received
                                            ack_err_reg <= 1'b1;
                                        end
                                    end
                                    state <= STOP;
                                end
                                default: begin
                                    // Other states don't require action in this phase
                                end
                            endcase
