    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] temp_rdata;
    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;
    reg sample_sda_next;
    reg [7:0] sample_sda_delayed;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div_cnt <= 8'h00;
            phase <= 2'b00;
            clk_div_max <= CLK_DIV - 1;

            state <= IDLE;
            bit_cnt <= 4'h0;
            shift_reg <= 8'h00;
            temp_rdata <= 8'h00;
            addr_reg <= 7'h00;
            rw_reg <= 1'b0;
