                case (phase)
                    2'b00: begin  // Phase 0: SCL low, update SDA
                        phase <= 2'b01;
                        case (state)
                            START: sda_o_r <= 1'b0;  // Start condition
                            ADDR_TX, WRITE_DATA: sda_o_r <= shift_reg[7];
