                                        bit_cnt <= 4'h0;
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        state <= ADDR_ACK;
                                    end else begin
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                    end
                                end

