                                                state <= WRITE_DATA;
                                                shift_reg <= wdata_reg;
                                                bit_cnt <= 4'h0;
                                            end else begin
                                                state <= READ_DATA;
                                                bit_cnt <= 4'h0;
                                                temp_rdata <= 8'h00;
                                            end
                                        end
                                    end
                                end

                                WRITE_DATA: begin
                                    if (bit_cnt == 4'd7) begin  // After sending 8 bits
                                        bit_cnt <= 4'h0;
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        state <= WRITE_ACK;
