    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;
    reg sample_sda_next;
    reg [7:0] sample_sda_delayed;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div_cnt <= 8'h00;
            phase <= 2'b00;
            clk_div_max <= CLK_DIV - 1;

            state <= IDLE;
            bit_cnt <= 4'h0;
