                        scl_o_r <= 1'b0;
                        sample_sda_next <= 1'b0;

                        if (state == STOP && bit_cnt == 4'd1) begin
                            // End of stop sequence
                            done_r <= 1'b1;
                            busy_r <= 1'b0;
                            scl_o_r <= 1'b1;
                            sda_o_r <= 1'b1;
                            state <= IDLE;
                            bit_cnt <= 4'h0;
                        end else if (state != IDLE) begin
                            bit_cnt <= bit_cnt + 1'b1;

                            case (state)
                                START: begin
                                    if (bit_cnt == 4'd0) begin
                                        bit_cnt <= 4'h0;
                                        if (rw_reg == 1'b0) begin
                                            state <= ADDR_TX;
                                            shift_reg <= {addr_reg, 1'b0};  // Address + write bit
                                        end else begin
                                            state <= ADDR_TX;
                                            shift_reg <= {addr_reg, 1'b1};  // Address + read bit
                                        end
                                    end
                                end

                                ADDR_TX: begin
                                    if (bit_cnt == 4'd7) begin  // After sending 8 bits
                                        bit_cnt <= 4'h0;
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        state <= ADDR_ACK;
                                    end else begin
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                    end
                                end

                                ADDR_ACK: begin
                                    if (bit_cnt == 4'd0) begin
                                        bit_cnt <= 4'h0;
                                        if (sda_i == 1'b1) begin  // NACK received
                                            ack_err_r <= 1'b1;
                                            if (rw_reg == 1'b0) begin
                                                state <= STOP;
                                                bit_cnt <= 4'h0;
                                            end else begin
                                                state <= STOP;
                                                bit_cnt <= 4'h0;
                                            end
                                        end else begin  // ACK received
                                            if (rw_reg == 1'b0) begin
                                                state <= WRITE_DATA;
                                                shift_reg <= wdata_reg;
                                                bit_cnt <= 4'h0;
                                            end else begin
                                                state <= READ_DATA;
                                                bit_cnt <= 4'h0;
                                                temp_rdata <= 8'h00;
                                            end
                                        end
                                    end
                                end

                                WRITE_DATA: begin
                                    if (bit_cnt == 4'd7) begin  // After sending 8 bits
                                        bit_cnt <= 4'h0;
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        state <= WRITE_ACK;
                                    end else begin
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                    end
                                end

