                            DATA_ACK: ; // Already handled in phase 3
                            DATA_RECV: ; // Handled in phase 3
                        endcase
                    end
                end
            end else begin
                // In idle state and reset not active
                clk_cnt <= 0;
                scl_phase <= 0;
                bit_cnt <= 0;
                scl_o_r <= 1'b1;
                sda_o_r <= 1'b1;
            end
        end
    end

    // Handle STOP condition: SCL low -> SDA low -> SCL high -> SDA high
    reg [1:0] stop_step;
    always @(posedge clk) begin
        if (!rst_n) begin
            stop_step <= 0;
        end else if (state == STOP_PHASE && scl_phase == 1) begin
            if (scl_o_r == 1'b0) begin
                sda_o_r <= 1'b0; // SDA low when SCL is low
            end else if (scl_o_r == 1'b1) begin
                sda_o_r <= 1'b1; // SDA high when SCL is high (complete STOP)
            end
        end else if (state != STOP_PHASE) begin
            stop_step <= 0;
        end
    end

