module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    // Internal signals
    reg [3:0] phase;  // 0: low/update, 1: high rise, 2: high/sample, 3: low fall
    reg [6:0] clk_count;  // Counter for clock division
    reg [4:0] bit_count;  // Bit counter (0-15 for addr+rw, 16-23 for data, etc.)
    reg [7:0] shift_reg;
    reg [7:0] rdata_reg;
    reg state_busy;
    reg done_pulse;
    reg ack_error;
    reg scl_out;
    reg sda_out;
    reg [2:0] fsm_state;  // 0: idle, 1: start, 2: send_addr, 3: check_addr_ack, 4: write_data/read_data, 5: check_data_ack/send_read_ack, 6: stop
    reg [2:0] next_fsm_state;
    reg [7:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;

    // Phase and clock management
    wire clk_div_end = (clk_count == (CLK_DIV - 1));

    always @(posedge clk) begin
        if (!rst_n) begin
            clk_count <= 7'b0;
            phase <= 4'd0;
        end else if (state_busy) begin
            if (clk_div_end) begin
                clk_count <= 7'b0;
                phase <= phase + 1;
            end else begin
                clk_count <= clk_count + 1;
            end
        end else begin
            clk_count <= 7'b0;
            phase <= 4'd0;
        end
    end

    // FSM state transitions
    always @(posedge clk) begin
        if (!rst_n) begin
            fsm_state <= 3'd0;
        end else if (state_busy) begin
            if (phase == 4'd3 && clk_div_end)  // End of SCL cycle
                fsm_state <= next_fsm_state;
        end else if (start && !busy) begin
            fsm_state <= 3'd1;  // Start state
        end
    end

    // Next state logic
    always @(*) begin
        case (fsm_state)
            3'd0: next_fsm_state = 3'd0;  // Idle
            3'd1: next_fsm_state = 3'd2;  // After start -> send address
            3'd2: 
                if (bit_count == 7)  // After sending 8 bits (addr + rw)
                    next_fsm_state = 3'd3;  // Check ACK
                else
                    next_fsm_state = 3'd2;  // Continue sending address/rw
            3'd3:  // After checking addr ACK
                if (rw_reg == 1'b0)  // Write
                    next_fsm_state = 3'd4;  // Send data
                else  // Read
                    next_fsm_state = 3'd5;  // Read data
            3'd4:  // Write data - after sending 8 data bits
                if (bit_count == 16)  // Data sent (bits 8-15)
                    next_fsm_state = 3'd5;  // Check data ACK
                else
                    next_fsm_state = 3'd4;  // Continue sending data
            3'd5:  // Read/write ACK handling
                if (rw_reg == 1'b0) begin  // Write transaction
                    if (bit_count == 17)  // After checking data ACK (bit 17 = 8+8+1)
                        next_fsm_state = 3'd6;  // Go to stop
                    else
                        next_fsm_state = 3'd5;  // Still checking data ACK
                end else begin  // Read transaction
                    if (bit_count == 24)  // After reading 8 data bits (bits 16-23)
                        next_fsm_state = 3'd6;  // Go to stop
                    else
                        next_fsm_state = 3'd5;  // Continue reading data
                end
            3'd6: next_fsm_state = 3'd0;  // After stop return to idle
            default: next_fsm_state = 3'd0;
        endcase

        // If there's an ACK error, go directly to stop
        if (ack_error && (fsm_state == 3'd3 || (fsm_state == 3'd5 && rw_reg == 1'b0 && bit_count == 17))) begin
            next_fsm_state = 3'd6;
        end
    end

    // Bit counter
    always @(posedge clk) begin
        if (!rst_n) begin
            bit_count <= 5'd0;
        end else if (!state_busy) begin
            bit_count <= 5'd0;
        end else if (fsm_state != 3'd0 && phase == 4'd3 && clk_div_end) begin
            case (fsm_state)
                3'd2:  // Sending address/rw
                    if (bit_count < 7)
                        bit_count <= bit_count + 1;
                    else
                        bit_count <= bit_count + 1;  // For ACK sampling
                3'd4:  // Sending data
                    if (bit_count < 16)
                        bit_count <= bit_count + 1;
                    else
                        bit_count <= bit_count + 1;  // For ACK sampling
                3'd5:  // Reading data or sending ACK
                    if (rw_reg == 1'b1 && bit_count < 24)  // Reading: 16 to 23
                        bit_count <= bit_count + 1;
                    else if (rw_reg == 1'b0 && bit_count == 16)  // For data ACK
                        bit_count <= bit_count + 1;
                3'd3, 3'd6:  // ACK check or stop
                    bit_count <= bit_count + 1;
                default:
                    bit_count <= bit_count;
            endcase
        end else if (fsm_state == 3'd1 && phase == 4'd3 && clk_div_end) begin  // After start
            bit_count <= 5'd0;
        end
    end

    // Register inputs when start is accepted
    always @(posedge clk) begin
        if (!rst_n) begin
            addr_reg <= 7'b0;
            rw_reg <= 1'b0;
            wdata_reg <= 8'b0;
        end else if (start && !busy) begin
            addr_reg <= addr;
            rw_reg <= rw;
            wdata_reg <= wdata;
        end
    end

    // Shift register for sending/receiving
    always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg <= 8'b0;
        end else if (start && !busy) begin
            // Load address + rw bit
            shift_reg <= {addr_reg, rw_reg};
        end else if (fsm_state == 3'd4 && phase == 4'd0 && clk_div_end) begin  // Switch to data after addr ACK
            if (bit_count == 8)  // After sending address and checking ACK
                shift_reg <= wdata_reg;
        end else if ((fsm_state == 3'd2 || fsm_state == 3'd4) && phase == 4'd3 && clk_div_end) begin  // After sending bit
            shift_reg <= {shift_reg[6:0], 1'b0};  // Shift left
        end
    end

    // Read data collection
    reg [2:0] sample_bit_pos;
    always @(posedge clk) begin
        if (!rst_n) begin
            rdata_reg <= 8'b0;
            sample_bit_pos <= 3'b0;
        end else if (fsm_state == 3'd5 && rw_reg == 1'b1 && phase == 4'd2 && clk_div_end) begin  // During read sampling
            if (bit_count >= 16 && bit_count < 24) begin
                rdata_reg[23-bit_count] <= sda_i;
            end
        end else if (fsm_state != 3'd5 || rw_reg != 1'b1) begin
            sample_bit_pos <= 3'b0;
        end
    end

    // Busy signal
    always @(posedge clk) begin
        if (!rst_n) begin
            state_busy <= 1'b0;
        end else if (start && !state_busy) begin
            state_busy <= 1'b1;
        end else if (fsm_state == 3'd0) begin
            state_busy <= 1'b0;
        end
    end

    // ACK error detection
    reg last_sda_sample;
    always @(posedge clk) begin
        if (!rst_n) begin
            ack_error <= 1'b0;
            last_sda_sample <= 1'b1;
        end else if (start && !state_busy) begin
            ack_error <= 1'b0;
        end else if ((fsm_state == 3'd3 || (fsm_state == 3'd5 && rw_reg == 1'b0)) && 
                     phase == 4'd2 && clk_div_end) begin  // Sampling ACK
            if (sda_i == 1'b1)  // NACK detected
                ack_error <= 1'b1;
        end
    end

    // Done pulse
    always @(posedge clk) begin
        if (!rst_n) begin
            done_pulse <= 1'b0;
        end else if (fsm_state == 3'd6 && phase == 4'd3 && clk_div_end) begin  // At end of stop condition
            done_pulse <= 1'b1;
        end else begin
            done_pulse <= 1'b0;
        end
    end

    // SCL and SDA control
    always @(posedge clk) begin
        if (!rst_n) begin
            scl_out <= 1'b1;
            sda_out <= 1'b1;
        end else case (fsm_state)
            3'd0: begin  // Idle
                scl_out <= 1'b1;
                sda_out <= 1'b1;
            end
            3'd1: begin  // START
                case (phase)
                    4'd0: begin  // Prepare for start
                        scl_out <= 1'b1;
                        sda_out <= 1'b0;  // SDA goes low while SCL is high
                    end
                    4'd1: begin  // SCL still high, SDA already low
                        scl_out <= 1'b1;
                        sda_out <= 1'b0;
                    end
                    4'd2: begin  // SCL still high, SDA low
                        scl_out <= 1'b1;
                        sda_out <= 1'b0;
                    end
                    4'd3: begin  // Pull SCL low after start
                        scl_out <= 1'b0;
                        sda_out <= 1'b0;
                    end
                endcase
            end
            3'd2, 3'd4: begin  // Sending bits (address or data)
                case (phase)
                    4'd0: begin  // Set SDA
