    // Busy signal
    always @(posedge clk) begin
        if (!rst_n) begin
            state_busy <= 1'b0;
        end else if (start && !state_busy) begin
            state_busy <= 1'b1;
        end else if (fsm_state == 3'd0) begin
            state_busy <= 1'b0;
        end
    end

