                        scl_out <= 1'b1;
                        sda_out <= 1'b0;
                    end
                    4'd2: begin  // SCL still high, SDA low
                        scl_out <= 1'b1;
                        sda_out <= 1'b0;
                    end
                    4'd3: begin  // Pull SCL low after start
                        scl_out <= 1'b0;
                        sda_out <= 1'b0;
                    end
                endcase
            end
            3'd2, 3'd4: begin  // Sending bits (address or data)
                case (phase)
                    4'd0: begin  // Set SDA
