                                rdata_r[7-bit_cnt] <= sda_i;
                            end
                        end
                    endcase
                end

                4'd3: begin // SCL fall
                    scl_o_r <= 1'b0;

                    case ({state_idle, state_start, state_addr, state_ack1, state_write_data, state_read_data, state_ack2, state_stop})
