                                end else if (rw) begin
                                    state_read_data <= 1'b1;
                                end else begin
                                    state_ack1 <= 1'b1;
                                end
                            end
                        end

                        8'b00010000: begin // ack1 state
                            state_ack1 <= 1'b0;
                            if (ack_err_r) begin
