                        8'b00000100: begin // read data state
                            if (bit_cnt < 8) begin
                                bit_cnt <= bit_cnt + 1'b1;
                            end else begin
                                bit_cnt <= 0;
                                state_read_data <= 1'b0;
                                state_ack2 <= 1'b1;
                            end
                        end

                        8'b00000010: begin // ack2 state
                            state_ack2 <= 1'b0;
                            state_stop <= 1'b1;
