    // Internal signals
    reg [3:0] phase;          // Current phase (0-3)
    reg [6:0] clk_count;      // Clock counter for timing
    reg state_idle, state_start, state_addr, state_rw_data, state_read_sample, state_ack_wait, state_stop, state_done;
    reg [7:0] shift_reg;
    reg [2:0] bit_count;
    reg [7:0] rdata_r;
    reg busy_r, done_r, ack_err_r;
    reg scl_o_r, sda_o_r;
    reg [6:0] addr_r;
    reg rw_r;
    reg [7:0] wdata_r;
    reg in_transaction;
    reg [3:0] next_state;

    // Phase counter: 0=SCL low+update SDA, 1=SCL high, 2=SCL high+sample SDA, 3=SCL low
    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= 0;
            clk_count <= 0;
        end else if (in_transaction) begin
            if (clk_count == CLK_DIV - 1) begin
                clk_count <= 0;
                if (phase == 3) 
                    phase <= 0;
                else
                    phase <= phase + 1;
            end else
                clk_count <= clk_count + 1;
        end else begin
            phase <= 0;
            clk_count <= 0;
        end
    end

    // Main FSM
    parameter IDLE = 4'd0, START_COND = 4'd1, ADDR_PHASE = 4'd2, RW_DATA_PHASE = 4'd3;
    parameter READ_SAMPLE = 4'd4, ACK_WAIT = 4'd5, STOP_COND = 4'd6, DONE_STATE = 4'd7;

