            state_idle <= 1;
            state_start <= 0;
            state_addr <= 0;
            state_rw_data <= 0;
            state_read_sample <= 0;
            state_ack_wait <= 0;
            state_stop <= 0;
            state_done <= 0;
            in_transaction <= 0;
        end else begin
            case ({state_idle, state_start, state_addr, state_rw_data, state_read_sample, state_ack_wait, state_stop, state_done})
                8'b10000000: begin  // IDLE
                    if (start && !busy_r) begin
                        addr_r <= addr;
                        rw_r <= rw;
                        wdata_r <= wdata;
                        ack_err_r <= 0;
                        in_transaction <= 1;
                        state_idle <= 0;
                        state_start <= 1;
