                8'b00100000: begin  // ADDR_PHASE
                    if (phase == 3 && clk_count == CLK_DIV - 1) begin
                        if (bit_count < 7) begin
                            bit_count <= bit_count + 1;
                            shift_reg <= shift_reg << 1;
                        end else begin
                            bit_count <= 0;  // For ACK
                            state_addr <= 0;
                            state_ack_wait <= 1;  // Wait for ACK after address
                        end
                    end
                end
                8'b00010000: begin  // RW_DATA_PHASE (write)
