module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    // Internal signals
    reg [3:0] phase;          // Current phase (0-3)
    reg [6:0] clk_count;      // Clock counter within phase
    reg [3:0] bit_count;      // Bit counter for current byte
    reg [2:0] state;          // Main state machine
    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;
    reg [7:0] rdata_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg scl_o_reg;
    reg sda_o_reg;

    // State definitions
    parameter IDLE = 3'd0;
    parameter START_COND = 3'd1;
    parameter SEND_ADDR = 3'd2;
    parameter CHECK_ADDR_ACK = 3'd3;
    parameter WRITE_DATA = 3'd4;
    parameter CHECK_WRITE_ACK = 3'd5;
    parameter READ_DATA = 3'd6;
    parameter SEND_READ_NACK = 3'd7;
    parameter STOP_COND = 3'd8;

    // Phase counts for different operations
    parameter ADDR_BITS = 7'd8;   // Address + R/W bit
    parameter DATA_BITS = 7'd8;   // Data bits

    assign rdata = rdata_reg;
    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= 4'd0;
            clk_count <= 7'd0;
            bit_count <= 4'd0;
            state <= IDLE;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            addr_reg <= 7'd0;
            rw_reg <= 1'b0;
            wdata_reg <= 8'd0;
            rdata_reg <= 8'd0;
        end else begin
            done_reg <= 1'b0;  // Done is only high for one cycle

            if (clk_count < CLK_DIV - 1) begin
                clk_count <= clk_count + 1'b1;
            end else begin
                clk_count <= 7'd0;

                if (phase < 4'd3) begin
                    phase <= phase + 1'b1;
                end else begin
                    phase <= 4'd0;

                    case (state)
                        IDLE: begin
                            if (start && !busy_reg) begin
                                addr_reg <= addr;
                                rw_reg <= rw;
                                wdata_reg <= wdata;
                                ack_err_reg <= 1'b0;
                                busy_reg <= 1'b1;
                                state <= START_COND;
                                sda_o_reg <= 1'b0;  // Start condition: SDA goes low while SCL high
                            end
                        end

                        START_COND: begin
                            scl_o_reg <= 1'b0;  // Pull SCL low to prepare for data
                            bit_count <= 4'd0;
                            state <= SEND_ADDR;
                        end

                        SEND_ADDR: begin
                            if (bit_count < ADDR_BITS - 1) begin
                                // Continue sending address/RW bits
                                if (bit_count < 7'd7) 
                                    sda_o_reg <= addr_reg[6-bit_count];
                                else 
                                    sda_o_reg <= rw_reg;
                                bit_count <= bit_count + 1'b1;
                            end else begin
                                // Send last bit of address/RW
                                if (bit_count < 7'd7) 
                                    sda_o_reg <= addr_reg[6-bit_count];
                                else 
                                    sda_o_reg <= rw_reg;
                                bit_count <= bit_count + 1'b1;
                                state <= CHECK_ADDR_ACK;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
                        end

                        CHECK_ADDR_ACK: begin
                            // Sample ACK during phase 2 of the 9th clock cycle
                            if (sda_i == 1'b1) begin
                                ack_err_reg <= 1'b1;
                            end

                            if (rw_reg == 1'b0) begin  // Write transaction
                                bit_count <= 4'd0;
                                state <= WRITE_DATA;
                            end else begin  // Read transaction
                                bit_count <= 4'd0;
                                rdata_reg <= 8'd0;
                                state <= READ_DATA;
                                sda_o_reg <= 1'b1;  // Release SDA for reading
                            end
                        end

                        WRITE_DATA: begin
                            if (bit_count < DATA_BITS - 1) begin
                                sda_o_reg <= wdata_reg[7-bit_count];
                                bit_count <= bit_count + 1'b1;
                            end else begin
                                sda_o_reg <= wdata_reg[7-bit_count];
                                bit_count <= bit_count + 1'b1;
                                state <= CHECK_WRITE_ACK;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
                        end

                        CHECK_WRITE_ACK: begin
                            if (sda_i == 1'b1) begin
                                ack_err_reg <= 1'b1;
                            end
                            state <= STOP_COND;
                        end

                        READ_DATA: begin
                            // Sample data bit during phase 2
                            rdata_reg[7-bit_count] <= sda_i;

                            if (bit_count < DATA_BITS - 1) begin
                                bit_count <= bit_count + 1'b1;
                            end else begin
                                bit_count <= bit_count + 1'b1;
                                state <= SEND_READ_NACK;
                                sda_o_reg <= 1'b0;  // Send NACK after reading
                            end
                        end

                        SEND_READ_NACK: begin
                            state <= STOP_COND;
                        end

                        STOP_COND: begin
                            sda_o_reg <= 1'b0;  // Pull SDA low first
                            scl_o_reg <= 1'b1;  // Then release SCL
                            state <= IDLE;
                            busy_reg <= 1'b0;
                            done_reg <= 1'b1;
                            sda_o_reg <= 1'b1;  // Finally release SDA
                        end

                        default: begin
                            state <= IDLE;
                            busy_reg <= 1'b0;
                        end
                    endcase
                end

                // Handle SCL and SDA changes based on phase
                case (state)
                    START_COND: begin
                        if (phase == 4'd1) begin  // Phase 1: SCL high
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low
                            scl_o_reg <= 1'b0;
                        end
                    end

                    SEND_ADDR, WRITE_DATA: begin
                        if (phase == 4'd0) begin  // Phase 0: SCL low, update SDA
                            if (bit_count < 7'd8) begin  // Sending address or data
                                if (bit_count < 7'd7) 
                                    sda_o_reg <= addr_reg[6-bit_count];
                                else if (bit_count == 7'd7) 
                                    sda_o_reg <= rw_reg;
                            end else if (bit_count >= 7'd8 && bit_count < 7'd16) begin  // Writing data
                                sda_o_reg <= wdata_reg[15-bit_count];
                            end
                        end else if (phase == 4'd1) begin  // Phase 1: SCL high
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low
                            scl_o_reg <= 1'b0;
                        end
                    end

                    CHECK_ADDR_ACK, CHECK_WRITE_ACK: begin
                        if (phase == 4'd0) begin  // Phase 0: SCL low, release SDA
                            sda_o_reg <= 1'b1;  // Release SDA to let slave drive it
                        end else if (phase == 4'd1) begin  // Phase 1: SCL high
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd2) begin  // Phase 2: SCL high, sample SDA
                            if ((phase == 4'd2 && bit_count == 7'd8 && state == CHECK_ADDR_ACK) ||
                                (phase == 4'd2 && bit_count == 7'd16 && state == CHECK_WRITE_ACK)) begin
                                if (sda_i == 1'b1) begin
                                    ack_err_reg <= 1'b1;
                                end
                            end
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low
                            scl_o_reg <= 1'b0;
                        end
                    end

                    READ_DATA: begin
                        if (phase == 4'd0) begin  // Phase 0: SCL low
                            sda_o_reg <= 1'b1;  // Keep SDA released for reading
                        end else if (phase == 4'd1) begin  // Phase 1: SCL high
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd2) begin  // Phase 2: SCL high, sample SDA
                            rdata_reg[7-bit_count] <= sda_i;
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low
                            scl_o_reg <= 1'b0;
                        end
                    end

                    SEND_READ_NACK: begin
                        if (phase == 4'd0) begin  // Phase 0: SCL low, send NACK
                            sda_o_reg <= 1'b0;  // Send NACK
                        end else if (phase == 4'd1) begin  // Phase 1: SCL high
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low
                            scl_o_reg <= 1'b0;
                        end
                    end

                    STOP_COND: begin
                        if (phase == 4'd0) begin  // Phase 0: SCL low, SDA low
                            sda_o_reg <= 1'b0;
                        end else if (phase == 4'd1) begin  // Phase 1: SCL high, SDA still low
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd2) begin  // Phase 2: SCL high, release SDA for stop
                            sda_o_reg <= 1'b1;  // Stop condition: SDA goes high while SCL high
                        end else if (phase == 4'd3) begin  // Phase 3: SCL low, SDA high
                            scl_o_reg <= 1'b0;
                        end
                    end

                    default: begin
                        if (phase == 4'd1 || phase == 4'd2) begin
                            scl_o_reg <= 1'b1;
                        end else if (phase == 4'd3 || phase == 4'd0) begin
                            scl_o_reg <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    // Handle reset during transaction
    always @(posedge clk) begin
        if (!rst_n) begin
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            busy_reg <= 1'b0;
        end else if (!rst_n) begin  // This handles the reset condition
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            busy_reg <= 1'b0;
        end
    end

endmodule
