    parameter ADDR_PHASE = 4'd2;
    parameter ADDR_ACK = 4'd3;
    parameter WRITE_DATA = 4'd4;
    parameter WRITE_ACK = 4'd5;
    parameter READ_DATA = 4'd6;
    parameter SEND_NACK = 4'd7;
    parameter STOP_COND = 4'd8;

    // Phase definitions
    parameter PHASE_0 = 4'd0;  // SCL low, update SDA
    parameter PHASE_1 = 4'd1;  // SCL high
    parameter PHASE_2 = 4'd2;  // SCL high, sample SDA
    parameter PHASE_3 = 4'd3;  // SCL low

    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;
    assign rdata = rdata_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            phase <= PHASE_0;
            clk_count <= 0;
            bit_count <= 0;
            shift_reg <= 0;
            rdata_reg <= 0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
        end else begin
            done_reg <= 1'b0;  // Default to 0

            if (state == IDLE && start && !busy_reg) begin
                // Start new transaction
                busy_reg <= 1'b1;
                ack_err_reg <= 1'b0;
                state <= START_COND;
                phase <= PHASE_0;
                clk_count <= 0;
                bit_count <= 0;

                // Load address and R/W bit into shift register
                shift_reg <= {addr, rw};
                sda_o_reg <= 1'b1;  // Prepare for start condition
                scl_o_reg <= 1'b1;  // Ensure SCL is high initially
            end else if (clk_count < CLK_DIV - 1) begin
                // Continue counting within current phase
                clk_count <= clk_count + 1;
            end else begin
                // End of current phase, move to next phase
                clk_count <= 0;
                phase <= phase + 1;

                if (phase == PHASE_3) begin  // End of SCL cycle
                    phase <= PHASE_0;

                    case (state)
                        START_COND: begin
                            if (bit_count < 8) begin  // Still in address phase
                                state <= ADDR_PHASE;
                                bit_count <= 0;
                            end else if (rw == 1'b0) begin  // Write transaction
                                state <= WRITE_DATA;
                                bit_count <= 0;
                                shift_reg <= wdata;
                            end else begin  // Read transaction
                                state <= READ_DATA;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA for reading
                            end
                        end

                        ADDR_PHASE: begin
                            bit_count <= bit_count + 1;
                            if (bit_count == 7) begin  // Last address bit sent
                                state <= ADDR_ACK;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
