                                ack_err_reg <= 1'b1;
                                state <= STOP_COND;
                                bit_count <= 0;
                            end else if (rw == 1'b0) begin  // ACK received, write transaction
                                state <= WRITE_DATA;
                                bit_count <= 0;
                                shift_reg <= wdata;
                            end else begin  // ACK received, read transaction
                                state <= READ_DATA;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Keep SDA released for reading
                            end
                        end

                        WRITE_DATA: begin
                            bit_count <= bit_count + 1;
                            if (bit_count == 7) begin  // Last data bit sent
                                state <= WRITE_ACK;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
                        end

                        WRITE_ACK: begin
                            if (sda_i == 1'b1) begin  // NACK received
                                ack_err_reg <= 1'b1;
                            end
