                            state <= IDLE;
                            busy_reg <= 1'b0;
                            done_reg <= 1'b1;
                            scl_o_reg <= 1'b1;
                            sda_o_reg <= 1'b1;
                        end

                        default: begin
                            state <= IDLE;
                            busy_reg <= 1'b0;
                        end
