                                end
                                PHASE_1: begin  // SCL goes high
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_2: begin  // SCL high, sample SDA
                                    scl_o_reg <= 1'b1;
                                    // Sampling happens in the state transition logic above
                                end
                                PHASE_3: begin  // SCL goes low
                                    scl_o_reg <= 1'b0;
                                end
                            endcase
                        end

                        READ_DATA: begin
                            case (phase)
                                PHASE_0: begin  // SCL low, SDA released
                                    // SDA already released
                                end
                                PHASE_1: begin  // SCL goes high
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_2: begin  // SCL high, sample SDA
                                    scl_o_reg <= 1'b1;
                                    // Sampling handled in state transition
                                end
                                PHASE_3: begin  // SCL goes low
                                    scl_o_reg <= 1'b0;
                                end
                            endcase
                        end

                        SEND_NACK: begin
                            case (phase)
                                PHASE_0: begin  // SCL low, SDA high (NACK)
                                    sda_o_reg <= 1'b1;
                                end
                                PHASE_1: begin  // SCL goes high
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_2: begin  // SCL high, maintain
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_3: begin  // SCL goes low
                                    scl_o_reg <= 1'b0;
                                end
                            endcase
                        end

                        STOP_COND: begin
                            case (phase)
                                PHASE_0: begin  // SCL low, pull SDA low
                                    sda_o_reg <= 1'b0;
                                end
                                PHASE_1: begin  // SCL goes high
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_2: begin  // SCL high, keep SDA low briefly
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_3: begin  // SCL goes low, release SDA
                                    scl_o_reg <= 1'b0;
                                    sda_o_reg <= 1'b1;
