                clk_count <= 0;
                phase <= phase + 1;

                if (phase == PHASE_3) begin  // End of SCL cycle
                    phase <= PHASE_0;

                    case (state)
                        START_COND: begin
                            if (bit_count < 8) begin  // Still in address phase
                                state <= ADDR_PHASE;
                                bit_count <= 0;
                            end else if (rw == 1'b0) begin  // Write transaction
                                state <= WRITE_DATA;
                                bit_count <= 0;
                                shift_reg <= wdata;
                            end else begin  // Read transaction
                                state <= READ_DATA;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA for reading
                            end
                        end

                        ADDR_PHASE: begin
                            bit_count <= bit_count + 1;
                            if (bit_count == 7) begin  // Last address bit sent
                                state <= ADDR_ACK;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
                        end

                        ADDR_ACK: begin
                            if (sda_i == 1'b1) begin  // NACK received
                                ack_err_reg <= 1'b1;
                                state <= STOP_COND;
                                bit_count <= 0;
                            end else if (rw == 1'b0) begin  // ACK received, write transaction
                                state <= WRITE_DATA;
                                bit_count <= 0;
                                shift_reg <= wdata;
                            end else begin  // ACK received, read transaction
                                state <= READ_DATA;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Keep SDA released for reading
                            end
                        end

                        WRITE_DATA: begin
                            bit_count <= bit_count + 1;
                            if (bit_count == 7) begin  // Last data bit sent
                                state <= WRITE_ACK;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Release SDA to read ACK
                            end
                        end

                        WRITE_ACK: begin
                            if (sda_i == 1'b1) begin  // NACK received
                                ack_err_reg <= 1'b1;
                            end
                            state <= STOP_COND;
                            bit_count <= 0;
                        end

                        READ_DATA: begin
                            // Sample the bit
                            rdata_reg[7-bit_count] <= sda_i;
                            bit_count <= bit_count + 1;
                            if (bit_count == 7) begin  // Last data bit sampled
                                state <= SEND_NACK;
                                bit_count <= 0;
                                sda_o_reg <= 1'b1;  // Send NACK by keeping SDA high
                            end
