                                PHASE_2: begin  // Maintain SCL high
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_3: begin  // SCL goes low to prepare for data
                                    scl_o_reg <= 1'b0;
                                end
                            endcase
                        end

                        ADDR_PHASE, 
