                                end
                                PHASE_2: begin  // SCL high, maintain
                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_3: begin  // SCL goes low
                                    scl_o_reg <= 1'b0;
                                    if (bit_count < 7) begin
                                        shift_reg <= shift_reg << 1;  // Shift left for next bit
                                    end
                                end
                            endcase
                        end

