                                    scl_o_reg <= 1'b1;
                                end
                                PHASE_2: begin  // SCL high, sample SDA
                                    scl_o_reg <= 1'b1;
                                    // Sampling happens in the state transition logic above
                                end
                                PHASE_3: begin  // SCL goes low
                                    scl_o_reg <= 1'b0;
                                end
                            endcase
                        end

