                                PHASE_3: begin  // SCL goes low, release SDA
                                    scl_o_reg <= 1'b0;
                                    sda_o_reg <= 1'b1;
                                end
                            endcase
                        end

                        default: begin
                            scl_o_reg <= 1'b1;
                            sda_o_reg <= 1'b1;
