## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, start, rw, addr[6:0], wdata[7:0], sda_i
   - 寄存器输出：busy, done, ack_err, scl_o, sda_o, rdata[7:0]

2. **状态机设计**：
   - 状态：IDLE, START, TX_ADDR, RX_ADDR_ACK, TX_DATA/RX_DATA, RX_DATA_ACK/TX_NACK, STOP, DONE
   - 计数器：phase_cnt[3:0]控制4个相位(0-3)，bit_cnt[3:0]控制位传输(0-7)，byte_cnt[3:0]控制字节传输

3. **计数器**：
   - phase_cnt：4位，范围0-3对应SCL四相位
   - bit_cnt：4位，范围0-7表示8位数据传输
   - timer：多位，用于跟踪整个事务进度防止超时

4. **复位与时序**：同步复位使总线释放(scl_o=sda_o=1)，通过计数器确保SCL周期为4*CLK_DIV个时钟。

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [2:0] state;
    reg [3:0] phase_cnt;
    reg [3:0] bit_cnt;
    reg [3:0] byte_cnt; // 0=addr, 1=data
    reg [7:0] shift_reg;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;

    parameter IDLE = 3'd0,
              START = 3'd1,
              TX_ADDR = 3'd2,
              RX_ADDR_ACK = 3'd3,
              TX_DATA = 3'd4,
              RX_DATA = 3'd5,
              TX_NACK = 3'd6,
              STOP = 3'd7,
              DONE = 3'd8;

    wire [3:0] cnt_max = CLK_DIV - 1;
    reg [15:0] cnt;
    wire cnt_maxed = (cnt == cnt_max);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            phase_cnt <= 4'h0;
            bit_cnt <= 4'h0;
            byte_cnt <= 4'h0;
            shift_reg <= 8'h0;
            rdata_r <= 8'h0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_o_r <= 1'b1;
            sda_o_r <= 1'b1;
            cnt <= 16'h0;
        end else begin
            done_r <= 1'b0;

            if (cnt_maxed) begin
                cnt <= 16'h0;
                case (phase_cnt)
                    4'd0: begin // SCL low, update SDA
                        case (state)
                            IDLE: begin
                                if (start && !busy_r) begin
                                    busy_r <= 1'b1;
                                    ack_err_r <= 1'b0;
                                    state <= START;
                                    sda_o_r <= 1'b0; // Start condition
                                end
                            end
                            START: begin
                                scl_o_r <= 1'b0;
                                sda_o_r <= addr[6]; // First bit of address
                                shift_reg <= {addr[5:0], rw, 1'b0};
                                bit_cnt <= 4'd1;
                                state <= TX_ADDR;
                            end
                            TX_ADDR: begin
                                scl_o_r <= 1'b0;
                                if (bit_cnt < 4'd7) begin
                                    sda_o_r <= shift_reg[7];
                                    shift_reg <= {shift_reg[6:0], 1'b0};
                                    bit_cnt <= bit_cnt + 1'b1;
                                end else begin
                                    sda_o_r <= shift_reg[7];
                                    state <= RX_ADDR_ACK;
                                    bit_cnt <= 4'd0;
                                end
                            end
                            RX_ADDR_ACK: begin
                                scl_o_r <= 1'b0;
                                sda_o_r <= 1'b1; // Release SDA for ACK/NACK
                                if (sda_i) begin // NACK
                                    ack_err_r <= 1'b1;
                                    state <= STOP;
                                end else begin // ACK
                                    if (rw) begin
                                        state <= RX_DATA;
                                        bit_cnt <= 4'd0;
                                    end else begin
                                        state <= TX_DATA;
                                        shift_reg <= wdata;
                                        bit_cnt <= 4'd0;
                                    end
                                end
                            end
                            TX_DATA: begin
                                scl_o_r <= 1'b0;
                                if (bit_cnt < 4'd7) begin
                                    sda_o_r <= shift_reg[7];
                                    shift_reg <= {shift_reg[6:0], 1'b0};
                                    bit_cnt <= bit_cnt + 1'b1;
                                end else begin
                                    sda_o_r <= shift_reg[7];
                                    state <= TX_NACK;
                                    bit_cnt <= 4'd0;
                                end
                            end
                            RX_DATA: begin
                                scl_o_r <= 1'b0;
                                if (bit_cnt < 4'd7) begin
                                    bit_cnt <= bit_cnt + 1'b1;
                                end else begin
