## 设计思路

1. **信号分类**：输入信号包括控制信号(start/rw/addr/wdata/sda_i)和时钟复位，输出包括状态(busy/done/ack_err)和总线驱动(scl_o/sda_o)，其中rdata/done/ack_err/busy/scl_o/sda_o为寄存器输出。

2. **状态机设计**：采用FSM控制I2C事务流程，主要状态包括IDLE(空闲)、START(起始)、ADDR(发送地址+R/W)、ADDR_ACK(接收地址应答)、WRITE_DATA(写数据)、WRITE_ACK(写数据应答)、READ_DATA(读数据)、SEND_NACK(发送NACK)、STOP(停止)等。

3. **计数器设计**：使用clk_div_cnt计数器(位宽$bits(CLK_DIV-1))控制SCL时序，每个SCL周期分为4个相位(0-3)，每个相位CLK_DIV个时钟周期。

4. **复位处理**：同步复位时总线释放(scl_o=sda_o=1)，状态清零；时序要求通过相位计数器精确控制SCL高低电平时间。

## 完整代码

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] next_state;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] rdata_reg;
    reg ack_err_reg;
    reg busy_reg;
    reg done_reg;
    reg scl_o_reg;
    reg sda_o_reg;

    reg [2:0] clk_div_cnt;
    reg [3:0] scl_phase; // 0: low-update, 1: high-setup, 2: high-sample, 3: low-hold

    parameter IDLE = 4'd0,
              START = 4'd1,
              ADDR_SEND = 4'd2,
              ADDR_ACK = 4'd3,
              WRITE_DATA = 4'd4,
              WRITE_ACK = 4'd5,
              READ_SETUP = 4'd6,
              READ_DATA = 4'd7,
              SEND_NACK = 4'd8,
              STOP = 4'd9;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div_cnt <= 0;
            scl_phase <= 0;
        end else begin
            if (busy_reg && (state != IDLE)) begin
                if (clk_div_cnt == (CLK_DIV - 1)) begin
                    clk_div_cnt <= 0;
                    if (scl_phase == 3) 
                        scl_phase <= 0;
                    else
                        scl_phase <= scl_phase + 1;
                end else
                    clk_div_cnt <= clk_div_cnt + 1;
            end else begin
                clk_div_cnt <= 0;
                scl_phase <= 0;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (start && !busy_reg)
                    next_state = START;
                else
                    next_state = IDLE;
            end
            START: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = ADDR_SEND;
                else
                    next_state = START;
            end
            ADDR_SEND: begin
                if ((bit_cnt == 7) && (scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = ADDR_ACK;
                else
                    next_state = ADDR_SEND;
            end
            ADDR_ACK: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                    if (sda_i) // NACK from slave
                        next_state = STOP;
                    else begin // ACK received
                        if (rw)
                            next_state = READ_SETUP;
                        else
                            next_state = WRITE_DATA;
                    end
                end else
                    next_state = ADDR_ACK;
            end
            WRITE_DATA: begin
                if ((bit_cnt == 7) && (scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = WRITE_ACK;
                else
                    next_state = WRITE_DATA;
            end
            WRITE_ACK: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) 
                    next_state = STOP;
                else
                    next_state = WRITE_ACK;
            end
            READ_SETUP: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = READ_DATA;
                else
                    next_state = READ_SETUP;
            end
            READ_DATA: begin
                if ((bit_cnt == 7) && (scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = SEND_NACK;
                else
                    next_state = READ_DATA;
            end
            SEND_NACK: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = STOP;
                else
                    next_state = SEND_NACK;
            end
            STOP: begin
                if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                    next_state = IDLE;
                else
                    next_state = STOP;
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 0;
        end else begin
            case (next_state)
                IDLE: bit_cnt <= 0;
                START: bit_cnt <= 0;
                ADDR_SEND: begin
                    if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        if (bit_cnt < 7)
                            bit_cnt <= bit_cnt + 1;
                        else
                            bit_cnt <= 0;
                    end
                end
                ADDR_ACK: bit_cnt <= 0;
                WRITE_DATA: begin
                    if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        if (bit_cnt < 7)
                            bit_cnt <= bit_cnt + 1;
                        else
                            bit_cnt <= 0;
                    end
                end
                WRITE_ACK: bit_cnt <= 0;
                READ_SETUP: bit_cnt <= 0;
                READ_DATA: begin
                    if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        if (bit_cnt < 7)
                            bit_cnt <= bit_cnt + 1;
                        else
                            bit_cnt <= 0;
                    end
                end
                SEND_NACK: bit_cnt <= 0;
                STOP: bit_cnt <= 0;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 0;
        end else begin
            case (next_state)
                IDLE: begin
                    if (start && !busy_reg) begin
                        if (rw)
                            shift_reg <= {addr, 1'b1};
                        else
                            shift_reg <= {addr, 1'b0};
                    end
                end
                ADDR_SEND: begin
                    if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        if (bit_cnt < 7)
                            shift_reg <= {shift_reg[6:0], 1'b0};
                    end
                end
                WRITE_DATA: begin
                    if (state == IDLE) begin
                        shift_reg <= wdata;
                    end else if ((scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        if (bit_cnt < 7)
                            shift_reg <= {shift_reg[6:0], 1'b0};
                    end
                end
                READ_DATA: begin
                    if ((scl_phase == 2) && (clk_div_cnt == (CLK_DIV - 1))) begin
                        shift_reg <= {shift_reg[6:0], sda_i};
                    end
                end
                default: begin
                    if (state == IDLE)
                        shift_reg <= 0;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rdata_reg <= 0;
        end else begin
            if ((state == READ_DATA) && (scl_phase == 2) && (clk_div_cnt == (CLK_DIV - 1)) && (bit_cnt == 7))
                rdata_reg <= {shift_reg[6:0], sda_i};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ack_err_reg <= 0;
        end else begin
            if (state == IDLE && start && !busy_reg)
                ack_err_reg <= 0;
            else if ((state == ADDR_ACK || state == WRITE_ACK) && (scl_phase == 2) && (clk_div_cnt == (CLK_DIV - 1)) && sda_i)
                ack_err_reg <= 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy_reg <= 0;
        end else begin
            if (state == IDLE && start && !busy_reg)
                busy_reg <= 1;
            else if (state == IDLE && next_state == IDLE)
                busy_reg <= 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done_reg <= 0;
        end else begin
            if ((state == STOP) && (scl_phase == 3) && (clk_div_cnt == (CLK_DIV - 1)))
                done_reg <= 1;
            else
                done_reg <= 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            scl_o_reg <= 1;
        end else begin
            case (next_state)
                IDLE: scl_o_reg <= 1;
                START: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                ADDR_SEND: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                ADDR_ACK: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                WRITE_DATA: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                WRITE_ACK: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                READ_SETUP: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                READ_DATA: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                SEND_NACK: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
                STOP: begin
                    if (scl_phase == 0) scl_o_reg <= 0;
                    else if (scl_phase == 1) scl_o_reg <= 1;
                    else if (scl_phase == 2) scl_o_reg <= 1;
                    else scl_o_reg <= 0;
                end
            endcase
        end
    end

