## 设计思路

1. **信号分类**：
   - 输入：clk, rst_n, start, rw, addr[6:0], wdata[7:0], sda_i
   - 寄存器输出：busy, done, ack_err, scl_o, sda_o, rdata[7:0]

2. **状态机设计**：
   - 状态：IDLE, START, ADDR, ADDR_ACK, WRITE_DATA, WRITE_ACK, READ_DATA, READ_ACK, STOP, DONE
   - 计数器：phase_cnt[3:0]控制4个相位(0-3)，bit_cnt[3:0]控制位数(0-7)，byte_cnt[3:0]控制字节数

3. **计数器**：
   - phase_cnt：4位，范围0-3，控制SCL相位
   - bit_cnt：4位，范围0-7，控制数据位
   - timer：7位，用于超时检测

4. **复位行为**：同步复位，所有输出清零，总线释放(scl_o=sda_o=1)

## 代码实现

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    reg [3:0] next_state;
    reg [3:0] phase_cnt;
    reg [3:0] bit_cnt;
    reg [6:0] timer;
    reg [7:0] shift_reg;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;

    // 状态定义
    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter ADDR = 4'b0010;
    parameter ADDR_ACK = 4'b0011;
    parameter WRITE_DATA = 4'b0100;
    parameter WRITE_ACK = 4'b0101;
    parameter READ_DATA = 4'b0110;
    parameter READ_ACK = 4'b0111;
    parameter STOP = 4'b1000;
    parameter DONE = 4'b1001;

    assign rdata = rdata_r;
    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            phase_cnt <= 0;
            bit_cnt <= 0;
            timer <= 0;
            shift_reg <= 0;
            rdata_r <= 0;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_o_r <= 1'b1;
            sda_o_r <= 1'b1;
        end else begin
            done_r <= 1'b0;

            if (state == IDLE && start && !busy_r) begin
                busy_r <= 1'b1;
                ack_err_r <= 1'b0;
                state <= START;
                phase_cnt <= 0;
                bit_cnt <= 0;
                timer <= 0;
                if (rw)
                    shift_reg <= {addr, 1'b1};
                else
                    shift_reg <= {addr, 1'b0};
            end else if (timer >= 100 * CLK_DIV - 1) begin
                // 超时处理
                state <= IDLE;
                busy_r <= 1'b0;
                scl_o_r <= 1'b1;
                sda_o_r <= 1'b1;
            end else begin
                timer <= timer + 1;

                if (timer % CLK_DIV == 0) begin
                    case (phase_cnt)
                        4'd0: begin // Phase 0: SCL low, update SDA
                            scl_o_r <= 1'b0;
                            case (state)
                                START: sda_o_r <= 1'b0; // Start condition
                                ADDR, WRITE_DATA: sda_o_r <= shift_reg[7];
                                ADDR_ACK, WRITE_ACK: sda_o_r <= 1'b1; // Release for ACK
                                READ_DATA: sda_o_r <= 1'b1; // Release for reading
                                READ_ACK: sda_o_r <= 1'b1; // Send NACK
                                STOP: sda_o_r <= 1'b0; // Prepare for stop
                                default: sda_o_r <= 1'b1;
                            endcase
                        end
                        4'd1: begin // Phase 1: SCL rising edge
                            scl_o_r <= 1'b1;
                        end
                        4'd2: begin // Phase 2: SCL high, sample SDA
                            scl_o_r <= 1'b1;
                            case (state)
                                ADDR_ACK: begin
                                    if (sda_i) begin
                                        ack_err_r <= 1'b1;
                                        next_state <= STOP;
                                    end else begin
                                        if (rw)
                                            next_state <= READ_DATA;
                                        else
                                            next_state <= WRITE_DATA;
                                    end
                                end
                                WRITE_ACK: begin
                                    if (sda_i) begin
                                        ack_err_r <= 1'b1;
                                    end
                                    next_state <= STOP;
                                end
                                READ_DATA: begin
                                    shift_reg <= {shift_reg[6:0], sda_i};
                                    rdata_r[7-bit_cnt] <= sda_i;
                                end
                                default: ;
                            endcase
                        end
                        4'd3: begin // Phase 3: SCL falling edge
                            scl_o_r <= 1'b0;

                            if (state != IDLE) begin
                                phase_cnt <= 0;

                                case (state)
                                    START: next_state <= ADDR;
                                    ADDR: begin
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        bit_cnt <= bit_cnt + 1;
                                        if (bit_cnt == 7)
                                            next_state <= ADDR_ACK;
                                    end
                                    ADDR_ACK: next_state <= next_state;
                                    WRITE_DATA: begin
                                        shift_reg <= {shift_reg[6:0], 1'b0};
                                        bit_cnt <= bit_cnt + 1;
                                        if (bit_cnt == 7) begin
                                            next_state <= WRITE_ACK;
                                            bit_cnt <= 0;
                                        end
                                    end
                                    WRITE_ACK: next_state <= next_state;
                                    READ_DATA: begin
                                        bit_cnt <= bit_cnt + 1;
                                        if (bit_cnt == 7) begin
                                            next_state <= READ_ACK;
                                            bit_cnt <= 0;
                                        end
                                    end
                                    READ_ACK: next_state <= STOP;
                                    STOP: next_state <= DONE;
                                    DONE: begin
                                        next_state <= IDLE;
                                        busy_r <= 1'b0;
                                        done_r <= 1'b1;
                                        sda_o_r <= 1'b1; // Release SDA
                                    end
                                    default: next_state <= IDLE;
                                endcase

                                if (next_state != state) begin
                                    state <= next_state;
                                    if (next_state == ADDR || next_state == WRITE_DATA) begin
                                        if (next_state == WRITE_DATA)
                                            shift_reg <= wdata;
                                        bit_cnt <= 0;
                                    end
                                end
                            end
                        end
                    endcase
                end else begin
                    phase_cnt <= timer / CLK_DIV;
                end
            end

            if (state == STOP && phase_cnt == 2) begin
                sda_o_r <= 1'b1; // Stop condition: SDA goes high while SCL is high
            end
        end
    end

endmodule
