                                    state <= next_state;
                                    if (next_state == ADDR || next_state == WRITE_DATA) begin
                                        if (next_state == WRITE_DATA)
                                            shift_reg <= wdata;
                                        bit_cnt <= 0;
                                    end
                                end
                            end
                        end
                    endcase
                end else begin
                    phase_cnt <= timer / CLK_DIV;
                end
            end

            if (state == STOP && phase_cnt == 2) begin
                sda_o_r <= 1'b1; // Stop condition: SDA goes high while SCL is high
            end
        end
    end

