            phase_cnt <= 0;
            bit_cnt <= 0;
            byte_cnt <= 0;
            clk_div_cnt <= 0;
            busy_r <= 0;
            done_r <= 0;
            ack_err_r <= 0;
            scl_o_r <= 1;
