                                scl_o_r <= 1;  // SCL high
                            end
                        endcase
                    end else if (phase_cnt == 2) begin  // Phase 2: Sample SDA when SCL is high
                        case (state)
                            ADDR_ACK: begin
                                // ACK already handled in next state transition
                            end
                            WRITE_ACK: begin
                                // ACK already handled in next state transition
                            end
                            READ_DATA: begin
