                            WRITE_ACK: begin
                                scl_o_r <= 0;
                            end
                            READ_DATA: begin
                                scl_o_r <= 0;
                            end
                            READ_ACK: begin
                                scl_o_r <= 0;
                            end
                        endcase
                    end
                end
            end
        end
    end

