## 设计思路

1. **信号分类**：输入信号包括控制信号(start/rw/addr/wdata)和反馈信号(sda_i)，输出信号中rdata/busy/done/ack_err/scl_o/sda_o为寄存器输出，其他为组合逻辑。

2. **状态机设计**：采用FSM控制I2C事务流程，主要状态包括IDLE(空闲)、START(起始)、ADDR(发送地址)、ADDR_ACK(接收地址应答)、DATA_TX/RX(数据收发)、DATA_ACK(数据应答)、STOP(停止)等。

3. **计数器设计**：使用phase_cnt计数器(2位)控制SCL四相位时序，使用bit_cnt计数器(4位)跟踪位传输进度，使用state_timer控制各状态持续时间。

4. **时序控制**：通过CLK_DIV参数控制SCL频率，确保每个SCL周期为4*CLK_DIV个时钟周期，数据在SCL低电平时设置，在SCL高电平时采样。

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    parameter IDLE = 4'd0, START = 4'd1, ADDR_TX = 4'd2, ADDR_ACK = 4'd3;
    parameter DATA_TX = 4'd4, DATA_ACK = 4'd5, DATA_RX = 4'd6, STOP = 4'd7;

    reg [1:0] phase_cnt;
    reg [3:0] bit_cnt;
    reg [6:0] addr_reg;
    reg rw_reg;
    reg [7:0] wdata_reg;
    reg [7:0] rdata_reg;
    reg busy_reg;
    reg done_reg;
    reg ack_err_reg;
    reg scl_o_reg;
    reg sda_o_reg;

    assign rdata = rdata_reg;
    assign busy = busy_reg;
    assign done = done_reg;
    assign ack_err = ack_err_reg;
    assign scl_o = scl_o_reg;
    assign sda_o = sda_o_reg;

    reg [31:0] timer;
    wire timer_limit = (timer == CLK_DIV - 1);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            phase_cnt <= 2'b00;
            bit_cnt <= 4'h0;
            addr_reg <= 7'h0;
            rw_reg <= 1'b0;
            wdata_reg <= 8'h0;
            rdata_reg <= 8'h0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            ack_err_reg <= 1'b0;
            scl_o_reg <= 1'b1;
            sda_o_reg <= 1'b1;
            timer <= 32'h0;
        end else begin
            if (timer_limit) begin
                timer <= 32'h0;
                case (phase_cnt)
                    2'b00: begin // SCL low, update SDA
                        case (state)
                            IDLE: begin
                                if (start && !busy_reg) begin
                                    busy_reg <= 1'b1;
                                    done_reg <= 1'b0;
                                    ack_err_reg <= 1'b0;
                                    addr_reg <= addr;
                                    rw_reg <= rw;
                                    wdata_reg <= wdata;
                                    sda_o_reg <= 1'b0; // START condition
                                    scl_o_reg <= 1'b0;
                                    bit_cnt <= 4'h0;
                                    state <= START;
                                end else begin
                                    sda_o_reg <= 1'b1;
                                    scl_o_reg <= 1'b1;
                                end
                            end
                            START: begin
                                sda_o_reg <= addr_reg[6-bit_cnt];
                                scl_o_reg <= 1'b0;
                                state <= ADDR_TX;
                            end
                            ADDR_TX: begin
                                if (bit_cnt < 4'd7) begin
                                    sda_o_reg <= addr_reg[6-bit_cnt-1];
                                end else begin
                                    sda_o_reg <= rw_reg;
                                end
                                scl_o_reg <= 1'b0;
                            end
                            ADDR_ACK: begin
                                sda_o_reg <= 1'b1; // Release SDA to read ACK
                                scl_o_reg <= 1'b0;
                                if (sda_i) begin // NACK received
                                    ack_err_reg <= 1'b1;
                                    state <= STOP;
                                end else if (rw_reg) begin // Read transaction
                                    state <= DATA_RX;
                                    bit_cnt <= 4'h0;
                                end else begin // Write transaction
                                    state <= DATA_TX;
