              ADDR_ACK = 4'd3,
              DATA_TX = 4'd4,
              DATA_RX = 4'd5,
              DATA_ACK = 4'd6,
              DATA_TX_ACK = 4'd7,
              STOP_COND = 4'd8;

    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;
    assign rdata = rdata_r;

