            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_o_r <= 1'b1;
            sda_o_r <= 1'b1;
            bit_cnt <= 3'd0;
            state <= 4'd0;
            addr_reg <= 7'd0;
            wdata_reg <= 8'd0;
            rdata_r <= 8'd0;
            rw_r <= 1'b0;
        end else begin
            done_r <= 1'b0;

            if (phase == 2'b00 && (state == IDLE || state == START_COND || state == ADDR_TX || 
                                   state == ADDR_ACK || state == DATA_TX || state == DATA_RX || 
                                   state == DATA_ACK || state == DATA_TX_ACK || state == STOP_COND)) begin
                case (state)
