                            scl_o_r <= 1'b0;
                            sda_o_r <= 1'b0; // Prepare for stop
                            state <= STOP_COND;
                            bit_cnt <= 3'd0;
                        end else begin // ACK
                            scl_o_r <= 1'b0;
                            if (rw_r) begin // Read
                                sda_o_r <= 1'b1; // Release SDA for reading
                                state <= DATA_RX;
                                bit_cnt <= 3'd0;
                            end else begin // Write
                                sda_o_r <= wdata_reg[~bit_cnt];
                                state <= DATA_TX;
                                bit_cnt <= 3'd0;
                            end
