                            scl_o_r <= 1'b0;
                            sda_o_r <= 1'b1; // Release SDA for ACK
                            state <= DATA_TX_ACK;
                            bit_cnt <= 3'd0;
                        end else begin
                            bit_cnt <= bit_cnt + 1'b1;
                            sda_o_r <= wdata_reg[~bit_cnt];
                        end
