                        if (bit_cnt == 3'd7) begin
                            scl_o_r <= 1'b0;
                            sda_o_r <= 1'b1; // Send NACK to end read
                            state <= STOP_COND;
                            bit_cnt <= 3'd0;
                        end else begin
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                    end

                    DATA_TX_ACK: begin
                        if (sda_i) begin // NACK
                            ack_err_r <= 1'b1;
                        end
                        scl_o_r <= 1'b0;
                        sda_o_r <= 1'b0; // Prepare for stop
                        state <= STOP_COND;
                        bit_cnt <= 3'd0;
                    end

                    STOP_COND: begin
                        scl_o_r <= 1'b1;
                        sda_o_r <= 1'b1; // Stop condition
                        busy_r <= 1'b0;
                        done_r <= 1'b1;
                        state <= IDLE;
                    end
                endcase
            end else if (phase == 2'b01) begin
                scl_o_r <= 1'b1; // SCL rising edge
