                end
            end else if (phase == 2'b11) begin
                scl_o_r <= 1'b0; // SCL falling edge
            end

            // Phase counter
            if (phase == 2'b11) 
                phase <= 2'b00;
            else
                phase <= phase + 1'b1;

            // Reset on idle
