## 设计思路

1. **信号分类**：输入信号包括控制信号(start/rw/addr/wdata)和反馈信号(sda_i)，输出信号中rdata/busy/done/ack_err/scl_o/sda_o为寄存器输出，其他为组合逻辑。

2. **状态机设计**：采用FSM控制I2C协议流程，主要状态包括IDLE(空闲)、START(起始)、ADDR(发送地址)、ADDR_ACK(接收地址应答)、DATA_TX/RX(数据收发)、DATA_ACK(数据应答)、STOP(停止)等。

3. **计数器设计**：使用phase_cnt计数器(2位)控制SCL四相位时序，使用bit_cnt计数器(4位)跟踪位传输进度，使用state_timer控制状态转换时序。

4. **时序控制**：通过CLK_DIV参数控制SCL频率，确保每个SCL周期为4*CLK_DIV个时钟周期，数据在SCL低电平时改变，高电平时采样。

```verilog
module i2c_master #(parameter CLK_DIV = 4) (
    input clk,
    input rst_n,
    input start,
    input rw,
    input [6:0] addr,
    input [7:0] wdata,
    output [7:0] rdata,
    output busy,
    output done,
    output ack_err,
    output scl_o,
    output sda_o,
    input sda_i
);

    reg [3:0] state;
    parameter IDLE = 4'b0000,
              START = 4'b0001,
              ADDR_SEND = 4'b0010,
              ADDR_ACK = 4'b0011,
              DATA_WRITE = 4'b0100,
              DATA_WRITE_ACK = 4'b0101,
              DATA_READ = 4'b0110,
              DATA_READ_ACK = 4'b0111,
              STOP = 4'b1000;

    reg [1:0] phase_cnt;
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg [7:0] rdata_r;
    reg busy_r;
    reg done_r;
    reg ack_err_r;
    reg scl_o_r;
    reg sda_o_r;

    wire [3:0] next_state;
    reg [3:0] state_r;
    reg [7:0] addr_data; // addr + rw bit

    assign rdata = rdata_r;
    assign busy = busy_r;
    assign done = done_r;
    assign ack_err = ack_err_r;
    assign scl_o = scl_o_r;
    assign sda_o = sda_o_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_r <= IDLE;
            phase_cnt <= 2'b00;
            bit_cnt <= 4'b0000;
            shift_reg <= 8'b00000000;
            rdata_r <= 8'b00000000;
            busy_r <= 1'b0;
            done_r <= 1'b0;
            ack_err_r <= 1'b0;
            scl_o_r <= 1'b1;
            sda_o_r <= 1'b1;
            addr_data <= 8'b00000000;
        end else begin
            done_r <= 1'b0; // pulse

            if (state_r == IDLE && start && !busy_r) begin
                busy_r <= 1'b1;
                ack_err_r <= 1'b0;
                addr_data <= {addr, rw};
                state_r <= START;
                phase_cnt <= 2'b00;
                bit_cnt <= 4'b0000;
                scl_o_r <= 1'b1;
                sda_o_r <= 1'b1;
            end else if (busy_r) begin
                if (phase_cnt < 2'b11)
                    phase_cnt <= phase_cnt + 1'b1;
                else begin
                    phase_cnt <= 2'b00;

                    case (state_r)
                        START: begin
                            if (phase_cnt == 2'b11) begin
                                sda_o_r <= 1'b0; // START condition
                                state_r <= ADDR_SEND;
                                bit_cnt <= 4'b0000;
                                shift_reg <= addr_data;
                            end
                        end

                        ADDR_SEND: begin
                            if (phase_cnt == 2'b00) begin // update SDA in phase 0
                                sda_o_r <= shift_reg[7];
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin // pull SCL high
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin // sample SDA in phase 2
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin // pull SCL low
                                scl_o_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;
                                shift_reg <= {shift_reg[6:0], 1'b0};

                                if (bit_cnt == 4'b0111) // sent 8 bits
                                    state_r <= ADDR_ACK;
                            end
                        end

                        ADDR_ACK: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= 1'b1; // release SDA for ACK
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin // sample ACK
                                if (sda_i) // NACK
                                    ack_err_r <= 1'b1;
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b0;
                                if (rw) 
                                    state_r <= DATA_READ;
                                else 
                                    state_r <= DATA_WRITE;
                                bit_cnt <= 4'b0000;
                                shift_reg <= wdata;
                            end
                        end

                        DATA_WRITE: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= shift_reg[7];
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;
                                shift_reg <= {shift_reg[6:0], 1'b0};

                                if (bit_cnt == 4'b0111) // sent 8 bits
                                    state_r <= DATA_WRITE_ACK;
                            end
                        end

                        DATA_WRITE_ACK: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= 1'b1; // release SDA for ACK
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin // sample ACK
                                if (sda_i) // NACK
                                    ack_err_r <= 1'b1;
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b0;
                                state_r <= STOP;
                            end
                        end

                        DATA_READ: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= 1'b1; // release SDA for reading
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin // sample data
                                shift_reg <= {shift_reg[6:0], sda_i};
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b0;
                                bit_cnt <= bit_cnt + 1'b1;

                                if (bit_cnt == 4'b0111) // received 8 bits
                                    state_r <= DATA_READ_ACK;
                            end
                        end

                        DATA_READ_ACK: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= 1'b1; // send NACK to stop
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b10) begin
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b0;
                                rdata_r <= shift_reg; // store read data
                                state_r <= STOP;
                            end
                        end

                        STOP: begin
                            if (phase_cnt == 2'b00) begin
                                sda_o_r <= 1'b0; // SDA low while SCL is low
                                scl_o_r <= 1'b0;
                            end else if (phase_cnt == 2'b01) begin
                                scl_o_r <= 1'b1; // SCL high
                            end else if (phase_cnt == 2'b10) begin
                                sda_o_r <= 1'b1; // SDA high while SCL is high - STOP
                                scl_o_r <= 1'b1;
                            end else if (phase_cnt == 2'b11) begin
                                scl_o_r <= 1'b1;
                                sda_o_r <= 1'b1; // keep bus released
                                busy_r <= 1'b0;
                                done_r <= 1'b1;
                                state_r <= IDLE;
                            end
                        end

                        default: begin
                            state_r <= IDLE;
                            busy_r <= 1'b0;
                            scl_o_r <= 1'b1;
                            sda_o_r <= 1'b1;
                        end
                    endcase
                end
            end else begin
                // Not busy - reset counters and outputs
                phase_cnt <= 2'b00;
                bit_cnt <= 4'b0000;
                scl_o_r <= 1'b1;
                sda_o_r <= 1'b1;
            end
        end
    end

endmodule
