```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // Register file
    reg [31:0] regfile [0:31];
    wire [4:0] rs1, rs2, rd;
    wire [2:0] funct3;
    wire [6:0] opcode;
    wire [6:0] funct7;

    assign rs1 = instr[19:15];
    assign rs2 = instr[24:20];
    assign rd = instr[11:7];
    assign funct3 = instr[14:12];
    assign opcode = instr[6:0];
    assign funct7 = instr[31:25];

    // ALU control signals
    wire is_r_type, is_i_type;
    wire [3:0] alu_op;
    reg [31:0] operand_a, operand_b;
    reg [31:0] alu_out;

    assign is_r_type = (opcode == 7'b0110011) & valid;
    assign is_i_type = (opcode == 7'b0010011) & valid;

    // Immediate generation for I-type
    wire [31:0] imm_i;
    assign imm_i = {{20{instr[31]}}, instr[31:20]};

    // ALU operation selection
    always @(*) begin
        case ({is_r_type, is_i_type})
            2'b10: begin // R-type
                case ({funct7, funct3})
                    {7'b0000000, 3'b000}: alu_op = 4'b0000; // ADD
                    {7'b0100000, 3'b000}: alu_op = 4'b0001; // SUB
                    {7'b0000000, 3'b001}: alu_op = 4'b0010; // SLL
                    {7'b0000000, 3'b010}: alu_op = 4'b0011; // SLT
                    {7'b0000000, 3'b011}: alu_op = 4'b0100; // SLTU
                    {7'b0000000, 3'b100}: alu_op = 4'b0101; // XOR
                    {7'b0000000, 3'b101}: alu_op = 4'b0110; // SRL
                    {7'b0100000, 3'b101}: alu_op = 4'b0111; // SRA
                    {7'b0000000, 3'b110}: alu_op = 4'b1000; // OR
                    {7'b0000000, 3'b111}: alu_op = 4'b1001; // AND
                    default: alu_op = 4'bx;
                endcase
            end
            2'b01: begin // I-type arithmetic
                case (funct3)
                    3'b000: alu_op = 4'b0000; // ADDI
                    3'b010: alu_op = 4'b0011; // SLTI
                    3'b011: alu_op = 4'b0100; // SLTIU
                    3'b100: alu_op = 4'b0101; // XORI
                    3'b110: alu_op = 4'b1000; // ORI
                    3'b111: alu_op = 4'b1001; // ANDI
                    3'b001: alu_op = 4'b0010; // SLLI
                    3'b101: 
                        if (funct7 == 7'b0000000) alu_op = 4'b0110; // SRLI
                        else if (funct7 == 7'b0100000) alu_op = 4'b0111; // SRAI
                        else alu_op = 4'bx;
                    default: alu_op = 4'bx;
                endcase
            end
            default: alu_op = 4'bx;
        endcase
    end

    // Check for illegal instructions
    reg illegal_r, illegal_i;
    always @(*) begin
        illegal_r = 1'b0;
        case ({funct7, funct3})
            {7'b0000000, 3'b000},
            {7'b0100000, 3'b000},
            {7'b0000000, 3'b001},
            {7'b0000000, 3'b010},
            {7'b0000000, 3'b011},
            {7'b0000000, 3'b100},
            {7'b0000000, 3'b101},
            {7'b0100000, 3'b101},
            {7'b0000000, 3'b110},
            {7'b0000000, 3'b111}: illegal_r = 1'b0;
            default: illegal_r = 1'b1;
        endcase

        illegal_i = 1'b0;
        case (funct3)
            3'b000, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111: illegal_i = 1'b0;
            3'b001: illegal_i = 1'b0;
            3'b101: 
                if ((funct7 != 7'b0000000) && (funct7 != 7'b0100000))
                    illegal_i = 1'b1;
                else
                    illegal_i = 1'b0;
            default: illegal_i = 1'b1;
        endcase
    end

    assign illegal = (is_r_type & illegal_r) | (is_i_type & illegal_i);

    // Operands
    always @(*) begin
        operand_a = regfile[rs1];

        if (is_r_type)
            operand_b = regfile[rs2];
        else if (is_i_type)
            operand_b = imm_i;
        else
            operand_b = 32'h0;
    end

    // ALU
    always @(*) begin
        case (alu_op)
            4'b0000: alu_out = operand_a + operand_b;          // ADD / ADDI
            4'b0001: alu_out = operand_a - operand_b;          // SUB
            4'b0010: alu_out = operand_a << operand_b[4:0];    // SLL / SLLI
            4'b0011: alu_out = $signed(operand_a) < $signed(operand_b) ? 32'h1 : 32'h0; // SLT / SLTI
            4'b0100: alu_out = operand_a < operand_b ? 32'h1 : 32'h0; // SLTU / SLTIU
            4'b0101: alu_out = operand_a ^ operand_b;          // XOR / XORI
            4'b0110: alu_out = operand_a >> operand_b[4:0];    // SRL / SRLI
            4'b0111: alu_out = $signed(operand_a) >>> operand_b[4:0]; // SRA / SRAI
            4'b1000: alu_out = operand_a | operand_b;          // OR / ORI
            4'b1001: alu_out = operand_a & operand_b;          // AND / ANDI
            default: alu_out = 32'hx;
        endcase
    end

    assign alu_result = alu_out;

    // Write register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
        end
        else if (valid && !illegal && (rd != 5'd0)) begin
            if (is_r_type || is_i_type) begin
                regfile[rd] <= alu_out;
            end
        end
    end

