    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // Register file
    reg [31:0] regfile [0:31];
    integer i;

    // Write register control
    reg [4:0] wr_addr;
    reg [31:0] wr_data;
    reg wr_en;

    // ALU inputs
    wire [31:0] rs1_data, rs2_data;
    wire [31:0] imm;
    wire [31:0] alu_op1, alu_op2;
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;

    // Instruction fields
    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // Immediate generation for I-type
    assign imm = {{20{instr[31]}}, instr[31:20]};

    // ALU operands
    assign alu_op1 = (opcode == 7'b0010011) ? rs1_data : rs1_data; // I-type or R-type
    assign alu_op2 = (opcode == 7'b0010011) ? imm : rs2_data;      // I-type uses immediate

    // Register read
    assign rs1_data = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
    assign rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];

    // Debug port
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regfile[dbg_addr];

    // ALU operation
    wire [3:0] alu_control;
    reg [31:0] alu_out;

    // Decode instruction to determine ALU control
    always @(*) begin
        case(opcode)
            7'b0110011: begin // R-type
                case({funct7, funct3})
                    {7'b0000000, 3'b000}: alu_control = 4'b0010; // ADD
                    {7'b0100000, 3'b000}: alu_control = 4'b0110; // SUB
                    {7'b0000000, 3'b001}: alu_control = 4'b0001; // SLL
                    {7'b0000000, 3'b010}: alu_control = 4'b0111; // SLT
                    {7'b0000000, 3'b011}: alu_control = 4'b1000; // SLTU
                    {7'b0000000, 3'b100}: alu_control = 4'b0011; // XOR
                    {7'b0000000, 3'b101}: alu_control = 4'b0100; // SRL
                    {7'b0100000, 3'b101}: alu_control = 4'b0101; // SRA
                    {7'b0000000, 3'b110}: alu_control = 4'b0010; // OR (reuse ADD for OR)
                    {7'b0000000, 3'b111}: alu_control = 4'b0000; // AND
                    default: alu_control = 4'bx;
                endcase
            end
            7'b0010011: begin // I-type arithmetic
                case(funct3)
                    3'b000: alu_control = 4'b0010; // ADDI -> ADD
                    3'b010: alu_control = 4'b0111; // SLTI -> SLT
                    3'b011: alu_control = 4'b1000; // SLTIU -> SLTU
                    3'b100: alu_control = 4'b0011; // XORI -> XOR
                    3'b110: alu_control = 4'b0010; // ORI -> OR
                    3'b111: alu_control = 4'b0000; // ANDI -> AND
                    3'b001: alu_control = 4'b0001; // SLLI -> SLL
                    3'b101: 
                        if(funct7 == 7'b0000000) alu_control = 4'b0100; // SRLI -> SRL
                        else if(funct7 == 7'b0100000) alu_control = 4'b0101; // SRAI -> SRA
                        else alu_control = 4'bx;
                    default: alu_control = 4'bx;
                endcase
            end
            default: alu_control = 4'bx;
        endcase
    end

    // ALU implementation
    always @(*) begin
        case(alu_control)
            4'b0000: alu_out = alu_op1 & alu_op2;   // AND
            4'b0001: alu_out = alu_op1 << alu_op2[4:0]; // SLL
            4'b0010: alu_out = alu_op1 + alu_op2;   // ADD
            4'b0011: alu_out = alu_op1 ^ alu_op2;   // XOR
            4'b0100: alu_out = alu_op1 >> alu_op2[4:0]; // SRL
            4'b0101: alu_out = $signed(alu_op1) >>> alu_op2[4:0]; // SRA
            4'b0110: alu_out = alu_op1 - alu_op2;   // SUB
            4'b0111: alu_out = ($signed(alu_op1) < $signed(alu_op2)) ? 32'h1 : 32'h0; // SLT
            4'b1000: alu_out = (alu_op1 < alu_op2) ? 32'h1 : 32'h0; // SLTU
            default: alu_out = 32'hx;
        endcase
    end

    // Determine if instruction is illegal
    reg illegal_reg;
    always @(*) begin
        illegal_reg = 1'b0;

        case(opcode)
            7'b0110011: begin // R-type
                case({funct7, funct3})
                    {7'b0000000, 3'b000}: ; // ADD
                    {7'b0100000, 3'b000}: ; // SUB
                    {7'b0000000, 3'b001}: ; // SLL
                    {7'b0000000, 3'b010}: ; // SLT
                    {7'b0000000, 3'b011}: ; // SLTU
                    {7'b0000000, 3'b100}: ; // XOR
                    {7'b0000000, 3'b101}: ; // SRL
                    {7'b0100000, 3'b101}: ; // SRA
                    {7'b0000000, 3'b110}: ; // OR
                    {7'b0000000, 3'b111}: ; // AND
                    default: illegal_reg = 1'b1;
                endcase
            end
            7'b0010011: begin // I-type arithmetic
                case(funct3)
                    3'b000: ; // ADDI
                    3'b010: ; // SLTI
                    3'b011: ; // SLTIU
                    3'b100: ; // XORI
                    3'b110: ; // ORI
                    3'b111: ; // ANDI
                    3'b001: ; // SLLI
                    3'b101: 
                        if(funct7 != 7'b0000000 && funct7 != 7'b0100000) illegal_reg = 1'b1;
                    default: illegal_reg = 1'b1;
                endcase
            end
            default: illegal_reg = 1'b1;
        endcase
    end

    assign illegal = illegal_reg;

    // Write enable and address
    assign wr_en = valid & ~illegal_reg & (rd_addr != 5'b0); // Don't write to x0
    assign wr_addr = rd_addr;
    assign wr_data = alu_out;

    // Register file write
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'b0;
            end
        end
        else if (wr_en) begin
            regfile[wr_addr] <= wr_data;
        end
    end

    // Output ALU result
    assign alu_result = alu_out;

