    parameter ALU_SLT = 4'b0011;
    parameter ALU_SLTU = 4'b0100;
    parameter ALU_XOR = 4'b0101;
    parameter ALU_SRL = 4'b0110;
    parameter ALU_SRA = 4'b0111;
    parameter ALU_OR = 4'b1000;
    parameter ALU_AND = 4'b1001;

