    assign alu_op = 
        // R-type instructions
        (opcode == 7'b0110011) ? 
            (funct3 == 3'b000) ? (funct7 == 7'b0100000) ? ALU_SUB : ALU_ADD :
            (funct3 == 3'b001) ? ALU_SLL :
            (funct3 == 3'b010) ? ALU_SLT :
            (funct3 == 3'b011) ? ALU_SLTU :
