            (funct3 == 3'b001) ? (funct7 != 7'b0000000) : // SLL only
            (funct3 == 3'b010) ? (funct7 != 7'b0000000) : // SLT only
            (funct3 == 3'b011) ? (funct7 != 7'b0000000) : // SLTU only
            (funct3 == 3'b100) ? (funct7 != 7'b0000000) : // XOR only
            (funct3 == 3'b101) ? (funct7 != 7'b0000000 && funct7 != 7'b0100000) : // SRL/SRA only
            (funct3 == 3'b110) ? (funct7 != 7'b0000000) : // OR only
            (funct3 == 3'b111) ? (funct7 != 7'b0000000) : // AND only
            1'b1 :
        (opcode == 7'b0010011) ?  // I-type arithmetic
            (funct3 == 3'b000) ? 0 : // ADDI
            (funct3 == 3'b010) ? 0 : // SLTI
            (funct3 == 3'b011) ? 0 : // SLTIU
            (funct3 == 3'b100) ? 0 : // XORI
            (funct3 == 3'b110) ? 0 : // ORI
            (funct3 == 3'b111) ? 0 : // ANDI
            (funct3 == 3'b001) ? (funct7 != 7'b0000000) : // SLLI only
            (funct3 == 3'b101) ? (funct7 != 7'b0000000 && funct7 != 7'b0100000) : // SRLI/SRAI only
            1'b1 :
        1'b1;

    // 寄存器堆写入控制
    wire reg_write_en = valid & ~illegal & (rd != 5'd0); // x0 is always zero

