            {7'b0110011, 3'b000, 7'b0100000}: alu_control_reg = 4'b0110; // SUB
            {7'b0110011, 3'b001, 7'b0000000}: alu_control_reg = 4'b0001; // SLL
            {7'b0110011, 3'b010, 7'b0000000}: alu_control_reg = 4'b0111; // SLT
            {7'b0110011, 3'b011, 7'b0000000}: alu_control_reg = 4'b1111; // SLTU
            {7'b0110011, 3'b100, 7'b0000000}: alu_control_reg = 4'b0000; // XOR
            {7'b0110011, 3'b101, 7'b0000000}: alu_control_reg = 4'b0101; // SRL
            {7'b0110011, 3'b101, 7'b0100000}: alu_control_reg = 4'b0110; // SRA
            {7'b0110011, 3'b110, 7'b0000000}: alu_control_reg = 4'b0100; // OR
            {7'b0110011, 3'b111, 7'b0000000}: alu_control_reg = 4'b0011; // AND
            {7'b0010011, 3'b000}: alu_control_reg = 4'b0010; // ADDI
            {7'b0010011, 3'b010}: alu_control_reg = 4'b0111; // SLTI
            {7'b0010011, 3'b011}: alu_control_reg = 4'b1111; // SLTIU
            {7'b0010011, 3'b100}: alu_control_reg = 4'b0000; // XORI
            {7'b0010011, 3'b110}: alu_control_reg = 4'b0100; // ORI
            {7'b0010011, 3'b111}: alu_control_reg = 4'b0011; // ANDI
            {7'b0010011, 3'b001}: alu_control_reg = 4'b0001; // SLLI
            {7'b0010011, 3'b101, 7'b0000000}: alu_control_reg = 4'b0101; // SRLI
            {7'b0010011, 3'b101, 7'b0100000}: alu_control_reg = 4'b0110; // SRAI
            default: alu_control_reg = 4'bx; // Invalid instruction
        endcase
    end

    // ALU implementation
    always @(*) begin
        case (alu_control_reg)
            4'b0000: alu_out = alu_op1 ^ alu_op2;   // XOR
            4'b0001: alu_out = alu_op1 << alu_op2[4:0]; // SLL
            4'b0010: alu_out = alu_op1 + alu_op2;   // ADD
            4'b0011: alu_out = alu_op1 & alu_op2;   // AND
            4'b0100: alu_out = alu_op1 | alu_op2;   // OR
            4'b0101: alu_out = alu_op1 >> alu_op2[4:0]; // SRL
            4'b0110: alu_out = $signed(alu_op1) - $signed(alu_op2); // SUB / SRA (shift arithmetic handled separately)
            4'b0111: alu_out = ($signed(alu_op1) < $signed(alu_op2)) ? 32'h1 : 32'h0; // SLT
            4'b1010: alu_out = (alu_op1 < alu_op2) ? 32'h1 : 32'h0; // SGEU (not used but placeholder)
            4'b1111: alu_out = (alu_op1 < alu_op2) ? 32'h1 : 32'h0; // SLTU
            default: alu_out = 32'hx;
        endcase

