        if (alu_control_reg == 4'b0110 && opcode == 7'b0110011 && funct3 == 3'b101 && funct7 == 7'b0100000) // SRA
            alu_out = $signed(alu_op1) >>> alu_op2[4:0];
        else if (alu_control_reg == 4'b0110 && opcode == 7'b0010011 && funct3 == 3'b101 && funct7 == 7'b0100000) // SRAI
            alu_out = $signed(alu_op1) >>> alu_op2[4:0];
    end

