                    {7'b0000000, 3'b111}: alu_op = 4'b1001; // AND
                    default: alu_op = 4'bx;
                endcase
            end
            2'b01: begin // I-type arithmetic
                case (funct3)
                    3'b000: alu_op = 4'b0000; // ADDI
                    3'b010: alu_op = 4'b0011; // SLTI
                    3'b011: alu_op = 4'b0100; // SLTIU
                    3'b100: alu_op = 4'b0101; // XORI
                    3'b110: alu_op = 4'b1000; // ORI
                    3'b111: alu_op = 4'b1001; // ANDI
                    3'b001: alu_op = 4'b0010; // SLLI
                    3'b101: 
                        if (funct7 == 7'b0000000) 
                            alu_op = 4'b0110; // SRLI
                        else if (funct7 == 7'b0100000)
                            alu_op = 4'b0111; // SRAI
                        else
                            alu_op = 4'bx;
                    default: alu_op = 4'bx;
                endcase
            end
            default: alu_op = 4'bx;
        endcase
    end

    // Check if instruction is legal
    wire legal_r_type = is_r_type & (
        ({funct7, funct3} == {7'b0000000, 3'b000}) |  // ADD
        ({funct7, funct3} == {7'b0100000, 3'b000}) |  // SUB
        ({funct7, funct3} == {7'b0000000, 3'b001}) |  // SLL
        ({funct7, funct3} == {7'b0000000, 3'b010}) |  // SLT
        ({funct7, funct3} == {7'b0000000, 3'b011}) |  // SLTU
        ({funct7, funct3} == {7'b0000000, 3'b100}) |  // XOR
        ({funct7, funct3} == {7'b0000000, 3'b101}) |  // SRL
        ({funct7, funct3} == {7'b0100000, 3'b101}) |  // SRA
        ({funct7, funct3} == {7'b0000000, 3'b110}) |  // OR
        ({funct7, funct3} == {7'b0000000, 3'b111})    // AND
    );

    wire legal_i_type = is_i_type & (
        (funct3 == 3'b000) |  // ADDI
        (funct3 == 3'b010) |  // SLTI
        (funct3 == 3'b011) |  // SLTIU
        (funct3 == 3'b100) |  // XORI
        (funct3 == 3'b110) |  // ORI
        (funct3 == 3'b111) |  // ANDI
        (funct3 == 3'b001) |  // SLLI
        ((funct3 == 3'b101) & ((funct7 == 7'b0000000) | (funct7 == 7'b0100000)))  // SRLI or SRAI
    );

    assign illegal = ~(legal_r_type | legal_i_type);

    // ALU implementation
    always @(*) begin
        case (alu_op)
            4'b0000: alu_out = operand_a + operand_b;      // ADD / ADDI
            4'b0001: alu_out = operand_a - operand_b;      // SUB
            4'b0010: alu_out = operand_a << operand_b[4:0]; // SLL / SLLI
            4'b0011: alu_out = {{31{1'b0}}, $signed(operand_a) < $signed(operand_b)}; // SLT / SLTI
            4'b0100: alu_out = {{31{1'b0}}, operand_a < operand_b}; // SLTU / SLTIU
            4'b0101: alu_out = operand_a ^ operand_b;      // XOR / XORI
            4'b0110: alu_out = operand_a >> operand_b[4:0]; // SRL / SRLI
            4'b0111: alu_out = $signed(operand_a) >>> operand_b[4:0]; // SRA / SRAI
            4'b1000: alu_out = operand_a | operand_b;      // OR / ORI
            4'b1001: alu_out = operand_a & operand_b;      // AND / ANDI
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    assign alu_result = alu_out;

    // Write register
    wire [4:0] write_reg = rd;
    wire [31:0] write_data = alu_out;
    wire write_enable = valid & ~illegal & (rd != 5'b00000); // Don't write to x0

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'b0;
            end
        end
        else if (write_enable) begin
            regfile[write_reg] <= write_data;
        end
    end

    // Debug output
    assign dbg_data = regfile[dbg_addr];

endmodule

