## 设计思路

1. **信号分析**：
   - 输入：clk(rst_n控制)、instr(32位指令)、valid(使能信号)
   - 输出：alu_result(32位ALU结果，寄存器输出)、illegal(非法指令标志，组合输出)、dbg_data(32位调试数据，组合输出)
   - 寄存器：alu_result(下一周期输出)
   - 组合输出：illegal、dbg_data

2. **核心组件**：
   - 32×32位寄存器堆(32个寄存器，每个32位)
   - 32位ALU(支持R型和I型指令操作)
   - 指令译码逻辑判断操作类型

3. **复位行为**：rst_n低电平时清零alu_result输出，寄存器堆x0恒为0，其他寄存器复位值不确定

4. **时序要求**：valid=1时执行指令，结果在下一周期通过alu_result输出

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regfile [0:31];
    integer i;

    // 信号定义
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1, rs2, rd;
    wire [11:0] imm_i;
    wire [31:0] operand1, operand2;
    wire [31:0] alu_op1, alu_op2;
    wire [4:0] shamt;
    wire [31:0] alu_out;
    reg [31:0] alu_result_reg;

    // 指令字段提取
    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1 = instr[19:15];
    assign rs2 = instr[24:20];
    assign rd = instr[11:7];
    assign imm_i = instr[31:20];

    // 立即数扩展
    assign alu_op2 = { {20{imm_i[11]}}, imm_i };

    // 操作数选择
    assign operand1 = regfile[rs1];
    assign operand2 = (opcode == 7'b0010011) ? alu_op2 : regfile[rs2]; // I型 vs R型

    // 移位量
    assign shamt = (opcode == 7'b0010011) ? imm_i[4:0] : rs2[4:0]; // I型移位 vs R型移位

    // ALU操作
    always @(*) begin
        case ({funct7, funct3, opcode})
            // R-type instructions
            {7'b0000000, 3'b000, 7'b0110011}: alu_out = operand1 + operand2;      // ADD
            {7'b0100000, 3'b000, 7'b0110011}: alu_out = operand1 - operand2;      // SUB
            {7'b0000000, 3'b001, 7'b0110011}: alu_out = operand1 << shamt;        // SLL
            {7'b0000000, 3'b010, 7'b0110011}: alu_out = ($signed(operand1) < $signed(operand2)) ? 32'h1 : 32'h0; // SLT
            {7'b0000000, 3'b011, 7'b0110011}: alu_out = (operand1 < operand2) ? 32'h1 : 32'h0;                 // SLTU
            {7'b0000000, 3'b100, 7'b0110011}: alu_out = operand1 ^ operand2;      // XOR
            {7'b0000000, 3'b101, 7'b0110011}: alu_out = operand1 >> shamt;        // SRL
            {7'b0100000, 3'b101, 7'b0110011}: alu_out = $signed(operand1) >>> shamt; // SRA
            {7'b0000000, 3'b110, 7'b0110011}: alu_out = operand1 | operand2;      // OR
            {7'b0000000, 3'b111, 7'b0110011}: alu_out = operand1 & operand2;      // AND
            // I-type arithmetic instructions
            {3'b000, 3'b000, 7'b0010011}: alu_out = operand1 + operand2;          // ADDI
            {3'b000, 3'b010, 7'b0010011}: alu_out = ($signed(operand1) < $signed(operand2)) ? 32'h1 : 32'h0; // SLTI
            {3'b000, 3'b011, 7'b0010011}: alu_out = (operand1 < operand2) ? 32'h1 : 32'h0;                 // SLTIU
            {3'b000, 3'b100, 7'b0010011}: alu_out = operand1 ^ operand2;          // XORI
            {3'b000, 3'b110, 7'b0010011}: alu_out = operand1 | operand2;          // ORI
            {3'b000, 3'b111, 7'b0010011}: alu_out = operand1 & operand2;          // ANDI
            {3'b000, 3'b001, 7'b0010011}: alu_out = operand1 << shamt;            // SLLI
            {3'b000, 3'b101, 7'b0010011}: alu_out = operand1 >> shamt;            // SRLI
            {3'b010, 3'b101, 7'b0010011}: alu_out = $signed(operand1) >>> shamt;  // SRAI
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    // 非法指令检测
    assign illegal = 
        ((opcode == 7'b0110011) && 
         !((funct7 == 7'b0000000 && funct3 inside {3'b000, 3'b001, 3'b010, 3'b011, 3'b100, 3'b101, 3'b110, 3'b111}) ||
           (funct7 == 7'b0100000 && funct3 inside {3'b000, 3'b101}))) ||
        ((opcode == 7'b0010011) && 
         !((funct3 inside {3'b000, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111}) ||
           (funct3 == 3'b001) ||
           (funct3 == 3'b101 && funct7 inside {7'b0000000, 7'b0100000})));

    // 寄存器堆初始化
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            regfile[i] = 32'h0;
        end
    end

    // 写寄存器操作
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'h0;  // x0 is always 0
            alu_result_reg <= 32'h0;
        end else begin
            alu_result_reg <= alu_out;

            if (valid && (opcode == 7'b0110011 || opcode == 7'b0010011) && !illegal && rd != 5'd0) begin
                regfile[rd] <= alu_out;
            end
        end
    end

    // 输出
    assign alu_result = alu_result_reg;
    assign dbg_data = regfile[dbg_addr];

endmodule
