            {7'b0000000, 3'b011, 7'b0110011}: alu_out = (operand1 < operand2) ? 32'h1 : 32'h0;                 // SLTU
            {7'b0000000, 3'b100, 7'b0110011}: alu_out = operand1 ^ operand2;      // XOR
            {7'b0000000, 3'b101, 7'b0110011}: alu_out = operand1 >> shamt;        // SRL
            {7'b0100000, 3'b101, 7'b0110011}: alu_out = $signed(operand1) >>> shamt; // SRA
            {7'b0000000, 3'b110, 7'b0110011}: alu_out = operand1 | operand2;      // OR
            {7'b0000000, 3'b111, 7'b0110011}: alu_out = operand1 & operand2;      // AND
            // I-type arithmetic instructions
            {3'b000, 3'b000, 7'b0010011}: alu_out = operand1 + operand2;          // ADDI
            {3'b000, 3'b010, 7'b0010011}: alu_out = ($signed(operand1) < $signed(operand2)) ? 32'h1 : 32'h0; // SLTI
            {3'b000, 3'b011, 7'b0010011}: alu_out = (operand1 < operand2) ? 32'h1 : 32'h0;                 // SLTIU
            {3'b000, 3'b100, 7'b0010011}: alu_out = operand1 ^ operand2;          // XORI
            {3'b000, 3'b110, 7'b0010011}: alu_out = operand1 | operand2;          // ORI
            {3'b000, 3'b111, 7'b0010011}: alu_out = operand1 & operand2;          // ANDI
            {3'b000, 3'b001, 7'b0010011}: alu_out = operand1 << shamt;            // SLLI
            {3'b000, 3'b101, 7'b0010011}: alu_out = operand1 >> shamt;            // SRLI
            {3'b010, 3'b101, 7'b0010011}: alu_out = $signed(operand1) >>> shamt;  // SRAI
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    // 非法指令检测
    assign illegal = 
        ((opcode == 7'b0110011) && 
         !((funct7 == 7'b0000000 && funct3 inside {3'b000, 3'b001, 3'b010, 3'b011, 3'b100, 3'b101, 3'b110, 3'b111}) ||
           (funct7 == 7'b0100000 && funct3 inside {3'b000, 3'b101}))) ||
        ((opcode == 7'b0010011) && 
         !((funct3 inside {3'b000, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111}) ||
           (funct3 == 3'b001) ||
           (funct3 == 3'b101 && funct7 inside {7'b0000000, 7'b0100000})));

    // 寄存器堆初始化
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            regfile[i] = 32'h0;
        end
    end

    // 写寄存器操作
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'h0;  // x0 is always 0
            alu_result_reg <= 32'h0;
        end else begin
            alu_result_reg <= alu_out;

            if (valid && (opcode == 7'b0110011 || opcode == 7'b0010011) && !illegal && rd != 5'd0) begin
                regfile[rd] <= alu_out;
            end
        end
    end

    // 输出
    assign alu_result = alu_result_reg;
    assign dbg_data = regfile[dbg_addr];

