## 设计思路

**1. 信号分析**
- 输入：clk(rst_n), instr[31:0], valid - 寄存器；dbg_addr[4:0] - 组合
- 输出：alu_result[31:0], illegal - 寄存器；dbg_data[31:0] - 组合

**2. 状态机**
- 无状态机，单周期执行

**3. 复位行为**
- 复位时alu_result=0, illegal=0
- 时序要求：valid=1时当前周期执行，结果下周期输出

**4. 实现方案**
- 32×32位寄存器堆，读取rs1/rs2，写入rd
- ALU支持R/I型指令操作
- 译码判断指令类型和非法指令

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regfile [0:31];
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;
    wire [31:0] rs1_data, rs2_data;
    wire [31:0] imm;
    wire [31:0] alu_src1, alu_src2;
    wire [4:0] shamt;
    wire [31:0] alu_out;

    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // 立即数生成
    assign imm = {{20{instr[31]}}, instr[31:20]}; // I-type immediate

    // 寄存器堆读取
    assign rs1_data = regfile[rs1_addr];
    assign rs2_data = regfile[rs2_addr];

    // ALU源选择
    assign alu_src1 = rs1_data;
    assign alu_src2 = (opcode == 7'b0010011) ? imm : rs2_data; // I-type uses immediate

    // ALU操作
    always @(*) begin
        case({funct7, funct3, opcode})
            // ADD
            {7'b0000000, 3'b000, 7'b0110011}: alu_out = alu_src1 + alu_src2;
            {7'b0000000, 3'b000, 7'b0010011}: alu_out = alu_src1 + alu_src2;
            // SUB
            {7'b0100000, 3'b000, 7'b0110011}: alu_out = alu_src1 - alu_src2;
            // SLL
            {7'b0000000, 3'b001, 7'b0110011}: alu_out = alu_src1 << alu_src2[4:0];
            {7'b0000000, 3'b001, 7'b0010011}: begin
                shamt = instr[24:20]; // SLLI uses shamt from instruction
                alu_out = alu_src1 << shamt;
            end
            // SLT
            {7'b0000000, 3'b010, 7'b0110011}: alu_out = ($signed(alu_src1) < $signed(alu_src2)) ? 32'h1 : 32'h0;
            {7'b0000000, 3'b010, 7'b0010011}: alu_out = ($signed(alu_src1) < $signed(alu_src2)) ? 32'h1 : 32'h0;
            // SLTU
            {7'b0000000, 3'b011, 7'b0110011}: alu_out = (alu_src1 < alu_src2) ? 32'h1 : 32'h0;
            {7'b0000000, 3'b011, 7'b0010011}: alu_out = (alu_src1 < alu_src2) ? 32'h1 : 32'h0;
            // XOR
            {7'b0000000, 3'b100, 7'b0110011}: alu_out = alu_src1 ^ alu_src2;
            {7'b0000000, 3'b100, 7'b0010011}: alu_out = alu_src1 ^ alu_src2;
            // SRL
            {7'b0000000, 3'b101, 7'b0110011}: alu_out = alu_src1 >> alu_src2[4:0];
            {7'b0000000, 3'b101, 7'b0010011}: begin
                shamt = instr[24:20]; // SRLI uses shamt from instruction
                alu_out = alu_src1 >> shamt;
            end
            // SRA
            {7'b0100000, 3'b101, 7'b0110011}: alu_out = $signed(alu_src1) >>> alu_src2[4:0];
            {7'b0100000, 3'b101, 7'b0010011}: begin
                shamt = instr[24:20]; // SRAI uses shamt from instruction
                alu_out = $signed(alu_src1) >>> shamt;
            end
            // OR
            {7'b0000000, 3'b110, 7'b0110011}: alu_out = alu_src1 | alu_src2;
            {7'b0000000, 3'b110, 7'b0010011}: alu_out = alu_src1 | alu_src2;
            // AND
            {7'b0000000, 3'b111, 7'b0110011}: alu_out = alu_src1 & alu_src2;
            {7'b0000000, 3'b111, 7'b0010011}: alu_out = alu_src1 & alu_src2;
            default: alu_out = 32'h0;
        endcase
    end

    // 非法指令检测
    wire is_r_type = (opcode == 7'b0110011);
    wire is_i_type = (opcode == 7'b0010011);
    wire is_valid_r_type = is_r_type & (
        (funct3 == 3'b000 & (funct7 == 7'b0000000 | funct7 == 7'b0100000)) | // ADD/SUB
        (funct3 == 3'b001 & funct7 == 7'b0000000) | // SLL
        (funct3 == 3'b010 & funct7 == 7'b0000000) | // SLT
        (funct3 == 3'b011 & funct7 == 7'b0000000) | // SLTU
        (funct3 == 3'b100 & funct7 == 7'b0000000) | // XOR
        (funct3 == 3'b101 & (funct7 == 7'b0000000 | funct7 == 7'b0100000)) | // SRL/SRA
        (funct3 == 3'b110 & funct7 == 7'b0000000) | // OR
        (funct3 == 3'b111 & funct7 == 7'b0000000)   // AND
    );
    wire is_valid_i_type = is_i_type & (
        (funct3 == 3'b000) | // ADDI
        (funct3 == 3'b010) | // SLTI
        (funct3 == 3'b011) | // SLTIU
        (funct3 == 3'b100) | // XORI
        (funct3 == 3'b110) | // ORI
        (funct3 == 3'b111) | // ANDI
        (funct3 == 3'b001 & funct7 == 7'b0000000) | // SLLI
        (funct3 == 3'b101 & (funct7 == 7'b0000000 | funct7 == 7'b0100000))   // SRLI/SRAI
    );

    assign illegal = valid & !(is_valid_r_type | is_valid_i_type);

    // 寄存器堆写入控制
    wire write_enable = valid & !illegal & (is_r_type | is_i_type) & (rd_addr != 5'b0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'h0;
            integer i;
            for (i = 1; i < 32; i = i + 1)
                regfile[i] <= 32'h0;
        end else if (write_enable) begin
            regfile[rd_addr] <= alu_out;
        end
    end

    // 输出寄存器
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            alu_result_reg <= 32'h0;
            illegal_reg <= 1'b0;
        end else begin
            if (valid) begin
                alu_result_reg <= alu_out;
                illegal_reg <= illegal;
            end
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

    // 调试输出
    assign dbg_data = regfile[dbg_addr];

endmodule
