module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆定义
    reg [31:0] regfile [0:31];
    integer i;

    // 内部信号
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;
    reg [31:0] rs1_data, rs2_data;
    reg [31:0] alu_op1, alu_op2;
    reg [3:0] alu_control;
    reg [31:0] alu_out;
    reg illegal_reg;

    // 指令字段提取
    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // 寄存器堆读取
    always @(*) begin
        rs1_data = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
        rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];
    end

    // ALU操作数选择
    always @(*) begin
        alu_op1 = rs1_data;
        if(opcode == 7'b0010011) begin  // I-type
            alu_op2 = $signed(instr[31:20]);
        end else begin  // R-type
            alu_op2 = rs2_data;
        end
    end

    // ALU控制逻辑
    always @(*) begin
        case(opcode)
            7'b0110011: begin  // R-type
                case(funct3)
                    3'b000: begin  // ADD/SUB
                        if(funct7[5]) alu_control = 4'b0110;  // SUB
                        else alu_control = 4'b0000;          // ADD
                    end
                    3'b001: alu_control = 4'b0001;  // SLL
                    3'b010: alu_control = 4'b0010;  // SLT
                    3'b011: alu_control = 4'b0011;  // SLTU
                    3'b100: alu_control = 4'b0100;  // XOR
                    3'b101: begin  // SRL/SRA
                        if(funct7[5]) alu_control = 4'b0111;  // SRA
                        else alu_control = 4'b0101;          // SRL
                    end
                    3'b110: alu_control = 4'b1000;  // OR
                    3'b111: alu_control = 4'b1001;  // AND
                    default: alu_control = 4'bxxxx;
                endcase
            end
            7'b0010011: begin  // I-type arithmetic
                case(funct3)
                    3'b000: alu_control = 4'b0000;  // ADDI
                    3'b010: alu_control = 4'b0010;  // SLTI
                    3'b011: alu_control = 4'b0011;  // SLTIU
                    3'b100: alu_control = 4'b0100;  // XORI
                    3'b110: alu_control = 4'b1000;  // ORI
                    3'b111: alu_control = 4'b1001;  // ANDI
                    3'b001: alu_control = 4'b0001;  // SLLI
                    3'b101: begin  // SRLI/SRAI
                        if(funct7[5]) alu_control = 4'b0111;  // SRAI
                        else alu_control = 4'b0101;          // SRLI
                    end
                    default: alu_control = 4'bxxxx;
                endcase
            end
            default: alu_control = 4'bxxxx;
        endcase
    end

    // 非法指令检测
    always @(*) begin
        illegal_reg = 1'b0;
        case(opcode)
            7'b0110011: begin  // R-type
                case(funct3)
                    3'b000: ;  // ADD/SUB
                    3'b001: ;  // SLL
                    3'b010: ;  // SLT
                    3'b011: ;  // SLTU
                    3'b100: ;  // XOR
                    3'b101: ;  // SRL/SRA
                    3'b110: ;  // OR
                    3'b111: ;  // AND
                    default: illegal_reg = 1'b1;
                endcase
            end
            7'b0010011: begin  // I-type arithmetic
                case(funct3)
                    3'b000: ;  // ADDI
                    3'b010: ;  // SLTI
                    3'b011: ;  // SLTIU
                    3'b100: ;  // XORI
                    3'b110: ;  // ORI
                    3'b111: ;  // ANDI
                    3'b001: ;  // SLLI
                    3'b101: ;  // SRLI/SRAI
                    default: illegal_reg = 1'b1;
                endcase
            end
            default: illegal_reg = 1'b1;
        endcase
    end

    // ALU实现
    always @(*) begin
        case(alu_control)
            4'b0000: alu_out = alu_op1 + alu_op2;           // ADD/ADDI
            4'b0001: alu_out = alu_op1 << alu_op2[4:0];     // SLL/SLLI
            4'b0010: alu_out = ($signed(alu_op1) < $signed(alu_op2)) ? 32'h1 : 32'h0;  // SLT/SLTI
            4'b0011: alu_out = (alu_op1 < alu_op2) ? 32'h1 : 32'h0;                   // SLTU/SLTIU
            4'b0100: alu_out = alu_op1 ^ alu_op2;           // XOR/XORI
            4'b0101: alu_out = alu_op1 >> alu_op2[4:0];     // SRL/SRLI
            4'b0110: alu_out = $signed(alu_op1) - alu_op2;  // SUB
