    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1, rs2, rd;
    wire [31:0] imm_i;
    wire [31:0] operand_a, operand_b;
    wire [31:0] alu_input_a, alu_input_b;
    wire [4:0] shamt;
    wire [31:0] alu_out;
    wire illegal_comb;
    wire write_enable;

    // 指令字段提取
    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1 = instr[19:15];
    assign rs2 = instr[24:20];
    assign rd = instr[11:7];
    assign imm_i = { {20{instr[31]}}, instr[31:20] };

    // 寄存器堆读取
    assign operand_a = regfile[rs1];
    assign operand_b = (opcode == 7'b0010011) ? imm_i : regfile[rs2]; // I型用立即数，R型用rs2

    // ALU输入选择
    assign alu_input_a = operand_a;
    assign alu_input_b = operand_b;
    assign shamt = operand_b[4:0];

    // ALU操作
    always @(*) begin
        case ({funct7, funct3, opcode})
            // R-type instructions
            {7'b0000000, 3'b000, 7'b0110011}: alu_out = operand_a + operand_b;      // ADD
            {7'b0100000, 3'b000, 7'b0110011}: alu_out = operand_a - operand_b;      // SUB
            {7'b0000000, 3'b001, 7'b0110011}: alu_out = operand_a << shamt;         // SLL
            {7'b0000000, 3'b010, 7'b0110011}: alu_out = ($signed(operand_a) < $signed(operand_b)) ? 32'h1 : 32'h0; // SLT
            {7'b0000000, 3'b011, 7'b0110011}: alu_out = (operand_a < operand_b) ? 32'h1 : 32'h0; // SLTU
            {7'b0000000, 3'b100, 7'b0110011}: alu_out = operand_a ^ operand_b;      // XOR
            {7'b0000000, 3'b101, 7'b0110011}: alu_out = operand_a >> shamt;         // SRL
            {7'b0100000, 3'b101, 7'b0110011}: alu_out = operand_a >>> shamt;        // SRA
            {7'b0000000, 3'b110, 7'b0110011}: alu_out = operand_a | operand_b;      // OR
            {7'b0000000, 3'b111, 7'b0110011}: alu_out = operand_a & operand_b;      // AND
            // I-type arithmetic instructions
            {7'bxxxxxxx, 3'b000, 7'b0010011}: alu_out = operand_a + imm_i;          // ADDI
            {7'bxxxxxxx, 3'b010, 7'b0010011}: alu_out = ($signed(operand_a) < $signed(imm_i)) ? 32'h1 : 32'h0; // SLTI
            {7'bxxxxxxx, 3'b011, 7'b0010011}: alu_out = (operand_a < imm_i) ? 32'h1 : 32'h0; // SLTIU
            {7'bxxxxxxx, 3'b100, 7'b0010011}: alu_out = operand_a ^ imm_i;          // XORI
            {7'bxxxxxxx, 3'b110, 7'b0010011}: alu_out = operand_a | imm_i;          // ORI
            {7'bxxxxxxx, 3'b111, 7'b0010011}: alu_out = operand_a & imm_i;          // ANDI
            // I-type shift instructions
            {7'b0000000, 3'b001, 7'b0010011}: alu_out = operand_a << shamt;         // SLLI
            {7'b0000000, 3'b101, 7'b0010011}: alu_out = operand_a >> shamt;         // SRLI
            {7'b0100000, 3'b101, 7'b0010011}: alu_out = operand_a >>> shamt;        // SRAI
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    // 非法指令检测
    wire is_r_type = (opcode == 7'b0110011);
    wire is_i_arith = (opcode == 7'b0010011);
    wire is_shift_i = (is_i_arith && (funct3 == 3'b001 || funct3 == 3'b101));
    wire is_valid_r = (is_r_type && 
                      ((funct7 == 7'b0000000 || funct7 == 7'b0100000) && 
                       (funct3 == 3'b000 || funct3 == 3'b001 || funct3 == 3'b010 || 
                        funct3 == 3'b011 || funct3 == 3'b100 || funct3 == 3'b101 || 
                        funct3 == 3'b110 || funct3 == 3'b111)));
    wire is_valid_i_arith = (is_i_arith && 
                            (funct3 == 3'b000 || funct3 == 3'b010 || funct3 == 3'b011 || 
                             funct3 == 3'b100 || funct3 == 3'b110 || funct3 == 3'b111));
    wire is_valid_shift_i = (is_shift_i && 
                            ((funct3 == 3'b001 && funct7 == 7'b0000000) ||
                             ((funct3 == 3'b101) && (funct7 == 7'b0000000 || funct7 == 7'b0100000))));

    assign illegal_comb = !(is_valid_r || is_valid_i_arith || is_valid_shift_i);

    // 写使能控制
    assign write_enable = valid && !illegal_comb && (rd != 5'b0);

    // 寄存器堆写入
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
        end else if (write_enable) begin
            regfile[rd] <= alu_out;
        end
    end

    // 调试输出
    assign dbg_data = regfile[dbg_addr];

    // 输出寄存器
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            alu_result_reg <= 32'h0;
            illegal_reg <= 1'b0;
        end else begin
            if (valid) begin
                alu_result_reg <= alu_out;
                illegal_reg <= illegal_comb;
            end
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

endmodule
