            {7'bxxxxxxx, 3'b000, 7'b0010011}: alu_out = operand_a + imm_i;          // ADDI
            {7'bxxxxxxx, 3'b010, 7'b0010011}: alu_out = ($signed(operand_a) < $signed(imm_i)) ? 32'h1 : 32'h0; // SLTI
            {7'bxxxxxxx, 3'b011, 7'b0010011}: alu_out = (operand_a < imm_i) ? 32'h1 : 32'h0; // SLTIU
            {7'bxxxxxxx, 3'b100, 7'b0010011}: alu_out = operand_a ^ imm_i;          // XORI
            {7'bxxxxxxx, 3'b110, 7'b0010011}: alu_out = operand_a | imm_i;          // ORI
            {7'bxxxxxxx, 3'b111, 7'b0010011}: alu_out = operand_a & imm_i;          // ANDI
            // I-type shift instructions
            {7'b0000000, 3'b001, 7'b0010011}: alu_out = operand_a << shamt;         // SLLI
            {7'b0000000, 3'b101, 7'b0010011}: alu_out = operand_a >> shamt;         // SRLI
            {7'b0100000, 3'b101, 7'b0010011}: alu_out = operand_a >>> shamt;        // SRAI
            default: alu_out = 32'hxxxxxxxx;
        endcase
    end

    // 非法指令检测
    wire is_r_type = (opcode == 7'b0110011);
    wire is_i_arith = (opcode == 7'b0010011);
    wire is_shift_i = (is_i_arith && (funct3 == 3'b001 || funct3 == 3'b101));
    wire is_valid_r = (is_r_type && 
                      ((funct7 == 7'b0000000 || funct7 == 7'b0100000) && 
                       (funct3 == 3'b000 || funct3 == 3'b001 || funct3 == 3'b010 || 
                        funct3 == 3'b011 || funct3 == 3'b100 || funct3 == 3'b101 || 
                        funct3 == 3'b110 || funct3 == 3'b111)));
    wire is_valid_i_arith = (is_i_arith && 
                            (funct3 == 3'b000 || funct3 == 3'b010 || funct3 == 3'b011 || 
                             funct3 == 3'b100 || funct3 == 3'b110 || funct3 == 3'b111));
    wire is_valid_shift_i = (is_shift_i && 
                            ((funct3 == 3'b001 && funct7 == 7'b0000000) ||
                             ((funct3 == 3'b101) && (funct7 == 7'b0000000 || funct7 == 7'b0100000))));

    assign illegal_comb = !(is_valid_r || is_valid_i_arith || is_valid_shift_i);

    // 写使能控制
    assign write_enable = valid && !illegal_comb && (rd != 5'b0);

    // 寄存器堆写入
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
        end else if (write_enable) begin
            regfile[rd] <= alu_out;
        end
    end

    // 调试输出
    assign dbg_data = regfile[dbg_addr];

    // 输出寄存器
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            alu_result_reg <= 32'h0;
            illegal_reg <= 1'b0;
        end else begin
            if (valid) begin
                alu_result_reg <= alu_out;
                illegal_reg <= illegal_comb;
            end
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

endmodule

