## 设计思路

1. **信号分析**：
   - 输入：clk(1)、rst_n(1)、instr(32)、valid(1)
   - 输出：alu_result(32，寄存器输出)、illegal(1，组合输出)、dbg_data(32，组合输出)
   - 内部：寄存器堆(32×32位)、ALU等为组合逻辑

2. **无状态机**：单周期数据通路，无需状态机或计数器

3. **复位行为**：寄存器堆在复位时清零，x0恒为0；时序要求通过寄存器在时钟边沿更新alu_result满足

4. **实现要点**：解析R型/I型指令获取操作码、寄存器地址；ALU根据功能码执行对应运算；寄存器堆支持同时读写；非法指令检测

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output reg [31:0] alu_result,
    output wire illegal,
    input [4:0] dbg_addr,
    output wire [31:0] dbg_data
);

// 寄存器堆定义
reg [31:0] regfile [0:31];
integer i;

// 复位和写使能逻辑
wire [4:0] rs1, rs2, rd;
wire [6:0] opcode;
wire [2:0] funct3;
wire [6:0] funct7;
wire [31:0] imm_i;

assign rs1 = instr[19:15];
assign rs2 = instr[24:20];
assign rd = instr[11:7];
assign opcode = instr[6:0];
assign funct3 = instr[14:12];
assign funct7 = instr[31:25];
assign imm_i = { {20{instr[31]}}, instr[31:20] };

// ALU控制信号
wire [3:0] alu_op;
wire is_r_type, is_i_type;

assign is_r_type = (opcode == 7'b0110011);
assign is_i_type = (opcode == 7'b0010011);

// ALU操作码解码
reg [3:0] alu_op_reg;
always @(*) begin
    case ({is_r_type, is_i_type, funct3, funct7})
        // R-type instructions
        {1'b1, 1'b0, 3'b000, 7'b0000000}: alu_op_reg = 4'b0000; // ADD
        {1'b1, 1'b0, 3'b000, 7'b0100000}: alu_op_reg = 4'b0001; // SUB
        {1'b1, 1'b0, 3'b001, 7'b0000000}: alu_op_reg = 4'b0010; // SLL
        {1'b1, 1'b0, 3'b010, 7'b0000000}: alu_op_reg = 4'b0011; // SLT
        {1'b1, 1'b0, 3'b011, 7'b0000000}: alu_op_reg = 4'b0100; // SLTU
        {1'b1, 1'b0, 3'b100, 7'b0000000}: alu_op_reg = 4'b0101; // XOR
        {1'b1, 1'b0, 3'b101, 7'b0000000}: alu_op_reg = 4'b0110; // SRL
        {1'b1, 1'b0, 3'b101, 7'b0100000}: alu_op_reg = 4'b0111; // SRA
        {1'b1, 1'b0, 3'b110, 7'b0000000}: alu_op_reg = 4'b1000; // OR
        {1'b1, 1'b0, 3'b111, 7'b0000000}: alu_op_reg = 4'b1001; // AND

        // I-type instructions
        {1'b0, 1'b1, 3'b000}: alu_op_reg = 4'b0000; // ADDI
        {1'b0, 1'b1, 3'b010}: alu_op_reg = 4'b0011; // SLTI
        {1'b0, 1'b1, 3'b011}: alu_op_reg = 4'b0100; // SLTIU
        {1'b0, 1'b1, 3'b100}: alu_op_reg = 4'b0101; // XORI
        {1'b0, 1'b1, 3'b110}: alu_op_reg = 4'b1000; // ORI
        {1'b0, 1'b1, 3'b111}: alu_op_reg = 4'b1001; // ANDI
        {1'b0, 1'b1, 3'b001}: alu_op_reg = 4'b0010; // SLLI
        {1'b0, 1'b1, 3'b101, 7'b0000000}: alu_op_reg = 4'b0110; // SRLI
        {1'b0, 1'b1, 3'b101, 7'b0100000}: alu_op_reg = 4'b0111; // SRAI

        default: alu_op_reg = 4'b1111; // Invalid
    endcase
end

assign alu_op = alu_op_reg;

// ALU
function [31:0] alu_compute;
    input [31:0] a, b;
    input [3:0] op;
    reg [31:0] result;
    integer shamt;
    begin
        case(op)
            4'b0000: result = a + b;           // ADD / ADDI
            4'b0001: result = a - b;           // SUB
            4'b0010: begin                    // SLL / SLLI
                shamt = b[4:0];
                result = a << shamt;
            end
            4'b0011: begin                    // SLT / SLTI
                if ($signed(a) < $signed(b))
                    result = 32'h00000001;
                else
                    result = 32'h00000000;
            end
            4'b0100: begin                    // SLTU / SLTIU
                if (a < b)
                    result = 32'h00000001;
                else
                    result = 32'h00000000;
            end
            4'b0101: result = a ^ b;          // XOR / XORI
            4'b0110: begin                    // SRL / SRLI
                shamt = b[4:0];
                result = a >> shamt;
            end
            4'b0111: begin                    // SRA / SRAI
                shamt = b[4:0];
                result = $signed(a) >>> shamt;
            end
            4'b1000: result = a | b;          // OR / ORI
            4'b1001: result = a & b;          // AND / ANDI
            default: result = 32'hxxxxxxxx;
        endcase
        alu_compute = result;
    end
endfunction

// 读取源寄存器
wire [31:0] rs1_data = (rs1 == 5'd0) ? 32'h00000000 : regfile[rs1];
wire [31:0] rs2_data = (rs2 == 5'd0) ? 32'h00000000 : regfile[rs2];

// ALU输入选择
wire [31:0] alu_src_a = is_r_type ? rs1_data : rs1_data;
wire [31:0] alu_src_b = is_r_type ? rs2_data : imm_i;

// ALU输出
wire [31:0] alu_out = alu_compute(alu_src_a, alu_src_b, alu_op);

// 非法指令检测
assign illegal = (alu_op == 4'b1111) || 
                 (is_r_type && (funct3 == 3'b101) && (funct7 != 7'b0000000 && funct7 != 7'b0100000)) ||
                 (is_i_type && (funct3 == 3'b101) && (funct7 != 7'b0000000 && funct7 != 7'b0100000));

// 寄存器写使能和数据
wire reg_write_en = valid && !illegal && (rd != 5'd0) && (is_r_type || is_i_type);
wire [31:0] reg_write_data = alu_out;

// 寄存器堆写操作
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < 32; i = i + 1) begin
            regfile[i] <= 32'h00000000;
        end
    end else if (reg_write_en) begin
        regfile[rd] <= reg_write_data;
    end
end

// ALU结果输出（寄存器输出）
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        alu_result <= 32'h00000000;
    end else begin
        alu_result <= alu_out;
    end
end

// 调试输出（组合逻辑）
assign dbg_data = (dbg_addr == 5'd0) ? 32'h00000000 : regfile[dbg_addr];

endmodule
