## 设计思路

1. **信号分析**：输入包括时钟、复位、32位指令和valid信号；输出包括32位ALU结果、非法指令标志和调试接口。其中alu_result和illegal是寄存器输出，dbg_data是组合输出。

2. **内部结构**：需要32×32位寄存器堆（x0恒为0）、ALU（支持R型和I型指令操作）、指令译码逻辑。

3. **复位行为**：复位时所有寄存器清零，输出初始化为0。时序要求通过在valid信号有效时执行指令并下一周期输出结果来满足。

## 完整代码

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output reg [31:0] alu_result,
    output reg illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

// 寄存器堆定义
reg [31:0] regfile [0:31];
integer i;

// 信号定义
wire [6:0] opcode;
wire [2:0] funct3;
wire [6:0] funct7;
wire [4:0] rs1, rs2, rd;
wire [31:0] imm;
wire [31:0] operand1, operand2;
wire [4:0] shamt;
wire [31:0] alu_in1, alu_in2;
wire [3:0] alu_op;
reg [31:0] next_alu_result;
reg next_illegal;
reg [31:0] rs1_data, rs2_data;

// 指令字段提取
assign opcode = instr[6:0];
assign funct3 = instr[14:12];
assign funct7 = instr[31:25];
assign rs1 = instr[19:15];
assign rs2 = instr[24:20];
assign rd = instr[11:7];

// 立即数生成
assign imm = {{20{instr[31]}}, instr[31:20]}; // I-type immediate
assign shamt = instr[24:20]; // shift amount for SLLI/SRLI/SRAI

// 操作数选择
assign operand1 = regfile[rs1];
assign operand2 = (opcode == 7'b0010011 && (funct3 == 3'b001 || funct3 == 3'b101)) ? {27'b0, shamt} : 
                  (opcode == 7'b0010011) ? imm : regfile[rs2];

// ALU操作定义
localparam ALU_ADD = 4'b0000;
localparam ALU_SUB = 4'b0001;
localparam ALU_SLL = 4'b0010;
localparam ALU_SLT = 4'b0011;
localparam ALU_SLTU = 4'b0100;
localparam ALU_XOR = 4'b0101;
localparam ALU_SRL = 4'b0110;
localparam ALU_SRA = 4'b0111;
localparam ALU_OR = 4'b1000;
localparam ALU_AND = 4'b1001;

// 指令译码和ALU控制
always @(*) begin
    case(opcode)
        7'b0110011: begin // R-type
            case({funct7, funct3})
                {7'b0000000, 3'b000}: alu_op = ALU_ADD; // ADD
                {7'b0100000, 3'b000}: alu_op = ALU_SUB; // SUB
                {7'b0000000, 3'b001}: alu_op = ALU_SLL; // SLL
                {7'b0000000, 3'b010}: alu_op = ALU_SLT; // SLT
                {7'b0000000, 3'b011}: alu_op = ALU_SLTU; // SLTU
                {7'b0000000, 3'b100}: alu_op = ALU_XOR; // XOR
                {7'b0000000, 3'b101}: alu_op = ALU_SRL; // SRL
                {7'b0100000, 3'b101}: alu_op = ALU_SRA; // SRA
                {7'b0000000, 3'b110}: alu_op = ALU_OR;  // OR
                {7'b0000000, 3'b111}: alu_op = ALU_AND; // AND
                default: alu_op = 4'bxxxx;
            endcase
        end
        7'b0010011: begin // I-type arithmetic/logic
            case(funct3)
                3'b000: alu_op = ALU_ADD;  // ADDI
                3'b010: alu_op = ALU_SLT;  // SLTI
                3'b011: alu_op = ALU_SLTU; // SLTIU
                3'b100: alu_op = ALU_XOR;  // XORI
                3'b110: alu_op = ALU_OR;   // ORI
                3'b111: alu_op = ALU_AND;  // ANDI
                3'b001: alu_op = ALU_SLL;  // SLLI
                3'b101: 
                    if(funct7 == 7'b0000000) alu_op = ALU_SRL; // SRLI
                    else if(funct7 == 7'b0100000) alu_op = ALU_SRA; // SRAI
                    else alu_op = 4'bxxxx;
                default: alu_op = 4'bxxxx;
            endcase
        end
        default: alu_op = 4'bxxxx;
    endcase
end

// 非法指令检测
always @(*) begin
    case(opcode)
        7'b0110011: begin // R-type
            case({funct7, funct3})
                {7'b0000000, 3'b000},
                {7'b0100000, 3'b000},
                {7'b0000000, 3'b001},
                {7'b0000000, 3'b010},
                {7'b0000000, 3'b011},
                {7'b0000000, 3'b100},
                {7'b0000000, 3'b101},
                {7'b0100000, 3'b101},
                {7'b0000000, 3'b110},
                {7'b0000000, 3'b111}: next_illegal = 1'b0;
                default: next_illegal = 1'b1;
            endcase
        end
