## 设计思路

1. **信号分析**：
   - 输入：clk(1)、rst_n(1)、instr(32)、valid(1)
   - 输出：alu_result(32，寄存器输出)、illegal(1，组合输出)、dbg_data(32，组合输出)
   - 寄存器堆：32×32位，带写使能控制(rd≠0且valid)

2. **无状态机**：单周期执行，无需状态机或计数器

3. **复位行为**：寄存器堆全清零，alu_result在rst_n=0时清零；x0恒为0；时序要求通过寄存器输出alu_result满足

4. **ALU实现**：根据funct3和funct7解析R/I型指令，支持19种操作

## 完整代码

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regfile [0:31];
    integer i;

    // 信号定义
    wire [6:0] opcode;
    wire [4:0] rs1, rs2, rd;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [31:0] imm_i;
    wire [4:0] shamt;

    // 指令字段提取
    assign opcode = instr[6:0];
    assign rs1 = instr[19:15];
    assign rs2 = instr[24:20];
    assign rd = instr[11:7];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign imm_i = { {21{instr[31]}}, instr[30:20] };
    assign shamt = instr[24:20];

    // ALU控制信号
    wire is_r_type, is_i_type;
    wire [3:0] alu_op;

    assign is_r_type = (opcode == 7'b0110011);
    assign is_i_type = (opcode == 7'b0010011);

    // 非法指令检测
    assign illegal = 
        (valid & is_r_type & !(
            (funct3 == 3'b000 & funct7 == 7'b0000000) |  // ADD
            (funct3 == 3'b000 & funct7 == 7'b0100000) |  // SUB
            (funct3 == 3'b001 & funct7 == 7'b0000000) |  // SLL
            (funct3 == 3'b010 & funct7 == 7'b0000000) |  // SLT
            (funct3 == 3'b011 & funct7 == 7'b0000000) |  // SLTU
            (funct3 == 3'b100 & funct7 == 7'b0000000) |  // XOR
            (funct3 == 3'b101 & funct7 == 7'b0000000) |  // SRL
            (funct3 == 3'b101 & funct7 == 7'b0100000) |  // SRA
            (funct3 == 3'b110 & funct7 == 7'b0000000) |  // OR
            (funct3 == 3'b111 & funct7 == 7'b0000000)    // AND
        )) |
        (valid & is_i_type & !(
            (funct3 == 3'b000) |  // ADDI
            (funct3 == 3'b010) |  // SLTI
            (funct3 == 3'b011) |  // SLTIU
            (funct3 == 3'b100) |  // XORI
            (funct3 == 3'b110) |  // ORI
            (funct3 == 3'b111) |  // ANDI
            (funct3 == 3'b001 & funct7 == 7'b0000000) |  // SLLI
            (funct3 == 3'b101 & funct7 == 7'b0000000) |  // SRLI
            (funct3 == 3'b101 & funct7 == 7'b0100000)    // SRAI
        ));

    // ALU操作码生成
    reg [3:0] alu_op_reg;
    always @(*) begin
        if (is_r_type) begin
            case ({funct3, funct7})
                {3'b000, 7'b0000000}: alu_op_reg = 4'b0000;  // ADD
                {3'b000, 7'b0100000}: alu_op_reg = 4'b0001;  // SUB
                {3'b001, 7'b0000000}: alu_op_reg = 4'b0010;  // SLL
                {3'b010, 7'b0000000}: alu_op_reg = 4'b0011;  // SLT
                {3'b011, 7'b0000000}: alu_op_reg = 4'b0100;  // SLTU
                {3'b100, 7'b0000000}: alu_op_reg = 4'b0101;  // XOR
                {3'b101, 7'b0000000}: alu_op_reg = 4'b0110;  // SRL
                {3'b101, 7'b0100000}: alu_op_reg = 4'b0111;  // SRA
                {3'b110, 7'b0000000}: alu_op_reg = 4'b1000;  // OR
                {3'b111, 7'b0000000}: alu_op_reg = 4'b1001;  // AND
                default: alu_op_reg = 4'bx;
            endcase
        end else if (is_i_type) begin
            case ({funct3, funct7})
                {3'b000, 7'bxxxxxxx}: alu_op_reg = 4'b0000;  // ADDI -> ADD
                {3'b010, 7'bxxxxxxx}: alu_op_reg = 4'b0011;  // SLTI -> SLT
                {3'b011, 7'bxxxxxxx}: alu_op_reg = 4'b0100;  // SLTIU -> SLTU
                {3'b100, 7'bxxxxxxx}: alu_op_reg = 4'b0101;  // XORI -> XOR
                {3'b110, 7'bxxxxxxx}: alu_op_reg = 4'b1000;  // ORI -> OR
                {3'b111, 7'bxxxxxxx}: alu_op_reg = 4'b1001;  // ANDI -> AND
                {3'b001, 7'b0000000}: alu_op_reg = 4'b0010;  // SLLI -> SLL
                {3'b101, 7'b0000000}: alu_op_reg = 4'b0110;  // SRLI -> SRL
                {3'b101, 7'b0100000}: alu_op_reg = 4'b0111;  // SRAI -> SRA
                default: alu_op_reg = 4'bx;
            endcase
        end else begin
            alu_op_reg = 4'bx;
        end
    end

    // ALU实现
    function [31:0] alu_compute;
        input [31:0] a, b;
        input [3:0] op;
        begin
            case (op)
                4'b0000: alu_compute = a + b;           // ADD/SUB
                4'b0001: alu_compute = a - b;           // SUB
                4'b0010: alu_compute = a << b[4:0];     // SLL
                4'b0011: alu_compute = $signed(a) < $signed(b) ? 32'h1 : 32'h0;  // SLT
                4'b0100: alu_compute = a < b ? 32'h1 : 32'h0;  // SLTU
                4'b0101: alu_compute = a ^ b;           // XOR
                4'b0110: alu_compute = a >> b[4:0];     // SRL
                4'b0111: alu_compute = $signed(a) >>> b[4:0];  // SRA
                4'b1000: alu_compute = a | b;           // OR
                4'b1001: alu_compute = a & b;           // AND
                default: alu_compute = 32'hx;
            endcase
        end
    endfunction

    wire [31:0] operand_a, operand_b;
    assign operand_a = regfile[rs1];
    assign operand_b = is_r_type ? regfile[rs2] : imm_i;

    wire [31:0] alu_out;
    assign alu_out = alu_compute(operand_a, operand_b, alu_op_reg);

    // 寄存器堆写入
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
        end else if (valid && (is_r_type || is_i_type) && !illegal && rd != 5'b0) begin
            regfile[rd] <= alu_out;
        end
    end

    // x0恒为0
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            regfile[0] <= 32'h0;
        end else begin
            regfile[0] <= 32'h0;
        end
    end

    // ALU结果输出
    reg [31:0] alu_result_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            alu_result_reg <= 32'h0;
        end else if (valid && (is_r_type || is_i_type) && !illegal) begin
            alu_result_reg <= alu_out;
        end else begin
            alu_result_reg <= 32'h0;
        end
    end

    assign alu_result = alu_result_reg;

    // 调试输出
    assign dbg_data = regfile[dbg_addr];

endmodule
