    wire valid_ori = is_i_type & (funct3 == 3'b110);
    wire valid_andi = is_i_type & (funct3 == 3'b111);
    wire valid_slli = is_i_type & (funct3 == 3'b001) & (funct7 == 7'b0000000);
    wire valid_srli = is_i_type & (funct3 == 3'b101) & (funct7 == 7'b0000000);
    wire valid_srai = is_i_type & (funct3 == 3'b101) & (funct7 == 7'b0100000);

    assign instr_valid = 
        valid_add | valid_sub | valid_sll | valid_slt | valid_sltu | 
        valid_xor | valid_srl | valid_sra | valid_or | valid_and |
        valid_addi | valid_slti | valid_sltiu | valid_xori | valid_ori | 
        valid_andi | valid_slli | valid_srli | valid_srai;

    // ALU control based on instruction type and funct3
    wire [3:0] alu_ctrl;
    always @(*) begin
        case ({is_r_type, is_i_type, funct3})
            {1'b1, 1'b0, 3'b000}: alu_ctrl = funct7[5] ? 4'b0110 : 4'b0010; // SUB : ADD
            {1'b1, 1'b0, 3'b001}: alu_ctrl = 4'b1010; // SLL
            {1'b1, 1'b0, 3'b010}: alu_ctrl = 4'b0111; // SLT
            {1'b1, 1'b0, 3'b011}: alu_ctrl = 4'b1111; // SLTU
            {1'b1, 1'b0, 3'b100}: alu_ctrl = 4'b0001; // XOR
            {1'b1, 1'b0, 3'b101}: alu_ctrl = funct7[5] ? 4'b0101 : 4'b0100; // SRA : SRL
            {1'b1, 1'b0, 3'b110}: alu_ctrl = 4'b0011; // OR
            {1'b1, 1'b0, 3'b111}: alu_ctrl = 4'b0000; // AND
            {1'b0, 1'b1, 3'b000}: alu_ctrl = 4'b0010; // ADDI -> ADD
            {1'b0, 1'b1, 3'b001}: alu_ctrl = 4'b1010; // SLLI -> SLL
            {1'b0, 1'b1, 3'b010}: alu_ctrl = 4'b0111; // SLTI -> SLT
            {1'b0, 1'b1, 3'b011}: alu_ctrl = 4'b1111; // SLTIU -> SLTU
            {1'b0, 1'b1, 3'b100}: alu_ctrl = 4'b0001; // XORI -> XOR
            {1'b0, 1'b1, 3'b101}: alu_ctrl = funct7[5] ? 4'b0101 : 4'b0100; // SRAI/SRLI -> SRA/SRL
            {1'b0, 1'b1, 3'b110}: alu_ctrl = 4'b0011; // ORI -> OR
            {1'b0, 1'b1, 3'b111}: alu_ctrl = 4'b0000; // ANDI -> AND
            default: alu_ctrl = 4'bxxxx; // Invalid
        endcase
    end

    // ALU implementation
    wire [32:0] add_result = {1'b0, alu_op1} + {1'b0, alu_op2};
    wire [32:0] sub_result = {1'b0, alu_op1} - {1'b0, alu_op2};
    wire less_signed = $signed(alu_op1) < $signed(alu_op2);
    wire less_unsigned = $unsigned(alu_op1) < $unsigned(alu_op2);
    wire [4:0] shamt = (opcode == 7'b0110011) ? rs2_data[4:0] : immediate[4:0];

    always @(*) begin
        case (alu_ctrl)
            4'b0000: alu_out = alu_op1 & alu_op2;           // AND
            4'b0001: alu_out = alu_op1 ^ alu_op2;           // XOR
            4'b0010: alu_out = add_result[31:0];            // ADD
            4'b0011: alu_out = alu_op1 | alu_op2;           // OR
            4'b0100: alu_out = alu_op1 >> shamt;            // SRL
            4'b0101: alu_out = $signed(alu_op1) >>> shamt;  // SRA
            4'b0110: alu_out = sub_result[31:0];            // SUB
            4'b0111: alu_out = less_signed ? 32'h1 : 32'h0; // SLT
            4'b1010: alu_out = alu_op1 << shamt;            // SLL
            4'b1111: alu_out = less_unsigned ? 32'h1 : 32'h0; // SLTU
            default: alu_out = 32'h0;
        endcase
    end

    // Write enable
    assign write_reg = valid & instr_valid & (rd_addr != 5'b0); // Don't write to x0

    // Outputs
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

    // Sequential logic
    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            // Reset all registers to 0
            for (i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end
        else if (valid) begin
            if (instr_valid) begin
                if (write_reg) begin
                    regs[rd_addr] <= alu_out;
                end
                alu_result_reg <= alu_out;
                illegal_reg <= 1'b0;
            end
            else begin
                alu_result_reg <= 32'b0;
                illegal_reg <= 1'b1;
            end
        end
    end

endmodule
