        is_sltiu ? sltiu_res :
        is_xori ? xori_res :
        is_ori ? ori_res :
        is_andi ? andi_res :
        is_slli ? slli_res :
        is_srl_i ? srli_res :
        is_sra_i ? srai_res : 32'h0;

