        (!(is_r_type || is_i_type));

    // Update register file and outputs on valid signal
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end
        else if (valid) begin
            if (!illegal_instr && rd_addr != 5'b0) begin
                regs[rd_addr] <= alu_out;
            end
            alu_result_reg <= illegal_instr ? 32'b0 : alu_out;
            illegal_reg <= illegal_instr;
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

endmodule
