                    (is_i_type && funct3 == 3'b001 && funct7 == 7'b0000000);
    wire slt_inst = (is_r_type && funct3 == 3'b010 && funct7 == 7'b0000000) ||
                    (is_i_type && funct3 == 3'b010);
    wire sltu_inst = (is_r_type && funct3 == 3'b011 && funct7 == 7'b0000000) ||
                     (is_i_type && funct3 == 3'b011);
    wire xor_inst = (is_r_type && funct3 == 3'b100 && funct7 == 7'b0000000) ||
                    (is_i_type && funct3 == 3'b100);
    wire or_inst = (is_r_type && funct3 == 3'b110 && funct7 == 7'b0000000) ||
                   (is_i_type && funct3 == 3'b110);
    wire and_inst = (is_r_type && funct3 == 3'b111 && funct7 == 7'b0000000) ||
                    (is_i_type && funct3 == 3'b111);
    wire srl_inst = (is_r_type && funct3 == 3'b101 && funct7 == 7'b0000000) ||
                    (is_i_type && funct3 == 3'b101 && funct7 == 7'b0000000);
    wire sra_inst = (is_r_type && funct3 == 3'b101 && funct7 == 7'b0100000) ||
                    (is_i_type && funct3 == 3'b101 && funct7 == 7'b0100000);

    // Illegal instruction detection
    assign illegal_instr = !(
        (is_r_type && (
            (funct3 == 3'b000 && (funct7 == 7'b0000000 || funct7 == 7'b0100000)) ||  // ADD/SUB
            (funct3 == 3'b001 && funct7 == 7'b0000000) ||  // SLL
