    assign is_slt = (opcode == 7'b0110011) & (funct3 == 3'b010) & (funct7 == 7'b0000000);
    assign is_sltu = (opcode == 7'b0110011) & (funct3 == 3'b011) & (funct7 == 7'b0000000);
