                3'b010: illegal_instr = !(funct7 == 7'b0000000); // SLT
                3'b011: illegal_instr = !(funct7 == 7'b0000000); // SLTU
                3'b100: illegal_instr = !(funct7 == 7'b0000000); // XOR
                3'b101: illegal_instr = !(funct7 == 7'b0000000 || funct7 == 7'b0100000); // SRL/SRA
                3'b110: illegal_instr = !(funct7 == 7'b0000000); // OR
                3'b111: illegal_instr = !(funct7 == 7'b0000000); // AND
                default: illegal_instr = 1'b1;
            endcase
        end
        else if(opcode == 7'b0010011) begin
            case(funct3)
                3'b000: illegal_instr = 1'b0; // ADDI
                3'b001: illegal_instr = !(funct7 == 7'b0000000); // SLLI
                3'b010: illegal_instr = 1'b0; // SLTI
                3'b011: illegal_instr = 1'b0; // SLTIU
                3'b100: illegal_instr = 1'b0; // XORI
                3'b101: illegal_instr = !(funct7 == 7'b0000000 || funct7 == 7'b0100000); // SRLI/SRAI
                3'b110: illegal_instr = 1'b0; // ORI
                3'b111: illegal_instr = 1'b0; // ANDI
                default: illegal_instr = 1'b1;
            endcase
        end
        else begin
            illegal_instr = 1'b1;
        end
    end

    // Next state logic
    always @(*) begin
        if(valid) begin
            next_alu_result = alu_out;
            next_illegal = illegal_instr;
        end
        else begin
            next_alu_result = alu_result;
            next_illegal = illegal;
        end
    end

    // Write register file on valid and not illegal
    wire write_reg;
    assign write_reg = valid & ~illegal_instr & (rd_addr != 5'b0);

    always @(posedge clk) begin
        if(!rst_n) begin
            integer i;
            for(i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
            alu_result <= 32'b0;
            illegal <= 1'b0;
        end
        else begin
            if(write_reg) begin
                regs[rd_addr] <= alu_out;
            end
            alu_result <= next_alu_result;
            illegal <= next_illegal;
        end
    end

    // Debug output
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

