                        next_illegal = 1'b1;
                end
                3'b001, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111: begin  // Other R-type operations
                    if (funct7 != 7'b0000000)
                        next_illegal = 1'b1;
                end
                3'b101: begin  // SRL / SRA
                    if ((funct7 != 7'b0000000) && (funct7 != 7'b0100000))
                        next_illegal = 1'b1;
                end
                default: next_illegal = 1'b1;
            endcase
        end
        else if (is_i_type) begin
            case (funct3)
                3'b001: begin  // SLLI
                    if (immediate[11:5] != 7'b0000000)
                        next_illegal = 1'b1;
                end
                3'b101: begin  // SRLI / SRAI
                    if ((immediate[11:5] != 7'b0000000) && (immediate[11:5] != 7'b0100000))
                        next_illegal = 1'b1;
                end
                3'b000, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111: begin  // Other I-type operations
                    // These are valid for I-type with any immediate
                end
                default: next_illegal = 1'b1;
            endcase
        end
        else begin
            // Not R-type or I-type
            next_illegal = 1'b1;
        end

        // Check for invalid opcode combinations
        if (!is_r_type && !is_i_type)
            next_illegal = 1'b1;
    end

    // Next ALU result
    assign next_alu_result = next_illegal ? 32'b0 : alu_out;

    // Outputs
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

    // Debug data output
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

    // Sequential logic
    always @(posedge clk) begin
        if (!rst_n) begin
            // Reset all registers to 0
            for (i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end
        else begin
            if (valid) begin
                // Update outputs based on current instruction
                alu_result_reg <= next_alu_result;
                illegal_reg <= next_illegal;

                // Write back to register if not x0 and instruction is legal
                if (!next_illegal && rd_addr != 5'b0) begin
                    regs[rd_addr] <= next_alu_result;
                end
            end
            // If valid is 0, keep everything unchanged
