                alu_out = {31'b0, ($signed(rs1_data) < $signed(rs2_data))};

            is_sltu:
                alu_out = {31'b0, (rs1_data < rs2_data)};

            is_xor:
                alu_out = rs1_data ^ rs2_data;

            is_or:
                alu_out = rs1_data | rs2_data;

            is_and:
                alu_out = rs1_data & rs2_data;

            is_srl_sra:
                if(funct7[5]) // SRA
                    alu_out = $signed(rs1_data) >>> shamt_r;
                else // SRL
                    alu_out = rs1_data >> shamt_r;

            is_addi:
                alu_out = rs1_data + imm_i;

            is_slti:
                alu_out = {31'b0, ($signed(rs1_data) < $signed(imm_i))};

            is_sltiu:
                alu_out = {31'b0, (rs1_data < imm_i)};

            is_xori:
                alu_out = rs1_data ^ imm_i;

            is_ori:
                alu_out = rs1_data | imm_i;

            is_andi:
                alu_out = rs1_data & imm_i;

            is_slli:
                alu_out = rs1_data << shamt_i;

            is_srli_srai:
                if(funct7[5]) // SRAI
                    alu_out = $signed(rs1_data) >>> shamt_i;
                else // SRLI
                    alu_out = rs1_data >> shamt_i;

            default:
                alu_out = 32'b0;
        endcase
    end

    // Check for illegal instructions
    wire illegal_instr;
    assign illegal_instr = 
        (opcode == 7'b0110011) ? (
            (funct3 == 3'b000) ? !(funct7 == 7'b0000000 || funct7 == 7'b0100000) : // ADD/SUB
            (funct3 == 3'b001) ? !(funct7 == 7'b0000000) : // SLL
            (funct3 == 3'b010) ? !(funct7 == 7'b0000000) : // SLT
            (funct3 == 3'b011) ? !(funct7 == 7'b0000000) : // SLTU
            (funct3 == 3'b100) ? !(funct7 == 7'b0000000) : // XOR
            (funct3 == 3'b101) ? !(funct7 == 7'b0000000 || funct7 == 7'b0100000) : // SRL/SRA
            (funct3 == 3'b110) ? !(funct7 == 7'b0000000) : // OR
            (funct3 == 3'b111) ? !(funct7 == 7'b0000000) : // AND
            1'b1
        ) :
        (opcode == 7'b0010011) ? (
            (funct3 == 3'b000) ? 1'b0 : // ADDI
            (funct3 == 3'b001) ? !(funct7 == 7'b0000000) : // SLLI
            (funct3 == 3'b010) ? 1'b0 : // SLTI
            (funct3 == 3'b011) ? 1'b0 : // SLTIU
            (funct3 == 3'b100) ? 1'b0 : // XORI
            (funct3 == 3'b101) ? !(funct7 == 7'b0000000 || funct7 == 7'b0100000) : // SRLI/SRAI
            (funct3 == 3'b110) ? 1'b0 : // ORI
            (funct3 == 3'b111) ? 1'b0 : // ANDI
            1'b1
        ) :
        1'b1;

    // Next state logic
    always @(*) begin
        if(valid) begin
            next_alu_result = alu_out;
            next_illegal = illegal_instr;
        end
        else begin
            next_alu_result = alu_result;
            next_illegal = illegal;
        end
    end

    // Write register file on valid instruction
    reg [31:0] write_data;
    reg [4:0] write_addr;
    reg write_enable;

    always @(*) begin
        if(valid && !illegal_instr) begin
            write_data = alu_out;
            write_addr = rd_addr;
            write_enable = (rd_addr != 5'b0); // Don't write to x0
        end
        else begin
            write_data = 32'b0;
            write_addr = 5'b0;
            write_enable = 1'b0;
        end
    end

    // Register file write
    integer i;
    always @(posedge clk) begin
        if(!rst_n) begin
            for(i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
        end
        else if(write_enable) begin
            regs[write_addr] <= write_data;
        end
    end

    // Outputs
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

    reg [31:0] alu_result_reg;
    reg illegal_reg;

    always @(posedge clk) begin
        if(!rst_n) begin
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end
        else begin
            alu_result_reg <= next_alu_result;
            illegal_reg <= next_illegal;
        end
