## 设计思路

1. **输入/输出分析**：
   - 输入：clk(1)、rst_n(1)、instr(32)、valid(1)、dbg_addr(5)
   - 输出：alu_result(32)、illegal(1)、dbg_data(32)
   - 寄存器输出：alu_result、illegal
   - 组合输出：dbg_data

2. **状态机**：无状态机，单周期执行

3. **复位行为**：所有寄存器清零，alu_result=0，illegal=0

4. **设计要点**：
   - 实现32×32位寄存器堆，x0恒为0
   - 指令译码判断合法性
   - ALU实现所有支持的运算
   - valid信号控制执行时机

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output reg [31:0] alu_result,
    output reg illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

// 寄存器堆
reg [31:0] regfile [0:31];

// 译码信号
wire [6:0] opcode;
wire [2:0] funct3;
wire [6:0] funct7;
wire [4:0] rs1_addr, rs2_addr, rd_addr;
wire [31:0] rs1_data, rs2_data;
wire [31:0] immediate;

assign opcode = instr[6:0];
assign funct3 = instr[14:12];
assign funct7 = instr[31:25];
assign rs1_addr = instr[19:15];
assign rs2_addr = instr[24:20];
assign rd_addr = instr[11:7];

// 读取寄存器数据（x0恒为0）
assign rs1_data = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
assign rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];

// 立即数生成
assign immediate = {{20{instr[31]}}, instr[31:20]};

// ALU操作
wire [31:0] alu_out;
wire illegal_instr;

// ALU实现
always @(*) begin
    case ({opcode, funct3, funct7})
        // R-type instructions
        {7'b0110011, 3'b000, 7'b0000000}: alu_out = rs1_data + rs2_data;  // ADD
        {7'b0110011, 3'b000, 7'b0100000}: alu_out = rs1_data - rs2_data;  // SUB
        {7'b0110011, 3'b001, 7'b0000000}: alu_out = rs1_data << rs2_data[4:0];  // SLL
        {7'b0110011, 3'b010, 7'b0000000}: alu_out = (signed'(rs1_data) < signed'(rs2_data)) ? 32'h1 : 32'h0;  // SLT
        {7'b0110011, 3'b011, 7'b0000000}: alu_out = (rs1_data < rs2_data) ? 32'h1 : 32'h0;  // SLTU
        {7'b0110011, 3'b100, 7'b0000000}: alu_out = rs1_data ^ rs2_data;  // XOR
        {7'b0110011, 3'b110, 7'b0000000}: alu_out = rs1_data | rs2_data;  // OR
        {7'b0110011, 3'b111, 7'b0000000}: alu_out = rs1_data & rs2_data;  // AND
        {7'b0110011, 3'b101, 7'b0000000}: alu_out = rs1_data >> rs2_data[4:0];  // SRL
        {7'b0110011, 3'b101, 7'b0100000}: alu_out = $signed(rs1_data) >>> rs2_data[4:0];  // SRA

        // I-type instructions
        {7'b0010011, 3'b000}: alu_out = rs1_data + immediate;  // ADDI
        {7'b0010011, 3'b010}: alu_out = (signed'(rs1_data) < signed'(immediate)) ? 32'h1 : 32'h0;  // SLTI
        {7'b0010011, 3'b011}: alu_out = (rs1_data < immediate) ? 32'h1 : 32'h0;  // SLTIU
        {7'b0010011, 3'b100}: alu_out = rs1_data ^ immediate;  // XORI
        {7'b0010011, 3'b110}: alu_out = rs1_data | immediate;  // ORI
        {7'b0010011, 3'b111}: alu_out = rs1_data & immediate;  // ANDI
        {7'b0010011, 3'b001}: alu_out = rs1_data << immediate[4:0];  // SLLI
        {7'b0010011, 3'b101, 7'b0000000}: alu_out = rs1_data >> immediate[4:0];  // SRLI
        {7'b0010011, 3'b101, 7'b0100000}: alu_out = $signed(rs1_data) >>> immediate[4:0];  // SRAI

        default: alu_out = 32'h0;
    endcase
end

// 非法指令检测
always @(*) begin
    illegal_instr = 1'b0;

    case (opcode)
        7'b0110011: begin  // R-type
            case (funct3)
                3'b000: begin  // ADD/SUB
                    if (funct7 != 7'b0000000 && funct7 != 7'b0100000)
                        illegal_instr = 1'b1;
                end
                3'b001, 3'b010, 3'b011, 3'b100, 3'b110, 3'b111: begin  // Other operations with funct7=0
                    if (funct7 != 7'b0000000)
                        illegal_instr = 1'b1;
                end
                3'b101: begin  // SRL/SRA
                    if (funct7 != 7'b0000000 && funct7 != 7'b0100000)
                        illegal_instr = 1'b1;
                end
                default: illegal_instr = 1'b1;
            endcase
        end
        7'b0010011: begin  // I-type
            case (funct3)
                3'b001: begin  // SLLI
                    if (immediate[11:5] != 7'b0)
                        illegal_instr = 1'b1;
                end
                3'b101: begin  // SRLI/SRAI
                    if (immediate[11:5] != 7'b0 && immediate[11:5] != 7'b0100000)
