assign rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];

// 立即数生成
assign immediate = {{20{instr[31]}}, instr[31:20]};

// ALU操作
wire [31:0] alu_out;
wire illegal_instr;

// ALU实现
always @(*) begin
    case ({opcode, funct3, funct7})
        // R-type instructions
        {7'b0110011, 3'b000, 7'b0000000}: alu_out = rs1_data + rs2_data;  // ADD
        {7'b0110011, 3'b000, 7'b0100000}: alu_out = rs1_data - rs2_data;  // SUB
        {7'b0110011, 3'b001, 7'b0000000}: alu_out = rs1_data << rs2_data[4:0];  // SLL
        {7'b0110011, 3'b010, 7'b0000000}: alu_out = (signed'(rs1_data) < signed'(rs2_data)) ? 32'h1 : 32'h0;  // SLT
        {7'b0110011, 3'b011, 7'b0000000}: alu_out = (rs1_data < rs2_data) ? 32'h1 : 32'h0;  // SLTU
        {7'b0110011, 3'b100, 7'b0000000}: alu_out = rs1_data ^ rs2_data;  // XOR
        {7'b0110011, 3'b110, 7'b0000000}: alu_out = rs1_data | rs2_data;  // OR
        {7'b0110011, 3'b111, 7'b0000000}: alu_out = rs1_data & rs2_data;  // AND
        {7'b0110011, 3'b101, 7'b0000000}: alu_out = rs1_data >> rs2_data[4:0];  // SRL
        {7'b0110011, 3'b101, 7'b0100000}: alu_out = $signed(rs1_data) >>> rs2_data[4:0];  // SRA

