);

    // 寄存器堆
    reg [31:0] regfile [0:31];
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    // 指令字段
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;

    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // 操作数
    wire [31:0] rs1_val, rs2_val;
    assign rs1_val = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
    assign rs2_val = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];

    // 立即数生成
    wire [31:0] immediate;
    assign immediate = {{20{instr[31]}}, instr[31:20]};

    // ALU操作
    wire [31:0] alu_op1, alu_op2;
    wire [4:0] shamt;
    wire [6:0] alu_funct7;

    assign alu_op1 = (opcode == 7'b0010011) ? rs1_val : rs1_val; // I-type or R-type
    assign alu_op2 = (opcode == 7'b0010011) ? immediate : rs2_val; // I-type uses immediate

    // 对于移位指令，I型的shamt来自imm[4:0]，R型来自rs2[4:0]
    assign shamt = (opcode == 7'b0010011) ? immediate[4:0] : 
                   (opcode == 7'b0110011 && (funct3 == 3'b001 || funct3 == 3'b101)) ? rs2_val[4:0] : 5'b0;

    assign alu_funct7 = (opcode == 7'b0010011) ? {7{1'b0}} : funct7;

    // ALU结果计算
    wire [31:0] alu_out;
    always @(*) begin
        case({opcode, funct3, alu_funct7})
            {7'b0110011, 3'b000, 7'b0000000}: alu_out = rs1_val + rs2_val;      // ADD
            {7'b0110011, 3'b000, 7'b0100000}: alu_out = rs1_val - rs2_val;      // SUB
            {7'b0110011, 3'b001, 7'b0000000}: alu_out = rs1_val << rs2_val[4:0]; // SLL
            {7'b0110011, 3'b010, 7'b0000000}: alu_out = (signed'(rs1_val) < signed'(rs2_val)) ? 32'h1 : 32'h0; // SLT
            {7'b0110011, 3'b011, 7'b0000000}: alu_out = (rs1_val < rs2_val) ? 32'h1 : 32'h0; // SLTU
            {7'b0110011, 3'b100, 7'b0000000}: alu_out = rs1_val ^ rs2_val;      // XOR
            {7'b0110011, 3'b110, 7'b0000000}: alu_out = rs1_val | rs2_val;      // OR
            {7'b0110011, 3'b111, 7'b0000000}: alu_out = rs1_val & rs2_val;      // AND
            {7'b0110011, 3'b101, 7'b0000000}: alu_out = rs1_val >> rs2_val[4:0]; // SRL
            {7'b0110011, 3'b101, 7'b0100000}: alu_out = $signed(rs1_val) >>> rs2_val[4:0]; // SRA
            {7'b0010011, 3'b000}: alu_out = rs1_val + immediate;                // ADDI
            {7'b0010011, 3'b010}: alu_out = (signed'(rs1_val) < signed'(immediate)) ? 32'h1 : 32'h0; // SLTI
            {7'b0010011, 3'b011}: alu_out = (rs1_val < immediate) ? 32'h1 : 32'h0; // SLTIU
            {7'b0010011, 3'b100}: alu_out = rs1_val ^ immediate;                // XORI
            {7'b0010011, 3'b110}: alu_out = rs1_val | immediate;                // ORI
            {7'b0010011, 3'b111}: alu_out = rs1_val & immediate;                // ANDI
            {7'b0010011, 3'b001}: alu_out = rs1_val << shamt;                   // SLLI
            {7'b0010011, 3'b101, 8'b00000000}: alu_out = rs1_val >> shamt;      // SRLI
            {7'b0010011, 3'b101, 8'b01000000}: alu_out = $signed(rs1_val) >>> shamt; // SRAI
            default: alu_out = 32'h0;
        endcase
    end

    // 非法指令检测
    wire is_r_type = (opcode == 7'b0110011);
    wire is_i_type = (opcode == 7'b0010011);
    wire illegal_inst;

    always @(*) begin
        if (is_r_type) begin
            case(funct3)
                3'b000: illegal_inst = (funct7 != 7'b0000000 && funct7 != 7'b0100000); // ADD/SUB
                3'b001: illegal_inst = (funct7 != 7'b0000000); // SLL
                3'b010: illegal_inst = (funct7 != 7'b0000000); // SLT
                3'b011: illegal_inst = (funct7 != 7'b0000000); // SLTU
                3'b100: illegal_inst = (funct7 != 7'b0000000); // XOR
                3'b101: illegal_inst = (funct7 != 7'b0000000 && funct7 != 7'b0100000); // SRL/SRA
                3'b110: illegal_inst = (funct7 != 7'b0000000); // OR
                3'b111: illegal_inst = (funct7 != 7'b0000000); // AND
                default: illegal_inst = 1'b1;
            endcase
        end
        else if (is_i_type) begin
            case(funct3)
                3'b000: illegal_inst = 1'b0; // ADDI
                3'b001: illegal_inst = (immediate[11:5] != 7'b0000000); // SLLI
                3'b010: illegal_inst = 1'b0; // SLTI
                3'b011: illegal_inst = 1'b0; // SLTIU
                3'b100: illegal_inst = 1'b0; // XORI
                3'b101: illegal_inst = (immediate[11:5] != 7'b0000000 && immediate[11:5] != 7'b0100000); // SRLI/SRAI
                3'b110: illegal_inst = 1'b0; // ORI
                3'b111: illegal_inst = 1'b0; // ANDI
                default: illegal_inst = 1'b1;
            endcase
        end
        else begin
            illegal_inst = 1'b1;
        end
    end

    // 主时序逻辑
    reg valid_d;
    always @(posedge clk) begin
        valid_d <= valid;
        if (!rst_n) begin
            alu_result_reg <= 32'h0;
            illegal_reg <= 1'b0;
            // Reset all registers to 0
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
        end
        else if (valid && !valid_d) begin // Rising edge of valid
            alu_result_reg <= illegal_inst ? 32'h0 : alu_out;
            illegal_reg <= illegal_inst;

            if (!illegal_inst && rd_addr != 5'b0) begin
                regfile[rd_addr] <= alu_out;
            end
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

    // Debug output - combinational read
    assign dbg_data = (dbg_addr == 5'b0) ? 32'h0 : regfile[dbg_addr];

endmodule
