## 设计思路

1. **输入输出分析**：
   - 输入：clk(1)、rst_n(1)、instr(32)、valid(1)、dbg_addr(5)
   - 输出：alu_result(32)、illegal(1)、dbg_data(32)
   - 寄存器输出：alu_result、illegal
   - 组合输出：dbg_data

2. **内部结构**：
   - 32×32位寄存器堆（x0恒为0）
   - 指令译码逻辑
   - ALU（支持所有RV32I基本运算）
   - 控制逻辑判断指令合法性

3. **复位行为**：所有寄存器清零，alu_result=0，illegal=0

4. **时序要求**：valid上升沿时执行指令，更新寄存器堆和输出

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regs [0:31];
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    // 指令字段
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;

    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // ALU操作数
    wire [31:0] rs1_data, rs2_data;
    assign rs1_data = (rs1_addr == 5'b0) ? 32'b0 : regs[rs1_addr];
    assign rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regs[rs2_addr];

    // 立即数生成
    wire [31:0] immediate;
    assign immediate = {{20{instr[31]}}, instr[31:20]};

    // ALU控制信号
    wire is_r_type, is_i_type;
    wire [3:0] alu_op;
    wire [4:0] shamt;

    assign is_r_type = (opcode == 7'b0110011);
    assign is_i_type = (opcode == 7'b0010011);

    // 移位量
    assign shamt = is_r_type ? rs2_data[4:0] : immediate[4:0];

    // 指令合法性检查
    wire legal_add = is_r_type & (funct3 == 3'b000) & (funct7 == 7'b0000000);
    wire legal_sub = is_r_type & (funct3 == 3'b000) & (funct7 == 7'b0100000);
    wire legal_sll = is_r_type & (funct3 == 3'b001) & (funct7 == 7'b0000000);
    wire legal_slt = is_r_type & (funct3 == 3'b010) & (funct7 == 7'b0000000);
    wire legal_sltu = is_r_type & (funct3 == 3'b011) & (funct7 == 7'b0000000);
    wire legal_xor = is_r_type & (funct3 == 3'b100) & (funct7 == 7'b0000000);
    wire legal_srl = is_r_type & (funct3 == 3'b101) & (funct7 == 7'b0000000);
    wire legal_sra = is_r_type & (funct3 == 3'b101) & (funct7 == 7'b0100000);
    wire legal_or = is_r_type & (funct3 == 3'b110) & (funct7 == 7'b0000000);
    wire legal_and = is_r_type & (funct3 == 3'b111) & (funct7 == 7'b0000000);

    wire legal_addi = is_i_type & (funct3 == 3'b000);
    wire legal_slti = is_i_type & (funct3 == 3'b010);
    wire legal_sltiu = is_i_type & (funct3 == 3'b011);
    wire legal_xori = is_i_type & (funct3 == 3'b100);
    wire legal_ori = is_i_type & (funct3 == 3'b110);
    wire legal_andi = is_i_type & (funct3 == 3'b111);
    wire legal_slli = is_i_type & (funct3 == 3'b001) & (immediate[11:5] == 7'b0000000);
    wire legal_srli = is_i_type & (funct3 == 3'b101) & (immediate[11:5] == 7'b0000000);
    wire legal_srai = is_i_type & (funct3 == 3'b101) & (immediate[11:5] == 7'b0100000);

    wire legal_instr = legal_add | legal_sub | legal_sll | legal_slt | legal_sltu | 
                       legal_xor | legal_srl | legal_sra | legal_or | legal_and |
                       legal_addi | legal_slti | legal_sltiu | legal_xori | legal_ori | 
                       legal_andi | legal_slli | legal_srli | legal_srai;

    // ALU操作
    wire [31:0] alu_out;
    always @(*) begin
        case ({is_r_type, funct3})
            {1'b1, 3'b000}: begin // ADD/SUB
                if(funct7 == 7'b0100000)
                    alu_out = rs1_data - rs2_data;
                else
                    alu_out = rs1_data + rs2_data;
            end
            {1'b1, 3'b001}: alu_out = rs1_data << shamt; // SLL
            {1'b1, 3'b010}: alu_out = ($signed(rs1_data) < $signed(rs2_data)) ? 32'h1 : 32'h0; // SLT
            {1'b1, 3'b011}: alu_out = (rs1_data < rs2_data) ? 32'h1 : 32'h0; // SLTU
            {1'b1, 3'b100}: alu_out = rs1_data ^ rs2_data; // XOR
            {1'b1, 3'b101}: begin // SRL/SRA
                if(funct7 == 7'b0100000)
                    alu_out = $signed(rs1_data) >>> shamt; // SRA
                else
                    alu_out = rs1_data >> shamt; // SRL
            end
            {1'b1, 3'b110}: alu_out = rs1_data | rs2_data; // OR
            {1'b1, 3'b111}: alu_out = rs1_data & rs2_data; // AND
            default: begin
                case (funct3)
                    3'b000: alu_out = rs1_data + immediate; // ADDI
                    3'b010: alu_out = ($signed(rs1_data) < $signed(immediate)) ? 32'h1 : 32'h0; // SLTI
                    3'b011: alu_out = (rs1_data < immediate) ? 32'h1 : 32'h0; // SLTIU
                    3'b100: alu_out = rs1_data ^ immediate; // XORI
                    3'b110: alu_out = rs1_data | immediate; // ORI
                    3'b111: alu_out = rs1_data & immediate; // ANDI
                    3'b001: alu_out = rs1_data << shamt; // SLLI
                    3'b101: begin // SRLI/SRAI
                        if(opcode == 7'b0010011 && immediate[11:5] == 7'b0100000)
                            alu_out = $signed(rs1_data) >>> shamt; // SRAI
                        else
                            alu_out = rs1_data >> shamt; // SRLI
                    end
                    default: alu_out = 32'h0;
                endcase
            end
        endcase
    end

    // 寄存器堆写使能
    wire reg_write_en = valid & legal_instr & (rd_addr != 5'b0);

    // 寄存器堆更新
    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regs[i] <= 32'b0;
            end
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end
        else if (valid) begin
            if (legal_instr) begin
                if (reg_write_en) begin
                    regs[rd_addr] <= alu_out;
                end
                alu_result_reg <= alu_out;
                illegal_reg <= 1'b0;
            end
            else begin
                alu_result_reg <= 32'b0;
                illegal_reg <= 1'b1;
            end
        end
    end

    // 输出赋值
    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regs[dbg_addr];

endmodule
