```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regfile [0:31];
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    // 指令字段提取
    wire [6:0] opcode = instr[6:0];
    wire [2:0] funct3 = instr[14:12];
    wire [6:0] funct7 = instr[31:25];
    wire [4:0] rs1_addr = instr[19:15];
    wire [4:0] rs2_addr = instr[24:20];
    wire [4:0] rd_addr = instr[11:7];

    // 立即数生成
    wire [31:0] imm_i = {{20{instr[31]}}, instr[31:20]};

    // ALU操作数
    wire [31:0] operand1 = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
    wire [31:0] operand2 = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];

    // 移位量
    wire [4:0] shamt_r = operand2[4:0];
    wire [4:0] shamt_i = instr[24:20];

    // ALU结果计算
    wire [31:0] alu_out;
    wire illegal_inst;

    always @(*) begin
        case ({opcode, funct3, funct7})
            {7'b0110011, 3'b000, 7'b0000000}: alu_out = operand1 + operand2;  // ADD
            {7'b0110011, 3'b000, 7'b0100000}: alu_out = operand1 - operand2;  // SUB
            {7'b0110011, 3'b001, 7'b0000000}: alu_out = operand1 << shamt_r;  // SLL
            {7'b0110011, 3'b010, 7'b0000000}: alu_out = ($signed(operand1) < $signed(operand2)) ? 32'h1 : 32'h0;  // SLT
            {7'b0110011, 3'b011, 7'b0000000}: alu_out = (operand1 < operand2) ? 32'h1 : 32'h0;  // SLTU
            {7'b0110011, 3'b100, 7'b0000000}: alu_out = operand1 ^ operand2;  // XOR
            {7'b0110011, 3'b110, 7'b0000000}: alu_out = operand1 | operand2;  // OR
            {7'b0110011, 3'b111, 7'b0000000}: alu_out = operand1 & operand2;  // AND
            {7'b0110011, 3'b101, 7'b0000000}: alu_out = operand1 >> shamt_r;  // SRL
            {7'b0110011, 3'b101, 7'b0100000}: alu_out = operand1 >>> shamt_r;  // SRA
            default: alu_out = 32'h0;
        endcase

        // 检查非法指令
        case (opcode)
            7'b0110011: begin  // R-type
                if ((funct3 == 3'b000 && funct7 != 7'b0000000 && funct7 != 7'b0100000) ||
                    (funct3 == 3'b001 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b010 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b011 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b100 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b101 && funct7 != 7'b0000000 && funct7 != 7'b0100000) ||
                    (funct3 == 3'b110 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b111 && funct7 != 7'b0000000) ||
                    (funct3 == 3'b000 && funct7 == 7'b0100000 && funct3 != 3'b101))  // SUB is valid
                    illegal_inst = 1'b1;
                else
                    illegal_inst = 1'b0;
            end
            7'b0010011: begin  // I-type
                if ((funct3 == 3'b001 && (imm_i[31:7] != 25'h0 || instr[31:25] != 7'b0000000)) ||
                    (funct3 == 3'b101 && (imm_i[31:7] != 25'h0) && 
                     !(instr[31:25] == 7'b0000000 || instr[31:25] == 7'b0100000)) ||
                    (funct3 != 3'b000 && funct3 != 3'b001 && funct3 != 3'b010 && 
                     funct3 != 3'b011 && funct3 != 3'b100 && funct3 != 3'b110 && funct3 != 3'b111))
                    illegal_inst = 1'b1;
                else
                    illegal_inst = 1'b0;
            end
            default: illegal_inst = 1'b1;
        endcase
    end

    // I-type指令ALU输出
    wire [31:0] alu_out_i;
    always @(*) begin
        case (funct3)
            3'b000: alu_out_i = operand1 + imm_i;  // ADDI
            3'b010: alu_out_i = ($signed(operand1) < $signed(imm_i)) ? 32'h1 : 32'h0;  // SLTI
            3'b011: alu_out_i = (operand1 < imm_i) ? 32'h1 : 32'h0;  // SLTIU
            3'b100: alu_out_i = operand1 ^ imm_i;  // XORI
            3'b110: alu_out_i = operand1 | imm_i;  // ORI
            3'b111: alu_out_i = operand1 & imm_i;  // ANDI
            3'b001: alu_out_i = operand1 << shamt_i;  // SLLI
            3'b101: begin
                if (funct7 == 7'b0000000)
                    alu_out_i = operand1 >> shamt_i;  // SRLI
                else if (funct7 == 7'b0100000)
                    alu_out_i = operand1 >>> shamt_i;  // SRAI
                else
                    alu_out_i = 32'h0;
            end
            default: alu_out_i = 32'h0;
        endcase
    end

    // 最终ALU输出选择
    wire [31:0] final_alu_out;
    wire final_illegal;
    assign final_alu_out = (opcode == 7'b0010011) ? alu_out_i : alu_out;
    assign final_illegal = illegal_inst | ((opcode != 7'b0110011) && (opcode != 7'b0010011));

    // 时序逻辑
    always @(posedge clk) begin
        if (!rst_n) begin
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'h0;
            end
            alu_result_reg <= 32'h0;
            illegal_reg <= 1'b0;
        end
        else if (valid) begin
            if (!final_illegal && rd_addr != 5'b0) begin
                regfile[rd_addr] <= final_alu_out;
            end
            alu_result_reg <= final_alu_out;
            illegal_reg <= final_illegal;
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;
    assign dbg_data = (dbg_addr == 5'b0) ? 32'h0 : regfile[dbg_addr];

endmodule
