```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [7:0] sync_ps2_data;
    reg sync_ps2_clk;
    reg prev_ps2_clk;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sync_ps2_data <= 8'b0;
            sync_ps2_clk <= 1'b0;
            prev_ps2_clk <= 1'b0;
        end else begin
            sync_ps2_data <= {sync_ps2_data[6:0], ps2_data};
            sync_ps2_clk <= ps2_clk;
            prev_ps2_clk <= sync_ps2_clk;
        end
    end

    wire ps2_clk_negedge = prev_ps2_clk & ~sync_ps2_clk;

    reg [3:0] bit_cnt;
    reg [10:0] frame_reg;
    reg [3:0] state; // 0: idle, 1: start, 2-9: data bits, 10: parity, 11: stop
    reg [9:0] timeout_cnt;
    reg timeout_flag;

    parameter IDLE = 0, START = 1, DATA = 2, PARITY = 10, STOP = 11;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_cnt <= 4'b0;
            frame_reg <= 11'b0;
            state <= IDLE;
            timeout_cnt <= 10'b0;
            timeout_flag <= 1'b0;
        end else begin
            if (ps2_clk_negedge) begin
                timeout_cnt <= 10'b0;
                case (state)
                    IDLE: begin
                        if (sync_ps2_data == 1'b0) begin // Start bit is 0
                            state <= START;
                            bit_cnt <= 4'b0;
                            frame_reg <= 11'b0;
                        end
                    end
                    START: begin
                        frame_reg[0] <= sync_ps2_data;
                        state <= DATA;
                        bit_cnt <= 4'b1;
                    end
                    DATA: begin
                        frame_reg[bit_cnt] <= sync_ps2_data;
                        bit_cnt <= bit_cnt + 1'b1;
                        if (bit_cnt == 4'd8) begin
                            state <= PARITY;
                        end
                    end
                    PARITY: begin
                        frame_reg[9] <= sync_ps2_data;
                        state <= STOP;
                    end
                    STOP: begin
                        frame_reg[10] <= sync_ps2_data;
                        state <= IDLE;
                    end
                    default: state <= IDLE;
                endcase
            end else begin
                if (state != IDLE) begin
                    timeout_cnt <= timeout_cnt + 1'b1;
                    if (timeout_cnt >= TIMEOUT - 1) begin
                        timeout_flag <= 1'b1;
                        state <= IDLE;
                        timeout_cnt <= 10'b0;
                    end else begin
                        timeout_flag <= 1'b0;
                    end
                end else begin
                    timeout_flag <= 1'b0;
                end
            end
        end
    end

    wire start_bit_ok = (frame_reg[0] == 1'b0);
    wire stop_bit_ok = (frame_reg[10] == 1'b1);

    // Calculate odd parity for the 8 data bits
    wire [7:0] data_bits = frame_reg[8:1];
    wire parity_calc = ^data_bits;
    wire parity_ok = (parity_calc != frame_reg[9]); // Odd parity means parity bit should make total 1's odd

    assign data = frame_reg[8:1];
    assign valid = (state == STOP && !timeout_flag && start_bit_ok && parity_ok && stop_bit_ok);
    assign err = ((state == STOP && !timeout_flag && !(start_bit_ok && parity_ok && stop_bit_ok)) || timeout_flag) && !valid;

endmodule
