## 设计思路

1. **输入输出分析**：
   - 输入：clk(1)、rst_n(1)、instr(32)、valid(1)、dbg_addr(5)
   - 输出：alu_result(32)、illegal(1)、dbg_data(32)
   - 寄存器输出：alu_result、illegal（在valid上升沿更新）
   - 组合输出：dbg_data（直接读寄存器堆）

2. **核心组件**：
   - 32×32位寄存器堆（x0恒为0）
   - 指令译码逻辑
   - ALU（支持所有RV32I基本运算）
   - 控制逻辑判断指令合法性

3. **复位与时序**：
   - 复位：所有寄存器清零，alu_result=0，illegal=0
   - valid上升沿：译码执行，更新寄存器和输出；否则保持不变

```verilog
module rv32_datapath (
    input clk,
    input rst_n,
    input [31:0] instr,
    input valid,
    output [31:0] alu_result,
    output illegal,
    input [4:0] dbg_addr,
    output [31:0] dbg_data
);

    // 寄存器堆
    reg [31:0] regfile [0:31];

    // 内部信号
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire [6:0] funct7;
    wire [4:0] rs1_addr, rs2_addr, rd_addr;
    wire [31:0] rs1_data, rs2_data;
    wire [31:0] immediate;
    wire [31:0] alu_op1, alu_op2;
    wire [6:0] alu_funct7;
    wire [2:0] alu_funct3;
    wire is_r_type, is_i_type;
    wire [31:0] alu_out;
    wire current_illegal;

    // 指令字段提取
    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];
    assign rs1_addr = instr[19:15];
    assign rs2_addr = instr[24:20];
    assign rd_addr = instr[11:7];

    // 立即数生成
    assign immediate = {{20{instr[31]}}, instr[31:20]}; // I-type immediate

    // 选择ALU操作数
    assign alu_op1 = (is_r_type) ? rs1_data : rs1_data;
    assign alu_op2 = (is_r_type) ? rs2_data : immediate;
    assign alu_funct7 = (is_r_type) ? funct7 : 7'b0000000;
    assign alu_funct3 = funct3;
    assign is_r_type = (opcode == 7'b0110011);
    assign is_i_type = (opcode == 7'b0010011);

    // 寄存器堆读取（组合逻辑）
    assign rs1_data = (rs1_addr == 5'b0) ? 32'b0 : regfile[rs1_addr];
    assign rs2_data = (rs2_addr == 5'b0) ? 32'b0 : regfile[rs2_addr];
    assign dbg_data = (dbg_addr == 5'b0) ? 32'b0 : regfile[dbg_addr];

    // ALU实现
    wire [3:0] alu_control;
    assign alu_control = {alu_funct7[5], alu_funct3};

    always @(*) begin
        casez({alu_funct7[5], alu_funct3})
            4'b0_000: alu_out = alu_op1 + alu_op2;  // ADD / ADDI
            4'b1_000: alu_out = alu_op1 - alu_op2;  // SUB
            4'b0_001: alu_out = alu_op1 << alu_op2[4:0];  // SLL / SLLI
            4'b0_010: alu_out = ($signed(alu_op1) < $signed(alu_op2)) ? 32'h1 : 32'h0;  // SLT / SLTI
            4'b0_011: alu_out = (alu_op1 < alu_op2) ? 32'h1 : 32'h0;  // SLTU / SLTIU
            4'b0_100: alu_out = alu_op1 ^ alu_op2;  // XOR / XORI
            4'b0_101: alu_out = (alu_funct7 == 7'b0100000) ? (alu_op1 >>> alu_op2[4:0]) : (alu_op1 >> alu_op2[4:0]);  // SRAI / SRLI or SRA / SRL
            4'b0_110: alu_out = alu_op1 | alu_op2;  // OR / ORI
            4'b0_111: alu_out = alu_op1 & alu_op2;  // AND / ANDI
            default: alu_out = 32'h0;
        endcase
    end

    // 指令合法性检查
    wire is_add = (opcode == 7'b0110011) && (funct3 == 3'b000) && (funct7 == 7'b0000000);
    wire is_sub = (opcode == 7'b0110011) && (funct3 == 3'b000) && (funct7 == 7'b0100000);
    wire is_sll = (opcode == 7'b0110011) && (funct3 == 3'b001) && (funct7 == 7'b0000000);
    wire is_slt = (opcode == 7'b0110011) && (funct3 == 3'b010) && (funct7 == 7'b0000000);
    wire is_sltu = (opcode == 7'b0110011) && (funct3 == 3'b011) && (funct7 == 7'b0000000);
    wire is_xor = (opcode == 7'b0110011) && (funct3 == 3'b100) && (funct7 == 7'b0000000);
    wire is_or = (opcode == 7'b0110011) && (funct3 == 3'b110) && (funct7 == 7'b0000000);
    wire is_and = (opcode == 7'b0110011) && (funct3 == 3'b111) && (funct7 == 7'b0000000);
    wire is_srl = (opcode == 7'b0110011) && (funct3 == 3'b101) && (funct7 == 7'b0000000);
    wire is_sra = (opcode == 7'b0110011) && (funct3 == 3'b101) && (funct7 == 7'b0100000);

    wire is_addi = (opcode == 7'b0010011) && (funct3 == 3'b000);
    wire is_slti = (opcode == 7'b0010011) && (funct3 == 3'b010);
    wire is_sltiu = (opcode == 7'b0010011) && (funct3 == 3'b011);
    wire is_xori = (opcode == 7'b0010011) && (funct3 == 3'b100);
    wire is_ori = (opcode == 7'b0010011) && (funct3 == 3'b110);
    wire is_andi = (opcode == 7'b0010011) && (funct3 == 3'b111);
    wire is_slli = (opcode == 7'b0010011) && (funct3 == 3'b001) && (instr[31:25] == 7'b0000000);
    wire is_srli = (opcode == 7'b0010011) && (funct3 == 3'b101) && (instr[31:25] == 7'b0000000);
    wire is_srai = (opcode == 7'b0010011) && (funct3 == 3'b101) && (instr[31:25] == 7'b0100000);

    assign current_illegal = !(
        is_add || is_sub || is_sll || is_slt || is_sltu || is_xor || is_or || is_and || 
        is_srl || is_sra || is_addi || is_slti || is_sltiu || is_xori || is_ori || 
        is_andi || is_slli || is_srli || is_srai
    );

    // 寄存器堆写入控制
    wire write_enable = valid && !current_illegal && (rd_addr != 5'b0);
    wire [31:0] write_data = alu_out;

    // 寄存器堆写入（时序逻辑）
    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1) begin
                regfile[i] <= 32'b0;
            end
        end else if (write_enable) begin
            regfile[rd_addr] <= write_data;
        end
    end

    // 输出寄存器
    reg [31:0] alu_result_reg;
    reg illegal_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            alu_result_reg <= 32'b0;
            illegal_reg <= 1'b0;
        end else if (valid) begin
            alu_result_reg <= current_illegal ? 32'b0 : alu_out;
            illegal_reg <= current_illegal;
        end
    end

    assign alu_result = alu_result_reg;
    assign illegal = illegal_reg;

endmodule
