            timeout_cnt <= 0;
            timeout_flag <= 1'b0;
        end else begin
            if (state != IDLE && timeout_cnt < TIMEOUT) begin
                timeout_cnt <= timeout_cnt + 1;
            end else if (timeout_cnt >= TIMEOUT) begin
                timeout_flag <= 1'b1;
            end else begin
                timeout_cnt <= timeout_cnt;
                timeout_flag <= 1'b0;
            end
        end
    end

    // 主状态机
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_count <= 0;
            shift_reg <= 0;
            parity_bit <= 1'b0;
