    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 8'h00;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
        end else begin
            valid_reg <= 1'b0;
            err_reg <= 1'b0;

