            if (prev_ps2_clk && !sync_ps2_clk) begin // falling edge of ps2_clk
                timeout_cnt <= 10'd0;

                case (state)
                    3'd0: begin // idle - waiting for start bit
                        if (sync_ps2_data == 1'b0) begin
                            state <= 3'd1;
                            bit_cnt <= 4'd0;
                            shift_reg <= 8'b0;
                            in_frame <= 1'b1;
                        end
                    end
                    3'd1: begin // start bit check
                        if (sync_ps2_data == 1'b0) begin
                            state <= 3'd2;
                            bit_cnt <= 4'd0;
                        end else begin
                            state <= 3'd0;
                            in_frame <= 1'b0;
                            rx_err <= 1'b1;
                        end
                    end
                    3'd2: begin // data bits
                        shift_reg <= {sync_ps2_data, shift_reg[7:1]};
                        bit_cnt <= bit_cnt + 1'b1;
                        if (bit_cnt == 4'd7) begin
                            state <= 3'd3; // move to parity
                        end
                    end
                    3'd3: begin // parity bit
                        // Calculate odd parity of the 8 data bits
                        rx_data <= shift_reg;
                        if (^shift_reg != sync_ps2_data) begin
                            state <= 3'd0;
                            in_frame <= 1'b0;
                            rx_err <= 1'b1;
                        end else begin
                            state <= 3'd4; // move to stop bit
                        end
                    end
                    3'd4: begin // stop bit
                        if (sync_ps2_data == 1'b1) begin
                            rx_valid <= 1'b1;
                        end else begin
                            rx_err <= 1'b1;
                        end
                        state <= 3'd0;
                        in_frame <= 1'b0;
                    end
                    default: begin
                        state <= 3'd0;
                        in_frame <= 1'b0;
                    end
                endcase
            end else begin
                // Check for timeout when not in frame or during frame
                if (in_frame || (state != 3'd0)) begin
                    if (timeout_cnt < TIMEOUT) begin
                        timeout_cnt <= timeout_cnt + 1'b1;
                    end else begin
                        // Timeout occurred
                        state <= 3'd0;
                        in_frame <= 1'b0;
                        rx_err <= 1'b1;
                    end
                end else begin
                    timeout_cnt <= 10'd0;
                end
            end
        end
    end

