    reg ps2_data_d1, ps2_data_d2;
    wire ps2_clk_negedge;

    // 状态机
    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter RECEIVING = 2'b01;

    // 计数器
    reg [3:0] bit_count;
    reg [9:0] timeout_count;

    // 移位寄存器存储11位数据
    reg [10:0] rx_shift_reg;

    assign ps2_clk_negedge = ps2_clk_d1 & ~ps2_clk_d2;
    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

