        if (!rst_n) begin
            ps2_clk_d1 <= 1'b1;
            ps2_clk_d2 <= 1'b1;
            ps2_data_d1 <= 1'b1;
            ps2_data_d2 <= 1'b1;
            state <= IDLE;
            bit_count <= 4'd0;
            timeout_count <= 10'd0;
            rx_shift_reg <= 11'b0;
            data_reg <= 8'h0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
        end else begin
            ps2_clk_d1 <= ps2_clk;
            ps2_clk_d2 <= ps2_clk_d1;
            ps2_data_d1 <= ps2_data;
            ps2_data_d2 <= ps2_data_d1;

            valid_reg <= 1'b0;
            err_reg <= 1'b0;

            case (state)
                IDLE: begin
                    if (ps2_clk_negedge && ps2_data_d2 == 1'b0) begin  // 检测起始位
                        state <= RECEIVING;
                        bit_count <= 4'd0;
                        timeout_count <= 10'd0;
                        rx_shift_reg <= {10'b0, ps2_data_d2};
                    end
                end

                RECEIVING: begin
                    if (ps2_clk_negedge) begin
                        rx_shift_reg <= {rx_shift_reg[9:0], ps2_data_d2};
                        bit_count <= bit_count + 1'b1;
                        timeout_count <= 10'd0;  // 重置超时计数

                        if (bit_count == 4'd10) begin  // 接收完11位
                            // 检查停止位是否为1
                            if (rx_shift_reg[10] != 1'b1) begin
                                err_reg <= 1'b1;
                            end else begin
                                // 验证奇校验
                                // 计算前9位(起始位+8数据位)的异或结果应等于校验位
                                reg parity_check;
                                parity_check = rx_shift_reg[0];  // 起始位
