                                    parity_check = parity_check ^ rx_shift_reg[i];
                                end

                                if (parity_check != rx_shift_reg[9]) begin  // 校验错误
                                    err_reg <= 1'b1;
                                end else begin  // 成功接收
                                    data_reg <= rx_shift_reg[8:1];  // 数据位
                                    valid_reg <= 1'b1;
                                end
                            end
                            state <= IDLE;
                        end
                    end else begin
                        timeout_count <= timeout_count + 1'b1;
                        if (timeout_count >= TIMEOUT) begin
                            err_reg <= 1'b1;
                            state <= IDLE;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

