```verilog
module ps2_rx #(parameter TIMEOUT = 200) (
    input clk,
    input rst_n,
    input ps2_clk,
    input ps2_data,
    output [7:0] data,
    output valid,
    output err
);

    reg [1:0] ps2_clk_sync;
    reg [1:0] ps2_data_sync;
    reg [2:0] bit_cnt;
    reg [7:0] data_reg;
    reg [8:0] parity_data;
    reg valid_reg;
    reg err_reg;
    reg [31:0] timeout_cnt;
    reg in_receiving;

    wire ps2_clk_negedge = (ps2_clk_sync[1:0] == 2'b10);

    always @(posedge clk) begin
        if (!rst_n) begin
            ps2_clk_sync <= 2'b11;
            ps2_data_sync <= 2'b11;
            bit_cnt <= 3'd0;
            data_reg <= 8'h0;
            parity_data <= 9'h0;
            valid_reg <= 1'b0;
            err_reg <= 1'b0;
            timeout_cnt <= 32'd0;
            in_receiving <= 1'b0;
        end else begin
            ps2_clk_sync <= {ps2_clk_sync[0], ps2_clk};
            ps2_data_sync <= {ps2_data_sync[0], ps2_data};

            valid_reg <= 1'b0;
            err_reg <= 1'b0;

            if (ps2_clk_negedge) begin
                timeout_cnt <= 32'd0;
                if (!in_receiving) begin
                    // Check for start bit (ps2_data should be 0)
                    if (ps2_data_sync[1] == 1'b0) begin
                        in_receiving <= 1'b1;
                        bit_cnt <= 3'd0;
                        parity_data <= 1'b0;  // Start with 0 for start bit
                    end
                end else begin
                    // In receiving state, collect bits
                    case (bit_cnt)
                        3'd0: begin
                            parity_data <= {parity_data[7:0], ps2_data_sync[1]};
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                        3'd1, 3'd2, 3'd3, 3'd4, 3'd5, 3'd6, 3'd7: begin
                            parity_data <= {parity_data[7:0], ps2_data_sync[1]};
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                        3'd8: begin
                            // Collect parity bit
                            parity_data <= {parity_data[7:0], ps2_data_sync[1]};
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                        3'd9: begin
                            // Check stop bit and parity
                            if (ps2_data_sync[1] == 1'b1) begin
                                // Stop bit is 1, check odd parity
                                // Count number of 1s in D0-D7 + P
                                if (^parity_data == 1'b1) begin  // Odd parity correct
                                    data_reg <= {ps2_data_sync[1], parity_data[7:1]}; // D7-D0
                                    valid_reg <= 1'b1;
                                end else begin
                                    err_reg <= 1'b1;
                                end
                            end else begin
                                // Stop bit is 0, error
                                err_reg <= 1'b1;
                            end
                            in_receiving <= 1'b0;
                        end
                    endcase
                end
            end else begin
                // Handle timeout
                if (in_receiving) begin
                    timeout_cnt <= timeout_cnt + 1'b1;
                    if (timeout_cnt >= TIMEOUT - 1) begin
                        in_receiving <= 1'b0;
                        timeout_cnt <= 32'd0;
                    end
                end
            end
        end
    end

    assign data = data_reg;
    assign valid = valid_reg;
    assign err = err_reg;

