    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [31:0] reg0, reg1, reg2;
    reg [31:0] write_reg_data;
    reg [7:0] write_addr;
    reg write_valid;
    reg read_valid;
    reg [7:0] read_addr;
    reg [31:0] read_data;
    reg [1:0] write_resp;
    reg [1:0] read_resp;

    // Write address channel state machine
    reg [1:0] aw_state;
    parameter AW_IDLE = 2'b00, AW_WAIT_W = 2'b01, AW_WAIT_B = 2'b10;

    // Write data channel state machine
    reg [1:0] w_state;
    parameter W_IDLE = 2'b00, W_WAIT_AW = 2'b01, W_WAIT_B = 2'b10;

    // Write response channel state machine
    reg [1:0] b_state;
    parameter B_IDLE = 2'b00, B_RESP = 2'b01;

    // Read address channel state machine
    reg [1:0] ar_state;
    parameter AR_IDLE = 2'b00, AR_WAIT_R = 2'b01;

    // Read data channel state machine
    reg [1:0] r_state;
    parameter R_IDLE = 2'b00, R_RESP = 2'b01;

    // Update registers on write
    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
        end else if (write_valid && (write_addr[7:2] == 6'h00)) begin
            if (write_addr[1:0] == 2'h0) begin
                if (wstrb[0]) reg0[7:0] <= write_reg_data[7:0];
                if (wstrb[1]) reg0[15:8] <= write_reg_data[15:8];
                if (wstrb[2]) reg0[23:16] <= write_reg_data[23:16];
                if (wstrb[3]) reg0[31:24] <= write_reg_data[31:24];
            end else if (write_addr[1:0] == 2'h1) begin
                if (wstrb[0]) reg1[7:0] <= write_reg_data[7:0];
                if (wstrb[1]) reg1[15:8] <= write_reg_data[15:8];
                if (wstrb[2]) reg1[23:16] <= write_reg_data[23:16];
                if (wstrb[3]) reg1[31:24] <= write_reg_data[31:24];
            end else if (write_addr[1:0] == 2'h2) begin
                if (wstrb[0]) reg2[7:0] <= write_reg_data[7:0];
                if (wstrb[1]) reg2[15:8] <= write_reg_data[15:8];
                if (wstrb[2]) reg2[23:16] <= write_reg_data[23:16];
                if (wstrb[3]) reg2[31:24] <= write_reg_data[31:24];
            end
        end
    end

    // Write address channel FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            aw_state <= AW_IDLE;
            write_addr <= 8'h00;
            write_reg_data <= 32'h0;
            write_valid <= 1'b0;
        end else case (aw_state)
            AW_IDLE: begin
                if (awvalid) begin
                    write_addr <= awaddr;
                    aw_state <= AW_WAIT_W;
                    write_valid <= 1'b0;
                end
            end
            AW_WAIT_W: begin
                if (wvalid) begin
                    write_reg_data <= wdata;
                    write_valid <= 1'b1;
                    aw_state <= AW_WAIT_B;
                end
            end
            AW_WAIT_B: begin
                if (bready && bvalid) begin
                    aw_state <= AW_IDLE;
                end
            end
        endcase
    end

    // Write data channel FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            w_state <= W_IDLE;
        end else case (w_state)
            W_IDLE: begin
                if (wvalid) begin
                    if (awvalid) begin
                        write_addr <= awaddr;
                        write_reg_data <= wdata;
                        write_valid <= 1'b1;
                        w_state <= W_WAIT_B;
                    end else begin
                        w_state <= W_WAIT_AW;
                    end
                end
            end
            W_WAIT_AW: begin
                if (awvalid) begin
                    write_addr <= awaddr;
                    write_valid <= 1'b1;
                    w_state <= W_WAIT_B;
                end
            end
            W_WAIT_B: begin
                if (bready && bvalid) begin
                    w_state <= W_IDLE;
                end
            end
        endcase
    end

    // Write response generation
    wire [1:0] write_resp_internal;
    assign write_resp_internal = 
        (write_addr >= 8'h10) ? 2'b11 :  // DECERR for addresses >= 0x10 but not in register range
        ((write_addr[7:2] == 6'h03) ? 2'b10 :  // SLVERR for write to ID register
         2'b00);  // OKAY otherwise

    always @(posedge clk) begin
        if (!rst_n) begin
            write_resp <= 2'b00;
        end else if (write_valid) begin
            write_resp <= write_resp_internal;
        end
    end

    // Write response channel FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            b_state <= B_IDLE;
        end else case (b_state)
            B_IDLE: begin
                if (write_valid) begin
                    b_state <= B_RESP;
                end
            end
            B_RESP: begin
                if (bready && bvalid) begin
                    b_state <= B_IDLE;
                    write_valid <= 1'b0;  // Clear after response is accepted
                end
            end
        endcase
    end

    // Read address channel FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            ar_state <= AR_IDLE;
            read_addr <= 8'h00;
            read_valid <= 1'b0;
        end else case (ar_state)
            AR_IDLE: begin
                if (arvalid) begin
                    read_addr <= araddr;
                    read_valid <= 1'b1;
                    ar_state <= AR_WAIT_R;
                end
            end
            AR_WAIT_R: begin
                if (rready && rvalid) begin
                    ar_state <= AR_IDLE;
                    read_valid <= 1'b0;
                end
            end
        endcase
    end

    // Read data preparation
    wire [1:0] read_resp_internal;
    reg [31:0] read_data_internal;

    always @(*) begin
        case ({read_addr[7:2], read_addr[1:0]})
            8'h00: read_data_internal = reg0;
            8'h04: read_data_internal = reg1;
            8'h08: read_data_internal = reg2;
            8'h0C: read_data_internal = 32'h5A5A0003;  // ID register
            default: read_data_internal = 32'h0;
        endcase

        if (read_addr >= 8'h10) begin
            read_resp_internal = 2'b11;  // DECERR
            read_data_internal = 32'h0;
        end else begin
            read_resp_internal = 2'b00;  // OKAY
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            read_data <= 32'h0;
            read_resp <= 2'b00;
        end else if (read_valid) begin
            read_data <= read_data_internal;
            read_resp <= read_resp_internal;
        end
    end

    // Read response channel FSM
    always @(posedge clk) begin
        if (!rst_n) begin
            r_state <= R_IDLE;
        end else case (r_state)
            R_IDLE: begin
                if (read_valid) begin
                    r_state <= R_RESP;
                end
            end
            R_RESP: begin
                if (rready && rvalid) begin
                    r_state <= R_IDLE;
                end
            end
        endcase
    end

    // Output assignments
    assign awready = (aw_state == AW_IDLE) || (aw_state == AW_WAIT_W && wvalid);
    assign wready = (w_state == W_IDLE) || (w_state == W_WAIT_AW && awvalid) || (w_state == W_WAIT_B);
    assign bvalid = (b_state == B_RESP);
    assign bresp = write_resp;
    assign arready = (ar_state == AR_IDLE);
    assign rvalid = (r_state == R_RESP);
    assign rdata = read_data;
    assign rresp = read_resp;

endmodule
