    reg write_transaction_active;
    reg [7:0] write_addr_latched;
    reg [31:0] write_data_latched;
    reg [3:0] write_strb_latched;
    reg write_aw_received;
    reg write_w_received;

    // Read transaction state
    reg read_transaction_active;
    reg [7:0] read_addr_latched;

