);

    // Internal registers
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] write_addr_reg;
    reg write_addr_valid;
    reg read_addr_valid;
    reg [7:0] read_addr_reg;
    reg [31:0] read_data_reg;
    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done;
    reg read_done;

    // Write channel state
    reg write_state_0, write_state_1;  // AW and W have arrived

    // Response types
    parameter RESP_OKAY = 2'b00;
    parameter RESP_EXOKAY = 2'b01;
    parameter RESP_SLVERR = 2'b10;
    parameter RESP_DECERR = 2'b11;

    // Register addresses
    parameter REG0_ADDR = 8'h00;
    parameter REG1_ADDR = 8'h04;
    parameter REG2_ADDR = 8'h08;
    parameter ID_REG_ADDR = 8'h0C;
    parameter MIN_ACCESS_ADDR = 8'h00;
    parameter MAX_ACCESS_ADDR = 8'h0F;

    // Update write state based on AWVALID and WVALID
    always @(posedge clk) begin
        if (!rst_n) begin
            write_state_0 <= 1'b0;
            write_state_1 <= 1'b0;
        end else begin
            if (awvalid && awready)
                write_state_0 <= 1'b1;
            if (wvalid && wready)
                write_state_1 <= 1'b1;

            // Reset when both AW and W are processed
            if (bvalid && bready) begin
                write_state_0 <= 1'b0;
                write_state_1 <= 1'b0;
            end
        end
    end

    // AWREADY: ready when we can accept the address
    assign awready = !write_state_0 || (wvalid && !write_state_1);

    // WREADY: ready when we can accept the data
    assign wready = !write_state_1 || (awvalid && !write_state_0);

    // B channel signals
    always @(posedge clk) begin
        if (!rst_n) begin
            bvalid <= 1'b0;
            write_resp_reg <= RESP_OKAY;
            write_done <= 1'b0;
        end else begin
            if (awready && awvalid && wready && wvalid && !write_done) begin
                // Process write request
                write_addr_reg <= {awaddr[7:2], 2'b00};  // Align to 32-bit boundary
                write_done <= 1'b1;

                // Determine response
                case (awaddr[7:2])
                    6'h00: write_resp_reg <= RESP_OKAY;  // REG0
                    6'h01: write_resp_reg <= RESP_OKAY;  // REG1
                    6'h02: write_resp_reg <= RESP_OKAY;  // REG2
                    6'h03: write_resp_reg <= RESP_SLVERR; // ID register is read-only
                    default: write_resp_reg <= RESP_DECERR; // Out of range
                endcase
            end

            if (bready && bvalid)
                bvalid <= 1'b0;
            else if (write_done && !bvalid)
                bvalid <= 1'b1;

            if (bready && bvalid)
