module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // Internal registers
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] write_addr_reg;
    reg write_addr_valid;
    reg read_addr_valid;
    reg [7:0] read_addr_reg;
    reg [31:0] read_data_reg;
    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done;
    reg read_done;

    // Write channel state
    reg write_state_0, write_state_1;  // AW and W have arrived

    // Response types
    parameter RESP_OKAY = 2'b00;
    parameter RESP_EXOKAY = 2'b01;
    parameter RESP_SLVERR = 2'b10;
    parameter RESP_DECERR = 2'b11;

    // Register addresses
    parameter REG0_ADDR = 8'h00;
    parameter REG1_ADDR = 8'h04;
    parameter REG2_ADDR = 8'h08;
    parameter ID_REG_ADDR = 8'h0C;
    parameter MIN_ACCESS_ADDR = 8'h00;
    parameter MAX_ACCESS_ADDR = 8'h0F;

    // Update write state based on AWVALID and WVALID
    always @(posedge clk) begin
        if (!rst_n) begin
            write_state_0 <= 1'b0;
            write_state_1 <= 1'b0;
        end else begin
            if (awvalid && awready)
                write_state_0 <= 1'b1;
            if (wvalid && wready)
                write_state_1 <= 1'b1;

            // Reset when both AW and W are processed
            if (bvalid && bready) begin
                write_state_0 <= 1'b0;
                write_state_1 <= 1'b0;
            end
        end
    end

    // AWREADY: ready when we can accept the address
    assign awready = !write_state_0 || (wvalid && !write_state_1);

    // WREADY: ready when we can accept the data
    assign wready = !write_state_1 || (awvalid && !write_state_0);

    // B channel signals
    always @(posedge clk) begin
        if (!rst_n) begin
            bvalid <= 1'b0;
            write_resp_reg <= RESP_OKAY;
            write_done <= 1'b0;
        end else begin
            if (awready && awvalid && wready && wvalid && !write_done) begin
                // Process write request
                write_addr_reg <= {awaddr[7:2], 2'b00};  // Align to 32-bit boundary
                write_done <= 1'b1;

                // Determine response
                case (awaddr[7:2])
                    6'h00: write_resp_reg <= RESP_OKAY;  // REG0
                    6'h01: write_resp_reg <= RESP_OKAY;  // REG1
                    6'h02: write_resp_reg <= RESP_OKAY;  // REG2
                    6'h03: write_resp_reg <= RESP_SLVERR; // ID register is read-only
                    default: write_resp_reg <= RESP_DECERR; // Out of range
                endcase
            end

            if (bready && bvalid)
                bvalid <= 1'b0;
            else if (write_done && !bvalid)
                bvalid <= 1'b1;

            if (bready && bvalid)
                write_done <= 1'b0;
        end
    end

    assign bresp = write_resp_reg;

    // Write registers based on address and strobe
    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
        end else if (awready && awvalid && wready && wvalid) begin
            case (awaddr[7:2])
                6'h00: begin  // REG0
                    if (write_resp_reg == RESP_OKAY) begin
                        if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                    end
                end
                6'h01: begin  // REG1
                    if (write_resp_reg == RESP_OKAY) begin
                        if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                    end
                end
                6'h02: begin  // REG2
                    if (write_resp_reg == RESP_OKAY) begin
                        if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                        if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                        if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                        if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                    end
                end
                default: ; // Do nothing for invalid addresses or read-only registers
            endcase
        end
    end

    // Read channel
    always @(posedge clk) begin
        if (!rst_n) begin
            read_addr_reg <= 8'h00;
            read_addr_valid <= 1'b0;
            rvalid <= 1'b0;
            read_data_reg <= 32'h0;
            read_resp_reg <= RESP_OKAY;
            read_done <= 1'b0;
        end else begin
            if (arvalid && arready) begin
                read_addr_reg <= {araddr[7:2], 2'b00};  // Align to 32-bit
                read_addr_valid <= 1'b1;

                // Determine response and data
                case (araddr[7:2])
                    6'h00: begin  // REG0
                        read_data_reg <= reg0;
                        read_resp_reg <= RESP_OKAY;
                    end
                    6'h01: begin  // REG1
                        read_data_reg <= reg1;
                        read_resp_reg <= RESP_OKAY;
                    end
                    6'h02: begin  // REG2
                        read_data_reg <= reg2;
                        read_resp_reg <= RESP_OKAY;
                    end
                    6'h03: begin  // ID register
                        read_data_reg <= 32'h5A5A0003;
                        read_resp_reg <= RESP_OKAY;
                    end
                    default: begin  // Invalid address
                        read_data_reg <= 32'h0;
                        read_resp_reg <= RESP_DECERR;
                    end
                endcase
            end

            if (read_addr_valid && !read_done) begin
                rvalid <= 1'b1;
                read_done <= 1'b1;
            end

            if (rready && rvalid) begin
                rvalid <= 1'b0;
                read_addr_valid <= 1'b0;
                read_done <= 1'b0;
            end
        end
    end

    assign arready = !(read_addr_valid && !read_done);

    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

