    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // Internal signals
    reg [31:0] reg0, reg1, reg2;
    reg [1:0] write_state, read_state;
    reg [31:0] read_data_reg;
    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done, read_done;
    reg [31:0] pending_write_data;
    reg [3:0] pending_write_strb;
    reg [7:0] pending_write_addr;
    reg pending_write_valid;
    reg [7:0] pending_read_addr;
    reg pending_read_valid;

    // Register addresses
    parameter REG0_ADDR = 8'h00;
    parameter REG1_ADDR = 8'h04;
    parameter REG2_ADDR = 8'h08;
    parameter REG_ID_ADDR = 8'h0C;
    parameter ID_VALUE = 32'h5A5A0003;

    // AXI Response types
    parameter AXI_OKAY   = 2'b00;
    parameter AXI_EXOKAY = 2'b01;
    parameter AXI_SLVERR = 2'b10;
    parameter AXI_DECERR = 2'b11;

    // Write state machine states
    parameter WRITE_IDLE     = 2'd0;
    parameter WRITE_WAIT_W   = 2'd1;
    parameter WRITE_RESP     = 2'd2;

    // Read state machine states
    parameter READ_IDLE      = 2'd0;
    parameter READ_RESP      = 2'd1;

    // AWREADY and WREADY control
    assign awready = (write_state == WRITE_IDLE) && (!pending_write_valid || (wvalid && wready));
    assign wready = (write_state == WRITE_IDLE) ? 
                   (awvalid && awready) : 
                   ((write_state == WRITE_WAIT_W) ? 1'b1 : 1'b0);

    // ARREADY control
    assign arready = (read_state == READ_IDLE) && !pending_read_valid;

    // B channel (write response)
    assign bvalid = (write_state == WRITE_RESP);
    assign bresp = write_resp_reg;

    // R channel (read data/response)
    assign rvalid = (read_state == READ_RESP);
    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            write_state <= WRITE_IDLE;
            read_state <= READ_IDLE;
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
            write_done <= 1'b0;
            read_done <= 1'b0;
            read_data_reg <= 32'h0;
            read_resp_reg <= AXI_OKAY;
            write_resp_reg <= AXI_OKAY;
            pending_write_valid <= 1'b0;
            pending_read_valid <= 1'b0;
        end else begin
            // Handle write transaction
            case (write_state)
                WRITE_IDLE: begin
                    if (awvalid && awready && wvalid && wready) begin
                        // Both AW and W are available
                        write_resp_reg <= get_write_response(awaddr);
                        if (get_write_response(awaddr) == AXI_OKAY) begin
                            // Perform write operation
                            perform_write(awaddr, wdata, wstrb);
                        end
                        write_state <= WRITE_RESP;
                    end else if (awvalid && awready && !wvalid) begin
                        // AW arrives first, store it
                        pending_write_addr <= awaddr;
                        pending_write_valid <= 1'b1;
                        write_state <= WRITE_WAIT_W;
                    end else if (wvalid && wready && !awvalid) begin
                        // W arrives first, store it
                        pending_write_data <= wdata;
                        pending_write_strb <= wstrb;
                        pending_write_valid <= 1'b1;
                        write_state <= WRITE_WAIT_W;
                    end
                end

                WRITE_WAIT_W: begin
                    if (awvalid && awready && wvalid && wready && pending_write_valid) begin
                        // Both AW and W are now available
                        write_resp_reg <= get_write_response(pending_write_addr);
                        if (get_write_response(pending_write_addr) == AXI_OKAY) begin
                            perform_write(pending_write_addr, wdata, wstrb);
                        end
                        pending_write_valid <= 1'b0;
                        write_state <= WRITE_RESP;
                    end else if (awvalid && awready && pending_write_valid) begin
                        // AW matches stored W
                        write_resp_reg <= get_write_response(pending_write_addr);
                        if (get_write_response(pending_write_addr) == AXI_OKAY) begin
                            perform_write(pending_write_addr, pending_write_data, pending_write_strb);
                        end
                        pending_write_valid <= 1'b0;
                        write_state <= WRITE_RESP;
                    end else if (wvalid && wready && pending_write_valid) begin
                        // W matches stored AW
                        write_resp_reg <= get_write_response(awaddr);
                        if (get_write_response(awaddr) == AXI_OKAY) begin
                            perform_write(awaddr, wdata, wstrb);
                        end
                        pending_write_valid <= 1'b0;
                        write_state <= WRITE_RESP;
                    end
                end

                WRITE_RESP: begin
                    if (bready) begin
                        write_state <= WRITE_IDLE;
                    end
                end

                default: write_state <= WRITE_IDLE;
            endcase

            // Handle read transaction
            case (read_state)
                READ_IDLE: begin
                    if (arvalid && arready) begin
