    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done, read_done;
    reg [31:0] pending_write_data;
    reg [3:0] pending_write_strb;
    reg [7:0] pending_write_addr;
    reg pending_write_valid;
    reg [7:0] pending_read_addr;
    reg pending_read_valid;

