                        awaddr_reg <= awaddr;
                        write_state <= 2'b10; // Waiting for W
                    end else if (wvalid) begin
                        wdata_reg <= wdata;
                        wstrb_reg <= wstrb;
                        write_state <= 2'b11; // Waiting for AW
                    end
                end

                2'b01: begin // Both AW and W received
                    write_req_valid <= 1'b1;
                    write_state <= 2'b10; // Process write
                end

                2'b10: begin // Processing write
                    write_req_valid <= 1'b0;
                    bvalid_reg <= 1'b1;

                    // Perform write operation based on address and byte enables
                    case (awaddr_reg[3:2])
                        2'b00: begin // Offset 0x00
                            if (wstrb_reg[0]) reg_00[7:0] <= wdata_reg[7:0];
                            if (wstrb_reg[1]) reg_00[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg_00[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg_00[31:24] <= wdata_reg[31:24];
