                            if (wstrb_reg[1]) reg_08[15:8] <= wdata_reg[15:8];
                            if (wstrb_reg[2]) reg_08[23:16] <= wdata_reg[23:16];
                            if (wstrb_reg[3]) reg_08[31:24] <= wdata_reg[31:24];
                            bresp_reg <= 2'b00; // OKAY
                        end
                        2'b11: begin // Offset 0x0C - ID register is read-only
                            bresp_reg <= 2'b10; // SLVERR
                        end
                        default: begin
                            bresp_reg <= 2'b11; // DECERR
                        end
