    always @(posedge clk) begin
        if (!rst_n) begin
            read_state <= 2'b00;
            araddr_reg <= 8'h00;
            rvalid_reg <= 1'b0;
            rdata_reg <= 32'h00000000;
            rresp_reg <= 2'b00;
        end else begin
            case (read_state)
                2'b00: begin // Idle
                    if (arvalid) begin
                        araddr_reg <= araddr;
                        read_state <= 2'b01;
                    end
                end

                2'b01: begin // Request captured
                    rvalid_reg <= 1'b1;

                    // Determine read data and response
                    case (araddr_reg[7:2])
                        6'h00: begin // Offset 0x00
                            rdata_reg <= reg_00;
                            rresp_reg <= 2'b00; // OKAY
                        end
                        6'h01: begin // Offset 0x04
