    always @(posedge clk) begin
        if (!rst_n) begin
            read_state <= 2'b00;
            araddr_reg <= 8'h00;
            rvalid_reg <= 1'b0;
            rdata_reg <= 32'h00000000;
            rresp_reg <= 2'b00;
        end else begin
            case (read_state)
