    assign awready = (write_state == 2'b00 || write_state == 2'b10) ? 1'b1 : 1'b0;
    assign wready = (write_state == 2'b00 || write_state == 2'b11) ? 1'b1 : 1'b0;
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;
    assign arready = (read_state == 2'b00) ? 1'b1 : 1'b0;
