    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // 下一状态逻辑
    always @(*) begin
        case (state)
            IDLE: begin
