                    next_state = IDLE;
                end else begin
                    next_state = READ;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    // 地址锁存
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            awaddr_reg <= 8'h00;
            araddr_reg <= 8'h00;
