                rvalid_reg <= 1'b1;
            end else if (state == READ && rready) begin
                rvalid_reg <= 1'b0;
            end
        end
    end

    // 输出逻辑
    assign awready = (state == IDLE && wvalid) || (state == WRITE);
    assign wready = (state == IDLE && awvalid) || (state == WRITE);
    assign arready = (state == IDLE) && !((awvalid && wvalid) || (arvalid));
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;
    assign rvalid = rvalid_reg;

