        case (araddr_reg[3:2])
            2'b00: rdata = reg0;
            2'b01: rdata = reg1;
            2'b10: rdata = reg2;
            2'b11: rdata = reg3;  // ID register
            default: rdata = 32'h00000000;
        endcase
    end

    assign rresp = rresp_reg;

