## 设计思路

**1. 信号分析**
- 输入：clk, rst_n, 各通道valid/ready信号，地址、数据、字节使能等
- 输出：各通道ready信号，响应信号，读数据等
- 寄存器：内部状态、寄存器组、响应信号等
- 组合输出：awready, wready, arready, bvalid, rvalid等

**2. 状态机设计**
- 写通道：等待AW和W都有效后处理写操作，生成B通道响应
- 读通道：根据地址生成R通道响应
- 独立处理读写通道，支持并发操作

**3. 复位行为**
- 复位时所有内部寄存器清零
- 响应默认为OKAY
- 支持AXI握手协议

**4. 寄存器映射**
- 0x00, 0x04, 0x08: 可读写寄存器
- 0x0C: 只读ID寄存器(0x5A5A0003)
- 0x10-0xFF: 地址错误区域

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state;
    reg [1:0] read_state;
    reg [31:0] reg_00;
    reg [31:0] reg_04;
    reg [31:0] reg_08;
    reg [31:0] write_addr_reg;
    reg [31:0] write_data_reg;
    reg [3:0] write_strb_reg;
    reg write_valid_reg;
    reg [31:0] read_addr_reg;
    reg read_valid_reg;
    reg [1:0] bresp_reg;
    reg [1:0] rresp_reg;
    reg bvalid_reg;
    reg rvalid_reg;

    parameter IDLE = 2'b00;
    parameter WAIT_W = 2'b01;
    parameter RESP_B = 2'b10;

    parameter RD_IDLE = 2'b00;
    parameter RD_RESP = 2'b01;

    assign awready = (write_state == IDLE) ? 1'b1 : 1'b0;
    assign wready = (write_state == IDLE || write_state == WAIT_W) ? 1'b1 : 1'b0;
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;
    assign arready = (read_state == RD_IDLE) ? 1'b1 : 1'b0;
    assign rvalid = rvalid_reg;
    assign rdata = rresp_reg == 2'b00 ? 
        (read_addr_reg[7:0] == 8'h00 ? reg_00 :
         read_addr_reg[7:0] == 8'h04 ? reg_04 :
         read_addr_reg[7:0] == 8'h08 ? reg_08 :
         read_addr_reg[7:0] == 8'h0C ? 32'h5A5A0003 : 32'h00000000) : 32'h00000000;
    assign rresp = rresp_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_state <= IDLE;
            read_state <= RD_IDLE;
            reg_00 <= 32'h0;
            reg_04 <= 32'h0;
            reg_08 <= 32'h0;
            write_addr_reg <= 32'h0;
            write_data_reg <= 32'h0;
            write_strb_reg <= 4'h0;
            write_valid_reg <= 1'b0;
            read_addr_reg <= 32'h0;
            read_valid_reg <= 1'b0;
            bresp_reg <= 2'b00;
            rresp_reg <= 2'b00;
            bvalid_reg <= 1'b0;
            rvalid_reg <= 1'b0;
        end else begin
            // Write channel state machine
            case (write_state)
                IDLE: begin
                    if (awvalid && wvalid) begin
                        write_addr_reg <= {24'h0, awaddr};
                        write_data_reg <= wdata;
                        write_strb_reg <= wstrb;
                        write_valid_reg <= 1'b1;

                        // Check if it's a read-only register
                        if (awaddr == 8'h0C) begin
                            bresp_reg <= 2'b10; // SLVERR
                        end
                        else if (awaddr >= 8'h10 && awaddr <= 8'hFF) begin
                            bresp_reg <= 2'b11; // DECERR
                        end
                        else begin
                            bresp_reg <= 2'b00; // OKAY
                        end

                        write_state <= RESP_B;
                        bvalid_reg <= 1'b1;
                    end
                    else if (awvalid && !wvalid) begin
                        write_addr_reg <= {24'h0, awaddr};
                        write_state <= WAIT_W;
                    end
                    else if (!awvalid && wvalid) begin
                        write_data_reg <= wdata;
                        write_strb_reg <= wstrb;
                        write_valid_reg <= 1'b1;
                    end
                end

                WAIT_W: begin
                    if (wvalid) begin
                        write_data_reg <= wdata;
                        write_strb_reg <= wstrb;
                        write_valid_reg <= 1'b1;

                        // Check if it's a read-only register
                        if (write_addr_reg[7:0] == 8'h0C) begin
                            bresp_reg <= 2'b10; // SLVERR
                        end
                        else if (write_addr_reg[7:0] >= 8'h10 && write_addr_reg[7:0] <= 8'hFF) begin
                            bresp_reg <= 2'b11; // DECERR
                        end
                        else begin
                            bresp_reg <= 2'b00; // OKAY
                        end

                        write_state <= RESP_B;
                        bvalid_reg <= 1'b1;
                    end
                end

                RESP_B: begin
                    if (bready) begin
                        bvalid_reg <= 1'b0;
                        write_valid_reg <= 1'b0;
                        write_state <= IDLE;
                    end
                end
            endcase

            // Perform write operation when both address and data are valid
            if (write_valid_reg && bresp_reg != 2'b10 && bresp_reg != 2'b11) begin
                if (write_addr_reg[7:0] == 8'h00) begin
                    if (write_strb_reg[0]) reg_00[7:0] <= write_data_reg[7:0];
                    if (write_strb_reg[1]) reg_00[15:8] <= write_data_reg[15:8];
                    if (write_strb_reg[2]) reg_00[23:16] <= write_data_reg[23:16];
                    if (write_strb_reg[3]) reg_00[31:24] <= write_data_reg[31:24];
                end
                else if (write_addr_reg[7:0] == 8'h04) begin
                    if (write_strb_reg[0]) reg_04[7:0] <= write_data_reg[7:0];
                    if (write_strb_reg[1]) reg_04[15:8] <= write_data_reg[15:8];
                    if (write_strb_reg[2]) reg_04[23:16] <= write_data_reg[23:16];
                    if (write_strb_reg[3]) reg_04[31:24] <= write_data_reg[31:24];
                end
