    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // 内部寄存器定义
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] write_addr_reg, read_addr_reg;
    reg [31:0] write_data_reg;
    reg [3:0] write_strb_reg;

    // 状态机定义 - 写通道
    reg [1:0] write_state, next_write_state;
    parameter WRITE_IDLE = 2'b00;
    parameter WRITE_REG = 2'b01;
    parameter WRITE_RESPOND = 2'b10;

    // 状态机定义 - 读通道
    reg [1:0] read_state, next_read_state;
    parameter READ_IDLE = 2'b00;
    parameter READ_REG = 2'b01;
    parameter READ_RESPOND = 2'b10;

