            if (write_strb_reg[1]) reg2[15:8] <= write_data_reg[15:8];
            if (write_strb_reg[2]) reg2[23:16] <= write_data_reg[23:16];
            if (write_strb_reg[3]) reg2[31:24] <= write_data_reg[31:24];
        end
