    // 地址和数据锁存
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_addr_reg <= 32'h0;
            write_data_reg <= 32'h0;
            write_strb_reg <= 4'h0;
            read_addr_reg <= 32'h0;
        end else begin
            if (awvalid && awready) begin
                write_addr_reg <= {24'h0, awaddr};
