            WRITE_RESPOND: begin
                if (bready) begin
                    next_write_state = WRITE_IDLE;
                end else begin
                    next_write_state = WRITE_RESPOND;
                end
            end
            default: next_write_state = WRITE_IDLE;
        endcase
    end

    // 读通道状态机
    always @(posedge clk or negedge rst_n) begin
