        case (read_state)
            READ_IDLE: begin
                if (arvalid) begin
                    next_read_state = READ_REG;
                end else begin
                    next_read_state = READ_IDLE;
                end
            end
            READ_REG: begin
                next_read_state = READ_RESPOND;
            end
            READ_RESPOND: begin
                if (rready) begin
                    next_read_state = READ_IDLE;
                end else begin
                    next_read_state = READ_RESPOND;
                end
            end
            default: next_read_state = READ_IDLE;
        endcase
    end

    // 输出逻辑
    assign awready = (write_state == WRITE_IDLE) && (wvalid || (awvalid && !wvalid));
    assign wready = (write_state == WRITE_IDLE) && awvalid;
    assign bvalid = (write_state == WRITE_RESPOND);
    assign arready = (read_state == READ_IDLE);
    assign rvalid = (read_state == READ_RESPOND);

    // 响应逻辑
    wire [1:0] write_resp;
    wire [1:0] read_resp;
    wire [31:0] read_data;

