    assign write_resp = ((write_addr_reg[7:4] == 4'h0) && (write_addr_reg[3:2] < 3)) ? 
                        RESP_OKAY : 
                        ((write_addr_reg[7:4] == 4'h0) && (write_addr_reg[3:2] == 3)) ? 
                        RESP_SLVERR : 
                        RESP_DECERR;

