    assign read_resp = ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] < 3)) ? 
                       RESP_OKAY : 
                       ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] == 3)) ? 
                       RESP_OKAY : 
                       RESP_DECERR;

    assign read_data = ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] == 0)) ? 
                       reg0 : 
                       ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] == 1)) ? 
                       reg1 : 
                       ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] == 2)) ? 
                       reg2 : 
                       ((read_addr_reg[7:4] == 4'h0) && (read_addr_reg[3:2] == 3)) ? 
