## 设计思路

1. **信号分类**：输入信号包括地址、数据、控制信号等，其中awvalid、wvalid、arvalid、bready、rready为握手信号；输出信号中awready、wready、arready为组合输出，bvalid、rvalid及响应信号为寄存器输出。

2. **状态机**：采用两个独立的状态机分别处理写操作和读操作。写状态机：IDLE→WAIT_W→SEND_B；读状态机：IDLE→SEND_R。写操作需要等待W通道数据到达。

3. **复位行为**：复位时所有输出信号清零，内部寄存器初始化。AXI握手协议通过valid/ready机制自然满足时序要求。

4. **寄存器实现**：4个32位寄存器映射到0x00-0x0C地址，支持字节级写使能。

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // Internal registers
    reg [31:0] reg0, reg1, reg2;
    reg [1:0] write_state, read_state;
    reg [31:0] read_data_reg;
    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done, read_done;
    reg [7:0] addr_reg;

    // Write state machine states
    parameter WRITE_IDLE = 2'b00;
    parameter WRITE_WAIT_W = 2'b01;
    parameter WRITE_SEND_B = 2'b10;

    // Read state machine states
    parameter READ_IDLE = 2'b00;
    parameter READ_SEND_R = 2'b01;

    // Register updates
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;
        end else if (write_done && write_resp_reg == 2'b00) begin // OKAY response
            case (addr_reg)
                8'h00: begin
                    if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                end
                8'h04: begin
                    if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                end
                8'h08: begin
                    if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                    if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                    if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                    if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                end
                default: ; // Do nothing for invalid or read-only addresses
            endcase
        end
    end

    // Write state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_state <= WRITE_IDLE;
            write_done <= 1'b0;
            write_resp_reg <= 2'b00;
            addr_reg <= 8'h00;
        end else case (write_state)
            WRITE_IDLE: begin
                if (awvalid && wvalid) begin
                    addr_reg <= awaddr;
                    write_resp_reg <= ((awaddr & 8'hFC) >= 8'h10) ? 2'b11 : 2'b00; // DECERR for 0x10-0xFF
                    if (((awaddr & 8'hFC) == 8'h0C)) // Only ID register is read-only at 0x0C
                        write_resp_reg <= 2'b10; // SLVERR for read-only
                    write_done <= 1'b1;
                    write_state <= WRITE_SEND_B;
                end else if (awvalid && !wvalid) begin
                    addr_reg <= awaddr;
                    write_resp_reg <= ((awaddr & 8'hFC) >= 8'h10) ? 2'b11 : 2'b00; // DECERR for 0x10-0xFF
                    if (((awaddr & 8'hFC) == 8'h0C)) // Only ID register is read-only at 0x0C
                        write_resp_reg <= 2'b10; // SLVERR for read-only
                    write_state <= WRITE_WAIT_W;
                end else if (!awvalid && wvalid) begin
                    write_state <= WRITE_WAIT_W;
                end
            end
            WRITE_WAIT_W: begin
                if (wvalid) begin
                    if (((addr_reg & 8'hFC) == 8'h0C)) // Check again in case AW came after W
                        write_resp_reg <= 2'b10; // SLVERR for read-only
                    else if ((addr_reg & 8'hFC) >= 8'h10)
                        write_resp_reg <= 2'b11; // DECERR for out of range
                    write_done <= 1'b1;
                    write_state <= WRITE_SEND_B;
                end
            end
            WRITE_SEND_B: begin
                if (bready) begin
                    write_done <= 1'b0;
                    write_state <= WRITE_IDLE;
                end
            end
            default: write_state <= WRITE_IDLE;
        endcase
    end

    // Read state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            read_state <= READ_IDLE;
            read_data_reg <= 32'h0;
            read_resp_reg <= 2'b00;
            read_done <= 1'b0;
        end else case (read_state)
            READ_IDLE: begin
                if (arvalid) begin
                    casez (araddr[7:0])
                        8'h00: read_data_reg <= reg0;
                        8'h04: read_data_reg <= reg1;
                        8'h08: read_data_reg <= reg2;
                        8'h0C: read_data_reg <= 32'h5A5A0003; // ID register
                        default: read_data_reg <= 32'h0; // For addresses 0x10-0xFF and others
                    endcase

                    if ((araddr & 8'hFC) >= 8'h10)
                        read_resp_reg <= 2'b11; // DECERR for 0x10-0xFF
                    else
                        read_resp_reg <= 2'b00; // OKAY for valid addresses

                    read_done <= 1'b1;
                    read_state <= READ_SEND_R;
                end
            end
            READ_SEND_R: begin
                if (rready) begin
                    read_done <= 1'b0;
                    read_state <= READ_IDLE;
                end
            end
            default: read_state <= READ_IDLE;
        endcase
    end

    // Output assignments
    assign awready = (write_state == WRITE_IDLE) && (wvalid || (write_state == WRITE_WAIT_W));
    assign wready = (write_state == WRITE_IDLE && awvalid) || (write_state == WRITE_WAIT_W);
    assign bvalid = (write_state == WRITE_SEND_B);
    assign bresp = write_resp_reg;

    assign arready = (read_state == READ_IDLE);
    assign rvalid = (read_state == READ_SEND_R);
    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

endmodule
