    parameter SLVERR = 2'b10;
    parameter DECERR = 2'b11;

    // Internal signals
    reg [31:0] reg0, reg1, reg2;
    reg [1:0] write_state; // 0: idle, 1: waiting for W, 2: waiting to respond, 3: responding
    reg [1:0] read_state;  // 0: idle, 1: waiting to respond, 2: responding
    reg [7:0] write_addr_reg;
    reg [31:0] write_data_reg;
    reg [3:0] write_strb_reg;
    reg [7:0] read_addr_reg;
    reg [2:0] write_resp_delay;
    reg [2:0] read_resp_delay;

    // Address decode
    wire [3:0] addr_high = awaddr[7:4];
    wire [3:0] read_addr_high = araddr[7:4];
    wire [1:0] reg_select = awaddr[3:2];
    wire [1:0] read_reg_select = araddr[3:2];
    wire is_mapped_write = (addr_high == 4'h0);
    wire is_mapped_read = (read_addr_high == 4'h0);
    wire is_id_reg_write = (reg_select == 2'b11 && is_mapped_write);
    wire is_id_reg_read = (read_reg_select == 2'b11 && is_mapped_read);

    // Write address and data handshake
    assign awready = (write_state == 0) || (write_state == 1 && wvalid);
    assign wready = (write_state == 0 && awvalid) || (write_state == 1);

    // Read address handshake
    assign arready = (read_state == 0);

    // Write response
    reg write_resp_valid;
    reg [1:0] write_resp;
    assign bvalid = write_resp_valid;
    assign bresp = write_resp;
    assign bready = bready; // Pass through

    // Read response
    reg read_resp_valid;
    reg [1:0] read_resp;
    assign rvalid = read_resp_valid;
    assign rresp = read_resp;
    assign rdata = read_resp_valid ? 
        (is_id_reg_read ? 32'h5A5A_0003 : 
         (read_reg_select == 2'b00) ? reg0 :
         (read_reg_select == 2'b01) ? reg1 : reg2) : 32'h0;

    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'h0;
            reg1 <= 32'h0;
            reg2 <= 32'h0;

            write_state <= 0;
            read_state <= 0;
            write_resp_valid <= 0;
            read_resp_valid <= 0;
            write_resp_delay <= 0;
