    reg [7:0] read_addr;
    reg [31:0] write_data;
    reg [3:0] write_strb;

    // Write state machine
    reg [2:0] write_state;  // 0: idle, 1: waiting for W, 2: waiting to respond
    reg [2:0] read_state;   // 0: idle, 1: waiting to respond

