    assign wready = (write_state == 0) ? 1'b1 : 
                    (write_state == 1) ? 1'b1 : 1'b0;

    // AR handshake control
    assign arready = (read_state == 0);

    // B channel
    assign bvalid = (write_state == 2) && (write_counter >= 3'd0);
    assign bresp = write_resp;

    // R channel
    assign rvalid = (read_state == 1) && (read_counter >= 3'd0);
    assign rdata = read_data;
    assign rresp = read_resp;

    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'h00000000;
            reg1 <= 32'h00000000;
            reg2 <= 32'h00000000;

            write_state <= 3'd0;
            read_state <= 3'd0;
            write_counter <= 3'd0;
            read_counter <= 3'd0;

