            // Update counters
            if (write_state == 2) begin
                if (bready && bvalid) begin
                    write_state <= 3'd0;
                    write_counter <= 3'd0;
                end else begin
                    write_counter <= write_counter + 1'b1;
                end
            end else if (write_state != 0) begin
                write_counter <= write_counter + 1'b1;
            end else begin
                write_counter <= 3'd0;
            end

            if (read_state == 1) begin
                if (rready && rvalid) begin
                    read_state <= 3'd0;
                    read_counter <= 3'd0;
                end else begin
                    read_counter <= read_counter + 1'b1;
