    wire ar_addr_mapped = (araddr_upper == 4'h0);
    wire ar_is_id_reg = (araddr_reg_select == ID_ADDR);

    // AW and W handshake control
    assign awready = !write_pending || (awvalid && wvalid && !internal_bvalid);
    assign wready = !write_pending || (awvalid && wvalid && !internal_bvalid);

    // AR handshake control
    assign arready = !read_pending || (arvalid && !internal_rvalid);

    // Outputs
    assign bvalid = internal_bvalid;
    assign bresp = internal_bresp;
    assign rvalid = internal_rvalid;
    assign rdata = internal_rdata;
    assign rresp = internal_rresp;

