    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state;
    reg [1:0] read_state;
    reg [7:0] saved_awaddr;
    reg [31:0] saved_araddr;
    reg [31:0] wdata_reg;
    reg [3:0] wstrb_reg;
    reg [2:0] b_count;
    reg [2:0] r_count;

    // Registers
    reg [31:0] reg0;
    reg [31:0] reg1; 
    reg [31:0] reg2;

    // Write channel handshake
    wire aw_handshake = awvalid & awready;
    wire w_handshake = wvalid & wready;

    // Address decode for write
    wire [3:0] aw_high_nibble = awaddr[7:4];
    wire [1:0] aw_reg_select = awaddr[3:2];
    wire aw_is_id_reg = (aw_addr == 8'h0C); // Actually offset 0x0C

    // Address decode for read  
    wire [3:0] ar_high_nibble = araddr[7:4];
    wire [1:0] ar_reg_select = araddr[3:2];
    wire ar_is_id_reg = (araddr == 8'h0C);

    // Outputs
    assign awready = (write_state == 2'b00) ? 1'b1 : 1'b0;
    assign wready = (write_state == 2'b00 || write_state == 2'b01) ? 1'b1 : 1'b0;
    assign arready = (read_state == 2'b00) ? 1'b1 : 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            write_state <= 2'b00;
            read_state <= 2'b00;
            bvalid <= 1'b0;
            rvalid <= 1'b0;
            bresp <= 2'b00;
            rresp <= 2'b00;
            rdata <= 32'h00000000;
            saved_awaddr <= 8'h00;
            saved_araddr <= 32'h00000000;
            wdata_reg <= 32'h00000000;
            wstrb_reg <= 4'h0;
            b_count <= 3'h0;
            r_count <= 3'h0;
            reg0 <= 32'h00000000;
            reg1 <= 32'h00000000;
            reg2 <= 32'h00000000;
        end else begin
            // Write state machine
            case (write_state)
                2'b00: begin // Idle
                    if (awvalid && wvalid) begin
                        saved_awaddr <= awaddr;
                        wdata_reg <= wdata;
                        wstrb_reg <= wstrb;
                        write_state <= 2'b10; // Go directly to response
                    end else if (awvalid) begin
                        saved_awaddr <= awaddr;
                        write_state <= 2'b01; // Wait for wvalid
                    end else if (wvalid) begin
                        wdata_reg <= wdata;
                        wstrb_reg <= wstrb;
                        write_state <= 2'b10; // Process immediately
                    end
                end

                2'b01: begin // Wait for wvalid
                    if (wvalid) begin
                        wdata_reg <= wdata;
                        wstrb_reg <= wstrb;
                        write_state <= 2'b10; // Go to response
                    end
                end

                2'b10: begin // Wait to send bresp
                    if (b_count < 3'd4) begin
                        b_count <= b_count + 1'b1;
                    end
                    if (b_count == 3'd3 || b_count == 3'd4) begin
                        bvalid <= 1'b1;

                        // Determine response based on address
                        if (saved_awaddr[7:4] != 4'h0) begin
                            bresp <= 2'b11; // DECERR
                        end else if (saved_awaddr == 8'h0C) begin
                            bresp <= 2'b10; // SLVERR for ID register (read-only)
                        end else begin
                            bresp <= 2'b00; // OKAY

                            // Update registers based on wstrb
                            if (aw_reg_select == 2'b00) begin
                                if (wstrb_reg[0]) reg0[7:0] <= wdata_reg[7:0];
                                if (wstrb_reg[1]) reg0[15:8] <= wdata_reg[15:8];
                                if (wstrb_reg[2]) reg0[23:16] <= wdata_reg[23:16];
                                if (wstrb_reg[3]) reg0[31:24] <= wdata_reg[31:24];
                            end else if (aw_reg_select == 2'b01) begin
                                if (wstrb_reg[0]) reg1[7:0] <= wdata_reg[7:0];
                                if (wstrb_reg[1]) reg1[15:8] <= wdata_reg[15:8];
                                if (wstrb_reg[2]) reg1[23:16] <= wdata_reg[23:16];
                                if (wstrb_reg[3]) reg1[31:24] <= wdata_reg[31:24];
                            end else if (aw_reg_select == 2'b10) begin
                                if (wstrb_reg[0]) reg2[7:0] <= wdata_reg[7:0];
                                if (wstrb_reg[1]) reg2[15:8] <= wdata_reg[15:8];
                                if (wstrb_reg[2]) reg2[23:16] <= wdata_reg[23:16];
                                if (wstrb_reg[3]) reg2[31:24] <= wdata_reg[31:24];
                            end
                        end
                    end

                    if (bvalid && bready) begin
                        bvalid <= 1'b0;
                        b_count <= 3'h0;
                        write_state <= 2'b00;
                    end
                end

                default: write_state <= 2'b00;
            endcase

            // Read state machine
            if (arvalid && arready) begin
                saved_araddr <= araddr;
                read_state <= 2'b01;
                r_count <= 3'h0;
            end

            case (read_state)
                2'b01: begin // Wait to send rresp
                    if (r_count < 3'd4) begin
                        r_count <= r_count + 1'b1;
                    end
                    if (r_count == 3'd3 || r_count == 3'd4) begin
                        rvalid <= 1'b1;

                        if (ar_high_nibble != 4'h0) begin
                            rresp <= 2'b11; // DECERR
                            rdata <= 32'h00000000;
                        end else if (ar_is_id_reg) begin
                            rresp <= 2'b00; // OKAY
                            rdata <= 32'h5A5A0003;
                        end else begin
                            case (ar_reg_select)
                                2'b00: begin
                                    rresp <= 2'b00; // OKAY
                                    rdata <= reg0;
                                end
                                2'b01: begin
                                    rresp <= 2'b00; // OKAY
                                    rdata <= reg1;
                                end
                                2'b10: begin
                                    rresp <= 2'b00; // OKAY
                                    rdata <= reg2;
                                end
                                default: begin
                                    rresp <= 2'b11; // DECERR
                                    rdata <= 32'h00000000;
                                end
                            endcase
                        end
                    end

                    if (rvalid && rready) begin
                        rvalid <= 1'b0;
                        read_state <= 2'b00;
                    end
                end
            endcase
        end
    end

