## 设计思路

1. **信号分类**：awready、wready、arready为组合输出；bvalid、rvalid、bresp、rdata、rresp为寄存器输出；四个寄存器(REG0~REG2, ID)需要存储。

2. **状态机设计**：写通路用2位计数器跟踪AW/W握手状态(0=空闲,1=已接收AW,2=已接收W,3=W响应中)；读通路用3位计数器跟踪(0=空闲,1~4=响应延迟)。

3. **复位行为**：清零所有寄存器输出和内部寄存器，设置ID为0x5A5A0003；时序要求通过计数器确保写响应在4周期内，读响应在4周期内完成。

4. **地址译码**：[7:4]非零返回DECERR，[3:2]选择寄存器(0-2对应REG0-2,3对应ID)，wstrb控制字节写使能。

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state;
    reg [2:0] read_delay;
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] read_data_reg;
    reg [1:0] read_resp_reg;
    reg [1:0] write_resp_reg;
    reg write_done;
    reg read_valid_reg;

    parameter OKAY = 2'b00;
    parameter SLVERR = 2'b10;
    parameter DECERR = 2'b11;

    assign awready = (write_state < 2);
    assign wready = (write_state < 2);
    assign arready = (read_delay == 0);
    assign bvalid = write_done;
    assign rvalid = read_valid_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            write_state <= 0;
            read_delay <= 0;
            reg0 <= 0;
            reg1 <= 0;
            reg2 <= 0;
            read_data_reg <= 0;
            read_resp_reg <= OKAY;
            write_resp_reg <= OKAY;
            write_done <= 0;
            read_valid_reg <= 0;
        end else begin
            // Write state machine
            case (write_state)
                2'b00: begin
                    if (awvalid && wvalid) begin
                        write_state <= 2'b11;  // Both AW and W available
                    end else if (awvalid) begin
                        write_state <= 2'b01;  // Only AW available
                    end else if (wvalid) begin
                        write_state <= 2'b10;  // Only W available
                    end
                end
                2'b01: begin  // Waiting for W
                    if (wvalid) begin
                        write_state <= 2'b11;
                    end
                end
                2'b10: begin  // Waiting for AW
                    if (awvalid) begin
                        write_state <= 2'b11;
                    end
                end
                2'b11: begin  // Both AW and W received
                    write_state <= 2'b11;  // Stay until we start response
                    write_done <= 1;
                    if (awaddr[7:4] != 4'h0) begin
                        write_resp_reg <= DECERR;
                    end else if (awaddr[3:2] == 3) begin  // Address 0x0C
                        write_resp_reg <= SLVERR;
                    end else begin
                        write_resp_reg <= OKAY;
                        // Update registers based on wstrb
                        if (awaddr[3:2] == 0) begin
                            if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                            if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                            if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                            if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                        end else if (awaddr[3:2] == 1) begin
                            if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                            if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                            if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                            if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                        end else if (awaddr[3:2] == 2) begin
                            if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                            if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                            if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                            if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                        end
                    end
                end
            endcase

            // Handle write response handshake
            if (write_done && bready) begin
                write_done <= 0;
                write_state <= 0;  // Reset to idle after response
            end

            // Read path handling
            if (arvalid && arready) begin
                read_delay <= 1;  // Start read delay counter
                if (araddr[7:4] != 4'h0) begin
                    read_resp_reg <= DECERR;
                    read_data_reg <= 0;
                end else if (araddr[3:2] == 0) begin
                    read_resp_reg <= OKAY;
                    read_data_reg <= reg0;
                end else if (araddr[3:2] == 1) begin
                    read_resp_reg <= OKAY;
                    read_data_reg <= reg1;
                end else if (araddr[3:2] == 2) begin
                    read_resp_reg <= OKAY;
                    read_data_reg <= reg2;
                end else if (araddr[3:2] == 3) begin
                    read_resp_reg <= OKAY;
                    read_data_reg <= 32'h5A5A0003;
                end
            end else if (read_delay > 0 && read_delay < 4) begin
                read_delay <= read_delay + 1;
            end else if (read_delay == 4) begin
                read_delay <= 0;
                read_valid_reg <= 1;
            end

            // Handle read response handshake
            if (rready && rvalid) begin
                read_valid_reg <= 0;
            end
        end
    end

    assign bresp = write_resp_reg;
    assign rdata = read_data_reg;
    assign rresp = read_resp_reg;

endmodule
