```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    // Register addresses
    parameter REG0_ADDR = 8'h00;
    parameter REG1_ADDR = 8'h04;
    parameter REG2_ADDR = 8'h08;
    parameter ID_ADDR   = 8'h0C;

    // Response codes
    parameter RESP_OKAY   = 2'b00;
    parameter RESP_SLVERR = 2'b10;
    parameter RESP_DECERR = 2'b11;

    // Internal signals for write transaction
    reg write_transaction_pending;
    reg [7:0] write_addr_reg;
    reg [31:0] write_data_reg;
    reg [3:0] write_strb_reg;
    reg [1:0] write_response;
    reg [2:0] write_resp_delay_counter;

    // Internal signals for read transaction
    reg read_transaction_pending;
    reg [7:0] read_addr_reg;
    reg [2:0] read_resp_delay_counter;

    // Registers
    reg [31:0] reg0, reg1, reg2;

    // Write response channel
    reg bvalid_reg;
    reg [1:0] bresp_reg;

    // Read response channel
    reg rvalid_reg;
    reg [31:0] rdata_reg;
    reg [1:0] rresp_reg;

    // AW and W handshake control
    reg aw_handshake_done;
    reg w_handshake_done;

    // AR handshake control
    reg ar_handshake_done;

    // Address decode for write
    wire [3:0] addr_high_nz = araddr[7:4] | awaddr[7:4];
    wire write_addr_valid = (awaddr == REG0_ADDR) | (awaddr == REG1_ADDR) | 
                           (awaddr == REG2_ADDR) | (awaddr == ID_ADDR);
    wire read_addr_valid = (araddr == REG0_ADDR) | (araddr == REG1_ADDR) | 
                          (araddr == REG2_ADDR) | (araddr == ID_ADDR);

    // AWREADY - independent of other channels
    assign awready = !aw_handshake_done;

    // WREADY - independent of other channels  
    assign wready = !w_handshake_done;

    // ARREADY - independent of write channels
    assign arready = !ar_handshake_done;

    // BVALID/BRESP
    assign bvalid = bvalid_reg;
    assign bresp = bresp_reg;

    // RVALID/RDATA/RRESP
    assign rvalid = rvalid_reg;
    assign rdata = rdata_reg;
    assign rresp = rresp_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            reg0 <= 32'h00000000;
            reg1 <= 32'h00000000;
            reg2 <= 32'h00000000;

            write_transaction_pending <= 1'b0;
            write_addr_reg <= 8'h00;
            write_data_reg <= 32'h00000000;
            write_strb_reg <= 4'h0;
            write_response <= 2'b00;
            write_resp_delay_counter <= 3'd0;

            read_transaction_pending <= 1'b0;
            read_addr_reg <= 8'h00;
            read_resp_delay_counter <= 3'd0;

            bvalid_reg <= 1'b0;
            bresp_reg <= 2'b00;

            rvalid_reg <= 1'b0;
            rdata_reg <= 32'h00000000;
            rresp_reg <= 2'b00;

            aw_handshake_done <= 1'b0;
            w_handshake_done <= 1'b0;
            ar_handshake_done <= 1'b0;
        end else begin
            // Handle write address channel handshake
            if (awvalid && awready) begin
                aw_handshake_done <= 1'b1;
                write_addr_reg <= awaddr;
            end

            // Handle write data channel handshake
            if (wvalid && wready) begin
                w_handshake_done <= 1'b1;
                write_data_reg <= wdata;
                write_strb_reg <= wstrb;
            end

            // Start write transaction when both AW and W are done
            if (aw_handshake_done && w_handshake_done && !write_transaction_pending) begin
                write_transaction_pending <= 1'b1;
                aw_handshake_done <= 1'b0;
                w_handshake_done <= 1'b0;

                // Determine response based on address
                if (awaddr[7:4] != 4'h0) begin
                    write_response <= RESP_DECERR;
                end else if (awaddr == ID_ADDR) begin
                    write_response <= RESP_SLVERR;  // ID register is read-only
                end else begin
                    write_response <= RESP_OKAY;
                end

                write_resp_delay_counter <= 3'd0;
            end

            // Handle write response generation
            if (write_transaction_pending) begin
                if (write_resp_delay_counter < 3'd4) begin
                    write_resp_delay_counter <= write_resp_delay_counter + 1'b1;
                end else if (!bvalid_reg) begin
                    bvalid_reg <= 1'b1;
                    bresp_reg <= write_response;

                    // Perform actual write if address is valid and not ID register
                    if ((write_addr_reg == REG0_ADDR) && (write_response == RESP_OKAY)) begin
                        if (write_strb_reg[0]) reg0[7:0] <= write_data_reg[7:0];
                        if (write_strb_reg[1]) reg0[15:8] <= write_data_reg[15:8];
                        if (write_strb_reg[2]) reg0[23:16] <= write_data_reg[23:16];
                        if (write_strb_reg[3]) reg0[31:24] <= write_data_reg[31:24];
                    end else if ((write_addr_reg == REG1_ADDR) && (write_response == RESP_OKAY)) begin
                        if (write_strb_reg[0]) reg1[7:0] <= write_data_reg[7:0];
                        if (write_strb_reg[1]) reg1[15:8] <= write_data_reg[15:8];
                        if (write_strb_reg[2]) reg1[23:16] <= write_data_reg[23:16];
                        if (write_strb_reg[3]) reg1[31:24] <= write_data_reg[31:24];
                    end else if ((write_addr_reg == REG2_ADDR) && (write_response == RESP_OKAY)) begin
                        if (write_strb_reg[0]) reg2[7:0] <= write_data_reg[7:0];
                        if (write_strb_reg[1]) reg2[15:8] <= write_data_reg[15:8];
                        if (write_strb_reg[2]) reg2[23:16] <= write_data_reg[23:16];
                        if (write_strb_reg[3]) reg2[31:24] <= write_data_reg[31:24];
                    end
                end
            end

            // Handle write response handshake
            if (bvalid_reg && bready) begin
                bvalid_reg <= 1'b0;
                write_transaction_pending <= 1'b0;
