## 设计思路

1. **信号分类**：输入信号均为组合，输出中awready/wready/arready为组合，bvalid/rvalid/bresp/rdata/rresp为寄存器输出
2. **状态机**：写通路用2位计数器记录AW/W握手状态，读通路用3位计数器记录延迟，避免状态冲突
3. **复位**：bvalid/rvalid清零，寄存器清零；时序要求通过计数器确保4周期内响应
4. **地址译码**：[7:4]非零返回DECERR，[3:2]选择寄存器，0x0C返回ID且拒绝写入

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state; // 00: idle, 01: got aw, 10: got w, 11: both ready
    reg [2:0] read_delay;
    reg [31:0] reg0, reg1, reg2;
    reg [1:0] pending_bresp;
    reg [31:0] pending_rdata;
    reg [1:0] pending_rresp;
    reg bvalid_reg;
    reg rvalid_reg;

    assign awready = (write_state == 2'b00) || (write_state == 2'b01);
    assign wready = (write_state == 2'b00) || (write_state == 2'b10);
    assign arready = (read_delay == 0);
    assign bvalid = bvalid_reg;
    assign rvalid = rvalid_reg;
    assign rdata = pending_rdata;
    assign rresp = pending_rresp;
    assign bresp = pending_bresp;

    always @(posedge clk) begin
        if (!rst_n) begin
            write_state <= 2'b00;
            read_delay <= 3'b000;
            reg0 <= 32'h00000000;
            reg1 <= 32'h00000000;
            reg2 <= 32'h00000000;
            bvalid_reg <= 1'b0;
            rvalid_reg <= 1'b0;
        end else begin
            // Write state machine
            case (write_state)
                2'b00: begin
                    if (awvalid && awready) write_state <= 2'b01;
                    if (wvalid && wready) write_state <= 2'b10;
                    if (awvalid && awready && wvalid && wready) write_state <= 2'b11;
                end
                2'b01: begin
                    if (wvalid && wready) write_state <= 2'b11;
                end
                2'b10: begin
                    if (awvalid && awready) write_state <= 2'b11;
                end
                2'b11: begin
                    // Both AW and W are received, prepare response
                    if (!bvalid_reg) begin
                        if (awaddr[7:4] != 4'h0) begin
                            pending_bresp <= 2'b11; // DECERR
                        end else if (awaddr[3:2] == 2'b11) begin
                            pending_bresp <= 2'b10; // SLVERR for ID register
                        end else begin
                            // Update register based on wstrb
                            case (awaddr[3:2])
                                2'b00: begin
                                    if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                                    if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                                    if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                                    if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                                end
                                2'b01: begin
                                    if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                                    if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                                    if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                                    if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                                end
                                2'b10: begin
                                    if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                                    if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                                    if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                                    if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                                end
                            endcase
                            pending_bresp <= 2'b00; // OKAY
                        end
                        bvalid_reg <= 1'b1;
                    end
                end
            endcase

            // Handle write response handshake
            if (bvalid_reg && bready) begin
                bvalid_reg <= 1'b0;
                write_state <= 2'b00;
            end

            // Read handling
            if (arvalid && arready) begin
                read_delay <= 3'b001; // Start delay counter
                if (araddr[7:4] != 4'h0) begin
                    pending_rresp <= 2'b11; // DECERR
                    pending_rdata <= 32'h00000000;
                end else begin
                    pending_rresp <= 2'b00; // OKAY
                    case (araddr[3:2])
                        2'b00: pending_rdata <= reg0;
                        2'b01: pending_rdata <= reg1;
                        2'b10: pending_rdata <= reg2;
                        2'b11: pending_rdata <= 32'h5A5A0003; // ID register
                    endcase
                end
            end

            if (read_delay != 0 && read_delay < 5) begin
                read_delay <= read_delay + 1;
            end

            if (read_delay == 5) begin
                rvalid_reg <= 1'b1;
                read_delay <= 3'b000;
            end

            if (rvalid_reg && rready) begin
                rvalid_reg <= 1'b0;
            end
        end
    end

endmodule
