## 设计思路

1. **信号分类**：awready、wready、arready为组合输出；bvalid、bresp、rvalid、rdata、rresp为寄存器输出
2. **状态机**：写通路用2bit计数器(0-3)跟踪AW/W握手后等待B响应的时间；读通路用2bit计数器跟踪AR握手后等待R响应的时间
3. **复位**：清零所有寄存器输出和内部寄存器，计数器归零
4. **时序**：写计数器在AW+W握手后开始计数，最多4周期内发出B响应；读计数器在AR握手后开始计数，最多4周期内发出R响应

```verilog
module axi_lite_slave (
    input clk,
    input rst_n,
    input awvalid,
    input [7:0] awaddr,
    output awready,
    input wvalid,
    input [31:0] wdata,
    input [3:0] wstrb,
    output wready,
    output bvalid,
    output [1:0] bresp,
    input bready,
    input arvalid,
    input [7:0] araddr,
    output arready,
    output rvalid,
    output [31:0] rdata,
    output [1:0] rresp,
    input rready
);

    reg [1:0] write_state; // 0: idle, 1: waiting for w, 2: waiting for aw+w, 3: waiting for b
    reg [1:0] read_state;  // 0: idle, 1: waiting for r
    reg [1:0] write_delay_counter;
    reg [1:0] read_delay_counter;
    reg [31:0] reg0, reg1, reg2;
    reg [31:0] current_rdata;
    reg [1:0] current_bresp;
    reg [1:0] current_rresp;
    reg bvalid_reg;
    reg rvalid_reg;

    wire addr_valid;
    wire [1:0] reg_select;
    wire is_id_reg;

    assign addr_valid = (awaddr[7:4] == 4'h0) && (araddr[7:4] == 4'h0);
    assign reg_select = awaddr[3:2];
    assign is_id_reg = (araddr[3:2] == 2'h3);

    assign awready = (write_state == 2'b00) || (write_state == 2'b01);
    assign wready = (write_state == 2'b00) || (write_state == 2'b10);
    assign arready = (read_state == 2'b00);
    assign bvalid = bvalid_reg;
    assign rvalid = rvalid_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            write_state <= 2'b00;
            read_state <= 2'b00;
            write_delay_counter <= 2'b00;
            read_delay_counter <= 2'b00;
            reg0 <= 32'h00000000;
            reg1 <= 32'h00000000;
            reg2 <= 32'h00000000;
            bvalid_reg <= 1'b0;
            rvalid_reg <= 1'b0;
            current_bresp <= 2'b00;
            current_rresp <= 2'b00;
            current_rdata <= 32'h00000000;
        end else begin
            // Handle write transaction
            case (write_state)
                2'b00: begin // Idle state
                    if (awvalid && wvalid) begin
                        write_state <= 2'b11; // Both AW and W are available
                    end else if (awvalid) begin
                        write_state <= 2'b01; // Waiting for W
                    end else if (wvalid) begin
                        write_state <= 2'b10; // Waiting for AW
                    end
                end
                2'b01: begin // Waiting for W
                    if (wvalid) begin
                        write_state <= 2'b11;
                    end
                end
                2'b10: begin // Waiting for AW
                    if (awvalid) begin
                        write_state <= 2'b11;
                    end
                end
                2'b11: begin // Both AW and W received, start delay counter
                    write_delay_counter <= 2'b00;
                    if (!addr_valid) begin
                        current_bresp <= 2'b11; // DECERR
                    end else if (awaddr[3:2] == 2'h3) begin
                        current_bresp <= 2'b10; // SLVERR for ID register
                    end else begin
                        current_bresp <= 2'b00; // OKAY
                        // Update register based on wstrb
                        case (awaddr[3:2])
                            2'h0: begin
                                if (wstrb[0]) reg0[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg0[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg0[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg0[31:24] <= wdata[31:24];
                            end
                            2'h1: begin
                                if (wstrb[0]) reg1[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg1[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg1[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg1[31:24] <= wdata[31:24];
                            end
                            2'h2: begin
                                if (wstrb[0]) reg2[7:0] <= wdata[7:0];
                                if (wstrb[1]) reg2[15:8] <= wdata[15:8];
                                if (wstrb[2]) reg2[23:16] <= wdata[23:16];
                                if (wstrb[3]) reg2[31:24] <= wdata[31:24];
                            end
                        endcase
                    end
                    write_state <= 2'b00; // Reset to idle
                    bvalid_reg <= 1'b1;   // Start B response
                end
            endcase

            // Handle write response handshake
            if (bvalid_reg && bready) begin
                bvalid_reg <= 1'b0;
            end else if (!bvalid_reg && (write_state == 2'b00) && (write_delay_counter != 2'b00)) begin
                write_delay_counter <= write_delay_counter - 1'b1;
                if (write_delay_counter == 2'b01) begin
                    bvalid_reg <= 1'b1;
                end
            end

            // Handle read transaction
            if (arvalid && arready) begin
                read_state <= 2'b01;
                read_delay_counter <= 2'b00;

                if (!addr_valid) begin
                    current_rresp <= 2'b11; // DECERR
                    current_rdata <= 32'h00000000;
                end else if (is_id_reg) begin
                    current_rresp <= 2'b00; // OKAY for ID register
                    current_rdata <= 32'h5A5A0003;
                end else begin
                    current_rresp <= 2'b00; // OKAY
                    case (araddr[3:2])
                        2'h0: current_rdata <= reg0;
                        2'h1: current_rdata <= reg1;
                        2'h2: current_rdata <= reg2;
                        default: current_rdata <= 32'h00000000;
                    endcase
                end
            end

            // Handle read response timing
            if (read_state == 2'b01) begin
                if (read_delay_counter < 2'b11) begin
                    read_delay_counter <= read_delay_counter + 1'b1;
                end

                if ((read_delay_counter == 2'b11) || (read_delay_counter == 2'b00)) begin
                    rvalid_reg <= 1'b1;
                    read_state <= 2'b00;
                end
            end

            // Handle read response handshake
            if (rvalid_reg && rready) begin
                rvalid_reg <= 1'b0;
            end
        end
    end

    assign bresp = current_bresp;
    assign rdata = current_rdata;
    assign rresp = current_rresp;

endmodule
