module priority_encoder8 (
    input [7:0] in,
    output [2:0] idx,
    output valid
);
    wire [2:0] idx0, idx1, idx2, idx3;
    wire valid0, valid1, valid2, valid3;

    // Level 0: direct assignment for each bit
    assign idx0 = 3'b111;
    assign valid0 = in[7];

    assign idx1 = 3'b110;
    assign valid1 = in[6];

    assign idx2 = 3'b101;
    assign valid2 = in[5];

    assign idx3 = 3'b100;
    assign valid3 = in[4];

    // Level 1: combine pairs
    assign idx[2] = (valid0) ? idx0[2] : 
                    (valid1) ? idx1[2] : 
                    (valid2) ? idx2[2] : 
                    (valid3) ? idx3[2] : 1'b0;

    assign idx[1] = (valid0) ? idx0[1] : 
                    (valid1) ? idx1[1] : 
                    (valid2) ? idx2[1] : 
                    (valid3) ? idx3[1] : 1'b0;

    assign idx[0] = (valid0) ? idx0[0] : 
                    (valid1) ? idx1[0] : 
                    (valid2) ? idx2[0] : 
                    (valid3) ? idx3[0] : 1'b0;

    assign valid = (valid0 || valid1 || valid2 || valid3);

endmodule
