module pwm_gen (
    input clk,
    input rst_n,
    input [7:0] duty,
    output pwm
);

reg [7:0] counter;
reg [7:0] D;
reg pwm_reg;

// Free-running counter
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        counter <= 8'd0;
    else
        counter <= counter + 8'd1;
end

// Latch duty at the start of each period
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        D <= 8'd0;
    else if (counter == 8'd255)
        D <= duty;
end

// Generate PWM output
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
